  ('e83af4e4-b440-5bf2-889b-eff1171e82c1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b17cac49-2d2b-59c4-bc80-5de456998e75', 'dedbd84d-c472-50ab-8e4a-58090509c117', 'Directed study', 'a1', true, 36),
  ('460effc6-93c3-5f5f-8336-fdae680089d1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b17cac49-2d2b-59c4-bc80-5de456998e75', 'dedbd84d-c472-50ab-8e4a-58090509c117', 'Doctrine, evidence & standards', 'a2', true, 23),
