  ('47815c44-7762-543e-8653-8e27395a980a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b17cac49-2d2b-59c4-bc80-5de456998e75', 'dedbd84d-c472-50ab-8e4a-58090509c117', 'PS-4 · Integrated Athlete Decision Case', 'a5', true, null),
  ('31f1901e-24b9-597f-83b9-29f38158ea86', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b17cac49-2d2b-59c4-bc80-5de456998e75', 'dedbd84d-c472-50ab-8e4a-58090509c117', 'T-01 · Foundations of Athletic Performance Defense', 'a6', true, null)
insert into public.content_blocks (id, organization_id, lesson_id, block_type, schema_version, data, position) values
  ('1d67cb76-58e8-51a3-a42d-480a2821a59c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c437a27b-32c8-54a9-9aa9-4a78ac043f65', 'quote', 1, ('{"text":"Most coaching arguments are definitional arguments that nobody has noticed are definitional. This module removes four of them before they can cost an athlete anything."}')::jsonb, 'a0'),
  ('7ba10c15-e8ea-5af7-b684-31d87f6b5eba', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c437a27b-32c8-54a9-9aa9-4a78ac043f65', 'rich_text', 1, ('{"text":"To establish what athletic performance is, what physical preparation can and cannot do, and what the performance coach is actually responsible for — so that every later decision has a defined subject."}')::jsonb, 'a1'),
  ('abb0c036-6093-5643-8fbd-b3b39b0a49e4', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c437a27b-32c8-54a9-9aa9-4a78ac043f65', 'checklist', 1, ('{"items":[{"id":"56caebd9-a0bf-5448-8e8e-e0d4f1e607b7","text":"M1.1 Define athletic performance as multifactorial, and name its contributors."},{"id":"31ca0f7a-e391-526e-bdec-00b6f1c6c3ca","text":"M1.2 Distinguish physical capacity, sport skill, and competitive performance."},{"id":"afd0b2ae-54a3-57db-a652-a13b4703902b","text":"M1.3 Define physical preparation as an applied umbrella term rather than a fixed scientific construct."},{"id":"f2a52b6f-adc6-5f8c-97d1-90c0738af0c5","text":"M1.4 State what the GPP / SPP / sport-specific / sport-practice taxonomy is and is not."},{"id":"3d964a81-3a4d-566f-899d-fa24530d89b1","text":"M1.5 Explain why a method can be valuable without resembling the sport."},{"id":"51766fcd-be6c-5ccb-8aca-f24e46bbb6a1","text":"M1.6 State the boundary of the performance coach''s role."}]}')::jsonb, 'a2'),
  ('b5b873db-7fa1-5dd5-85e1-f056a8b27ef4', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c437a27b-32c8-54a9-9aa9-4a78ac043f65', 'callout', 2, ('{"tone":"info","title":"Sequence & gating","body":"entry module"}')::jsonb, 'a3'),
  ('19f418af-77d4-5743-a2ad-7e24eff71572', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cbf1906c-21a9-5649-9a08-6a89dea0c46e', 'heading', 1, ('{"text":"L1.1 Four arguments that are really definitions","level":3}')::jsonb, 'a0'),
  ('6fbc8657-8973-5d60-bdac-f1452b7431c5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cbf1906c-21a9-5649-9a08-6a89dea0c46e', 'rich_text', 1, ('{"text":"\"Is that sport-specific?\" · \"Is conditioning training?\" · \"Does the weight room make athletes better?\" · \"Is he a good athlete?\" Each is unanswerable until the terms are fixed."}')::jsonb, 'a1'),
  ('fbe0f880-6a8f-517e-aadd-94a168080184', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cbf1906c-21a9-5649-9a08-6a89dea0c46e', 'heading', 1, ('{"text":"L1.2 Athletic performance, defined","level":3}')::jsonb, 'a2'),
  ('a52bdfac-9136-58bf-b786-0f4034882b09', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cbf1906c-21a9-5649-9a08-6a89dea0c46e', 'rich_text', 1, ('{"text":"The six contributor families, and why physical capacity is one of them rather than the whole."}')::jsonb, 'a3'),
  ('e96f95bb-f160-56ed-b8bd-39bc146bac3c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cbf1906c-21a9-5649-9a08-6a89dea0c46e', 'heading', 1, ('{"text":"L1.3 What physical preparation is for","level":3}')::jsonb, 'a4'),
  ('2577624b-5287-5763-b723-143716b7817a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cbf1906c-21a9-5649-9a08-6a89dea0c46e', 'rich_text', 1, ('{"text":"Health, availability, and performance support — with availability named explicitly, because it is the contribution coaches most often fail to claim."}')::jsonb, 'a5'),
  ('c3a5c451-e251-5fe1-b320-24c313ac8d6c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cbf1906c-21a9-5649-9a08-6a89dea0c46e', 'heading', 1, ('{"text":"L1.4 Capacity, skill, and performance","level":3}')::jsonb, 'a6'),
  ('ff86ddc0-5a68-52a0-9fdd-c7bb6607689e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cbf1906c-21a9-5649-9a08-6a89dea0c46e', 'rich_text', 1, ('{"text":"Three different things that improve at different rates, respond to different work, and are measured differently."}')::jsonb, 'a7'),
  ('69d020b6-cc6b-5943-8486-e4054ed8324b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cbf1906c-21a9-5649-9a08-6a89dea0c46e', 'heading', 1, ('{"text":"L1.5 GPP, SPP, and honest labeling","level":3}')::jsonb, 'a8'),
  ('bca0b119-fc4d-511e-87c5-534e529a9083', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cbf1906c-21a9-5649-9a08-6a89dea0c46e', 'rich_text', 1, ('{"text":"The taxonomy as adopted G3 language (§3.3), its three constraints, and the sentence that marks it as language rather than science."}')::jsonb, 'a9'),
  ('de1f6a67-eff2-57b4-8755-6f722adfffde', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cbf1906c-21a9-5649-9a08-6a89dea0c46e', 'heading', 1, ('{"text":"L1.6 Why resemblance is not the test","level":3}')::jsonb, 'b0'),
  ('1cbc5f73-c31d-5da0-a432-818bd0311957', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cbf1906c-21a9-5649-9a08-6a89dea0c46e', 'rich_text', 1, ('{"text":"Introduced here, developed fully in M4: a method earns its place by developing a limiting or target quality, not by looking like the game."}')::jsonb, 'b1'),
  ('1b962338-1d7c-5cbf-9d67-fa2b9ca44d9f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cbf1906c-21a9-5649-9a08-6a89dea0c46e', 'heading', 1, ('{"text":"L1.7 The role and its edges","level":3}')::jsonb, 'b2'),
  ('b7aac50c-af58-563c-9cd8-e0daddf7ed50', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cbf1906c-21a9-5649-9a08-6a89dea0c46e', 'rich_text', 1, ('{"text":"What a performance coach does, and the first statement of scope (D101-21) that M12 completes."}')::jsonb, 'b3'),
  ('f4ae57cf-a947-5d22-bbf5-4a7a7b77e505', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c69df759-3f00-5142-b0ee-f109fa2c4ea8', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D101-01 — Principles Are Decision Frameworks","body":"Training principles guide reasoning. They are not universal algorithms and not rigid biological laws. — Teaching boundary: \"Conditional\" does not mean \"optional\" or \"anything goes.\" A principle that is conditional still constrains: it tells the coach what to look at and what would count as evidence. A coach who uses conditionality as a licence to do whatever they prefer has misunderstood the doctrine more badly than one who treats it as a law. — Evidence class: A/B"}')::jsonb, 'a0'),
  ('914eaeb9-f74b-513d-bc60-44cbcd2c4d2c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c69df759-3f00-5142-b0ee-f109fa2c4ea8', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D101-07 — Physical Preparation Supports Sport; It Does Not Replace Sport","body":"Performance training develops physical capacities. Sport practice develops sport-specific skill, perception, decision-making, and tactical execution. The two are not substitutes. — Teaching boundary: This is not a demotion of the weight room. A method can be valuable even when it does not resemble a sport action, provided it develops a limiting or target quality that contributes in the athlete''s context. The doctrine sets the claim boundary, not the value. — Evidence class: A"}')::jsonb, 'a1'),
  ('829ad6ec-28b8-58bd-9335-e60a7d6a644f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c69df759-3f00-5142-b0ee-f109fa2c4ea8', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D101-21 — Scope of Practice Is Part of Coaching Competence","body":"Performance coaches train and monitor performance. They do not independently diagnose medical conditions, provide medical clearance, or substitute for qualified healthcare professionals. — Teaching boundary: Scope is a competence, not a disclaimer. Recognizing the boundary early, communicating clearly, and referring well is skilled coaching — not an admission of limitation. Referring reflexively to avoid a conversation is its own failure. — Evidence class: A/B"}')::jsonb, 'a2'),
  ('1ebbc0fb-24f9-5802-8efd-8bdf8c9e8ca7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c69df759-3f00-5142-b0ee-f109fa2c4ea8', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A / Known","body":"Sport performance is determined by technical, tactical, perceptual-cognitive, physical, psychological, and contextual factors — Basis: EP101-01, EP101-03; EP101-01; EP101-03"}')::jsonb, 'a3'),
  ('96b5d011-596e-583e-85d8-1b9f117de511', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c69df759-3f00-5142-b0ee-f109fa2c4ea8', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A / Known","body":"Physical capacity can support sport performance but is not equivalent to sport skill or competitive success — Basis: EP101-03; EP101-03"}')::jsonb, 'a4'),
  ('22e3fced-9132-5fff-a8e8-829736073058', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c69df759-3f00-5142-b0ee-f109fa2c4ea8', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A / Known","body":"Physical training can improve component qualities — strength, hypertrophy, sprint, jump, power — within studied populations — Basis: EP101-04, EP101-13, EP101-25, EP101-26; EP101-04; EP101-13; EP101-25; EP101-26"}')::jsonb, 'a5'),
  ('490809a0-913d-5599-9f7e-1fd28d50c2c2', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c69df759-3f00-5142-b0ee-f109fa2c4ea8', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B / Probable","body":"Improvements in component qualities may contribute to sport performance; the practical effect is sport-, athlete-, and task-dependent — Basis: EP101-03; EP101-03"}')::jsonb, 'a6'),
  ('e302f151-b03b-5560-8f2c-8c2ab8a70801', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c69df759-3f00-5142-b0ee-f109fa2c4ea8', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B / Probable","body":"Physical preparation and strength and conditioning are practical umbrella terms, not tightly standardized scientific constructs — Basis: EP101-03, EP101-05; EP101-03; EP101-05"}')::jsonb, 'a7'),
  ('d2738eae-aea5-5307-ae74-97c8773e02eb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c69df759-3f00-5142-b0ee-f109fa2c4ea8', 'callout', 2, ('{"tone":"info","title":"Evidence — Class E / Organizational Choice","body":"GPP / SPP / sport-specific / sport-practice labels are useful coaching language, not a complete causal model of transfer — Basis: EP101-03, EP101-05; EP101-03; EP101-05"}')::jsonb, 'a8'),
  ('0d7fb2fd-94e0-574e-a058-195522e8eda3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c69df759-3f00-5142-b0ee-f109fa2c4ea8', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A/B / Known-Probable","body":"Training principles are conditional decision frameworks rather than universal laws — Basis: EP101-04, EP101-05, EP101-07, EP101-08; EP101-04; EP101-05; EP101-07; EP101-08"}')::jsonb, 'a9'),
  ('c5996757-1ca8-5503-9354-e7d21ae85506', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c69df759-3f00-5142-b0ee-f109fa2c4ea8', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B / Probable","body":"A method can be valuable without visual sport resemblance if it develops a limiting or target quality — Basis: EP101-03; EP101-03"}')::jsonb, 'b0'),
  ('e9284c4e-8299-5453-9a81-e4dce6202671', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c69df759-3f00-5142-b0ee-f109fa2c4ea8', 'callout', 2, ('{"tone":"success","title":"G3 Applied Standard AS-101-01 — Define the Target Before the Method","body":"Name the desired performance quality or outcome before selecting exercises or technology. — Enforcement: every exposure object requires target_quality and demand (§21.4)."}')::jsonb, 'b1'),
  ('22721d84-d6b1-5e65-9d32-cfd8ab9d5517', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c69df759-3f00-5142-b0ee-f109fa2c4ea8', 'callout', 2, ('{"tone":"success","title":"G3 Applied Standard AS-101-15 — Refer Beyond Scope","body":"Escalate medical, injury, nutritional, psychological, or return-to-play concerns to qualified professionals when appropriate."}')::jsonb, 'b2'),
  ('556abbde-9b41-5473-96ce-b8a8a0226502', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c69df759-3f00-5142-b0ee-f109fa2c4ea8', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"whether the GPP/SPP taxonomy is used in a given conversation, and how emphasis is distributed across it (CJ-10)."}')::jsonb, 'b3'),
  ('69091aab-7fc6-59b2-bea2-1b01672da92a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c69df759-3f00-5142-b0ee-f109fa2c4ea8', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Treating a physical test result as a performance verdict · using \"sport-specific\" as a property an exercise owns (CA-07) · defending a definition as though it were a finding · claiming sport outcomes for weight-room work (CA-07 family, developed in M4) · describing the coach''s role in terms that overlap medical scope (D101-21)."}')::jsonb, 'b4'),
  ('e750a551-c39b-5813-8223-7c3ee8d11b42', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c69df759-3f00-5142-b0ee-f109fa2c4ea8', 'callout', 2, ('{"tone":"warning","title":"Population-transfer disclosure (AS-101-16)","body":"the definitional material is conceptual rather than population-limited. The component-quality evidence is drawn substantially from adults and from male-dominant samples, and the youth outcome evidence is adolescent-weighted — disclosed again wherever it is used to justify a method (M4, M9)."}')::jsonb, 'b5'),
  ('0ef77f45-8cd0-586e-9d2a-5c6a570f5e1b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a1dcfc36-7086-58b8-a389-e8c668745549', 'rich_text', 1, ('{"text":"Applied immediately to how G3 sessions and blocks are labeled. \"Speed day\" is a schedule entry, not a target. The module ends with coaches rewriting their own current session labels into demand-and-target language."}')::jsonb, 'a0'),
  ('3f7fcf7e-eac2-5cb8-9475-15f595046ad7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a1dcfc36-7086-58b8-a389-e8c668745549', 'scenario', 1, ('{"intro":"Scenario M1-A — Four labels, one athlete. A high-school athlete''s week is presented as it is actually labeled — \"speed,\" \"lift,\" \"conditioning,\" \"skills.\" Coaches rewrite each block as demand, target quality, and intended contribution, then identify which of the four they cannot rewrite without more information.","steps":[{"id":"a2454b19-cebd-5ce4-8120-2d960eed9b77","situation":"Work the case with your assessor: name the decision, the evidence class behind it, and what would change your answer."}]}')::jsonb, 'a1'),
  ('63f24e51-60b2-5613-b335-11a755199de0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a1dcfc36-7086-58b8-a389-e8c668745549', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"Feeds PS-1. Definitional accuracy carries into every sign-off and is scored in T-01."}')::jsonb, 'a2'),
  ('d95d0355-6cb0-59e6-8447-e33cd8e776d2', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '41ced866-53c1-52c1-b297-8ed250a8715f', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('a16b94ab-7d59-5e43-8f29-c9b2f28071a8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '41ced866-53c1-52c1-b297-8ed250a8715f', 'assessment_reference', 1, ('{"assessmentId":"8bf7bf17-c157-5797-b87e-388618d3d410","title":"G3-101 · M1 Assessment — What Athletic Performance Training Is"}')::jsonb, 'a1'),
  ('095c9ec4-e396-5e86-9f16-e45e81515f87', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '47617a34-fd42-5d84-adcd-1eaea21e7814', 'quote', 1, ('{"text":"A coach who cannot tell a response from an adaptation will spend a career reacting to noise — changing programs that were working and keeping ones that were not."}')::jsonb, 'a0'),
  ('ee8423a9-6b7c-5c03-99a3-045333b7777f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '47617a34-fd42-5d84-adcd-1eaea21e7814', 'rich_text', 1, ('{"text":"To install the acute-versus-chronic distinction, the trend-reading habit that follows from it, and the specific reason that soreness cannot be used as a readout."}')::jsonb, 'a1'),
  ('45d3a3d5-3bc3-524b-a516-456a7b1b98ca', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '47617a34-fd42-5d84-adcd-1eaea21e7814', 'checklist', 1, ('{"items":[{"id":"8f873c74-9c0d-55e7-87ae-e4ed65882a86","text":"M2.1 Distinguish acute response from chronic adaptation."},{"id":"36094327-11db-5688-97ad-eab592208413","text":"M2.2 Explain why repeated, relevant, tolerable exposure is required for adaptation."},{"id":"3b35dc4a-c3fb-5761-8804-d4725d617e92","text":"M2.3 Explain the repeated-bout effect and its consequence for program judgment."},{"id":"13565d7b-2b45-5964-8224-bfa8509d1e0a","text":"M2.4 Explain why exact adaptation timing is not individually predictable from field models."},{"id":"d7ed4064-1956-5d32-87c2-84bc33725d9a","text":"M2.5 Identify what a single session can and cannot establish."},{"id":"a5933d8e-7692-5fb0-aaf3-395d1f9594f3","text":"M2.6 Describe how a trend is evaluated: what is measured, over what period, against what."},{"id":"6341b016-4261-5c90-a268-37b051f5ffd6","text":"M2.7 State why \"nonresponder\" is a claim requiring caution."}]}')::jsonb, 'a2'),
  ('d107bbc1-7594-500c-93cf-265f923796f2', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '47617a34-fd42-5d84-adcd-1eaea21e7814', 'callout', 2, ('{"tone":"info","title":"Sequence & gating","body":"requires M1"}')::jsonb, 'a3'),
  ('6fd68d47-401d-5569-9530-b8d0bc89bb6e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '066613d4-6e01-566a-af95-66fe37b176eb', 'heading', 1, ('{"text":"L2.1 Two timescales","level":3}')::jsonb, 'a0'),
  ('72c99d1c-945a-5283-9757-a644864f158f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '066613d4-6e01-566a-af95-66fe37b176eb', 'rich_text', 1, ('{"text":"What happens in a session, what happens across a block, and why coaches routinely read the first as evidence of the second."}')::jsonb, 'a1'),
  ('53476da1-6c68-5929-8698-6cd931eab3fb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '066613d4-6e01-566a-af95-66fe37b176eb', 'heading', 1, ('{"text":"L2.2 What adaptation requires","level":3}')::jsonb, 'a2'),
  ('f4b527cd-78df-5d12-be40-5e22dbd09934', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '066613d4-6e01-566a-af95-66fe37b176eb', 'rich_text', 1, ('{"text":"Repeated · relevant · tolerable · sustained. Remove any one and the exposure stops producing change."}')::jsonb, 'a3'),
  ('83afcb45-bb0e-53c1-821b-681f91463484', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '066613d4-6e01-566a-af95-66fe37b176eb', 'heading', 1, ('{"text":"L2.3 The repeated-bout effect","level":3}')::jsonb, 'a4'),
  ('3c5b5dea-0cf5-5481-89c5-1be872c3aa5a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '066613d4-6e01-566a-af95-66fe37b176eb', 'rich_text', 1, ('{"text":"Why the third week feels easier, and why that is the program working rather than the program failing."}')::jsonb, 'a5'),
  ('b0bf8fd0-09ca-5ee0-bb47-e62d811f02d1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '066613d4-6e01-566a-af95-66fe37b176eb', 'heading', 1, ('{"text":"L2.4 The supercompensation problem","level":3}')::jsonb, 'a6'),
  ('bbb7c9df-a13a-52b5-9817-503ecc3869cc', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '066613d4-6e01-566a-af95-66fe37b176eb', 'rich_text', 1, ('{"text":"A useful picture with a false promise: it explains a relationship, it does not schedule an athlete. Full historical treatment in M6."}')::jsonb, 'a7'),
  ('24d85236-3083-535f-9d45-bcccd74cbe07', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '066613d4-6e01-566a-af95-66fe37b176eb', 'heading', 1, ('{"text":"L2.5 Reading a trend","level":3}')::jsonb, 'a8'),
  ('6565ec41-6ff6-5200-98ac-23bfc291669d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '066613d4-6e01-566a-af95-66fe37b176eb', 'rich_text', 1, ('{"text":"What is measured, how often, over what period, against what baseline — and what would count as no change."}')::jsonb, 'a9'),
  ('f2ce0153-d455-5491-88b3-618640ff9aa0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '066613d4-6e01-566a-af95-66fe37b176eb', 'heading', 1, ('{"text":"L2.6 Variability and its sources","level":3}')::jsonb, 'b0'),
  ('84ef457c-f01e-556c-bf12-806e41c0ee58', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '066613d4-6e01-566a-af95-66fe37b176eb', 'rich_text', 1, ('{"text":"Training status, adherence, outcome selection, measurement error, recovery context. Each is checked before biology is blamed."}')::jsonb, 'b1'),
  ('16cde1c1-91ad-5baa-848a-7a1aac32df13', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '066613d4-6e01-566a-af95-66fe37b176eb', 'heading', 1, ('{"text":"L2.7 \"Nonresponder,\" carefully","level":3}')::jsonb, 'b2'),
  ('e23e92d8-f7be-51ee-a8f2-f3de2c4f0434', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '066613d4-6e01-566a-af95-66fe37b176eb', 'rich_text', 1, ('{"text":"What the label would require, why it is almost never available after one block, and what to say instead (§3.2)."}')::jsonb, 'b3'),
  ('94ccce30-71a4-5139-90be-2fd0472f3db6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '857cfcf7-2bc9-593d-8112-8cd5b137ee87', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D101-02 — Adaptation Requires Repeated Relevant Exposure","body":"A single session produces responses. Chronic adaptation requires repeated, relevant, appropriately dosed exposure over time. Coaches evaluate trends rather than inferring adaptation from one workout. — Teaching boundary: Trend-reading is not an excuse for never evaluating. A coach who says \"it''s a trend, give it time\" for six months without a defined outcome or review point has not applied the doctrine — they have avoided measurement. — Evidence class: A"}')::jsonb, 'a0'),
  ('596aa91e-ffc9-5d9b-b6d0-01c7c98eccea', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '857cfcf7-2bc9-593d-8112-8cd5b137ee87', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D101-10 — Fatigue Is a Cost, Not the Product","body":"Fatigue and soreness may accompany training but do not establish effectiveness. Training quality is judged against intended adaptation and performance outcomes. — Teaching boundary: The correction does not make fatigue meaningless. Fatigue is real information about exposure and tolerance, and managing it is a coaching obligation (obligation 6). What it is not is a measure of whether the session worked. — Evidence class: A"}')::jsonb, 'a1'),
  ('4a30116e-7da6-5b86-8648-328945f099f5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '857cfcf7-2bc9-593d-8112-8cd5b137ee87', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D101-01 — Principles Are Decision Frameworks","body":"Training principles guide reasoning. They are not universal algorithms and not rigid biological laws. — Teaching boundary: \"Conditional\" does not mean \"optional\" or \"anything goes.\" A principle that is conditional still constrains: it tells the coach what to look at and what would count as evidence. A coach who uses conditionality as a licence to do whatever they prefer has misunderstood the doctrine more badly than one who treats it as a law. — Evidence class: A/B"}')::jsonb, 'a2'),
  ('6a0fd689-51c5-5c53-8372-4f251b64526e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '857cfcf7-2bc9-593d-8112-8cd5b137ee87', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A / Known","body":"Training produces acute responses; repeated appropriately dosed exposure can produce chronic adaptation — Basis: EP101-04, EP101-05; EP101-04; EP101-05"}')::jsonb, 'a3'),
  ('27eab0ee-58be-575f-8c3a-6bb2e31cf236', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '857cfcf7-2bc9-593d-8112-8cd5b137ee87', 'callout', 2, ('{"tone":"info","title":"Evidence — Class F / Known against the precision claim","body":"Exact adaptation timelines and the optimal next exposure are not individually predictable with the precision simplified supercompensation curves imply — Basis: EP101-04, EP101-05; EP101-04; EP101-05"}')::jsonb, 'a4'),
  ('252bf948-3cd8-5fc8-9bad-af6bb547cdd1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '857cfcf7-2bc9-593d-8112-8cd5b137ee87', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A / Known","body":"The repeated-bout effect means a familiar bout produces less damage and soreness after prior exposure — Basis: EP101-04, EP101-05; EP101-04; EP101-05"}')::jsonb, 'a5'),
  ('5e6af1eb-d4fa-5596-9f95-491b34fe3a39', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '857cfcf7-2bc9-593d-8112-8cd5b137ee87', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A / Known against the claim","body":"Reduced soreness does not establish that a program has become ineffective or that exercises must be changed — Basis: EP101-04, EP101-05; EP101-04; EP101-05"}')::jsonb, 'a6'),
  ('2d84f82b-59c5-53c1-9f48-727a45088717', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '857cfcf7-2bc9-593d-8112-8cd5b137ee87', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A / Known","body":"Training status, prior exposure, adherence, outcome choice, measurement error, and recovery context all modify observed response — Basis: EP101-04, EP101-27, EP101-28; EP101-04; EP101-27; EP101-28"}')::jsonb, 'a7'),
  ('748fd9ad-3bf8-5327-bdf5-ff6c9efae00e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '857cfcf7-2bc9-593d-8112-8cd5b137ee87', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B / Probable","body":"Apparent nonresponse may be outcome-specific, dose-dependent, measurement-dependent, or temporary; broad global nonresponse is unlikely on current conceptual analysis — Basis: EP101-27, EP101-28; EP101-27; EP101-28"}')::jsonb, 'a8'),
  ('ce7e1b20-1e8c-5af1-b729-349e590f1f5a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '857cfcf7-2bc9-593d-8112-8cd5b137ee87', 'callout', 2, ('{"tone":"info","title":"Evidence — Class F / Known against claim","body":"Soreness quantifies adaptation or session quality — Basis: EP101-04, EP101-05; EP101-04; EP101-05"}')::jsonb, 'a9'),
  ('f4d36226-ebfd-552b-a603-97e6e71a0d33', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '857cfcf7-2bc9-593d-8112-8cd5b137ee87', 'callout', 2, ('{"tone":"success","title":"G3 Applied Standard AS-101-02 — Separate Acute Response From Chronic Adaptation","body":"Do not use soreness, fatigue, pump, sweat, or a single performance response as proof of adaptation."}')::jsonb, 'b0'),
  ('df332e96-edf9-5b78-bdd1-eb7b976253f9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '857cfcf7-2bc9-593d-8112-8cd5b137ee87', 'callout', 2, ('{"tone":"success","title":"G3 Applied Standard AS-101-05 — Preserve Program Stability Long Enough to Coach and Evaluate","body":"Do not rotate exercises solely to create novelty. Change when demand, response, constraints, or practical utility justify it."}')::jsonb, 'b1'),
  ('5a6718b6-546b-50d9-b00f-d56831ef65fc', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '857cfcf7-2bc9-593d-8112-8cd5b137ee87', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"how long a trend must run before it is read (CJ-05, CJ-19); which outcome is the one worth tracking for this athlete."}')::jsonb, 'b2'),
  ('9321e60d-af70-5e21-8edc-b5b77692fdbc', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '857cfcf7-2bc9-593d-8112-8cd5b137ee87', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Soreness treated as a readout (CA-02) · fatigue treated as productivity (CA-19) · changing a program because it stopped being sore (CA-02, CA-15) · \"muscle confusion\" (CA-16) · supercompensation used as a schedule (CA-18) · labeling an athlete a nonresponder after one block (CA-28)."}')::jsonb, 'b3'),
  ('062c0b36-21b5-5fb6-ae2e-df757397ebef', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '857cfcf7-2bc9-593d-8112-8cd5b137ee87', 'callout', 2, ('{"tone":"warning","title":"Population-transfer disclosure (AS-101-16)","body":"the adaptation and repeated-bout literature is adult-weighted and not youth-specific; the responder/nonresponder analysis is conceptual and not resistance-training-exclusive. Both are disclosed where the material is applied to youth (M9)."}')::jsonb, 'b4'),
  ('a1fcfdb8-d99b-5a68-9fcf-513e74b7b60e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '18d274a0-11ea-588d-855f-dd54c3fd8656', 'rich_text', 1, ('{"text":"Applied to how G3 evaluates a block. The module produces a standing G3 habit: before changing a program, state which of the five variability sources has been ruled out."}')::jsonb, 'a0'),
  ('7ae27a9e-f781-569f-875c-3ba6174f88ce', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '18d274a0-11ea-588d-855f-dd54c3fd8656', 'scenario', 1, ('{"intro":"The Athlete Is Sore. Two athletes, same session, three days ago. Athlete A is still sore and says it was the best workout they have had in months. Athlete B is not sore at all and asks whether they should be doing more. Both are on the same program, in week three of a block.","steps":[{"id":"fa3bff81-45e9-5edd-95a2-c18e770e27c5","situation":"Situation"},{"id":"a031d23d-50d8-588f-9e63-9a845acc6896","situation":"Decision"},{"id":"79eb02d2-f6d6-58c5-812e-bfdf757d0349","situation":"Defense"},{"id":"812fc271-8956-542e-9fe5-cc81d8995bd6","situation":"Discussion"}],"debrief":"Decision required: What does the soreness tell you about each athlete, and what changes?\n\nFailure modes: Soreness read as effectiveness (CA-02) · absence of soreness read as failure · fatigue read as productivity (CA-19) · changing the block on either athlete''s report (CA-15) · adding volume to chase soreness (CA-03) · no defined outcome ever named.\n\nDefensible variation: A coach who reduces Athlete A''s session today after triangulating passes. A coach who runs both as planned and explains why passes. A coach who adds work for Athlete B because they are not sore fails."}')::jsonb, 'a1'),
  ('ea214175-4503-545e-8d1e-ceca18741869', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '18d274a0-11ea-588d-855f-dd54c3fd8656', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"Feeds PS-1."}')::jsonb, 'a2'),
  ('45aad58e-f433-5f1f-8bb0-f979d6c91a8d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ea3f79e6-f3d7-5b53-a976-4beae036b4bb', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('b8167ce7-7c76-5707-9f20-15abd8e4ed51', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ea3f79e6-f3d7-5b53-a976-4beae036b4bb', 'assessment_reference', 1, ('{"assessmentId":"f8c940b7-0926-5f85-a700-aca394c4699c","title":"G3-101 · M2 Assessment — Adaptation: What Training Actually Changes"}')::jsonb, 'a1'),
  ('ed95d39f-6d35-5954-8cbc-53f87c48443b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b36427f9-3dee-5ab8-a199-d9e6eaed8e3d', 'quote', 1, ('{"text":"\"Progressive overload\" is the most-cited and least-understood phrase in the profession. This module replaces it with a question the coach can actually answer: which variable, and why that one?"}')::jsonb, 'a0'),
  ('86edf311-4681-59df-b5e5-b5282ff1a828', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b36427f9-3dee-5ab8-a199-d9e6eaed8e3d', 'rich_text', 1, ('{"text":"To establish overload as multi-variable demand, progression as a targeted choice, and dose as a judgment about opportunity against cost — without publishing a single number G3 cannot support."}')::jsonb, 'a1'),
  ('c6e12127-3f2d-5e3a-ae57-dfea59de9c8f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b36427f9-3dee-5ab8-a199-d9e6eaed8e3d', 'checklist', 1, ('{"items":[{"id":"328571cd-c573-5aa7-8323-518ca314e7b9","text":"M3.1 Define overload as demand relative to current capacity and intended adaptation."},{"id":"295bd88f-88f2-5d9e-89e3-41f198b297d1","text":"M3.2 Name the variables through which demand can be changed."},{"id":"59d8b250-ee48-50c6-961c-d90ab5eabc48","text":"M3.3 Select a progression variable for a stated target and justify the selection."},{"id":"44d1cd9c-c4d4-54ef-84a8-940a71911cc6","text":"M3.4 Explain why no universal progression sequence exists."},{"id":"398b1515-5443-53a6-b135-42dc038b1279","text":"M3.5 Explain dose-response, diminishing returns, and their limits."},{"id":"f0715ab7-251d-5be1-abad-47875cc37b0e","text":"M3.6 Use \"minimum effective dose\" and \"maximum recoverable volume\" correctly, as heuristics."},{"id":"45a32238-fe63-5172-bfb6-d470a2f7e3c1","text":"M3.7 Explain why not every session must create overload."}]}')::jsonb, 'a2'),
  ('95263b3d-9960-5454-b9bb-6726ad722932', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b36427f9-3dee-5ab8-a199-d9e6eaed8e3d', 'callout', 2, ('{"tone":"info","title":"Sequence & gating","body":"requires M2"}')::jsonb, 'a3'),
  ('52e32a3b-5c49-5072-9e52-ba8b07fba7eb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c203f792-901d-563d-bf20-0e4ef21fd386', 'heading', 1, ('{"text":"L3.1 What overload actually means","level":3}')::jsonb, 'a0'),
  ('042a295c-7226-5bc6-8111-aa0ce14a82bc', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c203f792-901d-563d-bf20-0e4ef21fd386', 'rich_text', 1, ('{"text":"Demand relative to capacity and target — the definition that makes the rest of the module possible."}')::jsonb, 'a1'),
  ('18f5d756-6989-5706-967d-2ed3e1a98101', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c203f792-901d-563d-bf20-0e4ef21fd386', 'heading', 1, ('{"text":"L3.2 Ten ways to change demand","level":3}')::jsonb, 'a2'),
  ('fb48ad66-217a-5063-b91b-8639ed753f77', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c203f792-901d-563d-bf20-0e4ef21fd386', 'rich_text', 1, ('{"text":"Load, volume, frequency, density, ROM, contraction emphasis, velocity and intent, complexity, technical demand, exposure distribution — each with what it is good for and what it costs."}')::jsonb, 'a3'),
  ('d1a52b45-3899-5f8c-97c8-3214d2e9c3c1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c203f792-901d-563d-bf20-0e4ef21fd386', 'heading', 1, ('{"text":"L3.3 Choosing the variable","level":3}')::jsonb, 'a4'),
  ('70228df1-73c4-59f1-85c3-ceba7b389cb6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c203f792-901d-563d-bf20-0e4ef21fd386', 'rich_text', 1, ('{"text":"The target selects the variable. Worked examples in which load is the right answer, and worked examples in which it is the expensive answer."}')::jsonb, 'a5'),
  ('e1ea2c18-1dd4-5095-887c-48e6e773e52e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c203f792-901d-563d-bf20-0e4ef21fd386', 'heading', 1, ('{"text":"L3.4 Why there is no sequence","level":3}')::jsonb, 'a6'),
  ('bed83924-f959-57a3-b88a-32147dc07e3b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c203f792-901d-563d-bf20-0e4ef21fd386', 'rich_text', 1, ('{"text":"What a universal progression ladder would require, and why the evidence does not supply one."}')::jsonb, 'a7'),
  ('ff73db4a-f2b9-5001-9a9f-64b4e853a042', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c203f792-901d-563d-bf20-0e4ef21fd386', 'heading', 1, ('{"text":"L3.5 Dose and diminishing returns","level":3}')::jsonb, 'a8'),
  ('e552c669-47dc-5a0a-8bef-f5e354be63bb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c203f792-901d-563d-bf20-0e4ef21fd386', 'rich_text', 1, ('{"text":"What the volume evidence supports, in whom, for which outcomes — and where the curve stops being knowable."}')::jsonb, 'a9'),
  ('a784e1cb-0334-5af1-a9f1-091dd95ae20b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c203f792-901d-563d-bf20-0e4ef21fd386', 'heading', 1, ('{"text":"L3.6 MED and MRV, honestly","level":3}')::jsonb, 'b0'),
  ('a5e55929-2ba8-5170-a59c-f94b6db06493', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c203f792-901d-563d-bf20-0e4ef21fd386', 'rich_text', 1, ('{"text":"Useful for talking about a real trade-off; not individual constants a coach can discover. The G3 sentence for each."}')::jsonb, 'b1'),
  ('dae507bf-dc28-58f1-a4b4-d4d0b85d453e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c203f792-901d-563d-bf20-0e4ef21fd386', 'heading', 1, ('{"text":"L3.7 Sessions that are not supposed to overload","level":3}')::jsonb, 'b2'),
  ('11db9f20-e952-50dd-b4e3-643e070425fa', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c203f792-901d-563d-bf20-0e4ef21fd386', 'rich_text', 1, ('{"text":"Maintenance, technical practice, deliberate low-load exposure, and the coaching confidence to run them."}')::jsonb, 'b3'),
  ('ad9e9c82-381a-5d8e-ad28-1d10eea29421', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '43ae203b-6459-5783-9d18-2903e1e79484', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D101-03 — Overload Is Multi-Variable","body":"Progressive overload means progressively appropriate training demand relative to current capacity and intended adaptation. It is not synonymous with adding external weight. — Teaching boundary: Rejecting load-only progression is not rejecting load. Load remains one of the most reliable and most easily coached progression variables. The doctrine forbids the reduction, not the tool. — Evidence class: A"}')::jsonb, 'a0'),
  ('542f165b-fd2e-5242-a5fc-34e9234c4184', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '43ae203b-6459-5783-9d18-2903e1e79484', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D101-04 — Progression Must Serve the Target","body":"Load, volume, frequency, density, range, velocity or intent, complexity, specificity, or exposure distribution may progress. The variable selected must match the athlete and the intended adaptation. — Teaching boundary: \"It depends\" is not the answer. The coach must name the variable, name the target it serves, and name what would make them choose differently. A progression decision without a stated target is not individualization; it is improvisation. — Evidence class: B"}')::jsonb, 'a1'),
  ('f10b04fe-02e1-52fb-93d7-c42ee780cc09', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '43ae203b-6459-5783-9d18-2903e1e79484', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D101-12 — Dose Is Outcome- and Context-Specific","body":"More training is not automatically better. Effective dose balances adaptation opportunity against fatigue, adherence, schedule, and recoverability. — Teaching boundary: Rejecting \"more is better\" is not adopting \"less is better.\" Dose is a judgment about opportunity and cost, made against a target — and a coach who systematically under-doses because dosing feels risky has made the opposite error with the same root. — Evidence class: A"}')::jsonb, 'a2'),
  ('1c82e3fb-9469-50ce-bbcc-71011d0ba988', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '43ae203b-6459-5783-9d18-2903e1e79484', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D101-01 — Principles Are Decision Frameworks","body":"Training principles guide reasoning. They are not universal algorithms and not rigid biological laws. — Teaching boundary: \"Conditional\" does not mean \"optional\" or \"anything goes.\" A principle that is conditional still constrains: it tells the coach what to look at and what would count as evidence. A coach who uses conditionality as a licence to do whatever they prefer has misunderstood the doctrine more badly than one who treats it as a law. — Evidence class: A/B"}')::jsonb, 'a3'),
  ('12046a21-f19c-56bc-8de7-c712a3cc4d96', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '43ae203b-6459-5783-9d18-2903e1e79484', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A / Known","body":"Resistance-training variables influence strength and hypertrophy responses — Basis: EP101-21, EP101-22; EP101-21; EP101-22"}')::jsonb, 'a4'),
  ('cebac8b5-b6b6-5353-9fd2-a833fc68584a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '43ae203b-6459-5783-9d18-2903e1e79484', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A / Known","body":"Volume has a dose-response relationship with hypertrophy within the bounds of the evidence base — Basis: EP101-21, EP101-22, EP101-29; EP101-21; EP101-22; EP101-29"}')::jsonb, 'a5'),
  ('a33311c0-49ed-5bde-940a-3e0c05d29b3c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '43ae203b-6459-5783-9d18-2903e1e79484', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A / Known","body":"Demand can be changed through load, volume, frequency, density, ROM, contraction emphasis, velocity/intent, complexity, technical demand, and exposure distribution — Basis: EP101-05, EP101-21, EP101-22; EP101-05; EP101-21; EP101-22"}')::jsonb, 'a6'),
  ('aac99d30-d442-5e59-8820-a0f7f090ca14', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '43ae203b-6459-5783-9d18-2903e1e79484', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B / Probable","body":"Frequency can facilitate distribution and may support strength gains; its independent effect is often entangled with volume, training status, and task practice — Basis: EP101-21, EP101-29; EP101-21; EP101-29"}')::jsonb, 'a7'),
  ('cb349380-fd89-51ec-b01b-ef7aacda2d8e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '43ae203b-6459-5783-9d18-2903e1e79484', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D / Applied inference","body":"A coach may progress load, volume, complexity, velocity, density, range, or specificity when the change matches target and readiness — Basis: EP101-05, EP101-07; EP101-05; EP101-07"}')::jsonb, 'a8'),
  ('4459904e-1859-5c37-9d52-f2a47f298099', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '43ae203b-6459-5783-9d18-2903e1e79484', 'callout', 2, ('{"tone":"info","title":"Evidence — Class F / Known against the claim","body":"No evidence supports one universal progression sequence — Basis: EP101-05, EP101-07; EP101-05; EP101-07"}')::jsonb, 'a9'),
  ('0db702e1-dd26-5e0a-bca4-3d6290171b77', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '43ae203b-6459-5783-9d18-2903e1e79484', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B / Probable","body":"Lower doses can improve performance, especially in novices or when maintaining a quality — Basis: EP101-04, EP101-21; EP101-04; EP101-21"}')::jsonb, 'b0'),
  ('723fe734-3afa-5614-8b65-0d290dc389bd', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '43ae203b-6459-5783-9d18-2903e1e79484', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A/B / Known-Probable","body":"Diminishing returns are likely as dose rises; the exact curve differs by outcome and design — Basis: EP101-21, EP101-29; EP101-21; EP101-29"}')::jsonb, 'b1'),
  ('9ffbac22-1e5a-5b50-b5ed-552b522018db', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '43ae203b-6459-5783-9d18-2903e1e79484', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D / Applied inference","body":"\"Minimum effective dose\" and \"maximum recoverable volume\" as communication heuristics — Basis: EP101-04, EP101-05; EP101-04; EP101-05"}')::jsonb, 'b2'),
  ('8f237e68-7fdc-588f-9f5d-597c335d8907', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '43ae203b-6459-5783-9d18-2903e1e79484', 'callout', 2, ('{"tone":"info","title":"Evidence — Class F / Unknown","body":"Exact individualized dose thresholds discoverable without repeated valid measurement — Basis: EP101-04, EP101-05; EP101-04; EP101-05"}')::jsonb, 'b3'),
  ('dca22af8-4ad0-5be9-af37-34f6a6e61beb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '43ae203b-6459-5783-9d18-2903e1e79484', 'callout', 2, ('{"tone":"info","title":"Evidence — Class F / Known against claim","body":"\"Progressive overload means add weight every session\" — Basis: EP101-05, EP101-21; EP101-05; EP101-21"}')::jsonb, 'b4'),
  ('a681b1d1-9539-5ae9-a311-96e76e1223fc', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '43ae203b-6459-5783-9d18-2903e1e79484', 'callout', 2, ('{"tone":"info","title":"Evidence — Class F / Probable against claim — maintenance, technical practice, recovery, and strategic low-load expo…","body":"Every session must create overload — Basis: EP101-05; EP101-05"}')::jsonb, 'b5'),
  ('4ee8caa9-e53d-5362-8c0b-fa31626e0a82', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '43ae203b-6459-5783-9d18-2903e1e79484', 'callout', 2, ('{"tone":"success","title":"G3 Applied Standard AS-101-03 — Progress the Variable That Solves the Problem","body":"Do not default to load progression when another variable better serves the target."}')::jsonb, 'b6'),
  ('a2d3417d-3013-5011-a946-9b15e9ce1bc6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '43ae203b-6459-5783-9d18-2903e1e79484', 'callout', 2, ('{"tone":"success","title":"G3 Applied Standard AS-101-01 — Define the Target Before the Method","body":"Name the desired performance quality or outcome before selecting exercises or technology. — Enforcement: every exposure object requires target_quality and demand (§21.4)."}')::jsonb, 'b7'),
  ('cefeca76-0e7d-5006-81e1-8f8b48abcccd', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '43ae203b-6459-5783-9d18-2903e1e79484', 'callout', 2, ('{"tone":"success","title":"G3 Applied Standard AS-101-05 — Preserve Program Stability Long Enough to Coach and Evaluate","body":"Do not rotate exercises solely to create novelty. Change when demand, response, constraints, or practical utility justify it."}')::jsonb, 'b8'),
  ('cd1b157f-c98c-5dea-8202-f431244cbd16', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '43ae203b-6459-5783-9d18-2903e1e79484', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"weekly volume (CJ-01) · frequency (CJ-02) · intensity (CJ-03) · minimum effective dose (CJ-05) · maximum recoverable volume (CJ-06) · exercise order (CJ-09) · progression sequence (CJ-19)."}')::jsonb, 'b9'),
  ('ec7ef346-52da-5e8a-9634-eaec9baacdba', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '43ae203b-6459-5783-9d18-2903e1e79484', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Progressive overload read as added weight (CA-06) · more is better (CA-03) · heavier is always better (CA-04) · every session must overload (CA-05) · training to failure treated as required (CA-20) · publishing a weekly set target · treating MED or MRV as a measurable constant · progressing the variable the coach is most comfortable coaching."}')::jsonb, 'c0'),
  ('5d6673fc-1c72-5393-bbba-7e7a1d93fbba', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '43ae203b-6459-5783-9d18-2903e1e79484', 'callout', 2, ('{"tone":"warning","title":"Population-transfer disclosure (AS-101-16)","body":"the dose-response and resistance-training-variable evidence is drawn from healthy adults, frequently male or mixed samples. Exact set, frequency, or progression claims may not be transferred to youth without adaptation (§18.1, §18.3). The most recent dose-response meta-regression is flagged for downstream risk-of-bias review before any precise educational claim rests on it (§20.1)."}')::jsonb, 'c1'),
  ('22fe6c94-dfa3-5dd4-8802-a1e3ea0c5d65', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '8e450e09-b442-5052-b1ae-15d95cc9d197', 'rich_text', 1, ('{"text":"Applied to G3 progression records. From this module on, every progression entered in NovaKore names the variable and the target it serves — the constraint is enforced in the data layer (§21.4)."}')::jsonb, 'a0'),
  ('754d9a54-0068-54a2-a606-2c00f977fa4c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '8e450e09-b442-5052-b1ae-15d95cc9d197', 'scenario', 1, (('{"intro":"\"Progressive Overload Means More Weight\". Marcus, 16, has been in the G3 program for seven months. His main lift has not moved in five weeks. His technique degrades noticeably in the last two reps of every working set, he plays a fall sport with four practices a week, and he reports sleeping about six hours on school nights. His previous coach''s rule was to add five pounds every session, and Marcus asks why that has stopped happening.","steps":[{"id":"cdc68b4b-c2ca-5827-8c3d-31d65f38db1c","situation":"Situation"},{"id":"050533a1-34a0-5558-b3c2-892571bed536","situation":"Decision"},{"id":"4932f14d-05bf-5325-a074-f9c08e7d8514","situation":"Defense"},{"id":"e496a086-a897-5dc3-b43a-754dd249f7a8","situation":"Discussion"}],"debrief":"Decision required: What progresses, what does not, and what do you tell Marcus?\n\nFailure modes: Adding load anyway · publishing a replacement rule · declaring the athlete a nonresponder (CA-28) · progressing the variable the coach prefers to coach rather than the one that serves the target · never progressing anything and calling it caution · omitting sport load and sleep from the analysis.\n\nDefensible variation: A coach who progresses volum'
insert into public.lesson_versions (id, organization_id, lesson_id, course_id, version_number, title, required, estimated_minutes, blocks, published_by) values
  ('221fc036-3e39-5635-aa3a-1a8f6007a3e6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c437a27b-32c8-54a9-9aa9-4a78ac043f65', 'b17cac49-2d2b-59c4-bc80-5de456998e75', 1, 'Overview & objectives', true, 8, (('[{"id":"1d67cb76-58e8-51a3-a42d-480a2821a59c","type":"quote","schemaVersion":1,"data":{"text":"Most coaching arguments are definitional arguments that nobody has noticed are definitional. This module removes four of them before they can cost an athlete anything."},"position":"a0"},{"id":"7ba10c15-e8ea-5af7-b684-31d87f6b5eba","type":"rich_text","schemaVersion":1,"data":{"text":"To establish what athletic performance is, what physical preparation can and cannot do, and what the performance coach is actually responsible for — so that every later decision has a defined subject."},"position":"a1"},{"id":"abb0c036-6093-5643-8fbd-b3b39b0a49e4","type":"checklist","schemaVersion":1,"data":{"items":[{"id":"56caebd9-a0bf-5448-8e8e-e0d4f1e607b7","text":"M1.1 Define athletic performance as multifactorial, and name its contributors."},{"id":"31ca0f7a-e391-526e-bdec-00b6f1c6c3ca","text":"M1.2 Distinguish physical capacity, sport skill, and competitive performance."},{"id":"afd0b2ae-54a3-57db-a652-a13b4703902b","text":"M1.3 Define physical preparation as an applied umbrella term rather than a fixed scientific construct."},{"id":"f2a52b6f-adc6-5f8c-97d1-90c0738af0c5","text":"M1.4 State what the GPP'
