  ('f8c940b7-0926-5f85-a700-aca394c4699c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'G3-101 · M2 Assessment — Adaptation: What Training Actually Changes', 'manual_review', 'draft', ('{"schemaVersion":1,"passingPercent":80,"cooldownMinutes":0,"scorePolicy":"highest"}')::jsonb),
  ('998445f3-e273-5d2e-9b8b-b22c4e1a2aa0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'G3-101 · M3 Assessment — Overload, Progression & Dose', 'manual_review', 'draft', ('{"schemaVersion":1,"passingPercent":80,"cooldownMinutes":0,"scorePolicy":"highest"}')::jsonb),
  ('0cb7bbd5-7be7-5ebc-a46c-a28bfc57f22a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'G3-101 · M4 Assessment — Specificity & Transfer', 'manual_review', 'draft', ('{"schemaVersion":1,"passingPercent":80,"cooldownMinutes":0,"scorePolicy":"highest"}')::jsonb),
