insert into public.content_blocks (id, organization_id, lesson_id, block_type, schema_version, data, position) values
  ('7fbb2e42-8e3a-5e6a-bfa1-c4b506acba3c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '513ecb1c-3fd4-5071-a89d-4921afe074de', 'quote', 1, ('{"text":"Needs analysis is not a form. It is the reason your program looks the way it does."}')::jsonb, 'a0'),
  ('c72df2d9-4c87-542f-9f5f-a2cc419bf7eb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '513ecb1c-3fd4-5071-a89d-4921afe074de', 'checklist', 1, ('{"items":[{"id":"afbb71b9-f31c-57bc-b7ae-0f958add6c64","text":"M1.1 State the purpose of needs analysis in decision terms"},{"id":"6d9cc041-0b95-520c-b2f6-c953da0213af","text":"M1.2 Apply the decision test to any proposed assessment item"},{"id":"ff006ab8-b778-52e2-8986-462878993cfe","text":"M1.3 Name the ten decision categories"},{"id":"8917a3f5-7fb6-5dce-b7cb-a30fd26192cb","text":"M1.4 Describe the costs of undecidable data"},{"id":"8193ab3b-3c03-52a8-bd17-6c2cfb51bde4","text":"M1.5 Reproduce the decision model from memory"},{"id":"6cff92db-c69d-551e-b2d0-09f7723f794c","text":"M1.6 State the evidence standing of the model"}]}')::jsonb, 'a1'),
  ('3e8d4e36-03cd-5363-883d-1795f1e5fce3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '513ecb1c-3fd4-5071-a89d-4921afe074de', 'lesson_reference', 1, ('{"courseId":"b17cac49-2d2b-59c4-bc80-5de456998e75","lessonId":"460effc6-93c3-5f5f-8336-fdae680089d1","label":"Recall — the G3 reasoning system (G3 101, Module 12)","note":"Evidence classes, certainty language, and the three-layer discipline are governed by G3 101."}')::jsonb, 'a2'),
  ('8fc46f4d-aafd-5b35-a743-0ffad0605b8e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '81e0bab6-4baa-5a42-93cb-7c47b740ac4f', 'heading', 1, ('{"text":"L1.1 The purpose problem","level":3}')::jsonb, 'a0'),
  ('4bb3d003-34f9-50cb-b7a8-5cd2af5c3330', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '81e0bab6-4baa-5a42-93cb-7c47b740ac4f', 'rich_text', 1, ('{"text":"Most needs analysis in the field is descriptive: it produces a picture of the athlete. G3 requires it to be *decisional*: it produces a change in what the coach does. The difference is not academic. A descriptive assessment ends in a report; a decisional assessment ends in a program that would have been different without it."}')::jsonb, 'a1'),
  ('1985637d-7703-50b0-8f28-8a2d9c5754c0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '81e0bab6-4baa-5a42-93cb-7c47b740ac4f', 'heading', 1, ('{"text":"L1.2 The ten decision categories","level":3}')::jsonb, 'a2'),
  ('5404d4bc-698e-5187-afd8-0d6466dc805b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '81e0bab6-4baa-5a42-93cb-7c47b740ac4f', 'rich_text', 1, ('{"text":"Assessment information earns its place when it can meaningfully influence: exercise selection · training priority · load · volume · progression · regression · recovery · readiness modification · return-to-performance decisions · program evaluation. These ten categories are the complete list used across G3 102. If a proposed item cannot be connected to at least one, it does not enter the battery."}')::jsonb, 'a3'),
  ('e890d1e8-7c65-5ae5-821f-eee6b7f8ee7d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '81e0bab6-4baa-5a42-93cb-7c47b740ac4f', 'heading', 1, ('{"text":"L1.3 The cost of unused data","level":3}')::jsonb, 'a4'),
  ('f8151fe5-3186-5a80-aa82-36c252ec9167', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '81e0bab6-4baa-5a42-93cb-7c47b740ac4f', 'rich_text', 1, ('{"text":"More data is not free. It costs athlete time and goodwill, coach attention, and — most damagingly — it creates false confidence. A number that was never going to change anything still feels like knowledge. Lean assessment is not a shortcut; it is a way of protecting the quality of the decisions that remain."}')::jsonb, 'a5'),
  ('3588664a-9540-5a04-a1b8-7b58a2f1f6f0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '81e0bab6-4baa-5a42-93cb-7c47b740ac4f', 'heading', 1, ('{"text":"L1.4 Why the evidence supports this indirectly","level":3}')::jsonb, 'a6'),
  ('f61329b5-2b7d-5885-be3b-72f86180b33c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '81e0bab6-4baa-5a42-93cb-7c47b740ac4f', 'rich_text', 1, ('{"text":"Coaches should know the shape of the support. There are very few direct trials of complete needs-analysis frameworks. What exists is strong monitoring and testing literature showing that information has value only when it can be interpreted reliably and used to change a decision. G3 reasons *from* that to the needs-analysis position. That reasoning step is legitimate, and it is a step."}')::jsonb, 'a7'),
  ('5a105d51-20ae-57d5-8c85-cdac929a3917', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '81e0bab6-4baa-5a42-93cb-7c47b740ac4f', 'heading', 1, ('{"text":"L1.5 The G3 decision model, introduced","level":3}')::jsonb, 'a8'),
  ('a49bb022-2219-572b-8368-1148b5ac2898', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '81e0bab6-4baa-5a42-93cb-7c47b740ac4f', 'rich_text', 1, ('{"text":"Walk DEMAND → PROFILE → GAP → PRIORITY → PRESCRIPTION → RESPONSE → ADJUST end to end using one worked athlete. Introduce each stage''s question and artifact. State plainly: this model is G3''s organizing structure, classified as applied coaching inference, not a validated instrument."}')::jsonb, 'a9'),
  ('795307f9-6aee-5d37-b23e-27dd304bd70b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '81e0bab6-4baa-5a42-93cb-7c47b740ac4f', 'heading', 1, ('{"text":"L1.6 What \"defensible\" means at G3","level":3}')::jsonb, 'b0'),
  ('3a376243-62b1-5fb0-b936-ab57652bdd3b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '81e0bab6-4baa-5a42-93cb-7c47b740ac4f', 'rich_text', 1, ('{"text":"A defensible decision is one the coach can explain in terms of demand, profile, gap, and cost, and one for which the coach can name the evidence that would change it. Defensible does not mean provably correct. Two coaches can defend different answers. Neither can defend no answer."}')::jsonb, 'b1'),
  ('39f87d69-47e0-597a-9d89-ea771ce59eb3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ba71f4a4-a59d-50b8-b823-2b0bffa0c12e', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D1 — Needs analysis must change decisions","body":"Assessment exists to improve coaching decisions. A test, metric, questionnaire, or observation earns its place when it can meaningfully influence exercise selection, training priority, load, volume, progression, regression, recovery, readiness modification, return-to-performance decisions, or program evaluation. G3 favors decision-useful information over maximal data collection. — Teaching boundary: Do not teach that a specific battery size is correct. Teach that unused data has a cost that must be earned. — Evidence class: B"}')::jsonb, 'a0'),
  ('cad00e81-11e5-5096-939b-2d424388d0be', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ba71f4a4-a59d-50b8-b823-2b0bffa0c12e', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B — Supported Practice","body":"Information has value when it can be interpreted reliably and used to change a decision — Basis: Monitoring/testing literature; indirect to needs analysis [cite:4, cite:20, cite:48]"}')::jsonb, 'a1'),
  ('4dc5033e-c1f4-5a72-9bb9-4fd996c9df5a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ba71f4a4-a59d-50b8-b823-2b0bffa0c12e', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B — Supported Practice (a statement about the evidence base)","body":"Complete needs-analysis frameworks lack direct validation — Basis: [EP §1.17, §7, cite:48, cite:50]"}')::jsonb, 'a2'),
  ('c24505b4-0d2d-571c-bb69-1e623d591d00', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ba71f4a4-a59d-50b8-b823-2b0bffa0c12e', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D — Applied Coaching Inference","body":"The G3 decision model as an integrated whole — Basis: G3 construction from adjacent evidence"}')::jsonb, 'a3'),
  ('27c5d346-599d-533b-a10f-15ab96431186', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ba71f4a4-a59d-50b8-b823-2b0bffa0c12e', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D — Applied Coaching Inference / G3 Applied Standard","body":"The ten decision categories as a complete list — Basis: G3 operational definition"}')::jsonb, 'a4'),
  ('fb495fc9-0f96-5794-9c1d-eec82c2c0615', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ba71f4a4-a59d-50b8-b823-2b0bffa0c12e', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"how lean a given battery should be for a given athlete or group. G3 sets no minimum or maximum item count."}')::jsonb, 'a5'),
  ('2394df41-56a6-5243-a620-f861b59f1a3d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ba71f4a4-a59d-50b8-b823-2b0bffa0c12e', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Testing because the test exists · Confusing thoroughness with rigor · No plan for interpreting change · Presenting a needs analysis as a diagnosis · Treating the model as a form completed after the program"}')::jsonb, 'a6'),
  ('2cdee424-e318-59e0-a709-538933755fb9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '3c4e2ce1-9dae-523d-8e5e-ab05ec4ac39f', 'rich_text', 1, ('{"text":"Before the next assessment a coach runs, they write the decision test beside every item on the sheet. Any item without an answer is struck or justified in writing. In G3 Youth Strength & Conditioning, this typically reduces the battery substantially — and the reduction is the point, not a compromise."}')::jsonb, 'a0'),
  ('608bd634-9e75-59b3-9626-7be56e2ab0d3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '3c4e2ce1-9dae-523d-8e5e-ab05ec4ac39f', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"None for M1. Evidence carries forward into **PS-1**."}')::jsonb, 'a1'),
  ('bada54bd-03cf-5c1a-9ca1-679b1b978715', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '16764391-abfb-5ad9-b7da-9350b4a9219f', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('c6d8a57a-6494-53a1-8f8d-83426970721f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '16764391-abfb-5ad9-b7da-9350b4a9219f', 'assessment_reference', 1, ('{"assessmentId":"a083bd6a-770a-5984-b7c4-dea633ea52b4","title":"G3-102 · M1 Assessment — What Needs Analysis Is For"}')::jsonb, 'a1'),
  ('2d686b30-fe39-55c7-ac43-f43abdb11f6d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '82b072a6-658f-5790-a87e-5cfaf0053e1a', 'quote', 1, ('{"text":"The average tells you what the sport usually asks. The peak tells you what it asks when it matters."}')::jsonb, 'a0'),
  ('c8c2e7da-d35f-5bf7-832e-ee7f58fb50cf', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '82b072a6-658f-5790-a87e-5cfaf0053e1a', 'checklist', 1, ('{"items":[{"id":"f90e5f8d-1485-50ed-8298-eb878d8bf9fc","text":"M2.1 Build a demand profile across twelve categories"},{"id":"fd9ea77f-d2f4-5b07-8248-2ac90e54f01c","text":"M2.2 Distinguish average from peak demands"},{"id":"8b3d3d43-a73d-5d4c-8713-5b24d5cbc24a","text":"M2.3 Explain rolling averages vs fixed epochs"},{"id":"f6857daf-31f6-5409-b66c-5a08b70e41e2","text":"M2.4 Analyze positional differences"},{"id":"52eca4bf-f606-591c-a172-14d5b6f14969","text":"M2.5 Account for density and season structure"},{"id":"96890f54-e597-58f7-9e34-0e9859d75c50","text":"M2.6 Produce a defensible profile without tracking technology"}]}')::jsonb, 'a1'),
  ('09fe4766-6cea-5c0b-b2f0-5f55f335a58c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1fb71252-8eb1-590e-88da-0ffef40e8ee0', 'heading', 1, ('{"text":"L2.1 The twelve demand categories","level":3}')::jsonb, 'a0'),
  ('677df40f-2020-57ea-bdca-d99f20c349fb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1fb71252-8eb1-590e-88da-0ffef40e8ee0', 'rich_text', 1, ('{"text":"Movement · force · velocity · power · energetic · repeated-effort · positional · competition density · practice density · peak passages · injury exposure · season structure. Each is defined, with a volleyball and a field-sport example. The coach is taught to fill all twelve but to *rank* them — a profile in which everything matters equally has not been analyzed."}')::jsonb, 'a1'),
  ('a6c7671f-794b-593e-aee5-9fc5c2b70cf0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1fb71252-8eb1-590e-88da-0ffef40e8ee0', 'heading', 1, ('{"text":"L2.2 Averages conceal peaks","level":3}')::jsonb, 'a2'),
  ('4ac4cfa6-0a19-56a6-9fbb-3076fcb21988', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1fb71252-8eb1-590e-88da-0ffef40e8ee0', 'rich_text', 1, ('{"text":"Team-sport match analysis shows that peak or worst-case passages can be substantially more demanding than average values. Preparing an athlete for the average leaves them underprepared for the passage that decides matches and, plausibly, for the exposure that carries the most injury risk. The evidence here is strongest for locomotor demands in professional team sport; the extension to complete program design is an interpretive step."}')::jsonb, 'a3'),
  ('33e7a04f-bcc1-524c-b921-776981af2e9e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1fb71252-8eb1-590e-88da-0ffef40e8ee0', 'heading', 1, ('{"text":"L2.3 How peak demands are estimated","level":3}')::jsonb, 'a4'),
  ('d13dc552-7390-502e-8be3-b0f36a7ce65d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1fb71252-8eb1-590e-88da-0ffef40e8ee0', 'rich_text', 1, ('{"text":"Rolling averages generally estimate worst-case demands better than fixed discrete epochs, because a fixed window can split the most demanding passage across two boxes. Coaches do not need to compute this to benefit from understanding it — the lesson is that *how you slice the data changes what the data says*, and that the same caution applies to any peak metric a vendor supplies."}')::jsonb, 'a5'),
  ('d2b71147-e10b-5044-b324-2cc4609823a2', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1fb71252-8eb1-590e-88da-0ffef40e8ee0', 'heading', 1, ('{"text":"L2.4 Position and role","level":3}')::jsonb, 'a6'),
  ('aae89935-cd3f-54cc-b18c-f05fbfd3f637', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1fb71252-8eb1-590e-88da-0ffef40e8ee0', 'rich_text', 1, ('{"text":"Within one sport, demands differ by position and by role within position. A libero, an outside hitter, and a middle blocker do not share a demand profile. G3 builds demand profiles at the position-group level as standard, and at the individual level when role is unusual."}')::jsonb, 'a7'),
  ('fe48fac2-1946-5d33-944e-5903692d8a0c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1fb71252-8eb1-590e-88da-0ffef40e8ee0', 'heading', 1, ('{"text":"L2.5 Density and season structure","level":3}')::jsonb, 'a8'),
  ('45ad0561-a470-5b8c-93f2-bd745ccf1531', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1fb71252-8eb1-590e-88da-0ffef40e8ee0', 'rich_text', 1, ('{"text":"Competition density, practice density, travel, academic calendar, and the shape of the season determine how much training the athlete can actually absorb. A demand profile that ignores the schedule produces programs that cannot be delivered."}')::jsonb, 'a9'),
  ('5212a5e7-7068-586a-92d4-35cf36dd3212', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1fb71252-8eb1-590e-88da-0ffef40e8ee0', 'heading', 1, ('{"text":"L2.6 Demand analysis without instruments","level":3}')::jsonb, 'b0'),
  ('fedf8c08-a0f1-5a54-ad0e-8f4febb873fb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1fb71252-8eb1-590e-88da-0ffef40e8ee0', 'rich_text', 1, ('{"text":"Most G3 environments have no GPS and no force plates in competition. Demand analysis is still required. It is built from competition observation, position knowledge, the practice and competition calendar, and structured conversation with the sport coach. Every line is labeled **measured**, **estimated**, or **assumed**. Labeling honestly is the standard; pretending to precision is the failure."}')::jsonb, 'b1'),
  ('88a21e12-425f-508b-9ce3-f78e8764bfc2', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1a99df78-e60e-56b6-ad37-ca22746ade6b', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D2 — Sport demand is more than the average","body":"Sport-demand analysis must consider movement, force, velocity, power, energetic, repeated-effort, and positional demands, competition and practice density, peak or worst-case passages, injury exposure, and season structure. Average match demands can conceal the highest-performance requirements. — Teaching boundary: Peak-demand evidence is largely locomotor and largely professional. Teach peak-demand thinking without claiming measurement precision the environment does not have. — Evidence class: B"}')::jsonb, 'a0'),
  ('2471d12a-f980-54b1-96d7-2216efa6c2b0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1a99df78-e60e-56b6-ad37-ca22746ade6b', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B — Supported Practice, high confidence","body":"Match averages can underestimate peak competition demands — Basis: Team-sport match analysis [cite:18]"}')::jsonb, 'a1'),
  ('60372ee6-f7a5-5e98-9a2b-4a11c9f5bc8e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1a99df78-e60e-56b6-ad37-ca22746ade6b', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B — Supported Practice, high confidence","body":"Rolling averages usually estimate worst-case demands better than fixed epochs — Basis: [cite:22]"}')::jsonb, 'a2'),
  ('ee20bc6e-989f-5b52-bc85-97cd76522f50', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1a99df78-e60e-56b6-ad37-ca22746ade6b', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D — Applied Coaching Inference","body":"Peak-demand profiles should change program design in scholastic settings — Basis: Extension beyond studied populations"}')::jsonb, 'a3'),
  ('284380fe-4ecb-5b18-b42a-be95ba735b94', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1a99df78-e60e-56b6-ad37-ca22746ade6b', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D / G3 Applied Standard","body":"The twelve-category demand framework — Basis: G3 operational structure"}')::jsonb, 'a4'),
  ('81b1b667-ce1b-54d0-9f17-1eb1d4c6ae36', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1a99df78-e60e-56b6-ad37-ca22746ade6b', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"which three to five demands actually shape a given program. **Evidence caution:** peak-demand literature is largely locomotor and largely professional. Do not present locomotor worst-case findings as complete descriptions of sport demand."}')::jsonb, 'a5'),
  ('75d21482-3d90-5fb5-b879-264f7fef569b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1a99df78-e60e-56b6-ad37-ca22746ade6b', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Programming from a season average · Treating one position''s profile as the sport''s · Assuming unmeasurable means unanalyzable · Adopting professional profiles for scholastic rosters · Building demands from highlight actions"}')::jsonb, 'a6'),
  ('ae175b8a-ef7b-5b58-a5dc-7b88aa89ce1b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7cf80f33-8c8f-501d-9075-b25c35f7128a', 'rich_text', 1, ('{"text":"For G3 Volleyball Development, the demand profile drives: repeated jump exposure planning, the decision to train repeated-effort capacity rather than steady-state conditioning, landing and deceleration exposure as injury-relevant demand, and the recognition that in-season competition density is the binding constraint on development work."}')::jsonb, 'a0'),
  ('21340ebc-40cd-536d-b9ec-299c91647d5c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7cf80f33-8c8f-501d-9075-b25c35f7128a', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"None for M2. Feeds **PS-1** and **PS-3**."}')::jsonb, 'a1'),
  ('b0351503-7d41-5239-801b-8fed4fa398dd', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'bd9634ae-4e64-53d4-9a14-d4225025416e', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('e51418ce-b323-565f-b7d6-ab72d3dc695f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'bd9634ae-4e64-53d4-9a14-d4225025416e', 'assessment_reference', 1, ('{"assessmentId":"28ffb2e7-07e7-5295-9093-bfd3c1d3cae0","title":"G3-102 · M2 Assessment — Analyzing Sport Demands"}')::jsonb, 'a1'),
  ('e9ba5141-9ce2-5a30-8a0f-e3c398e3295a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7c0831d0-6a31-51f5-a9e2-b5fe46aa2dda', 'quote', 1, ('{"text":"The profile is not everything you know about the athlete. It is everything you will actually use."}')::jsonb, 'a0'),
  ('5020d205-83d8-5bba-b382-b0ae2dd0d0ce', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7c0831d0-6a31-51f5-a9e2-b5fe46aa2dda', 'checklist', 1, ('{"items":[{"id":"cfdb5fd7-b692-5be9-ba23-e7511b40912c","text":"M3.1 Construct a profile from six domains"},{"id":"884c1393-bb0a-5e16-9732-1ec545d5929a","text":"M3.2 Apply the decision test to every item"},{"id":"6a3d1828-8a9a-504f-a97a-cd801cc73df0","text":"M3.3 Record measurement conditions"},{"id":"a03f78e9-e3c1-53ba-910d-2e2fe926b3fb","text":"M3.4 Assess movement competency appropriately"},{"id":"c19b426d-1155-51a5-bfcf-e0437c5e1bf9","text":"M3.5 Apply youth readiness criteria"},{"id":"0fc73fe2-dc12-5738-ae26-e719c9f298d2","text":"M3.6 Integrate GPI at the correct stage"},{"id":"17eae11f-b9ca-591c-aa54-a622cc96c66b","text":"M3.7 State reliability limitations"}]}')::jsonb, 'a1'),
  ('2d4ea635-b4cc-570b-81fe-97ae8c552840', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f9580984-11e1-5886-a662-6963dee0f90d', 'heading', 1, ('{"text":"L3.1 The six required domains","level":3}')::jsonb, 'a0'),
  ('301871c2-dd47-5f67-937c-9a98a7b35b9a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f9580984-11e1-5886-a662-6963dee0f90d', 'rich_text', 1, ('{"text":"(i) Training age and history; (ii) availability and injury context; (iii) current schedule — practice, competition, other sport, academic load; (iv) movement competency; (v) validated performance measures, including GPI where applicable; (vi) relevant individual context — growth and maturation for youth, psychological readiness, instructional responsiveness. A profile missing a domain is incomplete regardless of how many test numbers it contains."}')::jsonb, 'a1'),
  ('3d9821d1-761e-588b-b13f-f11e83aac5d4', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f9580984-11e1-5886-a662-6963dee0f90d', 'heading', 1, ('{"text":"L3.2 Training age is not chronological age","level":3}')::jsonb, 'a2'),
  ('75f6ad5a-6196-55f6-92c6-2a5d88e54a77', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f9580984-11e1-5886-a662-6963dee0f90d', 'rich_text', 1, ('{"text":"Training age — how long an athlete has trained deliberately and how well — predicts more programming decisions than birth date. It governs complexity tolerance, rate of progression, expected adaptation potential, and how much of the session can be spent on new skill."}')::jsonb, 'a3'),
  ('f308f78b-f90a-5a46-af37-dc5069752d64', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f9580984-11e1-5886-a662-6963dee0f90d', 'heading', 1, ('{"text":"L3.3 Availability is a programming variable","level":3}')::jsonb, 'a4'),
  ('ae0ce5c2-3543-54b6-a40e-30403cfed915', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f9580984-11e1-5886-a662-6963dee0f90d', 'rich_text', 1, ('{"text":"Injury status, medical restriction, and attendance reality are not context around the program; they are inputs to it. A program the athlete cannot attend is not a better program than one they can."}')::jsonb, 'a5'),
  ('897d9492-358a-553c-a7de-b7f7e4871c35', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f9580984-11e1-5886-a662-6963dee0f90d', 'heading', 1, ('{"text":"L3.4 Movement competency at the depth the decision needs","level":3}')::jsonb, 'a6'),
  ('8be58b29-1d91-5b3a-b639-6bf042617909', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f9580984-11e1-5886-a662-6963dee0f90d', 'rich_text', 1, ('{"text":"Screen to the level of the decisions being made. If the decision is whether an athlete loads a hinge pattern externally, assess the hinge. G3 does not require a comprehensive screening battery to justify a squat progression. Competency assessment continues inside training — the first sets of every session are assessment."}')::jsonb, 'a7'),
  ('9d42b5c6-e25c-52a4-81c0-5d52691c391d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f9580984-11e1-5886-a662-6963dee0f90d', 'heading', 1, ('{"text":"L3.5 Testing conditions and future comparability","level":3}')::jsonb, 'a8'),
  ('85935d4a-fce6-5c1d-844b-8c5a5f3e5d77', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f9580984-11e1-5886-a662-6963dee0f90d', 'rich_text', 1, ('{"text":"Record equipment, surface, footwear, warm-up, time of day, position in the training week, and who administered the test. Without these, a later \"change\" cannot be distinguished from a change in conditions. This is the single most common preventable failure in G3 testing."}')::jsonb, 'a9'),
  ('4ab435dc-163a-5898-890e-593a7f537ee5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f9580984-11e1-5886-a662-6963dee0f90d', 'heading', 1, ('{"text":"L3.6 Reliability, typical error, and practical significance — introduced","level":3}')::jsonb, 'b0'),
  ('cbeea94b-8bb6-58be-a468-893c4ddc35cd', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f9580984-11e1-5886-a662-6963dee0f90d', 'rich_text', 1, ('{"text":"Every measure carries noise. The coach''s obligation is to know roughly how much a given test moves when nothing has changed, and to refuse to act inside that band. Arbitrary cut points — \"a five percent change means something\" — are not well justified across settings and are not used at G3 as universal rules. Full treatment in M4."}')::jsonb, 'b1'),
  ('e1a049fa-fbd7-5970-9292-501fa583fde5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f9580984-11e1-5886-a662-6963dee0f90d', 'heading', 1, ('{"text":"L3.7 Youth readiness","level":3}')::jsonb, 'b2'),
  ('d4f02c15-c694-5cc7-801b-cca814b72549', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f9580984-11e1-5886-a662-6963dee0f90d', 'rich_text', 1, ('{"text":"Readiness for supervised progressive resistance training is determined by ability to follow instruction, psychological readiness, movement competency, maturity, training history, available supervision, and the presence of a progression — not by a chronological age threshold. The safety and efficacy evidence for youth resistance training is strong **and is conditioned on supervision and progression**; the coach states both conditions whenever they make the claim to a parent or administrator."}')::jsonb, 'b3'),
  ('eac2a783-222e-5269-920e-444defee371f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f9580984-11e1-5886-a662-6963dee0f90d', 'heading', 1, ('{"text":"L3.8 GPI in the profile","level":3}')::jsonb, 'b4'),
  ('ef34d269-0b7e-561e-8276-27c151b1841b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f9580984-11e1-5886-a662-6963dee0f90d', 'rich_text', 1, ('{"text":"GPI output enters the profile at Stage 2 as measured information with known limitations. It does not enter at Stage 4. A GPI result is an input to a gap analysis, never an instruction."}')::jsonb, 'b5'),
  ('d7563bb5-632e-5ed7-aafc-3e8c59f15cc8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9c502e81-d88e-5335-a1ef-a648dd6c0ece', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D1 — Needs analysis must change decisions","body":"Assessment exists to improve coaching decisions. A test, metric, questionnaire, or observation earns its place when it can meaningfully influence exercise selection, training priority, load, volume, progression, regression, recovery, readiness modification, return-to-performance decisions, or program evaluation. G3 favors decision-useful information over maximal data collection. — Teaching boundary: Do not teach that a specific battery size is correct. Teach that unused data has a cost that must be earned. — Evidence class: B"}')::jsonb, 'a0'),
  ('de723267-cc2c-5e1e-9d12-6ee19ae14060', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9c502e81-d88e-5335-a1ef-a648dd6c0ece', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D9 — Youth training is readiness-based, not age-myth-based","body":"Supervised progressive resistance training is appropriate for youth. Readiness considers instructional responsiveness, psychological readiness, movement competency, maturity, training history, supervision, and progression. — Teaching boundary: The safety and efficacy claim is conditioned on supervision and progression; state both conditions whenever the claim is made. — Evidence class: A"}')::jsonb, 'a1'),
  ('9357b0ff-b133-57f5-a6d9-4d68d9549844', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9c502e81-d88e-5335-a1ef-a648dd6c0ece', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B — Supported Practice","body":"Assessment should focus on information that changes programming — Basis: [cite:4, cite:20, cite:53]"}')::jsonb, 'a2'),
  ('6d940ab5-51dd-5720-a1c9-c53ce959bcd1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9c502e81-d88e-5335-a1ef-a648dd6c0ece', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A — Established Evidence","body":"Reliability, typical error, and practical significance are required for interpreting change — Basis: [cite:4, cite:14, cite:36]"}')::jsonb, 'a3'),
  ('5f581d08-2ede-5ff4-921d-f8c9e5a50dbb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9c502e81-d88e-5335-a1ef-a648dd6c0ece', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A — Established Evidence","body":"Supervised progressive youth resistance training is safe and effective — Basis: [cite:3, cite:38, cite:53, cite:55, cite:57]"}')::jsonb, 'a4'),
  ('9a06443e-e49c-52f0-be59-da0d955c67c5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9c502e81-d88e-5335-a1ef-a648dd6c0ece', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A — Established Evidence (position/consensus based)","body":"Youth readiness is better judged by maturity, attention, and instructional responsiveness than by fixed age — Basis: [cite:3, cite:38, cite:44, cite:55]"}')::jsonb, 'a5'),
  ('6bbf75ad-fa2f-5b20-8888-2e72050f4927', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9c502e81-d88e-5335-a1ef-a648dd6c0ece', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D / G3 Applied Standard","body":"The six-domain profile structure — Basis: G3 operational structure"}')::jsonb, 'a6'),
  ('763ef27f-4a94-53e8-b41f-7d21866a18eb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9c502e81-d88e-5335-a1ef-a648dd6c0ece', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"screening depth; which performance measures a given athlete needs. **Evidence caution:** some youth guidance derives from position stands and applied synthesis rather than trials alone. This does not weaken the practice recommendation; it does define how the claim should be stated."}')::jsonb, 'a7'),
  ('b2f2f200-9568-5164-aab7-68269b865b3e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9c502e81-d88e-5335-a1ef-a648dd6c0ece', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Profile built from test numbers only · Screening beyond decision need · Extensive youth testing to appear rigorous · Failing to record conditions · Treating GPI as the profile · Age-gating resistance training"}')::jsonb, 'a8'),
  ('b244da19-9d7f-5160-b219-a379c597467e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '479e5c52-f781-590e-98f6-6e0980198105', 'rich_text', 1, ('{"text":"In G3 Youth Strength & Conditioning, the profile is deliberately short: training history, availability, a movement competency screen sufficient to justify the starting progressions, instructional responsiveness, and little else. Performance testing is minimal, because at that stage almost no test result would change the program — the program is competency and progression, and the assessment is the training itself."}')::jsonb, 'a0'),
  ('0b40a509-8e49-5a06-9586-fd52cc007346', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '479e5c52-f781-590e-98f6-6e0980198105', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"Contributes to **PS-1 — Assessment & Profile Sign-Off** (completed at M4). Observed elements from M3: administration of a movement competency screen; accurate, calm explanation of testing purpose to the athlete; correct recording of conditions."}')::jsonb, 'a1'),
  ('cb2b4da4-cecc-5b2b-9ede-29add4638e21', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '33f40943-6319-5ba6-ad18-ed90b84c8db2', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('7deab29a-11a6-5b9c-92a8-2ca37dcace3e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '33f40943-6319-5ba6-ad18-ed90b84c8db2', 'assessment_reference', 1, ('{"assessmentId":"6239c630-0ee2-508a-bf8c-ddbb11d84596","title":"G3-102 · M3 Assessment — Building the Athlete Profile"}')::jsonb, 'a1'),
  ('4d79e767-6e39-5190-a049-fd627f434375', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b89db8e8-44f2-5fbd-8685-3a2114d2f798', 'quote', 1, ('{"text":"The test tells you what the number is. It never tells you what to do."}')::jsonb, 'a0'),
  ('f40bb58d-b314-581f-8065-d7f78c86a18e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b89db8e8-44f2-5fbd-8685-3a2114d2f798', 'checklist', 1, ('{"items":[{"id":"5c2a983b-3eea-54e9-94b3-3990ddad549c","text":"M4.1 Define and use both terms correctly"},{"id":"011c2a70-e70a-5809-bac3-86dc86c7a6ed","text":"M4.2 Apply the reality filter"},{"id":"25d3f932-f47e-58ff-b195-cb316a048ee6","text":"M4.3 Apply the relevance filter"},{"id":"dadc9352-676c-569b-9eaa-37cc54c1de65","text":"M4.4 State the six conditions"},{"id":"64079824-b258-5acf-b793-27c1ff0a25f6","text":"M4.5 Explain why field testing shows association not cause"},{"id":"9e448591-2657-56f1-9f59-497afceaac25","text":"M4.6 Produce a three-list gap statement"},{"id":"e499c364-1a62-59dc-89a3-f6b845a15003","text":"M4.7 Explain limits of normative comparison"}]}')::jsonb, 'a1'),
  ('52e5a253-2cc0-58e2-a011-c372e6308cb3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'da7a3b49-72df-52d7-94aa-d89f473db557', 'heading', 1, ('{"text":"L4.1 Two different objects","level":3}')::jsonb, 'a0'),
  ('21b32e7a-4c94-5117-9f10-f72c25ec1f07', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'da7a3b49-72df-52d7-94aa-d89f473db557', 'rich_text', 1, ('{"text":"A measured deficit is a property of a test result. A probable limiting factor is a property of a coach''s reasoning about an athlete. Conflating them is the most consequential error in applied programming, because it converts a number into an instruction without anyone deciding anything."}')::jsonb, 'a1'),
  ('609ceebc-9008-562a-be29-c51fb2b26114', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'da7a3b49-72df-52d7-94aa-d89f473db557', 'heading', 1, ('{"text":"L4.2 Filter one: is it real?","level":3}')::jsonb, 'a2'),
  ('5cb19427-c66e-557f-9fc6-1aacee47379e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'da7a3b49-72df-52d7-94aa-d89f473db557', 'rich_text', 1, ('{"text":"Compare the difference against typical error, against the athlete''s own baseline behavior, and against the conditions of measurement. A single occasion is weak evidence. A difference inside the noise band is not a finding. Fixed percentage thresholds are not well justified across settings and are not used at G3 as universal rules."}')::jsonb, 'a3'),
  ('868d2fd8-0f05-5de3-b4b4-c1900f266bb9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'da7a3b49-72df-52d7-94aa-d89f473db557', 'heading', 1, ('{"text":"L4.3 Filter two: is it relevant?","level":3}')::jsonb, 'a4'),
  ('3280c083-85c1-5168-9c8a-04bcd9ae509b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'da7a3b49-72df-52d7-94aa-d89f473db557', 'rich_text', 1, ('{"text":"Relevance is judged against the demand profile from M2, the athlete''s position and role, the level of competition, and the current phase. A quality can be genuinely low and genuinely irrelevant to this athlete''s performance this season. Saying so out loud is a coaching skill."}')::jsonb, 'a5'),
  ('41b15997-7ee7-5611-ba60-5a2521933d16', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'da7a3b49-72df-52d7-94aa-d89f473db557', 'heading', 1, ('{"text":"L4.4 The six conditions","level":3}')::jsonb, 'a6'),
  ('1a83ae59-a88e-5ae7-bd7f-9fd446f7ce90', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'da7a3b49-72df-52d7-94aa-d89f473db557', 'rich_text', 1, ('{"text":"A deficit''s claim on priority strengthens when it: matters to the sport or role; is meaningfully below the required level; can be changed; is relevant to current performance; can be addressed at acceptable training cost; and deserves emphasis relative to competing priorities. These are conditions that raise a claim, not a checklist that produces a verdict. **No G3 material converts them into a score.**"}')::jsonb, 'a7'),
  ('2c94fb05-c723-5a63-9bbf-1fe70addd007', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'da7a3b49-72df-52d7-94aa-d89f473db557', 'heading', 1, ('{"text":"L4.5 Why causation is rarely available","level":3}')::jsonb, 'a8'),
  ('113db57c-cd6e-5bdc-9347-39dab9b4423d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'da7a3b49-72df-52d7-94aa-d89f473db557', 'rich_text', 1, ('{"text":"Field tests capture associations. An athlete with a low score and poor performance may have a causal link, a common third cause, or a coincidence. Proving that one measured quality is the key causal limiter of sport performance is rarely possible from normal field data. G3''s language reflects this permanently: **probable** limiting factor, and never \"confirmed.\""}')::jsonb, 'a9'),
  ('13b05cc6-848f-52d8-88c0-cc3d89003881', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'da7a3b49-72df-52d7-94aa-d89f473db557', 'heading', 1, ('{"text":"L4.6 Normative comparison and its limits","level":3}')::jsonb, 'b0'),
  ('9d32cb16-af78-50c4-beaa-5db63642ae0b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'da7a3b49-72df-52d7-94aa-d89f473db557', 'rich_text', 1, ('{"text":"Norm tables describe populations, often not this population. A deficit against a norm is not automatically a deficit against this athlete''s requirement. The demand profile, not the table, defines the required level wherever a defensible requirement can be stated."}')::jsonb, 'b1'),
  ('b1e2cff4-68e6-5075-b32d-645159eb5981', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'da7a3b49-72df-52d7-94aa-d89f473db557', 'heading', 1, ('{"text":"L4.7 Writing the Gap Statement","level":3}')::jsonb, 'b2'),
  ('9017cb64-6c7d-5d76-a87f-404767168498', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'da7a3b49-72df-52d7-94aa-d89f473db557', 'rich_text', 1, ('{"text":"Three lists, plainly written: real and relevant; real but low relevance; within noise. The second and third lists are the ones that prove analysis happened — a coach who only produces the first list has not filtered anything."}')::jsonb, 'b3'),
  ('60786f96-2c92-50d1-b1de-5b8eb9c2e83b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '159e4ca5-e36b-5c5c-b7ec-0f79c1915c17', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D3 — A deficit is not automatically a limiting factor","body":"G3 distinguishes a measured deficit from a probable performance limiting factor. A deficit''s claim strengthens when it matters to the sport or role, is meaningfully below the required level, can be changed, is relevant to current performance, can be addressed at acceptable cost, and deserves emphasis relative to competing priorities. Testing identifies information; coaching determines significance. — Teaching boundary: No G3 material may state that a test identifies a limiting factor. The term ''confirmed limiting factor'' is prohibited. — Evidence class: B/D"}')::jsonb, 'a0'),
  ('0ef08f51-63b1-5a06-a873-09647196b1c3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '159e4ca5-e36b-5c5c-b7ec-0f79c1915c17', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B — Supported Practice","body":"A measured weakness is not automatically a causal limiting factor — Basis: [cite:4, cite:20, cite:27]"}')::jsonb, 'a1'),
  ('7e34ee24-61c2-5ee6-911d-56be6d24ef3b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '159e4ca5-e36b-5c5c-b7ec-0f79c1915c17', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A — Established Evidence","body":"Reliability, typical error, and practical significance govern interpretation of change — Basis: [cite:4, cite:14, cite:36]"}')::jsonb, 'a2'),
  ('5dd6ec8f-7ddf-5047-a103-f0ccd1dcdbd8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '159e4ca5-e36b-5c5c-b7ec-0f79c1915c17', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B — Supported Practice","body":"Arbitrary fixed-percentage change thresholds are not well justified across settings — Basis: [cite:4, cite:36]"}')::jsonb, 'a3'),
  ('9744f381-ed02-52c8-8914-f56bebc95184', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '159e4ca5-e36b-5c5c-b7ec-0f79c1915c17', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D — Applied Coaching Inference","body":"Identification of a specific limiting factor in an individual athlete — Basis: Limited direct causal trials in field settings [cite:27]"}')::jsonb, 'a4'),
  ('11aadf01-554e-5a9b-a5d1-3938f6f85d52', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '159e4ca5-e36b-5c5c-b7ec-0f79c1915c17', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D / G3 Applied Standard","body":"The two-filter gap method — Basis: G3 operational structure"}')::jsonb, 'a5'),
  ('7119c808-8dde-5b28-b97f-42197e129cb5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '159e4ca5-e36b-5c5c-b7ec-0f79c1915c17', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"which probable limiting factors to carry forward, and how confidently. **Research gap acknowledged to learners:** better evidence on how coaches should identify true limiting factors rather than measured deficits is an open question, and G3 states this in the lesson rather than concealing it."}')::jsonb, 'a6'),
  ('6b172107-d073-597d-8398-cf767b5a9205', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '159e4ca5-e36b-5c5c-b7ec-0f79c1915c17', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Reading the lowest bar as the target · Acting inside the noise band · Comparing to inapplicable norms · Retesting until a number moves · Causal language · A gap statement with only one list"}')::jsonb, 'a7'),
  ('3a2c6230-1f70-526b-80a7-d30748103e7b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '34e877b0-d5db-5831-a51f-df3d14f5e9ce', 'rich_text', 1, ('{"text":"Applied directly to GPI interpretation. A GPI profile with one conspicuously low sub-score produces a *candidate*, not a plan. The coach runs both filters, writes the gap statement, and only then enters Stage 4. Coaches are taught the sentence used with athletes and parents: *\"This is the lowest number on the sheet. That is not the same as the thing holding you back, and here is how we will tell the difference.\"*"}')::jsonb, 'a0'),
  ('e5e28e15-0293-5184-8edb-d77cfcef961f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '34e877b0-d5db-5831-a51f-df3d14f5e9ce', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"**PS-1 — Assessment & Profile Sign-Off.** See §13.2. Gates entry to M5."}')::jsonb, 'a1'),
  ('489482ae-0489-558c-b2ac-4d5a0c58d309', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9850012b-a0be-5982-b138-e0fbfd3931f3', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('a2737b45-0d51-5769-bfbf-8e5e8df13f7d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9850012b-a0be-5982-b138-e0fbfd3931f3', 'assessment_reference', 1, ('{"assessmentId":"2b6b81ea-a669-5bfa-b02c-ff93a1007a53","title":"G3-102 · M4 Assessment — From Test Result to Limiting Factor"}')::jsonb, 'a1'),
  ('bf744aa3-9a23-5d8f-a29b-848eedb72220', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b0d984a6-8c6e-52d3-b705-59d12178ccd2', 'callout', 2, ('{"tone":"info","title":"PS-1 — Observed practical sign-off","body":"Completed at: M4 — Function: gates M5 — This sign-off is observed and recorded by an approved G3 assessor. It cannot be self-recorded."}')::jsonb, 'a0'),
  ('b8738abe-9d8c-5a5e-9f06-accbb6eb8df6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b0d984a6-8c6e-52d3-b705-59d12178ccd2', 'heading', 1, ('{"text":"Observed behaviors","level":3}')::jsonb, 'a1'),
  ('bda9adde-8b9e-5511-a13a-e63e2120d193', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b0d984a6-8c6e-52d3-b705-59d12178ccd2', 'checklist', 1, ('{"items":[{"id":"74d0c2b7-5b7a-53af-8752-fae45241c4bf","text":"Administers a movement competency screen competently and safely"},{"id":"1f7e08f5-e044-5243-be70-24ee8ad46dad","text":"Explains testing purpose in plain, non-alarming language"},{"id":"4fbb1e27-bf87-5d09-a93b-e3bede16fa82","text":"Records testing conditions without prompting"},{"id":"8debf2f2-027c-501b-aa8b-d441b50172e7","text":"States which decision each battery item informs"},{"id":"45a9bc83-3dc5-5932-b1d5-23c5f32792de","text":"Uses ''measured deficit'' and ''probable limiting factor'' correctly"},{"id":"50cbfefe-72c4-554a-9ded-add8ad95813e","text":"Declines to interpret change inside typical error"},{"id":"ddd32726-68a4-5c15-b729-b7fd86d08319","text":"States youth safety claims with supervision and progression conditions"}]}')::jsonb, 'a2'),
  ('47ae00bf-7469-597f-ad80-05956c489717', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b0d984a6-8c6e-52d3-b705-59d12178ccd2', 'heading', 1, ('{"text":"Required artifacts","level":3}')::jsonb, 'a3'),
  ('effbfd0f-d189-5a9a-b2eb-e94ede4715f1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b0d984a6-8c6e-52d3-b705-59d12178ccd2', 'checklist', 1, ('{"items":[{"id":"36aaa8d4-8e6e-5204-8bdd-45d6f37deae2","text":"A1"},{"id":"16534266-a810-588f-8f76-0c2a1d7b1de2","text":"A2"},{"id":"c468a114-7e90-58c8-865b-ce40b7180617","text":"A3"},{"id":"4e2c7e92-b349-53cd-b7ed-8dca656cd276","text":"A4"}]}')::jsonb, 'a4'),
  ('2a82e1ee-6f25-5254-87e9-8c9f6738cc60', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b0d984a6-8c6e-52d3-b705-59d12178ccd2', 'heading', 1, ('{"text":"Assessor questions","level":3}')::jsonb, 'a5'),
  ('b468cdb5-2e0f-55ab-9208-335e2ab8252d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b0d984a6-8c6e-52d3-b705-59d12178ccd2', 'checklist', 1, ('{"items":[{"id":"92b5e71e-0dcd-5183-8c28-1fa78a9c1111","text":"Why is this item in your battery?"},{"id":"32fe58d6-7436-5ea5-92ea-e846e0d16488","text":"What would you have done differently if this result were the opposite?"},{"id":"ded73775-4d14-5800-a76a-2f22b7719d1e","text":"Which differences did you set aside, and why?"},{"id":"19e13efc-cd0d-55ac-93a1-12e7f4710e92","text":"What are the conditions of this test, and why did you record them?"}]}')::jsonb, 'a6'),
  ('c7cd382f-9a0c-5eb5-b3ec-b24e714ae39a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b0d984a6-8c6e-52d3-b705-59d12178ccd2', 'callout', 2, ('{"tone":"warning","title":"Practical window","body":"This course carries a minimum four-week practical window.  Practical observation time is additional to directed study and is collected on the floor."}')::jsonb, 'a7'),
  ('52dcda4f-34e4-5a2f-8c4e-3b94e3e0450a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '20ae3a46-1433-5219-92e0-3fa32e3e4c53', 'quote', 1, ('{"text":"Priority is a decision about where the athlete''s best effort goes, and what you give up to put it there."}')::jsonb, 'a0'),
  ('27bd24ab-d7a0-5e64-a0eb-1fcbf0ca3a7b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '20ae3a46-1433-5219-92e0-3fa32e3e4c53', 'checklist', 1, ('{"items":[{"id":"fa4502de-dde1-51b2-82b0-4c2a3af8f482","text":"M5.1 Reject the universal weakness-first rule with reasoning"},{"id":"c14c8403-259f-53f4-8f6c-bf293e9c4832","text":"M5.2 Assign emphasis tiers"},{"id":"5f46aa27-bf7e-5c05-9f9f-8d2870cfe306","text":"M5.3 Write an opportunity-cost statement"},{"id":"a566747b-7c68-59ce-bbf9-736ac85f7bac","text":"M5.4 Weigh considerations without scoring them"},{"id":"5d960118-bffb-5835-8641-f6172e73313a","text":"M5.5 Defend developing a strength"},{"id":"1bca7940-1ac5-57d6-a50c-62dd94dfd801","text":"M5.6 Defend tiering down a weakness"},{"id":"ece01c95-7522-52f8-b6ec-0f657a98a62a","text":"M5.7 Distinguish evidence, standard, and judgment"}]}')::jsonb, 'a1'),
  ('314bf538-c3fd-5d02-9e32-bfb510b4821e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dc6f571c-9690-5fa6-abc7-81b60163631a', 'heading', 1, ('{"text":"L5.1 Why \"train the weakness\" is not a rule","level":3}')::jsonb, 'a0'),
  ('414687c6-6920-51c1-a6b9-a60869f40ac8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dc6f571c-9690-5fa6-abc7-81b60163631a', 'rich_text', 1, ('{"text":"No strong evidence supports a universal rule that the weakest measured quality should be trained first. The decision is conditional on sport relevance, role, confidence that the weakness matters, and the opportunity cost of emphasizing it now. The rule is popular because it is simple, and it fails because athletes are not equally penalized by their weaknesses."}')::jsonb, 'a1'),
  ('4ef457d0-8021-513f-859a-7bb6f9b5b08a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dc6f571c-9690-5fa6-abc7-81b60163631a', 'heading', 1, ('{"text":"L5.2 The thirteen considerations","level":3}')::jsonb, 'a2'),
  ('374d9c1b-d4ab-55aa-9596-b3a8446e35e3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dc6f571c-9690-5fa6-abc7-81b60163631a', 'rich_text', 1, ('{"text":"Sport relevance · magnitude of deficit · athlete level · training age · current phase · injury and availability · adaptation potential · time available · practice and competition demands · fatigue cost · interference with other qualities · maintenance requirements · expected performance return. Coaches weigh these. They do not add them up. Any attempt to weight and total them produces false precision the evidence does not support."}')::jsonb, 'a3'),
  ('01fcd5c8-18ae-5357-80e0-347bb7f3e078', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dc6f571c-9690-5fa6-abc7-81b60163631a', 'heading', 1, ('{"text":"L5.3 The four emphasis tiers","level":3}')::jsonb, 'a4'),
  ('e9fcca55-9348-5276-90ef-d342c86cd0c1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dc6f571c-9690-5fa6-abc7-81b60163631a', 'rich_text', 1, ('{"text":"*Primary development* — receives best session position, highest-quality effort, progressive attention, and the most careful monitoring. *Secondary development* — genuine improvement expected, at lower priority and lower cost. *Maintenance* — a deliberate reduced dose to hold the quality, with a stated verification test. *Exposure* — low-dose contact to preserve competency, tissue tolerance, or familiarity, with no improvement expected. Every quality in a G3 program carries a tier. **A quality with no tier is an accident.**"}')::jsonb, 'a5'),
  ('b1101c69-26f8-5965-ada1-9e0beb51c6de', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dc6f571c-9690-5fa6-abc7-81b60163631a', 'heading', 1, ('{"text":"L5.4 The opportunity-cost sentence","level":3}')::jsonb, 'a6'),
  ('ed533397-d4c4-556e-be22-9a7b40d8b3db', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dc6f571c-9690-5fa6-abc7-81b60163631a', 'rich_text', 1, ('{"text":"Required in every G3 program: *\"By prioritizing ___, this athlete receives less ___, and I accept that because ___.\"* This sentence is the single most reliable indicator of whether prioritization actually happened. A coach who cannot complete it has not prioritized; they have listed."}')::jsonb, 'a7'),
  ('a67fd315-7946-5e40-a85f-34bded0f2ea5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dc6f571c-9690-5fa6-abc7-81b60163631a', 'heading', 1, ('{"text":"L5.5 When a strength deserves development","level":3}')::jsonb, 'a8'),
  ('ce8b18a4-1524-557e-b524-f042e9fab689', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dc6f571c-9690-5fa6-abc7-81b60163631a', 'rich_text', 1, ('{"text":"A strength may deserve further development when it is the athlete''s competitive weapon, when its further improvement has high expected performance return, when the athlete''s role rewards it disproportionately, or when adaptation potential there is high and elsewhere low. This is a legitimate, defensible decision and is explicitly not a coaching error. It is also inferential — the comparative evidence on strengthening a strength versus repairing a weakness is an acknowledged research gap."}')::jsonb, 'a9'),
  ('c4d3c295-469e-52c3-8b36-ab4ae4f6d8a0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dc6f571c-9690-5fa6-abc7-81b60163631a', 'heading', 1, ('{"text":"L5.6 When a weakness is tiered down","level":3}')::jsonb, 'b0'),
  ('cb06f58f-e4a0-5295-baef-b2281e4247ae', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dc6f571c-9690-5fa6-abc7-81b60163631a', 'rich_text', 1, ('{"text":"A weakness may be maintained or left alone when its relevance is low, when the cost of addressing it now is high, when the phase does not permit it, when availability constrains training, or when addressing it would compromise a higher-return priority. The decision is recorded, with a review date. Deprioritized is not forgotten."}')::jsonb, 'b1'),
  ('c9bee456-6568-5f3c-b468-e9a140f841f8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dc6f571c-9690-5fa6-abc7-81b60163631a', 'heading', 1, ('{"text":"L5.7 Priority as communication","level":3}')::jsonb, 'b2'),
  ('b08e2a2e-32a5-53ab-8d39-2f37d774a1e7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dc6f571c-9690-5fa6-abc7-81b60163631a', 'rich_text', 1, ('{"text":"Priority decisions are explained to athletes, parents, and sport coaches in demand-and-cost language. Coaches practice the explanation, because a decision that cannot be explained will not survive contact with a parent who read something different online."}')::jsonb, 'b3'),
  ('e1f4271c-456e-55db-8849-cb7047af3506', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dc8f51fd-bb61-5419-b3ec-bce544602d16', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D4 — Priority is a relevance x opportunity-cost decision","body":"G3 does not adopt ''always train the greatest weakness.'' Priority considers sport relevance, deficit magnitude, athlete level, training age, phase, injury/availability, adaptation potential, time, practice and competition demands, fatigue cost, interference, maintenance requirements, and expected performance return. A strength may deserve development; a weakness may deserve maintenance or no direct intervention. — Teaching boundary: Prioritization worksheets organize judgment; they never compute an answer. No weighted priority score may be created. — Evidence class: B/C"}')::jsonb, 'a0'),
  ('e3e78a1e-536f-574e-bf27-c58686412c15', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dc8f51fd-bb61-5419-b3ec-bce544602d16', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D7 — Multiple qualities can be developed concurrently","body":"Strength, speed, power, conditioning, and movement skill can coexist in a program. Concurrent does not mean equal emphasis: programs distinguish primary development, secondary development, maintenance, and exposure qualities. Interference is conditional and managed through sequencing, spacing, modality, volume, intensity, recovery, training status, and schedule. — Teaching boundary: No numeric interference thresholds or mandatory spacing presented as evidence. G3 spacing conventions are Applied Standards. — Evidence class: A/B/C"}')::jsonb, 'a1'),
  ('a0167787-e544-539d-848a-96913a107b28', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dc8f51fd-bb61-5419-b3ec-bce544602d16', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B — Supported Practice","body":"No universal rule supports always training the weakest quality first — Basis: [cite:19, cite:20, cite:35]"}')::jsonb, 'a2'),
  ('4b34163f-3e53-5b7d-ac22-fd8264033845', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dc8f51fd-bb61-5419-b3ec-bce544602d16', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B — Supported Practice","body":"Prioritization is necessary in real programs; not every quality can improve simultaneously — Basis: [cite:19, cite:35]"}')::jsonb, 'a3'),
  ('3d817b4d-8572-5820-b95f-da9223e3ba58', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dc8f51fd-bb61-5419-b3ec-bce544602d16', 'callout', 2, ('{"tone":"info","title":"Evidence — Class Not established","body":"Exact priority formulas — Basis: Literature is stronger on the need to prioritize than on how [cite:20, cite:48]"}')::jsonb, 'a4'),
  ('a335493c-a95a-5010-b64f-b24ca498ad23', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dc8f51fd-bb61-5419-b3ec-bce544602d16', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D — Applied Coaching Inference","body":"Whether to extend a strength or repair a weakness — Basis: Acknowledged research gap [EP §7.3]"}')::jsonb, 'a5'),
  ('460e85a9-d363-5ebe-b255-057bfe93bae4', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dc8f51fd-bb61-5419-b3ec-bce544602d16', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D / G3 Applied Standard","body":"The four-tier emphasis system and the opportunity-cost statement — Basis: G3 operational structure"}')::jsonb, 'a6'),
  ('e77045fc-69d9-54f6-959f-aa889f3cebcc', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dc8f51fd-bb61-5419-b3ec-bce544602d16', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"the priority itself. G3 does not supply the answer; it supplies the structure and requires the defense."}')::jsonb, 'a7'),
  ('fc01e4a0-6c8b-5424-84a1-23cafb658684', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dc8f51fd-bb61-5419-b3ec-bce544602d16', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Weakness-first as reflex · Everything tiered primary · Maintenance as euphemism for neglect · Weighted priority scores · No stated cost · Norm tables setting the priority"}')::jsonb, 'a8'),
  ('46950eaf-c445-509a-96fc-c26604ffa25a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '78947c0a-df3e-5bba-b5ab-4b2f3932ca32', 'rich_text', 1, ('{"text":"Run at the group level for teams and at the individual level for GPI-tested athletes. In a collegiate in-season block, most qualities sit in Maintenance or Exposure by necessity, and the coach''s real work is choosing the one or two that stay in development — and defending that choice to a sport coach who wants everything improved at once."}')::jsonb, 'a0'),
  ('faf9c061-187a-5c68-8510-404472565817', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '78947c0a-df3e-5bba-b5ab-4b2f3932ca32', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"None. Evidence carries into **PS-2**."}')::jsonb, 'a1'),
  ('ef23faf5-e1d8-5844-8555-0b709de91edf', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'd1cbd366-f2df-5ff3-97c7-295f665638c6', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('0c171398-d5f5-5435-8a4f-3117f343438d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'd1cbd366-f2df-5ff3-97c7-295f665638c6', 'assessment_reference', 1, ('{"assessmentId":"042608a9-bb8a-5569-8b6c-c289ea9c513a","title":"G3-102 · M5 Assessment — Establishing Training Priorities"}')::jsonb, 'a1'),
  ('0d160a73-834e-53ac-a570-0003474bbbc9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e25cc2b8-1a55-50cf-965f-cf231a9d0037', 'quote', 1, ('{"text":"Every exercise is an answer to a question. If you cannot state the question, remove the exercise."}')::jsonb, 'a0'),
  ('a34f91fb-2b53-5e13-af6c-1d4cb45b38e5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e25cc2b8-1a55-50cf-965f-cf231a9d0037', 'checklist', 1, ('{"items":[{"id":"38d45736-2e75-50b8-b3ea-bb16d34b090c","text":"M6.1 Select from intended adaptation"},{"id":"07793312-e0db-5844-8dab-3f0d14547372","text":"M6.2 Apply the fourteen considerations"},{"id":"fb3b6918-1b42-527d-b1b7-638c1a2928c0","text":"M6.3 Explain why visual specificity is not transfer"},{"id":"3474aa88-d634-5a47-9d63-9c3af0639fb6","text":"M6.4 Match complexity to competency"},{"id":"2d377e68-3398-53cd-b517-5b60e9345c0d","text":"M6.5 Evaluate loading, velocity, ROM, fatigue cost"},{"id":"c99cda70-fdfe-577d-a7d9-bf7794cf9178","text":"M6.6 Justify exercise count by focus"},{"id":"82fbd89a-489f-5f66-add5-299bb388d53c","text":"M6.7 Build a movement-category framework"}]}')::jsonb, 'a1'),
  ('476c28a5-bacf-51a0-838f-81f0c0887d63', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '19d7f377-48a8-5807-8e19-17237a340901', 'heading', 1, ('{"text":"L6.1 Start with the adaptation","level":3}')::jsonb, 'a0'),
  ('91c96b15-2ec6-5715-8612-7958924849df', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '19d7f377-48a8-5807-8e19-17237a340901', 'rich_text', 1, ('{"text":"Selection begins with a written intended adaptation: what physiological, neuromuscular, or skill change is this exercise meant to produce, and why does that change matter for this athlete''s priority? Everything else is a constraint on how that adaptation is best pursued."}')::jsonb, 'a1'),
  ('d1537237-a1c7-5631-95e2-89d300c8abea', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '19d7f377-48a8-5807-8e19-17237a340901', 'heading', 1, ('{"text":"L6.2 The fourteen considerations","level":3}')::jsonb, 'a2'),
  ('7f8c1caa-ad00-5d55-9cc2-13d2406e4f8f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '19d7f377-48a8-5807-8e19-17237a340901', 'rich_text', 1, ('{"text":"Desired adaptation · movement competency · loading potential · velocity · intent · range of motion · technical complexity · fatigue cost · risk/reward · available equipment · athlete history · training age · progression potential · place within the total program."}')::jsonb, 'a3'),
  ('15447731-cd35-5f11-8b0e-b0efda33c149', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '19d7f377-48a8-5807-8e19-17237a340901', 'heading', 1, ('{"text":"L6.3 The specificity trap","level":3}')::jsonb, 'a4'),
  ('0a952972-ea98-5d0d-8232-be652e37187c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '19d7f377-48a8-5807-8e19-17237a340901', 'rich_text', 1, ('{"text":"Resistance training clearly improves sport performance, including in elite athletes. There is no strong evidence that visually sport-specific exercises automatically transfer better. Transfer depends on loading, velocity, intent, skill, dose, and the rest of the program — not on resemblance. A loaded imitation of a sport skill frequently degrades the skill and under-loads the quality, achieving neither."}')::jsonb, 'a5'),
  ('3e94793d-701a-57a7-a031-f537319a8c6e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '19d7f377-48a8-5807-8e19-17237a340901', 'heading', 1, ('{"text":"L6.4 Loading potential and progression potential","level":3}')::jsonb, 'a6'),
  ('a955b7e3-b377-5cfa-a9fa-be775d1bf8ec', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '19d7f377-48a8-5807-8e19-17237a340901', 'rich_text', 1, ('{"text":"An exercise that cannot be loaded or progressed has a short useful life as a development tool. It may still be excellent for exposure, competency, or tissue tolerance — which is a tier decision, not a rejection."}')::jsonb, 'a7'),
  ('1dd05403-1691-56e4-9c49-bb05955eae9b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '19d7f377-48a8-5807-8e19-17237a340901', 'heading', 1, ('{"text":"L6.5 Complexity is a cost","level":3}')::jsonb, 'a8'),
  ('6d18c581-d8ed-52ad-818e-4319161691d2', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '19d7f377-48a8-5807-8e19-17237a340901', 'rich_text', 1, ('{"text":"Technical complexity consumes coaching attention, session time, and the athlete''s capacity for quality effort. In a group of thirty scholastic athletes, complexity is the most expensive variable in the program. Choose the least complex exercise that produces the intended adaptation at the required quality."}')::jsonb, 'a9'),
  ('fcb36108-a72a-5783-ae42-95ea3e757347', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '19d7f377-48a8-5807-8e19-17237a340901', 'heading', 1, ('{"text":"L6.6 Fatigue cost and risk/reward","level":3}')::jsonb, 'b0'),
  ('ab6a7d0d-92c0-59f5-ac7b-1e20a0f02e1d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '19d7f377-48a8-5807-8e19-17237a340901', 'rich_text', 1, ('{"text":"Every exercise costs something downstream. Selection asks what this exercise takes from the rest of the session, week, and practice schedule, and whether the expected adaptation justifies it."}')::jsonb, 'b1'),
  ('8524dd3d-ccc7-58bb-b218-eade9f57f0e9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '19d7f377-48a8-5807-8e19-17237a340901', 'heading', 1, ('{"text":"L6.7 Movement categories as G3 architecture","level":3}')::jsonb, 'b2'),
  ('f9dd3a67-9422-56b8-8e8f-f365b749007a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '19d7f377-48a8-5807-8e19-17237a340901', 'rich_text', 1, ('{"text":"G3 programs are built from movement categories — the standardized layer that makes group programming possible. Individualization then happens inside the category through variation, load, complexity, range, and substitution. This connects directly to Module 10."}')::jsonb, 'b3'),
  ('4140a846-9250-579f-814b-a806ef4bf104', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '19d7f377-48a8-5807-8e19-17237a340901', 'heading', 1, ('{"text":"L6.8 More is not more","level":3}')::jsonb, 'b4'),
  ('0c9d2592-5849-52b2-b4cb-18efd48feb77', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '19d7f377-48a8-5807-8e19-17237a340901', 'rich_text', 1, ('{"text":"More exercises do not make a program more complete. Additional content dilutes focus and adds fatigue and complexity cost. Exercise count is not a quality measure in either direction."}')::jsonb, 'b5'),
  ('cad02109-c954-5252-9307-17cd734ea2ab', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7f404b13-5f46-5326-a8a1-133d6f029a4f', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D5 — Exercise selection serves adaptation","body":"Do not confuse visual resemblance to sport with transfer. Selection considers desired adaptation, competency, loading potential, velocity, intent, range of motion, complexity, fatigue cost, risk/reward, equipment, history, training age, progression potential, and place in the total program. — Teaching boundary: Rejecting resemblance-as-transfer is not rejecting specificity of adaptation. — Evidence class: A/B"}')::jsonb, 'a0'),
  ('be176c1a-4580-54d7-850b-473572cd7bc4', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7f404b13-5f46-5326-a8a1-133d6f029a4f', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A — Established Evidence","body":"Resistance training improves sport-specific performance in elite athletes — Basis: [cite:34, cite:43]"}')::jsonb, 'a1'),
  ('e4319f5c-ebdc-52c6-8194-a994045d2ac1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7f404b13-5f46-5326-a8a1-133d6f029a4f', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A — Established Evidence","body":"Adaptation depends on interacting prescription variables rather than any single variable — Basis: [cite:43, cite:52]"}')::jsonb, 'a2'),
  ('fce90c12-45e4-5810-935a-4aa19bd2a673', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7f404b13-5f46-5326-a8a1-133d6f029a4f', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B — Supported Practice","body":"Visually specific exercises do not automatically transfer better — Basis: [cite:34, cite:43]"}')::jsonb, 'a3'),
  ('373098e5-6cbd-5327-9062-384db801e554', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7f404b13-5f46-5326-a8a1-133d6f029a4f', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B — Supported Practice","body":"More exercises do not make a program more complete — Basis: [cite:19, cite:43]"}')::jsonb, 'a4'),
  ('514b7a80-f47d-5954-baa5-2a255efb65c5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7f404b13-5f46-5326-a8a1-133d6f029a4f', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D / G3 Applied Standard","body":"The fourteen-consideration selection framework — Basis: G3 operational structure"}')::jsonb, 'a5'),
  ('5b612791-ed72-53ae-9bad-7031811f86c4', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7f404b13-5f46-5326-a8a1-133d6f029a4f', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"the specific exercise chosen for a given athlete, group, and facility. **Evidence caution:** the elite-athlete resistance-training evidence is heterogeneous in exercises, doses, and sports. It supports including resistance training; it does not prescribe particular exercises."}')::jsonb, 'a6'),
  ('0d060839-563a-563b-a790-89592c51c5fe', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7f404b13-5f46-5326-a8a1-133d6f029a4f', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Choosing because it looks like the sport · Adding exercises for thoroughness · Complexity beyond group competency · Rotating before adaptation or mastery · Coach preference over athlete priority · No stated intended adaptation"}')::jsonb, 'a7'),
  ('4820b41f-9098-57a0-9441-27fefb358b17', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4551a6bf-0de7-53b6-bdb7-e089c9f6864f', 'rich_text', 1, ('{"text":"In G3 small-group performance training, selection is constrained by equipment and coach-to-athlete ratio. The framework produces a defensible answer inside those constraints: choose the least complex exercise, from the correct movement category, that produces the intended adaptation at a coachable quality for the whole group — then individualize load and variation inside it."}')::jsonb, 'a0'),
  ('4c2d49d0-c07f-5c75-9d69-e1a48371ee43', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4551a6bf-0de7-53b6-bdb7-e089c9f6864f', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"Contributes to **PS-2**. Observed elements: the coach teaches a selected exercise to the standard required for its intended adaptation to actually occur."}')::jsonb, 'a1'),
  ('7130ccb1-bf94-5042-9511-ea30eb11a3d7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e91078f6-bf0d-5cf3-b6ea-13af27be268a', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('81a556fe-e662-5eab-9c4d-48ebd069e70e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e91078f6-bf0d-5cf3-b6ea-13af27be268a', 'assessment_reference', 1, ('{"assessmentId":"2c4abb73-95c7-505e-8542-c4aa39d78230","title":"G3-102 · M6 Assessment — Exercise Selection"}')::jsonb, 'a1'),
  ('5ec7ea8b-83ca-5419-8b1e-c50464deeecc', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '493f9957-b2fb-5225-9ebc-948828358e20', 'quote', 1, ('{"text":"Whatever you put first is what you decided mattered most, whether or not you meant to decide it."}')::jsonb, 'a0'),
  ('6e218f3b-22ac-525a-97b6-75ac9e79d54c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '493f9957-b2fb-5225-9ebc-948828358e20', 'checklist', 1, ('{"items":[{"id":"05ac7b22-d6cf-5fa1-a289-c76bd192d47e","text":"M7.1 Order a session by priority"},{"id":"d3ea1958-9996-5c02-a638-3cbb8b70a00e","text":"M7.2 Explain order evidence and its boundaries"},{"id":"d4516fe6-1d4d-57b7-92f7-df049b021828","text":"M7.3 Build G3 session architecture"},{"id":"fffdf814-22fe-5e16-bf82-23839b593631","text":"M7.4 Position qualities by tier"},{"id":"8b4a5040-b494-5451-93c3-99d1f794552d","text":"M7.5 Detect priority-order mismatch"},{"id":"a6285459-db93-536c-a3e9-0d7e09f321a3","text":"M7.6 Protect priority when time is lost"}]}')::jsonb, 'a1'),
  ('d28451c8-95c1-52a2-b8e2-8efcf9a83739', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '82ed5e20-3903-5c5d-a2e8-750a4263e02f', 'heading', 1, ('{"text":"L7.1 What the order evidence says","level":3}')::jsonb, 'a0'),
  ('6eb6424f-e343-594b-9b4f-196240be0bf0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '82ed5e20-3903-5c5d-a2e8-750a4263e02f', 'rich_text', 1, ('{"text":"Exercise order affects acute performance and often long-term adaptation in the prioritized exercise. The effect is clearest in untrained to moderately trained populations — which describes most scholastic athletes G3 serves. The doctrine that follows is not \"order matters a lot in every context\"; it is that whatever goes first is favored, so the coach should decide what that is on purpose."}')::jsonb, 'a1'),
  ('678d0828-5023-58fa-9d33-8dc10d424bd9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '82ed5e20-3903-5c5d-a2e8-750a4263e02f', 'heading', 1, ('{"text":"L7.2 G3 session architecture","level":3}')::jsonb, 'a2'),
  ('bccaec32-3aa1-5687-9b04-ce0eead17f07', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '82ed5e20-3903-5c5d-a2e8-750a4263e02f', 'rich_text', 1, ('{"text":"Preparation → primary quality → secondary quality → supporting work → conditioning or exposure as tiered → close. The architecture is standardized across G3 environments; what changes between environments is what occupies each block, not the shape of the session."}')::jsonb, 'a3'),
  ('8b8ae4d4-b1f4-59f8-a98d-22426d0b1855', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '82ed5e20-3903-5c5d-a2e8-750a4263e02f', 'heading', 1, ('{"text":"L7.3 Placing speed and power","level":3}')::jsonb, 'a4'),
  ('1b1add61-18e9-50b0-98e3-ef548421a76a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '82ed5e20-3903-5c5d-a2e8-750a4263e02f', 'rich_text', 1, ('{"text":"Qualities requiring high neuromuscular quality and low fatigue interference are placed early when they carry development tiers. Placing them after fatiguing work while claiming to develop them is a self-cancelling program."}')::jsonb, 'a5'),
  ('8077ee3b-02b2-55bb-a598-2ad05fe64df1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '82ed5e20-3903-5c5d-a2e8-750a4263e02f', 'heading', 1, ('{"text":"L7.4 The priority-order audit","level":3}')::jsonb, 'a6'),
  ('8198daaa-df6a-5157-8075-d9fc058fdbf7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '82ed5e20-3903-5c5d-a2e8-750a4263e02f', 'rich_text', 1, ('{"text":"A coach reads their own session and asks: *from the order alone, what would an outside coach say I prioritized?* If the answer does not match the Priority & Emphasis Sheet, one of the two documents is wrong. This audit is a scored competency."}')::jsonb, 'a7'),
  ('f3242889-e0d6-5d7c-ac2e-bdfc3692a1d5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '82ed5e20-3903-5c5d-a2e8-750a4263e02f', 'heading', 1, ('{"text":"L7.5 Time loss and protection","level":3}')::jsonb, 'a8'),
  ('39985827-5374-5610-882b-3140e4aef3db', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '82ed5e20-3903-5c5d-a2e8-750a4263e02f', 'rich_text', 1, ('{"text":"Sessions get cut — a late bus, a fire drill, an extended team meeting. G3 requires a pre-decided protection order: what is preserved, what is compressed, what is dropped. Deciding this in advance prevents the priority from being the casualty of the day''s schedule."}')::jsonb, 'a9'),
  ('326ad394-55b7-585b-927f-3f485e7105c7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '82ed5e20-3903-5c5d-a2e8-750a4263e02f', 'heading', 1, ('{"text":"L7.6 Session quality as coaching, not layout","level":3}')::jsonb, 'b0'),
  ('7f96523e-5cf3-5659-b1d9-cf42ae5fa4a4', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '82ed5e20-3903-5c5d-a2e8-750a4263e02f', 'rich_text', 1, ('{"text":"Order creates the opportunity for quality; coaching produces it. Intent, rest adherence, and the coach''s attention during the primary block are what make the priority real. A perfectly ordered session coached passively still trains nothing in particular."}')::jsonb, 'b1'),
  ('216cc622-c5db-543e-8d13-35653e7fafa3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4f3dad3d-004f-5616-8ae4-8f494c7b548c', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D6 — Priority determines order","body":"Exercises and qualities placed earlier in a session generally receive greater performance capacity. Session order reflects training priority rather than habit. — Teaching boundary: Order effects are clearest in untrained to moderately trained populations. Do not teach a numeric penalty for ordering second. — Evidence class: A"}')::jsonb, 'a0'),
  ('826a840b-9329-5372-bca1-a87e1879c61e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4f3dad3d-004f-5616-8ae4-8f494c7b548c', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A — Established Evidence","body":"Exercise order affects acute performance and often adaptation in the prioritized lift — Basis: [cite:19, cite:43]"}')::jsonb, 'a1'),
  ('7cf3cc18-a631-5095-9843-b314c4a743b7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4f3dad3d-004f-5616-8ae4-8f494c7b548c', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A — Established Evidence","body":"Order effects are clearest in untrained to moderately trained populations — Basis: [cite:19]"}')::jsonb, 'a2'),
  ('1537fb76-9de4-55d0-829e-372a2b550846', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4f3dad3d-004f-5616-8ae4-8f494c7b548c', 'callout', 2, ('{"tone":"info","title":"Evidence — Class C — Conditional","body":"Order effects in elite and team-sport contexts — Basis: Less direct evidence [cite:19, cite:43]"}')::jsonb, 'a3'),
  ('0f1bf12c-7f05-500c-bddc-65f174fdfe87', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4f3dad3d-004f-5616-8ae4-8f494c7b548c', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D / G3 Applied Standard","body":"The G3 session architecture and protection order — Basis: G3 operational structure"}')::jsonb, 'a4'),
  ('96ba23c2-5714-5380-965f-929631285d81', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4f3dad3d-004f-5616-8ae4-8f494c7b548c', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"the exception. A documented reason may justify placing something other than the primary quality first — for example, a skill or technical element requiring freshness that serves the primary quality''s development."}')::jsonb, 'a5'),
  ('9448316d-2ad9-536f-b4e9-71daba88c1d1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4f3dad3d-004f-5616-8ae4-8f494c7b548c', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Conditioning early in a strength session · Ordering by habit or equipment flow · Front-loading so nothing after is executed · Letting the schedule decide what is cut · Warm-up as ritual"}')::jsonb, 'a6'),
  ('863c3817-2201-5ea0-9bc8-6b2ddbc97bd7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '0eeccd45-7781-5235-8b59-e9d483a653af', 'rich_text', 1, ('{"text":"The most frequent real-world use is diagnostic. When a program is not producing, the first check is not the exercise selection or the loading scheme; it is whether the priority quality has actually been receiving the athlete''s best effort, or has been sitting third in a session behind fatiguing work."}')::jsonb, 'a0'),
  ('b1dd302c-aeb7-56fa-8734-0d71f7a868c8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '0eeccd45-7781-5235-8b59-e9d483a653af', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"Contributes to **PS-2 — Program Build & Session Delivery** (completed at M8). Observed elements from M7: the coach delivers the session as written, protects the primary block, and manages time without sacrificing the priority."}')::jsonb, 'a1'),
  ('b970e69e-7bbc-583d-88d3-9209c6d940ff', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7841d2ed-2051-5054-852b-2bd1f5ebba6c', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('457d6d31-4fba-577c-ab8c-24f07b9dbe62', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7841d2ed-2051-5054-852b-2bd1f5ebba6c', 'assessment_reference', 1, ('{"assessmentId":"fc6d36af-d719-5a1f-b9b1-d3335cef3fbe","title":"G3-102 · M7 Assessment — Building the Training Session"}')::jsonb, 'a1'),
  ('b1175ed1-eb40-5f99-a0c5-c5efaa4c2b59', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e9d70d48-0e76-5b2d-8bd0-b0bd5e448a9c', 'quote', 1, ('{"text":"The week is where programming stops being a list and starts being a system."}')::jsonb, 'a0'),
  ('e2976184-8906-5092-b841-6c5fc5a84dc0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e9d70d48-0e76-5b2d-8bd0-b0bd5e448a9c', 'checklist', 1, ('{"items":[{"id":"c1e6d670-fed9-5721-a3cc-015e475573a0","text":"M8.1 Organize concurrent development"},{"id":"4609e6ac-1c04-5fdd-85a9-697f77f8ac09","text":"M8.2 Explain conditional interference"},{"id":"bb39f59f-4035-5cb8-bc5f-c1807a9fa82e","text":"M8.3 Apply the six levers"},{"id":"fdadeb85-f394-533b-b41d-e8b151edd286","text":"M8.4 Distinguish tiers across the week"},{"id":"04cc2963-8b2d-587d-9ef3-d37a7b29ebee","text":"M8.5 Integrate the schedule as constraint"},{"id":"fc2f3e5b-7474-5e51-aed6-448ee621a00c","text":"M8.6 Explain how training status modifies tradeoffs"},{"id":"318891bf-f2c7-5f76-90dd-bc2baca6dcca","text":"M8.7 Build a deliverable week"}]}')::jsonb, 'a1'),
  ('5494a378-3756-5c20-801a-7b6fe2e8d412', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '5eaa9a31-82f3-5e57-a2ea-856cb12bb77c', 'heading', 1, ('{"text":"L8.1 Concurrent development is normal","level":3}')::jsonb, 'a0'),
  ('68fcb504-3195-5d3f-a8ba-8e4dfc1bd445', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '5eaa9a31-82f3-5e57-a2ea-856cb12bb77c', 'rich_text', 1, ('{"text":"Concurrent training can improve strength and endurance together in team-sport athletes. In real team environments it is not a compromise position; it is the only honest description of what the athlete is doing. The false choice — strength *or* conditioning — should not be taught."}')::jsonb, 'a1'),
  ('aee072c0-3e81-5491-8032-e15658972b8e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '5eaa9a31-82f3-5e57-a2ea-856cb12bb77c', 'heading', 1, ('{"text":"L8.2 Interference is real and conditional","level":3}')::jsonb, 'a2'),
  ('7d2697a8-1fc3-5420-bdb7-8148a731d1bd', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '5eaa9a31-82f3-5e57-a2ea-856cb12bb77c', 'rich_text', 1, ('{"text":"Interference risk increases under some conditions and is shaped by sequencing, recovery spacing, endurance modality, and training status. Broad anti-concurrent and pro-concurrent claims are both oversimplified. Notably, interference appears more pronounced in older and more experienced athletes than in youth samples — training status modifies the tradeoff."}')::jsonb, 'a3'),
  ('774c1647-4fe1-5d42-9cfc-c802b0a55fd0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '5eaa9a31-82f3-5e57-a2ea-856cb12bb77c', 'heading', 1, ('{"text":"L8.3 The six management levers","level":3}')::jsonb, 'a4'),
  ('1c9068ad-3f32-5233-9f00-04b6b06c8f09', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '5eaa9a31-82f3-5e57-a2ea-856cb12bb77c', 'rich_text', 1, ('{"text":"Sequencing (what follows what) · spacing (how much time between) · modality (which endurance mode) · volume · intensity · recovery. G3 teaches these as levers to pull, and is explicit that exact practical thresholds remain unsettled. G3 spacing conventions are Applied Standards, not evidence-derived numbers, and are labeled as such in the lesson."}')::jsonb, 'a5'),
  ('2e2caa32-0642-51a3-ae88-67ad0b62ff99', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '5eaa9a31-82f3-5e57-a2ea-856cb12bb77c', 'heading', 1, ('{"text":"L8.4 Emphasis tiers across the week","level":3}')::jsonb, 'a6'),
  ('71137c7e-6e0b-5acf-8b0e-703161b75009', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '5eaa9a31-82f3-5e57-a2ea-856cb12bb77c', 'rich_text', 1, ('{"text":"The week is where tiers become visible: the primary quality appears in the best slots with progressive loading; secondary appears with genuine but lower-cost development; maintenance appears at reduced dose with a verification test scheduled; exposure appears in small, deliberate doses. If every quality appears the same number of times at the same effort, no tiering has occurred."}')::jsonb, 'a7'),
  ('e4faff4f-d6c4-5b17-8806-8f83a9554a16', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '5eaa9a31-82f3-5e57-a2ea-856cb12bb77c', 'heading', 1, ('{"text":"L8.5 The schedule is the constraint","level":3}')::jsonb, 'a8'),
  ('2c52ca9e-7552-5b6a-9b8c-27dd6875cd11', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '5eaa9a31-82f3-5e57-a2ea-856cb12bb77c', 'rich_text', 1, ('{"text":"Practice density, competition density, travel, and academic load determine the real training capacity. G3 builds the week around the schedule that exists. In-season, the honest starting question is not \"what would be ideal\" but \"what can be delivered at quality, repeatedly, without degrading practice and competition.\""}')::jsonb, 'a9'),
  ('0e502a1f-6f64-5e8d-a8c7-c43756a5b992', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '5eaa9a31-82f3-5e57-a2ea-856cb12bb77c', 'heading', 1, ('{"text":"L8.6 Youth and adolescent weeks","level":3}')::jsonb, 'b0'),
  ('71b0e495-563a-5eac-926d-cf0c49f3fff1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '5eaa9a31-82f3-5e57-a2ea-856cb12bb77c', 'rich_text', 1, ('{"text":"Concurrent development in youth and adolescent team-sport samples shows strength and endurance improving together, with an interference pattern that may differ from older, more experienced athletes. Youth weeks are typically constrained more by supervision, competency, and attention than by interference."}')::jsonb, 'b1'),
  ('019df01b-c518-5e9e-a8d2-b66c29328378', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '5eaa9a31-82f3-5e57-a2ea-856cb12bb77c', 'heading', 1, ('{"text":"L8.7 Deliverability","level":3}')::jsonb, 'b2'),
  ('9058cfb0-32fc-5f47-8b2e-2765970fdf96', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '5eaa9a31-82f3-5e57-a2ea-856cb12bb77c', 'rich_text', 1, ('{"text":"A week that requires four training slots when three exist is not a program. G3 requires the written week to match the slots the athlete or team actually has, with the priority protected in the slots most likely to survive."}')::jsonb, 'b3'),
  ('27b143f0-6886-5dbf-8c3b-d10bbf05e293', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f73303bd-bd1d-53e4-9b41-214bacdada84', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D7 — Multiple qualities can be developed concurrently","body":"Strength, speed, power, conditioning, and movement skill can coexist in a program. Concurrent does not mean equal emphasis: programs distinguish primary development, secondary development, maintenance, and exposure qualities. Interference is conditional and managed through sequencing, spacing, modality, volume, intensity, recovery, training status, and schedule. — Teaching boundary: No numeric interference thresholds or mandatory spacing presented as evidence. G3 spacing conventions are Applied Standards. — Evidence class: A/B/C"}')::jsonb, 'a0'),
  ('abfdcd5f-ec35-5fff-86cd-29fc11ee3daa', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f73303bd-bd1d-53e4-9b41-214bacdada84', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A — Established Evidence","body":"Concurrent training can improve both strength and endurance in team-sport athletes — Basis: [cite:5, cite:35, cite:71]"}')::jsonb, 'a1'),
  ('a890daca-8fbc-5461-bcbd-3673ee9d5022', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f73303bd-bd1d-53e4-9b41-214bacdada84', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B — Supported Practice","body":"Interference risk is conditional, shaped by sequencing, spacing, modality, and training status — Basis: [cite:5, cite:35, cite:63, cite:68]"}')::jsonb, 'a2'),
  ('f1cc1d23-4025-5132-a65e-3f410f2e4cf7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f73303bd-bd1d-53e4-9b41-214bacdada84', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B — Supported Practice","body":"Interference is more pronounced in older/more experienced athletes than youth samples — Basis: [cite:35, cite:71]"}')::jsonb, 'a3'),
  ('601534c4-ee85-5eaa-bb8c-0d9ed86886b6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f73303bd-bd1d-53e4-9b41-214bacdada84', 'callout', 2, ('{"tone":"info","title":"Evidence — Class C — Emerging / unsettled","body":"Exact spacing thresholds and sequencing rules — Basis: Mechanisms and practical thresholds remain unsettled [cite:63, cite:68]"}')::jsonb, 'a4'),
  ('faceb607-27ca-5579-a2dd-814dc0fb04a0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f73303bd-bd1d-53e4-9b41-214bacdada84', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D / G3 Applied Standard","body":"G3 weekly architecture and spacing conventions — Basis: G3 operational structure"}')::jsonb, 'a5'),
  ('67d29d2b-f693-5f59-bb52-1fc40f4ceed0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f73303bd-bd1d-53e4-9b41-214bacdada84', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"the specific weekly layout for a given team, schedule, and facility."}')::jsonb, 'a6'),
  ('d8981b92-baa6-53dc-a58b-4cf53177bda1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f73303bd-bd1d-53e4-9b41-214bacdada84', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Interference as universal law · Interference as myth · Ideal weeks that cannot be delivered · Equal weekly presence called concurrent development · Quoting spacing rules as evidence · Adult interference expectations in middle-school groups"}')::jsonb, 'a7'),
  ('e0cb896e-11e7-5651-a008-f42b70440e85', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '236a3228-b006-58c5-9ae8-7ad3ebe88f03', 'rich_text', 1, ('{"text":"For a scholastic in-season week with two available slots and five practices, the coach protects one primary development quality, holds one or two qualities at maintenance with a scheduled verification test, and uses exposure doses for the rest — then states plainly to the sport coach what will and will not improve during the season. That conversation is part of the competency."}')::jsonb, 'a0'),
  ('4af2c4a7-dc38-5ac4-9d30-7c33e6026910', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '236a3228-b006-58c5-9ae8-7ad3ebe88f03', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"**PS-2 — Program Build & Session Delivery.** See §13.3. Gates entry to M9."}')::jsonb, 'a1'),
  ('2a03a666-2feb-53f2-b4d6-e2b9dfe348ad', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '2ad89871-eb4d-54ad-a025-8ecb50efafbf', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('5c75e9a8-b4d4-5957-bf45-d8d511dbfdce', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '2ad89871-eb4d-54ad-a025-8ecb50efafbf', 'assessment_reference', 1, ('{"assessmentId":"4a901de7-22a1-5a84-ae39-8893c6b82f4a","title":"G3-102 · M8 Assessment — Building the Training Week"}')::jsonb, 'a1'),
  ('74b4be87-8f5b-597d-8a0a-0abfb66e95c9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '44399257-416c-52aa-a55b-6fc2d1a45723', 'callout', 2, ('{"tone":"info","title":"PS-2 — Observed practical sign-off","body":"Completed at: M8 — Function: gates M9 — This sign-off is observed and recorded by an approved G3 assessor. It cannot be self-recorded."}')::jsonb, 'a0'),
  ('e877ccc2-696c-551f-8268-6a8224bb48e5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '44399257-416c-52aa-a55b-6fc2d1a45723', 'heading', 1, ('{"text":"Observed behaviors","level":3}')::jsonb, 'a1'),
  ('dec4b3f4-0801-5be9-bafe-14422ff50594', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '44399257-416c-52aa-a55b-6fc2d1a45723', 'checklist', 1, ('{"items":[{"id":"3eac87ed-6e35-5681-8c8c-7b21c40891d6","text":"Delivers a session as written with the primary block protected"},{"id":"d7689c3b-bcb3-5f1c-91f5-5834561aec31","text":"Coaches the primary quality actively rather than supervising"},{"id":"65d80cd1-ac2b-50c4-9645-12ac5257be58","text":"Teaches a selected exercise to the standard its adaptation requires"},{"id":"e3611759-1d7a-5793-b3a2-b8e03f33709d","text":"Applies the protection order when time is lost"},{"id":"be66df1e-d66c-5b3a-97a9-550c56181922","text":"Uses movement-category and emphasis-tier language"},{"id":"abf80ee3-644f-5961-9737-68ddd5774fb9","text":"States the session priority and its cost on the spot"}]}')::jsonb, 'a2'),
  ('c433b134-f7c7-5aa8-ae7e-8aeb731870bb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '44399257-416c-52aa-a55b-6fc2d1a45723', 'heading', 1, ('{"text":"Required artifacts","level":3}')::jsonb, 'a3'),
  ('44a28f10-c746-59c8-9951-d0122733c8c6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '44399257-416c-52aa-a55b-6fc2d1a45723', 'checklist', 1, ('{"items":[{"id":"6c2de370-9286-5e2c-9bec-4fb6a77f3b0f","text":"A5"},{"id":"452ff8ce-9a84-5e75-b3c2-02b51f0ceb02","text":"A6"},{"id":"e7040812-8c8e-534b-8a75-e8a616fed104","text":"A7"},{"id":"206c54e4-6e8c-578c-acc1-d3d8bd155386","text":"A8"}]}')::jsonb, 'a4'),
  ('80552c3b-7bb0-58f4-b40e-d660ef4c048e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '44399257-416c-52aa-a55b-6fc2d1a45723', 'heading', 1, ('{"text":"Assessor questions","level":3}')::jsonb, 'a5'),
  ('071136bc-c16f-5e3d-84a8-6522b0936e97', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '44399257-416c-52aa-a55b-6fc2d1a45723', 'checklist', 1, ('{"items":[{"id":"605af84d-87f0-5191-aa51-6dcfb0fff6e1","text":"From the order alone, what would I say your priority is?"},{"id":"6b2b8862-787a-5776-b33b-f1af1af75541","text":"What comes out if you lose fifteen minutes?"},{"id":"2f852c57-642f-54fd-bf03-02456ab42134","text":"What adaptation is this exercise producing?"},{"id":"9bf83298-8644-512d-b3e3-465acde2a05d","text":"What is this athlete not getting this week?"}]}')::jsonb, 'a6'),
  ('87d4c0b7-af7c-5b35-b3b7-78b56eb5caaf', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '44399257-416c-52aa-a55b-6fc2d1a45723', 'callout', 2, ('{"tone":"warning","title":"Practical window","body":"This course carries a minimum four-week practical window.  Practical observation time is additional to directed study and is collected on the floor."}')::jsonb, 'a7'),
  ('409cd4b2-d8a2-523a-bd6e-a1b9b39a55bb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7e66ebc6-e15a-5a2b-9933-17eb0bfb2fa1', 'quote', 1, ('{"text":"A phase is a promise about what will improve and what will not."}')::jsonb, 'a0'),
  ('9047053e-8fb9-51d6-a2e7-cc5383b908a1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7e66ebc6-e15a-5a2b-9933-17eb0bfb2fa1', 'checklist', 1, ('{"items":[{"id":"6c2b59a8-8c4d-5594-a6dd-7786b4835377","text":"M9.1 Define a phase by objective"},{"id":"a22fa7ca-007d-5f06-b5b9-1bb17511ac49","text":"M9.2 Build progression for the primary quality"},{"id":"f8dc6068-5dc4-5800-85be-43854fd233d1","text":"M9.3 Prescribe maintenance with verification"},{"id":"766502fb-f339-52af-9ad6-b828a568f633","text":"M9.4 Distinguish justified variation from novelty"},{"id":"a0e10ec7-d524-53a4-aa2f-086427f3c463","text":"M9.5 Explain why no model is universally superior"},{"id":"97167811-3752-54c4-a16a-0196b22ebade","text":"M9.6 Discuss historical models accurately"},{"id":"048ff03e-3faf-51d8-99d9-df020ef48111","text":"M9.7 Set phase review points"}]}')::jsonb, 'a1'),
  ('1a280df3-9f28-5bfb-8550-9161f7c5f668', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7d8c0ff4-fff1-54fc-befc-5245598c5dba', 'heading', 1, ('{"text":"L9.1 Objective before duration","level":3}')::jsonb, 'a0'),
  ('230bdbec-4837-5e2f-b185-981fc426090e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7d8c0ff4-fff1-54fc-befc-5245598c5dba', 'rich_text', 1, ('{"text":"A G3 phase is defined by what it is trying to change and what evidence would show it changed. Duration follows from the objective, the schedule, and the time required for the adaptation to become evaluable. No universal evidence-backed phase interval exists; \"four weeks\" is a habit, not a finding."}')::jsonb, 'a1'),
  ('fdf63199-3da2-5a39-b5db-eb478275bae0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7d8c0ff4-fff1-54fc-befc-5245598c5dba', 'heading', 1, ('{"text":"L9.2 Progression of the primary","level":3}')::jsonb, 'a2'),
  ('eeef8466-7e32-54eb-b972-9d51f5053fab', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7d8c0ff4-fff1-54fc-befc-5245598c5dba', 'rich_text', 1, ('{"text":"Progression is planned in advance for the primary quality: how load, complexity, velocity demand, or volume advances, and what would trigger holding instead. Progression planned only in the moment produces programs that drift."}')::jsonb, 'a3'),
  ('e00b5002-6b4a-5230-99e6-73ec928f18b3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7d8c0ff4-fff1-54fc-befc-5245598c5dba', 'heading', 1, ('{"text":"L9.3 Maintenance as a defended reduction","level":3}')::jsonb, 'a4'),
  ('81d0c39f-de20-5633-9e19-2fbb17652abe', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7d8c0ff4-fff1-54fc-befc-5245598c5dba', 'rich_text', 1, ('{"text":"The broad principle that maintaining a quality generally requires less dose than developing it is plausible and widely used, but exact doses remain underdetermined and vary too much for precise universal rules. G3 therefore prescribes maintenance as: a stated reduction, a stated rationale, and a **scheduled verification test** to confirm the quality actually held. **No G3 material publishes universal maintenance dose numbers.** Where a G3 environment adopts a working convention, it is labeled a G3 Applied Standard with a review date."}')::jsonb, 'a5'),
  ('062c8bf7-8a4a-5058-a21a-782ecf1e3504', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7d8c0ff4-fff1-54fc-befc-5245598c5dba', 'heading', 1, ('{"text":"L9.4 Variation that serves adaptation","level":3}')::jsonb, 'a6'),
  ('d2edd303-4e79-5b38-8a74-b723403d99db', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7d8c0ff4-fff1-54fc-befc-5245598c5dba', 'rich_text', 1, ('{"text":"Change is justified by adaptation, stagnation, technical mastery, pain, athlete response, schedule, phase objectives, progression needs, changing sport demands, or poor program fit. Change is not justified by elapsed time, boredom, novelty, or a popular exercise. Frequent rotation also obstructs evaluation: an exercise changed before adaptation could occur can never be assessed."}')::jsonb, 'a7'),
  ('72647e9a-1db8-5f01-8938-baa4f4a45cf6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7d8c0ff4-fff1-54fc-befc-5245598c5dba', 'heading', 1, ('{"text":"L9.5 Periodization models","level":3}')::jsonb, 'a8'),
  ('3e86e4ee-2681-5175-ae46-92d20b8fc578', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7d8c0ff4-fff1-54fc-befc-5245598c5dba', 'rich_text', 1, ('{"text":"No single periodization model is established as universally superior; model effectiveness depends on athlete level, season structure, and implementation quality. G3 teaches model *literacy* — coaches should understand the logic of the major models and be able to explain their choice — without adopting one as doctrine."}')::jsonb, 'a9'),
  ('66cc74cc-bd78-5744-be14-3abaf3507f0f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7d8c0ff4-fff1-54fc-befc-5245598c5dba', 'heading', 1, ('{"text":"L9.6 Historical frameworks, accurately stated","level":3}')::jsonb, 'b0'),
  ('c75f54f1-77ac-5c25-b60b-40764305e78a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7d8c0ff4-fff1-54fc-befc-5245598c5dba', 'rich_text', 1, ('{"text":"Matveyev contributed planned variation across longer cycles. Verkhoshansky contributed specialized strength training, shock methods, and the general/special preparation relationship. Bondarchuk contributed exercise classification and transfer logic with athlete-response-based organization. Bompa popularized periodization language and planning structure for wide audiences. Issurin''s block periodization clarified concentrated loading and sequential emphasis. Conjugate approaches are influential for concurrent development and weekly variation of qualities. Phase potentiation is a useful organizing idea that earlier emphases can support later qualities. **All are taught as influential frameworks — Class E — not as validated universal systems.** Historical influence is not intervention proof, and the Evidence Pack notes that exact historical claims require separate archival verification before being asserted as fact."}')::jsonb, 'b1'),
  ('0548ff5b-b8ac-5934-97e8-c57102bb31ec', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7d8c0ff4-fff1-54fc-befc-5245598c5dba', 'heading', 1, ('{"text":"L9.7 Review points","level":3}')::jsonb, 'b2'),
  ('87c82d89-eead-5f8b-a348-b930a48401cf', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7d8c0ff4-fff1-54fc-befc-5245598c5dba', 'rich_text', 1, ('{"text":"Each phase carries defined review points tied to the objective. Review points prevent both premature abandonment and indefinite continuation of an unproductive plan."}')::jsonb, 'b3'),
  ('39b0afaf-f2a3-55e1-a1e6-103e962e111a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9d9143fb-f80c-5399-893e-18d6afa8b0a3', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D12 — Programs change for reasons","body":"Programs do not need to change because four weeks passed, the athlete is bored, or novelty appears advanced. Change is justified by adaptation, stagnation, technical mastery, pain, athlete response, schedule, phase objectives, progression needs, changing sport demands, or poor fit. — Teaching boundary: Absence of evidence for mandatory change is not evidence that programs should rarely change. A coach who never changes anything also fails this doctrine. — Evidence class: D"}')::jsonb, 'a0'),
  ('ec709907-20d4-502f-b04f-c99e7c45e0cd', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9d9143fb-f80c-5399-893e-18d6afa8b0a3', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D7 — Multiple qualities can be developed concurrently","body":"Strength, speed, power, conditioning, and movement skill can coexist in a program. Concurrent does not mean equal emphasis: programs distinguish primary development, secondary development, maintenance, and exposure qualities. Interference is conditional and managed through sequencing, spacing, modality, volume, intensity, recovery, training status, and schedule. — Teaching boundary: No numeric interference thresholds or mandatory spacing presented as evidence. G3 spacing conventions are Applied Standards. — Evidence class: A/B/C"}')::jsonb, 'a1'),
  ('7197632a-1a3b-5865-aef1-68af8b10fe4d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9d9143fb-f80c-5399-893e-18d6afa8b0a3', 'callout', 2, ('{"tone":"info","title":"Evidence — Class C — Emerging / conditional","body":"No universally superior periodization model is established — Basis: [cite:51, cite:52, cite:48]"}')::jsonb, 'a2'),
  ('2e3edaaf-e7b1-5e46-b018-13156a17ee8c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9d9143fb-f80c-5399-893e-18d6afa8b0a3', 'callout', 2, ('{"tone":"info","title":"Evidence — Class C — Emerging Evidence, moderate-low confidence","body":"Maintenance likely requires less dose than development; exact doses vary too much for precise rules — Basis: [cite:35, cite:43]"}')::jsonb, 'a3'),
  ('df5e4b1b-33d1-5aeb-8160-41685d116ea5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9d9143fb-f80c-5399-893e-18d6afa8b0a3', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D — Applied Coaching Inference","body":"Mandatory rotation intervals and fixed phase lengths are not supported — Basis: [cite:4, cite:19, cite:20]"}')::jsonb, 'a4'),
  ('f240a8ea-b295-5126-8ac0-da37d1612618', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9d9143fb-f80c-5399-893e-18d6afa8b0a3', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D — Applied Coaching Inference","body":"Frequent variation is not inherently superior and can obstruct evaluation — Basis: [cite:19, cite:20, cite:27]"}')::jsonb, 'a5'),
  ('774b1591-4cf3-5cbc-854e-6cdcbab67c02', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9d9143fb-f80c-5399-893e-18d6afa8b0a3', 'callout', 2, ('{"tone":"info","title":"Evidence — Class E — Historical / Practitioner Framework","body":"Historical periodization models — Basis: [cite:48; EP §6]"}')::jsonb, 'a6'),
  ('411f2d63-678e-57b5-b565-b2e20bda2c80', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9d9143fb-f80c-5399-893e-18d6afa8b0a3', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"phase length, model selection, maintenance dose for a given athlete and schedule. **Manual-verification flag:** precise maintenance doses by quality and season phase, and detailed historical claims about periodization models, are listed in the Evidence Pack as requiring manual verification. They are excluded from graded answer keys."}')::jsonb, 'a7'),
  ('9d44b069-776b-525c-97c7-eee380188bca', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9d9143fb-f80c-5399-893e-18d6afa8b0a3', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Changing on the calendar · Rotating before adaptation · Maintenance without verification · Quoting precise maintenance doses · Presenting one model as proven · Unverified historical claims · No review points"}')::jsonb, 'a8'),
  ('eaee0d69-372a-525f-bf70-4939ee9cd78f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e6c1d582-de42-503f-923f-5af130b30672', 'rich_text', 1, ('{"text":"The most common G3 application is defending a *non-change*. A sport coach or parent asks why the program looks similar to last month. The competent answer names the phase objective, the progression that has occurred inside the same structure, the review point, and the evidence that would trigger a change — delivered in under thirty seconds."}')::jsonb, 'a0'),
  ('d9aab937-45a7-5394-a2dc-945543566032', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e6c1d582-de42-503f-923f-5af130b30672', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"None. Evidence carries into **PS-4**."}')::jsonb, 'a1'),
  ('6b1feabb-4ea8-5036-b905-58e57ab11162', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '21859234-843a-5ee5-aafe-d55d60ec57f5', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('85aa43f5-640a-5c8f-a58f-82c78129d43d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '21859234-843a-5ee5-aafe-d55d60ec57f5', 'assessment_reference', 1, ('{"assessmentId":"e3a86110-48b8-5801-a8e4-55279a298516","title":"G3-102 · M9 Assessment — Building the Training Phase"}')::jsonb, 'a1'),
  ('339986ba-b3e6-5147-a5c1-df31dd318ad9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '8540ba8e-c2e3-5608-965b-e95bcf6368ae', 'quote', 1, ('{"text":"Forty athletes, one coach, one hour. Individualization that cannot survive that room is a theory."}')::jsonb, 'a0'),
  ('2a617f1c-8230-5982-b638-7b23adc0abfb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '8540ba8e-c2e3-5608-965b-e95bcf6368ae', 'checklist', 1, ('{"items":[{"id":"84a1da6e-02e8-5048-8f84-780cc57c0a1f","text":"M10.1 Explain why unique programs are not required"},{"id":"efb2bd03-646e-50a2-9ba7-65cf65c373b5","text":"M10.2 Identify what to standardize and individualize"},{"id":"02ee7bad-6846-5834-a259-83b3a6c7b14b","text":"M10.3 Build a team template with channels"},{"id":"f119f301-4241-5609-a3a5-c5cd558ffce1","text":"M10.4 Apply pathways in a group session"},{"id":"fe49c7df-209d-564f-9294-5dc2fefea46c","text":"M10.5 Design youth groups around readiness and supervision"},{"id":"0c760a64-dc3f-5f67-a2fe-baccccf69b24","text":"M10.6 Substitute without breaking intent"},{"id":"69c2c0e2-4c2f-59d9-9402-87d029bb5b4f","text":"M10.7 State the evidence standing honestly"}]}')::jsonb, 'a1'),
  ('88b16d7f-cdc7-5438-ae46-b1aac8795fba', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b484a95e-5356-50ce-a4a4-ab4221c920f1', 'heading', 1, ('{"text":"L10.1 The template question","level":3}')::jsonb, 'a0'),
  ('cc3ec9cb-5591-5b4d-a9ad-2c30af551095', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b484a95e-5356-50ce-a4a4-ab4221c920f1', 'rich_text', 1, ('{"text":"Templates are not inherently poor programming. Quality depends on how the template handles priorities, progressions, and modifications. A template with no individualization channels is a poor program; a unique program per athlete that the coach cannot deliver at quality is also a poor program."}')::jsonb, 'a1'),
  ('e155855d-fb0c-538d-b4a8-cdaa4fbedaf8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b484a95e-5356-50ce-a4a4-ab4221c920f1', 'heading', 1, ('{"text":"L10.2 What is standardized","level":3}')::jsonb, 'a2'),
  ('20a46616-46e3-5590-be63-1660b51315bf', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b484a95e-5356-50ce-a4a4-ab4221c920f1', 'rich_text', 1, ('{"text":"Session structure · movement categories · primary objectives · coaching language · progression framework. Standardizing these is what makes a large group coachable, keeps quality consistent across staff, and makes the program auditable."}')::jsonb, 'a3'),
  ('a5525ee2-c0fb-5e6b-94a5-d05f017c5223', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b484a95e-5356-50ce-a4a4-ab4221c920f1', 'heading', 1, ('{"text":"L10.3 What is individualized","level":3}')::jsonb, 'a4'),
  ('f549c7fd-c6ef-5adc-9fb8-4e7bee794bbc', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b484a95e-5356-50ce-a4a4-ab4221c920f1', 'rich_text', 1, ('{"text":"Exercise variation · load · volume · complexity · range of motion · progression rate · regression · substitutions · readiness adjustments. These are the individualization channels. G3 requires that every template state which channels are open and who may adjust them."}')::jsonb, 'a5'),
  ('b3387986-b95d-55b4-bc95-944c981ef250', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b484a95e-5356-50ce-a4a4-ab4221c920f1', 'heading', 1, ('{"text":"L10.4 Progression and regression pathways","level":3}')::jsonb, 'a6'),
  ('9bf368d5-58ac-5937-94ae-5088041e8379', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b484a95e-5356-50ce-a4a4-ab4221c920f1', 'rich_text', 1, ('{"text":"Each movement category carries a defined pathway — the regression an athlete drops to and the progression they earn. Pathways let one coach serve a wide competency range without writing separate programs, and they make coaching decisions transferable between staff."}')::jsonb, 'a7'),
  ('faeedc84-14f9-582d-94e5-cd779f43eb46', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b484a95e-5356-50ce-a4a4-ab4221c920f1', 'heading', 1, ('{"text":"L10.5 Youth group design","level":3}')::jsonb, 'a8'),
  ('e668ed02-797a-56c6-b316-b7ef5b2ec76c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b484a95e-5356-50ce-a4a4-ab4221c920f1', 'rich_text', 1, ('{"text":"Youth groups are built around supervision ratio, instructional responsiveness, movement competency, and progression. Complexity is the expensive variable. Readiness — not chronological age — governs entry to loaded progressions, and supervision is part of the safety claim, not context around it."}')::jsonb, 'a9'),
  ('c7ee35a4-f7aa-59a9-8a4a-5d33b5883b27', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b484a95e-5356-50ce-a4a4-ab4221c920f1', 'heading', 1, ('{"text":"L10.6 Substitution without drift","level":3}')::jsonb, 'b0'),
  ('9767a523-0393-5fac-a7bd-6ec2c08b4783', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b484a95e-5356-50ce-a4a4-ab4221c920f1', 'rich_text', 1, ('{"text":"A substitution must serve the same intended adaptation and sit in the same movement category and emphasis tier. Substitutions that quietly change the adaptation cause a team program to drift from its own priorities within weeks."}')::jsonb, 'b1'),
  ('7df90321-2849-5ad8-a6b4-d621309f4003', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b484a95e-5356-50ce-a4a4-ab4221c920f1', 'heading', 1, ('{"text":"L10.7 Stating the evidence standing","level":3}')::jsonb, 'b2'),
  ('e48f4056-9537-58dc-8d48-4e47b02e940f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b484a95e-5356-50ce-a4a4-ab4221c920f1', 'rich_text', 1, ('{"text":"Scalable individualization is supported by professional practice surveys and applied inference, not by direct comparative trials. G3 adopts it as an Applied Standard because a defensible answer is required for large rosters, and says exactly that to learners. Coaches should be able to distinguish \"this is what G3 does and why\" from \"this is what the research shows.\""}')::jsonb, 'b3'),
  ('8e0e7037-63e2-5ce8-b859-be817834a81d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c123a0b9-b958-5757-9ff6-650bba2386d4', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D8 — Individualization does not require unique programs for everyone","body":"Standardize where athletes are similar; individualize where differences matter. Teams standardize session structure, movement categories, objectives, coaching language, and progression framework, and individualize through variation, load, volume, complexity, range of motion, progression rate, regression, substitution, and readiness adjustment. — Teaching boundary: Taught explicitly as applied inference, while binding as a G3 Applied Standard for team environments. — Evidence class: D"}')::jsonb, 'a0'),
  ('8c17be2f-f0b6-51ff-bd94-eb97ec36dc2f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c123a0b9-b958-5757-9ff6-650bba2386d4', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D9 — Youth training is readiness-based, not age-myth-based","body":"Supervised progressive resistance training is appropriate for youth. Readiness considers instructional responsiveness, psychological readiness, movement competency, maturity, training history, supervision, and progression. — Teaching boundary: The safety and efficacy claim is conditioned on supervision and progression; state both conditions whenever the claim is made. — Evidence class: A"}')::jsonb, 'a1'),
  ('38963b6d-57b1-5505-806d-4d69890e349d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c123a0b9-b958-5757-9ff6-650bba2386d4', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D — Applied Coaching Inference","body":"Team programs can preserve quality without fully unique plans — Basis: Practice surveys plus indirect literature [cite:19, cite:35, cite:51]"}')::jsonb, 'a2'),
  ('9ea3bd9d-43fd-59bc-8575-fceb521ceb74', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c123a0b9-b958-5757-9ff6-650bba2386d4', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D — Applied Coaching Inference","body":"Templates are not inherently poor programming — Basis: The counter-claim that templates are inherently poor is unsupported; the positive case rests on practice-survey evidence and inference, and is rated as in Doctrine 8 [cite:51]"}')::jsonb, 'a3'),
  ('ddc84e0f-f0d5-51da-abcc-049715bb3606', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c123a0b9-b958-5757-9ff6-650bba2386d4', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A — Established Evidence","body":"Supervised progressive youth resistance training is safe and effective — Basis: [cite:3, cite:38, cite:53, cite:55, cite:57]"}')::jsonb, 'a4'),
  ('47875e86-141c-52fb-90a9-d9e352075f35', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c123a0b9-b958-5757-9ff6-650bba2386d4', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D — Applied Coaching Inference","body":"Specific scalable-individualization architectures — Basis: More practice-based than experimentally validated"}')::jsonb, 'a5'),
  ('8e481cf1-ff3f-5bd1-bfcd-1dd7db315a29', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c123a0b9-b958-5757-9ff6-650bba2386d4', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"how many individualization channels to open for a given group and staffing level. **Research gap acknowledged:** stronger evidence on scalable individualization models for large team environments is an open need."}')::jsonb, 'a6'),
  ('186cd53f-0c99-572e-99b8-cc16ff89e428', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c123a0b9-b958-5757-9ff6-650bba2386d4', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Forty unique programs delivered badly · One program with no channels · Too many channels to coach · Substituting on equipment availability · Age-gating youth participation · Supervision ratio that invalidates the safety claim"}')::jsonb, 'a7'),
  ('17565c89-367d-5d9b-a822-766ac006a4d1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '567dea6c-6373-56fe-a6ae-476526efa88a', 'rich_text', 1, ('{"text":"For a 40-athlete scholastic volleyball roster with two coaches: one template, three competency lanes per movement category, load individualized by athlete, complexity individualized by lane, and readiness adjustments delegated within stated limits. The coach can name, for any athlete in the room, which channel is being used for them and why."}')::jsonb, 'a0'),
  ('aaf23182-2bc4-5591-ac33-b9963e99a525', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '567dea6c-6373-56fe-a6ae-476526efa88a', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"**PS-3 — Group & Team Delivery Sign-Off.** See §13.4."}')::jsonb, 'a1'),
  ('fb1aab8b-f418-5f4c-9569-d0a45c6f6b9a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4821c2c1-9ae4-5c64-aa7c-38df364a8d04', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('a087a31f-8410-56a2-bcd5-597a96eb05b8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4821c2c1-9ae4-5c64-aa7c-38df364a8d04', 'assessment_reference', 1, ('{"assessmentId":"282ed985-c5c3-57af-8ff7-6be59978da05","title":"G3-102 · M10 Assessment — Individualization at Scale"}')::jsonb, 'a1'),
  ('bfe9cb53-c3b5-5147-8cb6-e3e024a47d07', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '861ae554-5fdb-5910-a147-47097baf2631', 'callout', 2, ('{"tone":"info","title":"PS-3 — Observed practical sign-off","body":"Completed at: M10 — Function: completion requirement — This sign-off is observed and recorded by an approved G3 assessor. It cannot be self-recorded."}')::jsonb, 'a0'),
  ('909dc562-0cf3-5e18-b48d-6ae718aedf0b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '861ae554-5fdb-5910-a147-47097baf2631', 'heading', 1, ('{"text":"Observed behaviors","level":3}')::jsonb, 'a1'),
  ('2dd3e8d2-2bd3-5a37-8c20-bb9faac43168', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '861ae554-5fdb-5910-a147-47097baf2631', 'checklist', 1, ('{"items":[{"id":"825390d7-9304-523e-bc81-0c29a7a1f7cd","text":"Delivers a group session at the stated ratio without loss of standard"},{"id":"04ebd823-9301-5302-8bb6-bfac5db71db0","text":"Uses lanes and pathways for a mixed-competency group"},{"id":"44ded92c-5aa3-51a3-8bb0-4a14a0df68de","text":"Applies a regression without disrupting the session"},{"id":"9468015c-2df2-566c-a4e5-0a94398d1cc0","text":"Substitutes preserving adaptation, category, and tier"},{"id":"535ee559-fee4-57f2-9c4d-b16581657f13","text":"Applies readiness-based youth entry criteria and maintains supervision ratio"},{"id":"4ff58d6a-c874-5e96-8a75-dd0e12f001ba","text":"Names the channel in use for any athlete"}]}')::jsonb, 'a2'),
  ('74fd139a-d1cd-5dc2-8286-66eca469c924', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '861ae554-5fdb-5910-a147-47097baf2631', 'heading', 1, ('{"text":"Required artifacts","level":3}')::jsonb, 'a3'),
  ('83de2bfb-2be7-5290-8b4d-33772398ba05', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '861ae554-5fdb-5910-a147-47097baf2631', 'checklist', 1, ('{"items":[{"id":"2a89b77f-09f2-501f-adb8-15453010f185","text":"A10"},{"id":"9387e985-9ff8-5edd-9293-a91ac93792ee","text":"A11 (provisional)"}]}')::jsonb, 'a4'),
  ('a928872b-e939-52ca-937a-6a55b2e0ed8c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '861ae554-5fdb-5910-a147-47097baf2631', 'heading', 1, ('{"text":"Assessor questions","level":3}')::jsonb, 'a5'),
  ('80a7cdfd-6d4b-5f72-8463-124249bf2143', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '861ae554-5fdb-5910-a147-47097baf2631', 'checklist', 1, ('{"items":[{"id":"f73cc6a3-3ea9-534e-8baa-8399e27d3516","text":"Which channel is open for that athlete?"},{"id":"dcad9a5a-4993-5a02-bbb7-e7401b900f17","text":"What is the regression for this category and who may apply it?"},{"id":"db5d1a25-851a-5e1d-b2a3-e8c99d64714a","text":"What ratio does this session require to be defensible?"},{"id":"d6602891-a816-50aa-9df3-ca261dec0fcf","text":"Why is this athlete in this lane?"}]}')::jsonb, 'a6'),
  ('7ea8c23e-8a87-5e06-82ea-f4a783324e9d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '861ae554-5fdb-5910-a147-47097baf2631', 'callout', 2, ('{"tone":"warning","title":"Practical window","body":"This course carries a minimum four-week practical window.  Practical observation time is additional to directed study and is collected on the floor."}')::jsonb, 'a7'),
  ('65202482-5c81-5692-8933-420dc96d58eb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'fc50caa6-7214-5ec7-b094-b8084ed9102d', 'quote', 1, ('{"text":"Autoregulation is a steering input, not a driver. Readiness is an interpretation, not a number."}')::jsonb, 'a0'),
  ('35a7126a-bc25-5479-b688-79218ffe6dd9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'fc50caa6-7214-5ec7-b094-b8084ed9102d', 'checklist', 1, ('{"items":[{"id":"548f2ae3-5150-5e19-9af4-8f6589ceb24f","text":"M11.1 Define autoregulation and its legitimate inputs"},{"id":"78c95c26-adf3-5188-8c81-9134f36e48cb","text":"M11.2 Apply RPE and RIR with their limitations"},{"id":"ece11783-cf89-5aff-967a-97b9e2a9e71e","text":"M11.3 State the evidence comparison position"},{"id":"7704b740-337e-54ae-b00d-d6313b1c6167","text":"M11.4 Interpret readiness with the five-component formula"},{"id":"3cb51436-11aa-5b81-81df-db8eb17d54e0","text":"M11.5 Explain why no single metric dictates change"},{"id":"23653dd3-0aa3-58e5-a347-5fe3ae0e8c34","text":"M11.6 Set boundaries by population"},{"id":"fb4a4015-90cf-5390-8efa-46c2c5b13bb2","text":"M11.7 Evaluate dashboards and vendor claims"}]}')::jsonb, 'a1'),
  ('fbfb27be-f097-57de-98bb-d99dec23ef08', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '97941cba-3d74-5a1b-b6a7-8f2f6b7a7122', 'heading', 1, ('{"text":"L11.1 What autoregulation is","level":3}')::jsonb, 'a0'),
  ('2f34b1b3-10be-5dc5-bac7-f4ddbb5f5eab', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '97941cba-3d74-5a1b-b6a7-8f2f6b7a7122', 'rich_text', 1, ('{"text":"Adjusting prescription using performance or perceptual feedback: RPE, RIR, velocity, structured readiness indicators, coach observation. It is a legitimate individualization method with supportive evidence — most of it in resistance-trained adults."}')::jsonb, 'a1'),
  ('fad940ec-3833-53e3-9de8-3ef6ffcf90ab', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '97941cba-3d74-5a1b-b6a7-8f2f6b7a7122', 'heading', 1, ('{"text":"L11.2 RPE and RIR in practice","level":3}')::jsonb, 'a2'),
  ('c1bb0099-1fed-5538-bcaf-dca457d57a81', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '97941cba-3d74-5a1b-b6a7-8f2f6b7a7122', 'rich_text', 1, ('{"text":"Teaching the scale, calibrating it with athletes, and recognizing that novice athletes'' ratings are less reliable and improve with coaching. Autoregulation depends on the athlete''s ability to report accurately; where that ability is undeveloped, the input is weak and should carry less weight."}')::jsonb, 'a3'),
  ('57ddb8f2-4bd5-5404-b525-effc9080563c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '97941cba-3d74-5a1b-b6a7-8f2f6b7a7122', 'heading', 1, ('{"text":"L11.3 The comparison that matters","level":3}')::jsonb, 'a4'),
  ('274e34ca-76a8-5fbc-860d-333e74ceb58b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '97941cba-3d74-5a1b-b6a7-8f2f6b7a7122', 'rich_text', 1, ('{"text":"Autoregulated and standardized load prescription often produce similar strength outcomes when both are well designed. The advantage of autoregulation is not uniform across studies. G3 therefore treats it as an individualization and monitoring tool rather than an upgrade. A poorly designed autoregulated program is not superior to a well-designed standardized one."}')::jsonb, 'a5'),
  ('a742c973-b9ac-5a5f-99e2-569dc1ca202d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '97941cba-3d74-5a1b-b6a7-8f2f6b7a7122', 'heading', 1, ('{"text":"L11.4 Population boundaries","level":3}')::jsonb, 'a6'),
  ('cabf755d-1d11-5ec9-acdf-30e71df75e36', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '97941cba-3d74-5a1b-b6a7-8f2f6b7a7122', 'rich_text', 1, ('{"text":"Evidence is stronger in resistance-trained adults than in youth or large team settings. In G3 Youth S&C, formal autoregulation systems are extrapolated from adult evidence and are used minimally — coach observation and simple effort language, not structured RIR systems. In large teams, autoregulation must be simple enough to be applied consistently by every coach in the room, or it produces noise rather than individualization."}')::jsonb, 'a7'),
  ('d7eddc4b-f1dc-5884-bfd5-356083cb675a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '97941cba-3d74-5a1b-b6a7-8f2f6b7a7122', 'heading', 1, ('{"text":"L11.5 Readiness is interpreted, not read","level":3}')::jsonb, 'a8'),
  ('b76c455e-1d66-5391-bb1b-871fd5f3745f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '97941cba-3d74-5a1b-b6a7-8f2f6b7a7122', 'rich_text', 1, ('{"text":"The formula is taught explicitly: **Baseline + Reliability + Context + Multiple Signals + Coaching Judgment**. Baseline: how does this athlete''s number normally behave? Reliability: how much does this measure move when nothing has changed? Context: what happened yesterday, this week, in school, in life? Multiple signals: do independent inputs converge? Judgment: what does the athlete look like in the room?"}')::jsonb, 'a9'),
  ('f4055c22-deaa-5f1d-82b1-ea8e09639e96', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '97941cba-3d74-5a1b-b6a7-8f2f6b7a7122', 'heading', 1, ('{"text":"L11.6 Why no single metric decides","level":3}')::jsonb, 'b0'),
  ('8016e8c8-5500-5d85-b72d-b504868d903e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '97941cba-3d74-5a1b-b6a7-8f2f6b7a7122', 'rich_text', 1, ('{"text":"No single wellness score, jump variable, HRV value, questionnaire, or wearable metric is established as a definitive daily decision trigger. Normal biological and measurement variability is the central constraint. A single low number, in isolation, is usually noise or context — not a training verdict."}')::jsonb, 'b1'),
  ('6c0bb46c-79fe-53bb-92cc-951aca6abd81', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '97941cba-3d74-5a1b-b6a7-8f2f6b7a7122', 'heading', 1, ('{"text":"L11.7 Skepticism toward dashboards","level":3}')::jsonb, 'b2'),
  ('81ac7b60-17d8-5123-95f8-752c3908b30d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '97941cba-3d74-5a1b-b6a7-8f2f6b7a7122', 'rich_text', 1, ('{"text":"Highly confident readiness dashboards, composite athlete scores, and automated recommendations deserve skepticism unless their validity and decision value are independently demonstrated. Vendor and platform claims about monitoring technology are not evidence. **This applies to G3''s own outputs.** A GPI readiness display is subject to the same scrutiny G3 applies to a purchased platform."}')::jsonb, 'b3'),
  ('b70f1cfd-056b-5ba6-89f7-213c9b4ff63c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '97941cba-3d74-5a1b-b6a7-8f2f6b7a7122', 'heading', 1, ('{"text":"L11.8 Decision boundaries","level":3}')::jsonb, 'b4'),
  ('68398731-51ae-594c-8005-87a10487206e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '97941cba-3d74-5a1b-b6a7-8f2f6b7a7122', 'rich_text', 1, ('{"text":"G3 sets what autoregulation may adjust and what it may not: it may adjust load within a defined range, volume within a defined range, and exercise complexity or regression. It may not silently change the session''s primary quality, reorder the priority, or convert a training day into a different program. Larger changes require a documented decision in the adjustment log, not an in-session drift."}')::jsonb, 'b5'),
  ('f3ea88e8-82bd-5896-add4-7269f543117d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '624a7e01-ba54-52db-a91c-e10558e30f30', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D10 — Autoregulation is a tool, not a religion","body":"G3 may use RPE, RIR, velocity, performance feedback, structured readiness indicators, and coach observation. Autoregulation can improve individualization but is not universally superior to well-designed standardized programming. — Teaching boundary: Never teach that autoregulation beats a fixed program. Compare design quality against design quality. — Evidence class: B/C"}')::jsonb, 'a0'),
  ('fa60408f-d066-5588-a976-1338cf186535', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '624a7e01-ba54-52db-a91c-e10558e30f30', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D11 — No single readiness metric runs the program","body":"No single wellness score, jump score, HRV value, questionnaire, subjective rating, or wearable metric automatically dictates training. Readiness is interpreted through Baseline + Reliability + Context + Multiple Signals + Coaching Judgment. — Teaching boundary: Confident dashboards, composite scores, and automated recommendations require independent validation - including G3''s own GPI outputs. — Evidence class: A/B"}')::jsonb, 'a1'),
  ('24aca1d5-0d4b-55eb-ba4f-d58906d832a0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '624a7e01-ba54-52db-a91c-e10558e30f30', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B — Supported Practice","body":"Autoregulation is a credible individualization method — Basis: [cite:20, cite:54, cite:61]"}')::jsonb, 'a2'),
  ('1d110144-ccb2-5774-bc9d-bec066af1204', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '624a7e01-ba54-52db-a91c-e10558e30f30', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B — Supported Practice, moderate","body":"Well-designed autoregulated and standardized prescription often produce similar strength outcomes — Basis: [cite:58, cite:52]"}')::jsonb, 'a3'),
  ('80e6b681-9399-5845-a7d0-023ad51c4a0c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '624a7e01-ba54-52db-a91c-e10558e30f30', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B — Supported Practice, high confidence","body":"No single readiness metric should automatically trigger program change — Basis: [cite:4, cite:20, cite:62]"}')::jsonb, 'a4'),
  ('bb89096b-097f-565c-84aa-d29fe501c076', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '624a7e01-ba54-52db-a91c-e10558e30f30', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A — Established Evidence","body":"Reliability and typical error govern interpretation of readiness measures — Basis: [cite:4, cite:14, cite:36]"}')::jsonb, 'a5'),
  ('83cb6ca6-7257-509c-897a-e8f5d3c07085', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '624a7e01-ba54-52db-a91c-e10558e30f30', 'callout', 2, ('{"tone":"info","title":"Evidence — Class C — Emerging Evidence","body":"Comparative rankings among autoregulation modalities — Basis: Recent network meta-analyses; recency and method heterogeneity require caution [cite:56, cite:60]"}')::jsonb, 'a6'),
  ('e8c56e14-d3a8-5f03-98f1-78d0d20542f9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '624a7e01-ba54-52db-a91c-e10558e30f30', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D — Applied Coaching Inference","body":"Autoregulation in youth and large team settings — Basis: Adult evidence extrapolated"}')::jsonb, 'a7'),
  ('8f8667e4-3d78-5500-989d-99ce64a89c5b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '624a7e01-ba54-52db-a91c-e10558e30f30', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"how much weight to place on any given readiness input on any given day. **Excluded from answer keys:** any claim that one autoregulation modality outperforms another."}')::jsonb, 'a8'),
  ('cdf95f5f-6378-5f3f-bc06-fd75734c120f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '624a7e01-ba54-52db-a91c-e10558e30f30', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Autoregulation as automatically superior · RIR with uncalibrated athletes · Gutting a session on one low score · Invented composite weightings · Accepting vendor validity claims · In-session drift replacing the priority"}')::jsonb, 'a9'),
  ('03684889-a4f6-5b96-805c-94d3eace7fbb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '8573465b-2b8a-5ae3-a849-2370cdacb7ce', 'rich_text', 1, ('{"text":"The practical G3 form is narrow and consistent: a defined load range for the primary lift, an RIR or RPE target the athlete has been coached to use, a regression available in every movement category, and a coach who looks at the athlete. Everything larger is a logged decision."}')::jsonb, 'a0'),
  ('b197261f-8973-5c9c-8338-b6ca95287cf2', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '8573465b-2b8a-5ae3-a849-2370cdacb7ce', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"Contributes to **PS-4**. Observed element: the coach makes a real in-session readiness decision and explains it correctly on the spot."}')::jsonb, 'a1'),
  ('17272359-6768-5c45-98ae-35e2c0800145', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b5432d29-e066-5ef9-9f0e-466f3658a957', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('042415e9-0269-5025-ae68-924f1231140d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b5432d29-e066-5ef9-9f0e-466f3658a957', 'assessment_reference', 1, ('{"assessmentId":"20762d58-cc6a-5947-95f4-fd0667256d6a","title":"G3-102 · M11 Assessment — Autoregulation & Readiness"}')::jsonb, 'a1'),
  ('ccba3313-44ae-5d3b-a869-25b87b86f565', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c991021f-667e-533e-b63f-47df799300ff', 'quote', 1, ('{"text":"The last question separates a coach from a program writer: what evidence would make you change your mind?"}')::jsonb, 'a0'),
  ('c64c55ba-523b-5d42-b562-2b17cbd76ae8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c991021f-667e-533e-b63f-47df799300ff', 'checklist', 1, ('{"items":[{"id":"d7ccde3b-cfd6-57e7-9604-07810393b920","text":"M12.1 Distinguish and order the four information layers"},{"id":"5e9e351e-d781-54e5-b18e-1933dfc48943","text":"M12.2 Explain why outcomes cannot evaluate training quality"},{"id":"e0d0575c-09fc-5863-99a1-0646c0143e74","text":"M12.3 Interpret retests against error"},{"id":"ad0ac9ef-de21-5bf5-bdfb-012094c03826","text":"M12.4 Diagnose delivery failure before physiological failure"},{"id":"45aeed75-9e74-51a2-8850-1a598c1be129","text":"M12.5 Choose among progress, hold, modify, re-enter"},{"id":"c966c699-d00a-52ed-98d3-6edffa6689ec","text":"M12.6 Maintain an adjustment log"},{"id":"8b5817a2-3855-54bb-909e-af0009dff9be","text":"M12.7 Reject fatigue as evidence"},{"id":"aad432ca-c4f4-5cf9-b9c6-f09cb88c1f08","text":"M12.8 Defend a decision under questioning"}]}')::jsonb, 'a1'),
  ('0e584f36-c960-5f1b-ab35-e21e9b3f538f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cb84882b-a367-5d1f-a6a0-b0bd6fc8aff7', 'heading', 1, ('{"text":"L12.1 The four information layers","level":3}')::jsonb, 'a0'),
  ('439fa4bd-5046-514f-a730-fe966bcb7203', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cb84882b-a367-5d1f-a6a0-b0bd6fc8aff7', 'rich_text', 1, ('{"text":"*Process*: was the program delivered as written — attendance, completion, coaching quality, session count actually achieved. *Training*: load, volume, intensity, execution quality, session RPE. *Performance*: retests interpreted against measurement error. *Outcome*: competitive results, availability, injury. Read them in that order. A program that was never delivered cannot be evaluated as a program."}')::jsonb, 'a1'),
  ('6e291d73-d4c3-58e4-976d-6795e100e22b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cb84882b-a367-5d1f-a6a0-b0bd6fc8aff7', 'heading', 1, ('{"text":"L12.2 Outcomes are the noisiest layer","level":3}')::jsonb, 'a2'),
  ('eca131d9-108b-5388-a6a5-cfe50705e3aa', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cb84882b-a367-5d1f-a6a0-b0bd6fc8aff7', 'rich_text', 1, ('{"text":"Competitive results are influenced by opponent, selection, tactics, teammates, officiating, and chance. They are the last layer to consult and the weakest evidence about training quality. Coaches are taught to say this to sport coaches without dismissiveness."}')::jsonb, 'a3'),
  ('a2417052-2adc-5f5d-9572-962c42be3054', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cb84882b-a367-5d1f-a6a0-b0bd6fc8aff7', 'heading', 1, ('{"text":"L12.3 Retest interpretation","level":3}')::jsonb, 'a4'),
  ('f8add0c7-0272-5e0b-8d6e-a97c5ffe3634', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cb84882b-a367-5d1f-a6a0-b0bd6fc8aff7', 'rich_text', 1, ('{"text":"Compare against typical error and the athlete''s baseline behavior, under comparable conditions. Arbitrary fixed-percentage thresholds are not well justified across settings. Where a change sits inside the noise band, the defensible statement is \"we cannot yet tell,\" and G3 treats that as a competent answer rather than an evasion."}')::jsonb, 'a5'),
  ('ff6c3bfa-0458-5245-9cef-ac93ab361a4f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cb84882b-a367-5d1f-a6a0-b0bd6fc8aff7', 'heading', 1, ('{"text":"L12.4 Fatigue is not evidence","level":3}')::jsonb, 'a6'),
  ('552cdc35-6ddf-5cc7-9c11-5b8ec7902728', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cb84882b-a367-5d1f-a6a0-b0bd6fc8aff7', 'rich_text', 1, ('{"text":"Fatigue may reflect productive overload, poor timing, insufficient recovery, or simply a hard session. It is not proof that training is working, and a program should never be justified by how tired it makes athletes."}')::jsonb, 'a7'),
  ('a6ecdc24-15fd-50c4-bfa9-5fe811e0d144', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cb84882b-a367-5d1f-a6a0-b0bd6fc8aff7', 'heading', 1, ('{"text":"L12.5 The four adjustment actions","level":3}')::jsonb, 'a8'),
  ('14defc67-201b-5c6b-8984-ad5ee83c48ef', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cb84882b-a367-5d1f-a6a0-b0bd6fc8aff7', 'rich_text', 1, ('{"text":"Progress · hold · modify · re-enter the model. Each requires a stated trigger and reasoning. **Holding is a decision and is logged as one.** Re-entering the model is required when the demand or the gap itself has changed — a new position, a new level, a return from injury, a changed schedule."}')::jsonb, 'a9'),
  ('356eaab4-48de-5cc1-9e62-1017c6fbcdbf', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cb84882b-a367-5d1f-a6a0-b0bd6fc8aff7', 'heading', 1, ('{"text":"L12.6 The adjustment log","level":3}')::jsonb, 'b0'),
  ('e4acbf67-f53c-5315-97b3-cf2e5f02fb1c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cb84882b-a367-5d1f-a6a0-b0bd6fc8aff7', 'rich_text', 1, ('{"text":"Date · action · trigger · reasoning · expected effect · review date. The log is what makes the next review possible and what allows a coach — or a successor — to reconstruct why a program looks the way it does. It is also the artifact examined in the final defense."}')::jsonb, 'b1'),
  ('b41274e1-4f69-5df4-9f2c-9e91c7baae5d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cb84882b-a367-5d1f-a6a0-b0bd6fc8aff7', 'heading', 1, ('{"text":"L12.7 Defending the decision","level":3}')::jsonb, 'b2'),
  ('b1c0afba-aa11-56f1-b313-7f5af6d79857', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'cb84882b-a367-5d1f-a6a0-b0bd6fc8aff7', 'rich_text', 1, ('{"text":"Coaches practice the defense out loud: what the demand was, what the profile showed, which gaps were carried and which set aside, what was prioritized and at what cost, what the program did, what the response showed, and what would change the plan. Under questioning. This is the terminal competency of G3 102."}')::jsonb, 'b3'),
  ('0dcfb28f-756e-5c14-a8df-377c113db3ec', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e5d1f8da-4f1c-5552-b589-350d95657b20', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D11 — No single readiness metric runs the program","body":"No single wellness score, jump score, HRV value, questionnaire, subjective rating, or wearable metric automatically dictates training. Readiness is interpreted through Baseline + Reliability + Context + Multiple Signals + Coaching Judgment. — Teaching boundary: Confident dashboards, composite scores, and automated recommendations require independent validation - including G3''s own GPI outputs. — Evidence class: A/B"}')::jsonb, 'a0'),
  ('7e6d6a73-30f1-5873-826c-08a63ae5d6be', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e5d1f8da-4f1c-5552-b589-350d95657b20', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D12 — Programs change for reasons","body":"Programs do not need to change because four weeks passed, the athlete is bored, or novelty appears advanced. Change is justified by adaptation, stagnation, technical mastery, pain, athlete response, schedule, phase objectives, progression needs, changing sport demands, or poor fit. — Teaching boundary: Absence of evidence for mandatory change is not evidence that programs should rarely change. A coach who never changes anything also fails this doctrine. — Evidence class: D"}')::jsonb, 'a1'),
  ('8ae4bec0-3ee0-56f8-8ee5-008b44e0aa0e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e5d1f8da-4f1c-5552-b589-350d95657b20', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B — Supported Practice","body":"Monitoring should distinguish process, training, performance, and outcome information — Basis: [cite:4, cite:20, cite:70]"}')::jsonb, 'a2'),
  ('554fe7b2-36af-5517-9839-2087a0302b8c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e5d1f8da-4f1c-5552-b589-350d95657b20', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B — Supported Practice","body":"Competitive outcomes alone are too noisy to evaluate training quality — Basis: [cite:20, cite:70]"}')::jsonb, 'a3'),
  ('b6bf5c46-56c7-5d11-97c9-0266705aa7bf', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e5d1f8da-4f1c-5552-b589-350d95657b20', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A — Established Evidence","body":"Reliability, typical error, and practical significance govern change interpretation — Basis: [cite:4, cite:14, cite:36]"}')::jsonb, 'a4'),
  ('b5427224-79f5-5436-949c-900838327214', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e5d1f8da-4f1c-5552-b589-350d95657b20', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B — Supported Practice","body":"Fatigue does not demonstrate program effectiveness — Basis: [cite:4, cite:20, cite:62]"}')::jsonb, 'a5'),
  ('52705ef5-50d7-5530-a9fe-47229e3995cb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e5d1f8da-4f1c-5552-b589-350d95657b20', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D — Applied Coaching Inference","body":"Change decisions depend on adaptation, response, schedule, mastery, pain, and fit rather than the calendar — Basis: [cite:4, cite:19, cite:20]"}')::jsonb, 'a6'),
  ('9c599de9-601d-58d4-ad4e-790a23d38e83', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e5d1f8da-4f1c-5552-b589-350d95657b20', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"when accumulated signals are sufficient to justify change. **Research gap acknowledged:** better guidance on when a monitored change is large enough and meaningful enough to justify a program change in field settings is an open need."}')::jsonb, 'a7'),
  ('32041c8c-f747-506a-a105-37e5e922e491', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e5d1f8da-4f1c-5552-b589-350d95657b20', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Evaluating by wins and losses · Blaming physiology for delivery failure · Retesting into noise · Fatigue as proof · Unlogged changes · Treating ''cannot yet tell'' as failure"}')::jsonb, 'a8'),
  ('a6b0f0ad-6397-5fd3-bb11-34167ed39667', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '8fc63bc7-e39e-5da2-8d7e-e090aa18d5e9', 'rich_text', 1, ('{"text":"Used at every G3 phase review and in every conversation with a sport coach about whether \"it''s working.\" The competent coach opens with process and training data, moves to performance interpreted against error, and treats results last — and does so without appearing defensive, because the sequence was decided before the season, not after the loss."}')::jsonb, 'a0'),
  ('bdac20bd-e773-587a-9086-59819cae829c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '8fc63bc7-e39e-5da2-8d7e-e090aa18d5e9', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"**PS-4 — Monitoring & Defense Sign-Off.** See §13.5. Includes the final oral defense."}')::jsonb, 'a1'),
  ('7ec52055-c31d-5baf-955c-d6981db52742', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'eab6b201-3136-5284-8af7-6043fde7fe3f', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('6d824707-0853-55c7-9388-13207d805116', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'eab6b201-3136-5284-8af7-6043fde7fe3f', 'assessment_reference', 1, ('{"assessmentId":"4b27f99f-d1dc-54b6-94fb-b251e8342b30","title":"G3-102 · M12 Assessment — Monitoring & Program Adjustment"}')::jsonb, 'a1'),
  ('95ab4f30-2712-5f90-86b6-8a2316ba15ba', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '42655c00-b57e-5bae-9248-7853ffba2ee7', 'callout', 2, ('{"tone":"info","title":"PS-4 — Observed practical sign-off","body":"Completed at: M12 — Function: terminal — This sign-off is observed and recorded by an approved G3 assessor. It cannot be self-recorded."}')::jsonb, 'a0'),
  ('3be5c1b4-2473-5527-acfa-7ec139da6d1c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '42655c00-b57e-5bae-9248-7853ffba2ee7', 'heading', 1, ('{"text":"Observed behaviors","level":3}')::jsonb, 'a1'),
  ('2829aa7b-4fff-5e2f-942b-3299e1993676', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '42655c00-b57e-5bae-9248-7853ffba2ee7', 'checklist', 1, ('{"items":[{"id":"95b62423-e12f-56cb-8ce5-dc595be5d408","text":"Makes a real in-session readiness decision and explains it using the five-component formula"},{"id":"1cb0034f-83a0-5c97-ab2f-f21488b577a5","text":"Completes a response review reading the four layers in order"},{"id":"c30a92ac-c267-53ca-9aff-9acf67777768","text":"States ''we cannot yet tell'' where honest, without hedging"},{"id":"ca522176-087c-56fb-8ed8-becad8530a25","text":"Logs a hold as a decision"},{"id":"c02e2d0b-7ae1-5c43-8043-8d708e16b96b","text":"Communicates a program decision accurately and briefly"}]}')::jsonb, 'a2'),
  ('af405cdc-933f-500c-9d1a-c6628f1e0b08', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '42655c00-b57e-5bae-9248-7853ffba2ee7', 'heading', 1, ('{"text":"Required artifacts","level":3}')::jsonb, 'a3'),
  ('da6e025a-17b4-58e5-962f-09c90243f894', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '42655c00-b57e-5bae-9248-7853ffba2ee7', 'checklist', 1, ('{"items":[{"id":"3635b85a-811a-51a7-aa3d-602c8bb4ab22","text":"A9"},{"id":"bf980986-b734-5b18-b475-9fbf2172aa38","text":"A11"},{"id":"524fe7a9-0837-51d1-9672-abc0b15bfa46","text":"A12"},{"id":"c9d1d2d6-c09a-5a90-a3b9-25be0b52c1eb","text":"delivered program (4-week minimum)"}]}')::jsonb, 'a4'),
  ('7c7f74ff-0c5c-51f7-905c-203c3b585660', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '42655c00-b57e-5bae-9248-7853ffba2ee7', 'heading', 1, ('{"text":"Assessor questions","level":3}')::jsonb, 'a5'),
  ('28db309c-05f0-5f0b-9b5f-c7bf8d7752a9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '42655c00-b57e-5bae-9248-7853ffba2ee7', 'checklist', 1, ('{"items":[{"id":"b76a0ddb-7d14-5161-8134-7b2783426547","text":"Show me where your stated priority appears in the actual session order."},{"id":"153eb8f3-1d47-5f21-9e3c-67a4ab11f67e","text":"Name one thing you decided not to train and what it is costing you."},{"id":"cc6dfc04-9f27-5c9b-b7f5-5fad8434edd4","text":"Which part of that is evidence, which is G3 standard, and which is your judgment?"},{"id":"d3dd2b99-051b-5dd0-9b7b-6e27b562b987","text":"What would make you change this program? Be specific."},{"id":"bc5726ef-7481-551c-a5a5-2674f0893925","text":"What would make you say you can''t tell yet?"}]}')::jsonb, 'a6'),
  ('ee96e382-7dda-56e4-9531-cad8895a571a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '42655c00-b57e-5bae-9248-7853ffba2ee7', 'callout', 2, ('{"tone":"warning","title":"Practical window","body":"This course carries a minimum four-week practical window. PS-4 cannot be scheduled until the delivery window is complete. Practical observation time is additional to directed study and is collected on the floor."}')::jsonb, 'a7'),
  ('29929658-beed-5326-b6a2-391a4ce2508b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9100252f-df00-597a-99ee-e23cc022d8c8', 'callout', 2, ('{"tone":"info","title":"T-01 — Terminal defense","body":"The defense is evaluated live by an approved G3 evaluator. Failure on T-01 cannot be offset by module performance."}')::jsonb, 'a0'),
  ('b1946b2b-e6df-51a3-86ae-afd7d9017894', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9100252f-df00-597a-99ee-e23cc022d8c8', 'callout', 2, ('{"tone":"info","title":"T-01 — Programming defense","body":"The coach walks a real program end to end through the decision model, out loud, under questioning from a G3 assessor, answering all nine questions from §1.3 including what evidence would change the plan. Failure on T-01 cannot be offset by module performance."}')::jsonb, 'a1'),
  ('0226bbe1-a5d9-5105-8a90-6a96472a8b83', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9100252f-df00-597a-99ee-e23cc022d8c8', 'callout', 2, ('{"tone":"warning","title":"Scheduling","body":"20–30 minutes with an approved assessor, using the coach''s own program and artifacts. The assessor works the nine questions in order and probes at least three. Scored on the defense rubric."}')::jsonb, 'a2'),
  ('7188b3b9-a00e-5dd7-9cbe-87a495568d7f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9100252f-df00-597a-99ee-e23cc022d8c8', 'callout', 2, ('{"tone":"warning","title":"Practical window","body":"This course carries a minimum four-week practical window.  Practical observation time is additional to directed study and is collected on the floor."}')::jsonb, 'a3')
insert into public.lesson_versions (id, organization_id, lesson_id, course_id, version_number, title, required, estimated_minutes, blocks, published_by) values
  ('7b0e1d2a-2d0d-5fcf-8f2b-fb86eeb34b34', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '513ecb1c-3fd4-5071-a89d-4921afe074de', '4832fade-c765-5fcd-b784-d1a4103394fd', 1, 'Overview & objectives', true, 6, (('[{"id":"7fbb2e42-8e3a-5e6a-bfa1-c4b506acba3c","type":"quote","schemaVersion":1,"data":{"text":"Needs analysis is not a form. It is the reason your program looks the way it does."},"position":"a0"},{"id":"c72df2d9-4c87-542f-9f5f-a2cc419bf7eb","type":"checklist","schemaVersion":1,"data":{"items":[{"id":"afbb71b9-f31c-57bc-b7ae-0f958add6c64","text":"M1.1 State the purpose of needs analysis in decision terms"},{"id":"6d9cc041-0b95-520c-b2f6-c953da0213af","text":"M1.2 Apply the decision test to any proposed assessment item"},{"id":"ff006ab8-b778-52e2-8986-462878993cfe","text":"M1.3 Name the ten decision categories"},{"id":"8917a3f5-7fb6-5dce-b7cb-a30fd26192cb","text":"M1.4 Describe the costs of undecidable data"},{"id":"8193ab3b-3c03-52a8-bd17-6c2cfb51bde4","text":"M1.5 Reproduce the decision model from memory"},{"id":"6cff92db-c69d-551e-b2d0-09f7723f794c","text":"M1.6 State the evidence standing of the model"}]},"position":"a1"},{"id":"3e8d4e36-03cd-5363-883d-1795f1e5fce3","type":"lesson_reference","schemaVersion":1,"data":{"courseId":"b17cac49-2d2b-59c4-bc80-5de456998e75","lessonId":"460effc6-93c3-5f5f-8336-fdae680089d1","label":"Recall — the G3 reasoning system (G3 101, Module 12)","'
