insert into public.assessment_items (id, organization_id, assessment_id, item_type, schema_version, data, position, required) values
  ('ff7b8f91-3eaf-565a-94f8-3e889ff57bbf', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a083bd6a-770a-5984-b7c4-dea633ea52b4', 'short_answer', 1, ('{"prompt":"K1.1 Which of the following best describes the purpose of a needs analysis in the G3 system?","instructions":"Source item format: MC. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10,"rubric":"Key: to change coaching decisions."}')::jsonb, 'a0', true),
  ('c96c37bb-b637-5de6-9a32-68ef75a8e470', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a083bd6a-770a-5984-b7c4-dea633ea52b4', 'short_answer', 1, ('{"prompt":"K1.2 Which decision categories may a needs-analysis item legitimately influence?","instructions":"Source item format: Select all. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10,"rubric":"Key: all ten listed."}')::jsonb, 'a1', true),
  ('3c8fbebd-09e2-5bbc-9718-42ff4011af70', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a083bd6a-770a-5984-b7c4-dea633ea52b4', 'short_answer', 1, ('{"prompt":"K1.3 A test that produces a reliable number no one will act on is best described as…","instructions":"Source item format: MC. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10,"rubric":"Key: a cost without a benefit."}')::jsonb, 'a2', true),
  ('1f970ba8-169e-5e8e-87d2-ee98ac185f62', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a083bd6a-770a-5984-b7c4-dea633ea52b4', 'short_answer', 1, ('{"prompt":"K1.4 State the evidence class of the G3 decision model and explain in one sentence why it carries that class.","instructions":"Source item format: Short answer. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a3', true),
  ('828c1751-7620-565a-a7fd-bf889bcbe208', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a083bd6a-770a-5984-b7c4-dea633ea52b4', 'short_answer', 1, ('{"prompt":"K1.5 Place the seven stages of the G3 decision model in sequence.","instructions":"Source item format: Ordering. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a4', true),
  ('46776001-7946-505f-9d7a-0b792744b9ff', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a083bd6a-770a-5984-b7c4-dea633ea52b4', 'long_answer', 1, ('{"prompt":"Applied competency A1 — Battery audit: The coach submits an assessment battery they currently use (or the one supplied for scholastic volleyball), annotated item by item with the decision category served and the decision that would change. Items that cannot be justified must be struck.","maxLength":20000,"points":20,"rubric":"Standard: every retained item carries a decision category; at least one item is struck or explicitly defended; the written rationale distinguishes decision-useful from merely measurable.. One revision permitted; applied work must reach standard."}')::jsonb, 'a5', true),
  ('daaf8ee5-0eca-53bf-b204-c14d9d17e74b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '28ffb2e7-07e7-5295-9093-bfd3c1d3cae0', 'short_answer', 1, ('{"prompt":"K2.1 Why can average match demands mislead a program designer?","instructions":"Source item format: MC. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a0', true),
  ('9aebc6b2-ebd8-5d7e-b3e7-cd8be974edc6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '28ffb2e7-07e7-5295-9093-bfd3c1d3cae0', 'short_answer', 1, ('{"prompt":"K2.2 Rolling averages are generally preferred over fixed epochs for estimating worst-case demands because…","instructions":"Source item format: MC. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a1', true),
  ('fe28feb6-7e36-514f-9197-031d878cbd20', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '28ffb2e7-07e7-5295-9093-bfd3c1d3cae0', 'short_answer', 1, ('{"prompt":"K2.3 Which of the following belong in a G3 sport demand profile?","instructions":"Source item format: Select all. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a2', true),
  ('cb801cd7-c443-522f-8472-b2c30b45a9d7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '28ffb2e7-07e7-5295-9093-bfd3c1d3cae0', 'short_answer', 1, ('{"prompt":"K2.4 State one limitation of the peak-demand evidence base and how it constrains what you would claim to a sport coach.","instructions":"Source item format: Short answer. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a3', true),
  ('07b45981-5e62-53a5-acca-cbe372e9c5b8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '28ffb2e7-07e7-5295-9093-bfd3c1d3cae0', 'short_answer', 1, ('{"prompt":"K2.5 Given two positional demand summaries, identify the two demands that most differentiate them.","instructions":"Source item format: Interpretation. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a4', true),
  ('795458d8-cb47-5fdc-bd3a-8553c3cf9f55', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '28ffb2e7-07e7-5295-9093-bfd3c1d3cae0', 'long_answer', 1, ('{"prompt":"Applied competency A2 — Sport Demand Profile: The coach produces a complete written demand profile for one G3 sport-position group they actually work with, across all twelve categories, with each element labeled measured/estimated/assumed, and with a ranked top-five.","maxLength":20000,"points":20,"rubric":"Standard: all twelve categories addressed; labeling applied consistently; ranked demands are defensible against the competition and practice schedule supplied; peak passages identified separately from average demands.. One revision permitted; applied work must reach standard."}')::jsonb, 'a5', true),
  ('a2726cd9-fd84-5f3f-91b7-3c438da72aae', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6239c630-0ee2-508a-bf8c-ddbb11d84596', 'short_answer', 1, ('{"prompt":"K3.1 Which domains are required in a G3 athlete profile?","instructions":"Source item format: Select all. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a0', true),
  ('9ed27a9c-5ce3-5b53-b5ff-4a93f0c16eb1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6239c630-0ee2-508a-bf8c-ddbb11d84596', 'short_answer', 1, ('{"prompt":"K3.2 Training age is best described as…","instructions":"Source item format: MC. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a1', true),
  ('7de4ff42-da79-5c1a-bca9-f8998f4dd30e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6239c630-0ee2-508a-bf8c-ddbb11d84596', 'short_answer', 1, ('{"prompt":"K3.3 A retest is performed on a different surface, in different footwear, at a different point in the week. The result is 4% higher. The correct interpretation is…","instructions":"Source item format: MC. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a2', true),
  ('d0cebcea-ef6d-59b2-b343-1c56463cc606', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6239c630-0ee2-508a-bf8c-ddbb11d84596', 'short_answer', 1, ('{"prompt":"K3.4 \"Resistance training is unsafe until an athlete finishes growing.\"","instructions":"Source item format: True/False with justification. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10,"rubric":"Key: false; the learner must state the supervision and progression conditions."}')::jsonb, 'a3', true),
  ('41217ae0-266b-5615-a97f-31053030dbb9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6239c630-0ee2-508a-bf8c-ddbb11d84596', 'short_answer', 1, ('{"prompt":"K3.5 At which stage of the G3 decision model does GPI output enter, and at which stage may it never be used as an instruction?","instructions":"Source item format: Short answer. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a4', true),
  ('b19304c0-5623-53f6-901b-b046005a6851', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6239c630-0ee2-508a-bf8c-ddbb11d84596', 'long_answer', 1, ('{"prompt":"Applied competency A3 — Athlete Profile build: The coach builds a complete profile for one current athlete across all six domains, with recorded testing conditions and a written statement of what each performance measure is expected to inform.","maxLength":20000,"points":20,"rubric":"Standard: all domains present; conditions recorded; every measure connected to a decision; no item present that the coach cannot justify.. One revision permitted; applied work must reach standard."}')::jsonb, 'a5', true),
  ('9621202b-bb6c-5d0a-9a86-e0a18c4d1650', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '2b6b81ea-a669-5bfa-b02c-ff93a1007a53', 'short_answer', 1, ('{"prompt":"K4.1 The difference between a measured deficit and a probable limiting factor is best described as…","instructions":"Source item format: MC. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a0', true),
  ('f0dff2f4-6dea-5caa-b27a-b20f83638ed0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '2b6b81ea-a669-5bfa-b02c-ff93a1007a53', 'short_answer', 1, ('{"prompt":"K4.2 A vertical jump test with a typical error of roughly 2 cm shows a 1.5 cm improvement. The defensible interpretation is…","instructions":"Source item format: Interpretation. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a1', true),
  ('502110be-9c48-5ab0-bcfa-8290a4fe516b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '2b6b81ea-a669-5bfa-b02c-ff93a1007a53', 'short_answer', 1, ('{"prompt":"K4.3 Which conditions strengthen a deficit''s claim on programming priority?","instructions":"Source item format: Select all. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a2', true),
  ('cc73b4d0-42db-52b7-b50e-7930dd58d3fe', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '2b6b81ea-a669-5bfa-b02c-ff93a1007a53', 'short_answer', 1, ('{"prompt":"K4.4 Identify the flaw: \"The test identified his limiting factor as posterior-chain strength.\"","instructions":"Source item format: Error identification. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a3', true),
  ('22f30556-c9f6-5636-80a5-c1cd6e200b18', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '2b6b81ea-a669-5bfa-b02c-ff93a1007a53', 'short_answer', 1, ('{"prompt":"K4.5 Why does field testing rarely establish causation?","instructions":"Source item format: Short answer. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a4', true),
  ('f996714f-a74d-55a9-8014-ac752b35e315', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '2b6b81ea-a669-5bfa-b02c-ff93a1007a53', 'long_answer', 1, ('{"prompt":"Applied competency A4 — Gap Statement: Given a supplied athlete profile and demand profile (or the coach''s own athlete from A2/A3), produce a written Gap Statement with all three lists and a one-paragraph rationale for each probable limiting factor carried forward.","maxLength":20000,"points":20,"rubric":"Standard: every carried-forward item passes both filters explicitly; at least one real difference is set aside with reasoning; no causal language; no item acted on inside the noise band.. One revision permitted; applied work must reach standard."}')::jsonb, 'a5', true),
  ('b2b1874a-5108-577a-b692-3ea3ec4f4674', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '042608a9-bb8a-5569-8b6c-c289ea9c513a', 'short_answer', 1, ('{"prompt":"K5.1 The G3 position on \"always train the weakest quality first\" is best stated as…","instructions":"Source item format: MC. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a0', true),
  ('67ea1f0b-20a1-52b8-85fb-5eb70166312e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '042608a9-bb8a-5569-8b6c-c289ea9c513a', 'short_answer', 1, ('{"prompt":"K5.2 Which considerations belong in a prioritization decision?","instructions":"Source item format: Select all. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a1', true),
  ('edfa1350-17d2-5026-9ee0-0e87d6c43b32', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '042608a9-bb8a-5569-8b6c-c289ea9c513a', 'short_answer', 1, ('{"prompt":"K5.3 A quality in \"maintenance\" should be understood as…","instructions":"Source item format: MC. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a2', true),
  ('4bc4ba61-d84c-5c05-98ed-145d25541bee', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '042608a9-bb8a-5569-8b6c-c289ea9c513a', 'short_answer', 1, ('{"prompt":"K5.4 A program lists six primary development qualities. Identify the error and its consequence.","instructions":"Source item format: Error identification. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a3', true),
  ('cfc85ceb-f42e-5e30-800a-b3301e3cd16a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '042608a9-bb8a-5569-8b6c-c289ea9c513a', 'short_answer', 1, ('{"prompt":"K5.5 Give one legitimate reason to further develop an athlete''s existing strength.","instructions":"Source item format: Short answer. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a4', true),
