  ('89bf0ecd-d392-514d-bfeb-dd49cabfbe83', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4832fade-c765-5fcd-b784-d1a4103394fd', '42655c00-b57e-5bae-9248-7853ffba2ee7', 'practical_sign_off', 'PS-4', 'Monitoring & Defense Sign-Off', array['C-13','C-14','C-15','T-01']::text[], ('{"dimensions":["completeness","reasoning quality","deliverability","evidence honesty"],"scale":"0-3","pass":"2 = at standard"}')::jsonb, 'M12 — Record: ["coach_id","sign_off_id","assessor_id","date","environment","athlete_or_group_ref","behaviors_observed","artifacts","questions_asked","outcome","expiry_date","notes"] — Minimum four-week practical window per course. Every recorded result carries the evaluator''s identity; results are immutable once recorded — corrections are new records.', '00000000-0000-4000-8000-000000000031'),
  ('b0a5c04d-7425-5719-8a14-e14bd7e0c4e1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4832fade-c765-5fcd-b784-d1a4103394fd', '9100252f-df00-597a-99ee-e23cc022d8c8', 'terminal_defense', 'T-01', 'Terminal Defense', array['C-01','C-02','C-03','C-04','C-05','C-06','C-07','C-08','C-09','C-10','C-11','C-12','C-13','C-14','C-15','T-01']::text[], ('{"dimensions":["model fluency","cost articulation","evidence honesty","falsifiability","communication"],"scale":"0-3","pass":"11/15, no dimension below 2, never 0 on evidence honesty"}')::jsonb, 'Minimum four-week practical window per course. Every recorded result carries the evaluator''s identity; results are immutable once recorded — corrections are new records.', '00000000-0000-4000-8000-000000000031')
insert into public.curriculum_records (id, organization_id, course_id, kind, code, title, data, position) values
  ('17db039a-e701-54d4-a6bc-dfe853842e59', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4832fade-c765-5fcd-b784-d1a4103394fd', 'doctrine', 'D1', 'Needs analysis must change decisions', ('{"id":"D1","title":"Needs analysis must change decisions","statement":"Assessment exists to improve coaching decisions. A test, metric, questionnaire, or observation earns its place when it can meaningfully influence exercise selection, training priority, load, volume, progression, regression, recovery, readiness modification, return-to-performance decisions, or program evaluation. G3 favors decision-useful information over maximal data collection.","evidence_class":"B","teaching_boundary":"Do not teach that a specific battery size is correct. Teach that unused data has a cost that must be earned.","modules":["M1","M3"],"citation_tags":["cite:4","cite:20","cite:48"],"standing":"G3 Doctrine"}')::jsonb, 'a0'),
  ('4f9ee1e1-d16b-59aa-8951-def052fb3ff8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4832fade-c765-5fcd-b784-d1a4103394fd', 'doctrine', 'D2', 'Sport demand is more than the average', ('{"id":"D2","title":"Sport demand is more than the average","statement":"Sport-demand analysis must consider movement, force, velocity, power, energetic, repeated-effort, and positional demands, competition and practice density, peak or worst-case passages, injury exposure, and season structure. Average match demands can conceal the highest-performance requirements.","evidence_class":"B","teaching_boundary":"Peak-demand evidence is largely locomotor and largely professional. Teach peak-demand thinking without claiming measurement precision the environment does not have.","modules":["M2"],"citation_tags":["cite:18","cite:22"],"standing":"G3 Doctrine"}')::jsonb, 'a1'),
  ('b1d5945f-9ae7-5a11-abd8-13abf5136e43', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4832fade-c765-5fcd-b784-d1a4103394fd', 'doctrine', 'D3', 'A deficit is not automatically a limiting factor', ('{"id":"D3","title":"A deficit is not automatically a limiting factor","statement":"G3 distinguishes a measured deficit from a probable performance limiting factor. A deficit''s claim strengthens when it matters to the sport or role, is meaningfully below the required level, can be changed, is relevant to current performance, can be addressed at acceptable cost, and deserves emphasis relative to competing priorities. Testing identifies information; coaching determines significance.","evidence_class":"B/D","teaching_boundary":"No G3 material may state that a test identifies a limiting factor. The term ''confirmed limiting factor'' is prohibited.","modules":["M4"],"citation_tags":["cite:4","cite:20","cite:27"],"standing":"G3 Doctrine"}')::jsonb, 'a2'),
  ('460cce7b-c87d-56f5-b2fb-fe78fc7f669d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4832fade-c765-5fcd-b784-d1a4103394fd', 'doctrine', 'D4', 'Priority is a relevance x opportunity-cost decision', ('{"id":"D4","title":"Priority is a relevance x opportunity-cost decision","statement":"G3 does not adopt ''always train the greatest weakness.'' Priority considers sport relevance, deficit magnitude, athlete level, training age, phase, injury/availability, adaptation potential, time, practice and competition demands, fatigue cost, interference, maintenance requirements, and expected performance return. A strength may deserve development; a weakness may deserve maintenance or no direct intervention.","evidence_class":"B/C","teaching_boundary":"Prioritization worksheets organize judgment; they never compute an answer. No weighted priority score may be created.","modules":["M5"],"citation_tags":["cite:19","cite:20","cite:35","cite:48"],"standing":"G3 Doctrine"}')::jsonb, 'a3'),
  ('5a72883a-22b9-58b7-834e-a55d2a08a4a6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4832fade-c765-5fcd-b784-d1a4103394fd', 'doctrine', 'D5', 'Exercise selection serves adaptation', ('{"id":"D5","title":"Exercise selection serves adaptation","statement":"Do not confuse visual resemblance to sport with transfer. Selection considers desired adaptation, competency, loading potential, velocity, intent, range of motion, complexity, fatigue cost, risk/reward, equipment, history, training age, progression potential, and place in the total program.","evidence_class":"A/B","teaching_boundary":"Rejecting resemblance-as-transfer is not rejecting specificity of adaptation.","modules":["M6"],"citation_tags":["cite:34","cite:43"],"standing":"G3 Doctrine"}')::jsonb, 'a4'),
  ('70bc8e26-3cbb-50d9-9300-5824e73c0b6b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4832fade-c765-5fcd-b784-d1a4103394fd', 'doctrine', 'D6', 'Priority determines order', ('{"id":"D6","title":"Priority determines order","statement":"Exercises and qualities placed earlier in a session generally receive greater performance capacity. Session order reflects training priority rather than habit.","evidence_class":"A","teaching_boundary":"Order effects are clearest in untrained to moderately trained populations. Do not teach a numeric penalty for ordering second.","modules":["M7"],"citation_tags":["cite:19","cite:43"],"standing":"G3 Doctrine"}')::jsonb, 'a5'),
  ('1067b71f-8670-51c1-94f5-20b33a975903', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4832fade-c765-5fcd-b784-d1a4103394fd', 'doctrine', 'D7', 'Multiple qualities can be developed concurrently', ('{"id":"D7","title":"Multiple qualities can be developed concurrently","statement":"Strength, speed, power, conditioning, and movement skill can coexist in a program. Concurrent does not mean equal emphasis: programs distinguish primary development, secondary development, maintenance, and exposure qualities. Interference is conditional and managed through sequencing, spacing, modality, volume, intensity, recovery, training status, and schedule.","evidence_class":"A/B/C","teaching_boundary":"No numeric interference thresholds or mandatory spacing presented as evidence. G3 spacing conventions are Applied Standards.","modules":["M8"],"citation_tags":["cite:5","cite:35","cite:63","cite:68","cite:71"],"standing":"G3 Doctrine"}')::jsonb, 'a6'),
  ('9fd17919-419c-544b-a97b-634d7fbc3ccf', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4832fade-c765-5fcd-b784-d1a4103394fd', 'doctrine', 'D8', 'Individualization does not require unique programs for everyone', ('{"id":"D8","title":"Individualization does not require unique programs for everyone","statement":"Standardize where athletes are similar; individualize where differences matter. Teams standardize session structure, movement categories, objectives, coaching language, and progression framework, and individualize through variation, load, volume, complexity, range of motion, progression rate, regression, substitution, and readiness adjustment.","evidence_class":"D","teaching_boundary":"Taught explicitly as applied inference, while binding as a G3 Applied Standard for team environments.","modules":["M10"],"citation_tags":["cite:19","cite:20","cite:35","cite:51"],"standing":"G3 Doctrine"}')::jsonb, 'a7'),
  ('c98301df-a69e-53b4-a688-07236ad9d242', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4832fade-c765-5fcd-b784-d1a4103394fd', 'doctrine', 'D9', 'Youth training is readiness-based, not age-myth-based', ('{"id":"D9","title":"Youth training is readiness-based, not age-myth-based","statement":"Supervised progressive resistance training is appropriate for youth. Readiness considers instructional responsiveness, psychological readiness, movement competency, maturity, training history, supervision, and progression.","evidence_class":"A","teaching_boundary":"The safety and efficacy claim is conditioned on supervision and progression; state both conditions whenever the claim is made.","modules":["M10","M3"],"citation_tags":["cite:3","cite:38","cite:44","cite:53","cite:55","cite:57"],"standing":"G3 Doctrine"}')::jsonb, 'a8'),
  ('96966734-7af8-5d94-bebb-dfdde712adcf', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4832fade-c765-5fcd-b784-d1a4103394fd', 'doctrine', 'D10', 'Autoregulation is a tool, not a religion', ('{"id":"D10","title":"Autoregulation is a tool, not a religion","statement":"G3 may use RPE, RIR, velocity, performance feedback, structured readiness indicators, and coach observation. Autoregulation can improve individualization but is not universally superior to well-designed standardized programming.","evidence_class":"B/C","teaching_boundary":"Never teach that autoregulation beats a fixed program. Compare design quality against design quality.","modules":["M11"],"citation_tags":["cite:20","cite:54","cite:56","cite:58","cite:60","cite:61"],"standing":"G3 Doctrine"}')::jsonb, 'a9'),
  ('39300094-eddd-56b7-a03b-8b19a348e282', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4832fade-c765-5fcd-b784-d1a4103394fd', 'doctrine', 'D11', 'No single readiness metric runs the program', ('{"id":"D11","title":"No single readiness metric runs the program","statement":"No single wellness score, jump score, HRV value, questionnaire, subjective rating, or wearable metric automatically dictates training. Readiness is interpreted through Baseline + Reliability + Context + Multiple Signals + Coaching Judgment.","evidence_class":"A/B","teaching_boundary":"Confident dashboards, composite scores, and automated recommendations require independent validation - including G3''s own GPI outputs.","modules":["M11","M12"],"citation_tags":["cite:4","cite:14","cite:20","cite:36","cite:62"],"standing":"G3 Doctrine"}')::jsonb, 'b0'),
  ('6ba6c9af-d375-50ce-aff7-a743b9b486fa', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4832fade-c765-5fcd-b784-d1a4103394fd', 'doctrine', 'D12', 'Programs change for reasons', ('{"id":"D12","title":"Programs change for reasons","statement":"Programs do not need to change because four weeks passed, the athlete is bored, or novelty appears advanced. Change is justified by adaptation, stagnation, technical mastery, pain, athlete response, schedule, phase objectives, progression needs, changing sport demands, or poor fit.","evidence_class":"D","teaching_boundary":"Absence of evidence for mandatory change is not evidence that programs should rarely change. A coach who never changes anything also fails this doctrine.","modules":["M9","M12"],"citation_tags":["cite:4","cite:19","cite:20","cite:27"],"standing":"G3 Doctrine"}')::jsonb, 'b1'),
  ('7e9ccccd-f72e-5ab5-8e8a-75df5cd725ba', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4832fade-c765-5fcd-b784-d1a4103394fd', 'applied_standard', 'AS-01', 'AS-01', ('{"id":"AS-01","domain":"assessment","text":"Every assessment item is traceable to at least one of the ten decision categories, documented when the battery is built.","evidence_basis":"D","standing":"applied_standard","note":null}')::jsonb, 'b2'),
  ('09ef5733-7f57-57dc-be51-3e5f65dbde76', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4832fade-c765-5fcd-b784-d1a4103394fd', 'applied_standard', 'AS-02', 'AS-02', ('{"id":"AS-02","domain":"assessment","text":"The G3 decision model is the required reasoning sequence for all G3 program documentation.","evidence_basis":"D","standing":"applied_standard","note":null}')::jsonb, 'b3'),
  ('14e50af1-2f6c-5251-a997-3843bfc34c52', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4832fade-c765-5fcd-b784-d1a4103394fd', 'applied_standard', 'AS-03', 'AS-03', ('{"id":"AS-03","domain":"demand","text":"Every team and sport-group program is preceded by a written Sport Demand Profile, reviewed annually or on change of level or role.","evidence_basis":"D","standing":"applied_standard","note":null}')::jsonb, 'b4'),
  ('0104d2fd-465b-5bc6-9f43-d80252f3dd91', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4832fade-c765-5fcd-b784-d1a4103394fd', 'applied_standard', 'AS-04', 'AS-04', ('{"id":"AS-04","domain":"demand","text":"Demand profiles label every element measured, estimated, or assumed.","evidence_basis":"D","standing":"applied_standard","note":null}')::jsonb, 'b5'),
  ('3cfb7239-9d92-59a5-a350-14466b93a59d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4832fade-c765-5fcd-b784-d1a4103394fd', 'applied_standard', 'AS-05', 'AS-05', ('{"id":"AS-05","domain":"profile","text":"All six profile domains are completed for athletes carrying individual programs; team athletes carry domains (i)-(iv) at minimum.","evidence_basis":"D","standing":"applied_standard","note":null}')::jsonb, 'b6'),
