insert into public.content_blocks (id, organization_id, lesson_id, block_type, schema_version, data, position) values
  ('0664f4d8-f321-584d-9cf2-3e129f8589ae', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c6a2a08c-de04-5172-982c-5971351f8a33', 'quote', 1, ('{"text":"Every bad speed program starts with a word."}')::jsonb, 'a0'),
  ('2f45796e-20b9-5123-a84a-82df34577dd7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c6a2a08c-de04-5172-982c-5971351f8a33', 'rich_text', 1, ('{"text":"To install the controlled vocabulary the rest of the course depends on, and to make the learner capable of naming the quality a task actually trains before any programming decision is made."}')::jsonb, 'a1'),
  ('b5f01235-fcfa-544f-8c08-fbab43d5d7c6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c6a2a08c-de04-5172-982c-5971351f8a33', 'checklist', 1, ('{"items":[{"id":"3c1cca94-5b02-5864-862c-0ecb7d76001a","text":"M1.1 Define speed, acceleration, maximal velocity, deceleration, COD, agility, reactive agility using G3 definitions"},{"id":"0f0dd205-96d0-5a01-98e0-5924377ef9ec","text":"M1.2 Explain why acceleration and maximal velocity are distinct qualities"},{"id":"eeae3418-fbaa-5efe-a08c-cebb3d9fbb19","text":"M1.3 Explain why COD and agility are distinct constructs"},{"id":"24df550f-acdf-59f6-a212-5a10bafd21dc","text":"M1.4 Apply the five task-identification questions"},{"id":"2e4c4e94-5be2-584a-949d-addba01d01d5","text":"M1.5 Describe COD deficit as a task-dependent lens"},{"id":"a1ddfca6-26e9-5f94-a20f-e63c77c1e7cf","text":"M1.6 State why G3 does not use SAQ as a precise category"},{"id":"47ff871b-a066-565e-a13a-d9621fd222c7","text":"M1.7 Identify where terminology remains unsettled"}]}')::jsonb, 'a2'),
  ('0c407752-f3b5-5269-8dc5-ad88f2e5f803', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c6a2a08c-de04-5172-982c-5971351f8a33', 'callout', 2, ('{"tone":"info","title":"Sequence & gating","body":"[object Object]"}')::jsonb, 'a3'),
  ('f2ed137d-fcd0-57f2-992d-60ed1fd54158', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c6a2a08c-de04-5172-982c-5971351f8a33', 'lesson_reference', 1, ('{"courseId":"b17cac49-2d2b-59c4-bc80-5de456998e75","lessonId":"460effc6-93c3-5f5f-8336-fdae680089d1","label":"Recall — the G3 reasoning system (G3 101, Module 12)","note":"Evidence classes, certainty language, and the three-layer discipline are governed by G3 101."}')::jsonb, 'a4'),
  ('5e369984-a73a-5ae9-ba50-a5d6ba726997', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c6a2a08c-de04-5172-982c-5971351f8a33', 'lesson_reference', 1, ('{"courseId":"4832fade-c765-5fcd-b784-d1a4103394fd","lessonId":"81e0bab6-4baa-5a42-93cb-7c47b740ac4f","label":"Recall — the G3 programming decision model (G3 102, Module 1)","note":"DEMAND → PROFILE → GAP → PRIORITY → PRESCRIPTION → RESPONSE → ADJUST is governed by G3 102 and is never modified downstream."}')::jsonb, 'a5'),
  ('8c060889-9f3e-51c5-8119-f00f2a096e7e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52980f1e-7932-5d10-a9db-e56090848fc9', 'heading', 1, ('{"text":"L1.1 Why the word matters","level":3}')::jsonb, 'a0'),
  ('71efe680-21fc-5f65-8477-09572540032a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52980f1e-7932-5d10-a9db-e56090848fc9', 'rich_text', 1, ('{"text":"One session, four \"speed\" activities, four different adaptations. The cost of the collapsed vocabulary is that the coach cannot say what any of it was for."}')::jsonb, 'a1'),
  ('3f77c7e1-e230-51d2-9d41-4bc0a4d81dca', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52980f1e-7932-5d10-a9db-e56090848fc9', 'heading', 1, ('{"text":"L1.2 Speed, acceleration, maximal velocity","level":3}')::jsonb, 'a2'),
  ('e2ca9f92-17c2-53ff-bcd0-72424b1bf0d5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52980f1e-7932-5d10-a9db-e56090848fc9', 'rich_text', 1, ('{"text":"Speed as umbrella; acceleration as building velocity from a slower or stationary state; maximal velocity as the highest velocity achieved under the task''s constraints. The phase distinction is established; the boundary is not. G3 publishes no universal distance cut-point, and coaches should be suspicious of anyone who does."}')::jsonb, 'a3'),
  ('4df51e1a-6549-5a53-a9d3-a2512d248f0b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52980f1e-7932-5d10-a9db-e56090848fc9', 'heading', 1, ('{"text":"L1.3 Deceleration","level":3}')::jsonb, 'a4'),
  ('6ab78d68-1721-5685-9ac5-c8ae7aa700f5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52980f1e-7932-5d10-a9db-e56090848fc9', 'rich_text', 1, ('{"text":"Braking impulse, momentum control, eccentric loading, postural organization. Named as its own demand here so that it is not silently absorbed into COD in M8."}')::jsonb, 'a5'),
  ('ee4dfcab-f4a1-5834-889b-160121f341e5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52980f1e-7932-5d10-a9db-e56090848fc9', 'heading', 1, ('{"text":"L1.4 COD and agility","level":3}')::jsonb, 'a6'),
  ('d20e5637-eb24-5c81-b10a-846479fb9d47', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52980f1e-7932-5d10-a9db-e56090848fc9', 'rich_text', 1, ('{"text":"COD: the movement solution is known before execution. Agility: a rapid whole-body response to an external stimulus, containing perceptual and decision demands. Reactive agility as the operational term for tasks with a live or simulated cue."}')::jsonb, 'a7'),
  ('cb3cd17f-4e68-5a7c-b20e-a6590088e956', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52980f1e-7932-5d10-a9db-e56090848fc9', 'heading', 1, ('{"text":"L1.5 The five task-identification questions","level":3}')::jsonb, 'a8'),
  ('dedf0450-f99b-566c-b925-ba693f899974', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52980f1e-7932-5d10-a9db-e56090848fc9', 'rich_text', 1, ('{"text":"Applied to eight tasks on video: a block start, a flying 20, a shuttle, a shuffle-and-react, a ladder sequence, a hard braking stop, a 45° cut, a small-sided game moment. The learner names the quality and the demand for each, and states which are pre-planned."}')::jsonb, 'a9'),
  ('c5547974-a038-54f0-9ffd-7dcdc3117735', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52980f1e-7932-5d10-a9db-e56090848fc9', 'heading', 1, ('{"text":"L1.6 COD deficit, honestly","level":3}')::jsonb, 'b0'),
  ('b7ce1675-9434-5d18-92b9-28f3d61888ab', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52980f1e-7932-5d10-a9db-e56090848fc9', 'rich_text', 1, ('{"text":"What it attempts, why it is attractive, and why it remains task-dependent and cannot be treated as an isolated measure of \"true COD ability.\""}')::jsonb, 'b1'),
  ('5af47a2e-63de-527a-bd4c-d4c79059210e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52980f1e-7932-5d10-a9db-e56090848fc9', 'heading', 1, ('{"text":"L1.7 SAQ and unsettled language","level":3}')::jsonb, 'b2'),
  ('b605fed0-be5e-5ff3-b8b7-ac807a43f73e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52980f1e-7932-5d10-a9db-e56090848fc9', 'rich_text', 1, ('{"text":"SAQ is discussed as a historically influential category, not a precise one. Terminology in the wider literature — agility, reactive agility, COD speed, sport agility — is not fully consistent, and G3''s definitions govern inside G3 rather than claiming the field has reached consensus."}')::jsonb, 'b3'),
  ('14b64677-36d4-5613-b1a1-6c34b6ca1838', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ed6cc894-0043-58ba-8c83-af618ad35808', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-1 — Speed Is Phase-Specific","body":"Acceleration and maximal velocity are related but distinct sprint qualities. Coaches identify which speed demand is being trained or assessed rather than treating sprint performance as one undifferentiated quality. — Teaching boundary: The distinction is established; exact phase boundaries are not. G3 publishes no universal distance cut-point. — Evidence class: A"}')::jsonb, 'a0'),
  ('131519d8-ed8d-5939-b1a5-fc6c403dd040', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ed6cc894-0043-58ba-8c83-af618ad35808', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-5 — COD Is Not Agility","body":"Pre-planned COD and agility are different constructs. COD involves a known movement solution. Agility requires perception, decision, and response to external information. — Teaching boundary: Distinct does not mean unrelated. The doctrine forbids treating them as the same, not as connected. — Evidence class: A"}')::jsonb, 'a1'),
  ('0aba1a13-24c9-51d6-98ca-061622efaeae', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ed6cc894-0043-58ba-8c83-af618ad35808', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-6 — Closed Drills Do Not Automatically Train Agility","body":"Cone patterns, ladders, and pre-planned movement drills may train coordination, rhythm, movement skill, or COD. They are not labeled true agility development unless meaningful external information and response demands are present. — Teaching boundary: Closed drills are not condemned. The error is the label, not the drill. — Evidence class: B"}')::jsonb, 'a2'),
  ('343c0536-6abd-5246-8659-1f02769a7df8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ed6cc894-0043-58ba-8c83-af618ad35808', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Sprint performance is phase-specific; acceleration and maximal velocity are distinct — Basis: EP103-01, EP103-13 · cite:96, cite:101"}')::jsonb, 'a3'),
  ('19865ade-18be-5174-a8e5-de5357f98871', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ed6cc894-0043-58ba-8c83-af618ad35808', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A (a statement about the limits of the evidence)","body":"Exact phase boundaries vary by task, athlete level, and testing distance — Basis: EP103-01, EP103-13"}')::jsonb, 'a4'),
  ('1086bb9d-1069-5e9a-9a3d-967588e721e7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ed6cc894-0043-58ba-8c83-af618ad35808', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"COD and agility are distinct constructs; agility includes perception and decision-making — Basis: EP103-04, EP103-19, EP103-21"}')::jsonb, 'a5'),
  ('c25078e9-7691-52d1-9894-2c3106f99de8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ed6cc894-0043-58ba-8c83-af618ad35808', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Deceleration is a distinct athletic demand — Basis: EP103-14, EP103-15"}')::jsonb, 'a6'),
  ('3bc3a0b6-4b4c-59da-91ad-6a53285bac89', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ed6cc894-0043-58ba-8c83-af618ad35808', 'callout', 2, ('{"tone":"info","title":"Evidence — Class C","body":"COD deficit is a task-dependent lens, not a pure isolate — Basis: EP103-18, EP103-04"}')::jsonb, 'a7'),
  ('dd168b25-9509-590d-bfe1-5954b135b6df', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ed6cc894-0043-58ba-8c83-af618ad35808', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A (documented in the source base)","body":"Terminology across the applied literature is not fully consistent — Basis: EP103-04, EP103-03, EP103-19"}')::jsonb, 'a8'),
  ('36ed905c-9a87-58b2-8c0d-f270a7f3475b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ed6cc894-0043-58ba-8c83-af618ad35808', 'callout', 2, ('{"tone":"info","title":"Evidence — Class E / F","body":"SAQ as a precise scientific category — Basis: EP103-25 · historically influential, conceptually imprecise"}')::jsonb, 'a9'),
  ('5edf5222-9c63-5093-9089-8c06449e2f7a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ed6cc894-0043-58ba-8c83-af618ad35808', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"none in this module. Definitions are not negotiable inside G3."}')::jsonb, 'b0'),
  ('05f19eff-ab42-5606-ab5f-70b8d62f2afb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ed6cc894-0043-58ba-8c83-af618ad35808', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Using ''speed'' as the label for every fast activity · Calling a pre-planned cone pattern an agility drill · Treating a 10 m time as top speed · Absorbing deceleration into ''the cut'' · Publishing a fixed acceleration/max-velocity boundary · Using COD deficit as an isolate · Using SAQ as a technical taxonomy"}')::jsonb, 'b1'),
  ('1b760d92-798d-5562-8ce8-484bf466700f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '301af3c0-8d44-51e7-8aa8-cf73e868463f', 'rich_text', 1, ('{"text":"The immediate application is the session plan. Every line of a G3 speed session names its quality before it names its drill. In a G3 Youth or Volleyball Development environment this typically reveals that a session labeled \"speed and agility\" contained one acceleration exposure, several COD patterns, and no agility at all — which is a legitimate session, provided it is named correctly and the coach knows what was and was not trained."}')::jsonb, 'a0'),
  ('66b510a8-d351-57da-8e9f-0a057d817b3c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '301af3c0-8d44-51e7-8aa8-cf73e868463f', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"None. Terminology accuracy carries into **PS-1** and is scored in **T-01**."}')::jsonb, 'a1'),
  ('ce38a5cf-a25f-5a4a-aa26-1225fe138962', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e3b31155-38a8-5d66-948d-9e7a80c89032', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('481cafd9-9bae-5172-a5af-29608e4269e7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e3b31155-38a8-5d66-948d-9e7a80c89032', 'assessment_reference', 1, ('{"assessmentId":"a3131faf-caa0-59ea-b442-d7f5ba6c6465","title":"G3-103 · M1 Assessment — Language Before Programming"}')::jsonb, 'a1'),
  ('cf46241e-0927-547f-945d-4af88d758e9e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e03f6ab3-6466-515b-94d8-db9284a8dc97', 'quote', 1, ('{"text":"Acceleration is the phase most G3 athletes actually live in - and where a real mechanical finding gets flattened into a slogan."}')::jsonb, 'a0'),
  ('3f954e7b-98e2-5127-b39b-28b6ab28e827', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e03f6ab3-6466-515b-94d8-db9284a8dc97', 'rich_text', 1, ('{"text":"To give coaches a working understanding of acceleration demands and mechanics accurate enough to inform observation and method selection, without converting descriptive findings into universal cueing prescriptions."}')::jsonb, 'a1'),
  ('09179a46-e7b1-5d46-94ff-6fb4e100a5f6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e03f6ab3-6466-515b-94d8-db9284a8dc97', 'checklist', 1, ('{"items":[{"id":"1044ff06-6941-55ee-8c97-a7ff4ad5fb54","text":"M2.1 Describe primary acceleration demands"},{"id":"260d8159-22fd-51b3-bec1-2d2245679736","text":"M2.2 Explain horizontal impulse and force orientation without overclaiming"},{"id":"a072943d-3a5f-5fa6-82f5-bcc7a2e39d3a","text":"M2.3 Distinguish associational findings from intervention-supported targets"},{"id":"5b5f5d5d-8463-52f6-b5f4-bef6663bdc71","text":"M2.4 Identify physical qualities associated with acceleration"},{"id":"9ec45dde-dd93-582c-9bfa-1289051a5b56","text":"M2.5 Recognize population limits of the acceleration-mechanics literature"},{"id":"418d3cca-643a-5aba-90c7-3782e13006af","text":"M2.6 Identify acceleration demands within a sport or position"}]}')::jsonb, 'a2'),
  ('df8a7260-180c-5ec3-9f1e-f2b78f3a1964', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e03f6ab3-6466-515b-94d8-db9284a8dc97', 'callout', 2, ('{"tone":"info","title":"Sequence & gating","body":"[object Object]"}')::jsonb, 'a3'),
  ('8e95098f-7620-52fa-bf56-9e39dad70908', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9825283d-fb91-5d5c-bab8-3f83d35e7e30', 'heading', 1, ('{"text":"L2.1 What the task demands","level":3}')::jsonb, 'a0'),
  ('26c20041-c37b-5ed2-b208-bbafa118596e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9825283d-fb91-5d5c-bab8-3f83d35e7e30', 'rich_text', 1, ('{"text":"Building velocity from slow or still: large propulsive impulse, effective force orientation, a body position that permits it, and the step characteristics that follow from it."}')::jsonb, 'a1'),
  ('555f3931-2f15-5d22-b352-1e649c9cf144', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9825283d-fb91-5d5c-bab8-3f83d35e7e30', 'heading', 1, ('{"text":"L2.2 Force orientation, stated accurately","level":3}')::jsonb, 'a2'),
  ('c8a0712b-55e4-52f6-be74-99eaa9874c7b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9825283d-fb91-5d5c-bab8-3f83d35e7e30', 'rich_text', 1, ('{"text":"The evidence strongly supports the importance of net horizontal impulse and effective orientation of force in acceleration. It does not support \"horizontal force is all that matters.\" The distinction is not pedantic: the slogan produces coaching that chases a single visible feature and ignores the rest of the task."}')::jsonb, 'a3'),
  ('1fb0517e-a674-581c-a3a9-2df3d6b2a809', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9825283d-fb91-5d5c-bab8-3f83d35e7e30', 'heading', 1, ('{"text":"L2.3 Association versus intervention","level":3}')::jsonb, 'a4'),
  ('906938bb-4357-51f1-bf19-0db601c834da', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9825283d-fb91-5d5c-bab8-3f83d35e7e30', 'rich_text', 1, ('{"text":"A characteristic may correlate with better acceleration in stronger or faster athletes without proving that deliberately coaching that visible feature improves acceleration in a developing team-sport athlete. This lesson delivers §2.4 — the description-to-prescription rule — as a working habit."}')::jsonb, 'a5'),
  ('a4d95535-286a-5ee9-ba11-efc2a3d21fda', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9825283d-fb91-5d5c-bab8-3f83d35e7e30', 'heading', 1, ('{"text":"L2.4 Physical qualities associated with acceleration","level":3}')::jsonb, 'a6'),
  ('ae1a4a8d-ff94-59f2-aebf-8b093edf477c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9825283d-fb91-5d5c-bab8-3f83d35e7e30', 'rich_text', 1, ('{"text":"Strength and power qualities contribute; the relationship is real, partial, and outcome-specific rather than automatic. Full treatment in M6."}')::jsonb, 'a7'),
  ('bc4094f5-aa30-57ac-bcd2-b615d5e71258', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9825283d-fb91-5d5c-bab8-3f83d35e7e30', 'heading', 1, ('{"text":"L2.5 Where the evidence comes from","level":3}')::jsonb, 'a8'),
  ('24f35a2b-6481-5495-8ae8-5b2179b4658b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9825283d-fb91-5d5c-bab8-3f83d35e7e30', 'rich_text', 1, ('{"text":"The sprint-start and early-acceleration literature is largely track-based. G3 states this out loud whenever it borrows from it."}')::jsonb, 'a9'),
  ('e19d65f6-5d90-551a-b552-45509dbc9c73', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9825283d-fb91-5d5c-bab8-3f83d35e7e30', 'heading', 1, ('{"text":"L2.6 Acceleration in the sport","level":3}')::jsonb, 'b0'),
  ('d79adfb0-c7f8-5b67-b56d-5e92ca78fef3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9825283d-fb91-5d5c-bab8-3f83d35e7e30', 'rich_text', 1, ('{"text":"Identifying real acceleration demands: distances actually covered, how often from a standing versus rolling start, and what precedes them. This feeds DEMAND in the G3 102 model."}')::jsonb, 'b1'),
  ('1316f4a5-f474-5c96-99e9-dcf580f48e69', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '876c4e89-b37a-5be7-8f83-69150b9c5ee6', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-1 — Speed Is Phase-Specific","body":"Acceleration and maximal velocity are related but distinct sprint qualities. Coaches identify which speed demand is being trained or assessed rather than treating sprint performance as one undifferentiated quality. — Teaching boundary: The distinction is established; exact phase boundaries are not. G3 publishes no universal distance cut-point. — Evidence class: A"}')::jsonb, 'a0'),
  ('85732fce-198e-5233-bf6e-9eb4883fc975', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '876c4e89-b37a-5be7-8f83-69150b9c5ee6', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-3 — Mechanics Inform; They Do Not Dictate","body":"Biomechanics can describe characteristics associated with better sprint performance. A descriptive characteristic does not automatically become a causal coaching target. G3 does not impose one universal sprint-mechanics model on every athlete. — Teaching boundary: Descriptive support is A-class; technique-intervention evidence is limited by comparison; universalizing an elite track model is F. Technique coaching is not forbidden - gating exposure on it is. — Evidence class: B"}')::jsonb, 'a1'),
  ('a19c123b-93fe-5f5f-90a7-9934e3829c8b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '876c4e89-b37a-5be7-8f83-69150b9c5ee6', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Acceleration mechanics are distinct from maximal-velocity mechanics — Basis: EP103-01, EP103-13, EP103-12 · cite:96, cite:101, cite:104"}')::jsonb, 'a2'),
  ('75390050-5423-58c4-9152-4ba5adcc8706', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '876c4e89-b37a-5be7-8f83-69150b9c5ee6', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Net horizontal impulse and effective force orientation are important in acceleration — Basis: EP103-11, EP103-01 · cite:105, cite:96"}')::jsonb, 'a3'),
  ('1d334937-1a7d-5d36-b4db-57cfab2c4c5a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '876c4e89-b37a-5be7-8f83-69150b9c5ee6', 'callout', 2, ('{"tone":"info","title":"Evidence — Class F","body":"\"Horizontal force is all that matters\" — Basis: Acceleration is a whole-system task; the simplification exceeds the evidence"}')::jsonb, 'a4'),
  ('dd8371dd-8768-54f5-a7cc-15253f886968', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '876c4e89-b37a-5be7-8f83-69150b9c5ee6', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B","body":"Targeted acceleration training logic — Basis: EP103-01, EP103-05"}')::jsonb, 'a5'),
  ('40180875-bd7d-5b29-ade9-b590a4eab23f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '876c4e89-b37a-5be7-8f83-69150b9c5ee6', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D at best — often F when asserted causally","body":"A correlate of better acceleration is a trainable coaching target — Basis: EP103-01, EP103-11"}')::jsonb, 'a6'),
  ('38cb6d32-44ce-5470-bf0e-302c761845eb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '876c4e89-b37a-5be7-8f83-69150b9c5ee6', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A, from track-sprint populations","body":"Sprint-start and early-acceleration mechanical description — Basis: EP103-12 · cite:104"}')::jsonb, 'a7'),
  ('5f1aadd7-0c75-500a-be32-b6bf03de6231', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '876c4e89-b37a-5be7-8f83-69150b9c5ee6', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"which acceleration distances to use (CJ-02); how much technical emphasis to apply (CJ-12)."}')::jsonb, 'a8'),
  ('b533f650-1234-56f5-9647-a5569f1ec98c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '876c4e89-b37a-5be7-8f83-69150b9c5ee6', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Coaching ''horizontal force'' as a cue · Importing a track sprint-start model wholesale · Treating a correlate as a cause · Assuming every acceleration starts static · Failing to disclose adult track provenance"}')::jsonb, 'a9'),
  ('8e33afa6-0c80-5be1-8fcf-7ed345459942', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '12005e7f-07fb-5449-83bb-ce6f37a91976', 'rich_text', 1, ('{"text":"For G3 field- and court-sport athletes, most competitive accelerations begin from a moving or reactive state over short distances. That does not make standing-start acceleration work useless — it makes it a training constraint choice the coach should be able to defend, and it means the demand analysis should record which entry conditions the sport actually presents."}')::jsonb, 'a0'),
  ('110758c2-20f2-51dd-9e5b-9e8a91dc2106', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '12005e7f-07fb-5449-83bb-ce6f37a91976', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"Feeds **PS-1** (observation of acceleration exposures)."}')::jsonb, 'a1'),
  ('5dc2a5d1-9300-5025-baf5-d4e09f3e843e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7620554d-dc17-549f-9ccd-bf83ffbc3cbf', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('43f1f459-d46e-54a6-a532-697d7270cb42', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7620554d-dc17-549f-9ccd-bf83ffbc3cbf', 'assessment_reference', 1, ('{"assessmentId":"9c31a308-2b5a-5b1b-af3c-841bebdf0829","title":"G3-103 · M2 Assessment — Understanding Acceleration"}')::jsonb, 'a1'),
  ('6373e4cc-e07e-56d5-99f1-9dad578e7727', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '0303c5bf-3ed4-5ef5-bfc8-88a9381fa24b', 'quote', 1, ('{"text":"The quality most often claimed and least often trained."}')::jsonb, 'a0'),
  ('89ec41e0-7c51-521e-8da4-ff1b8d860c23', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '0303c5bf-3ed4-5ef5-bfc8-88a9381fa24b', 'rich_text', 1, ('{"text":"To establish maximal velocity as a distinct quality with its own demands and exposure requirement, and to make clear how rarely typical team-sport training or testing actually addresses it."}')::jsonb, 'a1'),
  ('3e1a04cc-bd30-567a-89d3-2d1c9a4baa59', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '0303c5bf-3ed4-5ef5-bfc8-88a9381fa24b', 'checklist', 1, ('{"items":[{"id":"62b552f1-f85b-5693-8967-8956499597d1","text":"M3.1 Describe maximal-velocity demands"},{"id":"5f5e6c9d-4b9c-57a3-9836-c4f50740b63e","text":"M3.2 Explain why maximal velocity is not reducible to one variable"},{"id":"822d3ad6-0d53-53db-9b1a-a75d10e42d73","text":"M3.3 Explain why short distances rarely develop or measure maximal velocity"},{"id":"3c62eaca-1ae2-5813-bebe-7e3b949dddcd","text":"M3.4 State population limits of elite-sprinter evidence"},{"id":"259fc8b5-5ad8-5ff0-9d22-b58447f6f154","text":"M3.5 Identify what a meaningful maximal-velocity exposure requires"},{"id":"583f8e0e-6656-58e2-9467-1b1ab4c6c3f7","text":"M3.6 Determine whether a sport and athlete need maximal-velocity development"}]}')::jsonb, 'a2'),
  ('66a15db2-660c-5eba-a12b-7c25ab551be5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '0303c5bf-3ed4-5ef5-bfc8-88a9381fa24b', 'callout', 2, ('{"tone":"info","title":"Sequence & gating","body":"[object Object]"}')::jsonb, 'a3'),
  ('1137b266-f4bc-5504-800c-2f6f64cee739', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'adb208fa-f5ae-5659-82da-dfd4325da28a', 'heading', 1, ('{"text":"L3.1 What top speed demands","level":3}')::jsonb, 'a0'),
  ('f05cd22a-125b-5002-9611-71ba604c386c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'adb208fa-f5ae-5659-82da-dfd4325da28a', 'rich_text', 1, ('{"text":"Short contacts, high force applied in very little time, cyclic organization, and postural conditions that differ meaningfully from early acceleration."}')::jsonb, 'a1'),
  ('8e3c154c-6284-5ef6-88e8-d4fb7d4c518f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'adb208fa-f5ae-5659-82da-dfd4325da28a', 'heading', 1, ('{"text":"L3.2 Not one variable","level":3}')::jsonb, 'a2'),
  ('78eab4d3-b534-5e42-ad9f-94290d7f37d2', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'adb208fa-f5ae-5659-82da-dfd4325da28a', 'rich_text', 1, ('{"text":"Vertical force matters at maximal velocity. It is not the whole story, and the mirror-image slogan to M2''s error is corrected here."}')::jsonb, 'a3'),
  ('7a79d0e0-5b0c-58cd-a1a5-726b453dc702', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'adb208fa-f5ae-5659-82da-dfd4325da28a', 'heading', 1, ('{"text":"L3.3 The exposure problem","level":3}')::jsonb, 'a4'),
  ('32cc655a-1c60-5a6e-b6ab-9258286940ee', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'adb208fa-f5ae-5659-82da-dfd4325da28a', 'rich_text', 1, ('{"text":"True maximal velocity requires distance and a rolling entry. A program of 10–20 m efforts is training acceleration, and calling it top-speed work does not make it so. Whether that matters depends on the sport''s demands — which is a DEMAND question, not a fashion question."}')::jsonb, 'a5'),
  ('e53451d7-f706-5aac-b098-224ac7f2024b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'adb208fa-f5ae-5659-82da-dfd4325da28a', 'heading', 1, ('{"text":"L3.4 Where the evidence comes from, and where it stops","level":3}')::jsonb, 'a6'),
  ('53e1610d-9b5a-5e20-9e6b-c1e3f76a8599', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'adb208fa-f5ae-5659-82da-dfd4325da28a', 'rich_text', 1, ('{"text":"Elite-sprinter observation informs interpretation; it is largely descriptive and largely adult track. Direct intervention evidence for maximal-velocity development in youth and general team-sport settings is a named gap in the Evidence Pack, and the course says so rather than filling it."}')::jsonb, 'a7'),
  ('68b1f7c5-8eec-5283-9108-8b5b84f83111', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'adb208fa-f5ae-5659-82da-dfd4325da28a', 'heading', 1, ('{"text":"L3.5 What a meaningful exposure looks like","level":3}')::jsonb, 'a8'),
  ('1aa9a229-fa72-55dc-805b-8451a063d647', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'adb208fa-f5ae-5659-82da-dfd4325da28a', 'rich_text', 1, ('{"text":"Sufficient distance or a rolling entry to reach a genuine high-velocity state, adequate recovery to repeat it at quality, and a surface and environment that permit it. Numbers remain judgment (CJ-01 to CJ-03)."}')::jsonb, 'a9'),
  ('dc66e232-28d1-501d-8c7e-5ae93daf2b78', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'adb208fa-f5ae-5659-82da-dfd4325da28a', 'heading', 1, ('{"text":"L3.6 Does this athlete need it?","level":3}')::jsonb, 'b0'),
  ('5cbb974f-fddd-5e4e-9a36-0f56a802c19b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'adb208fa-f5ae-5659-82da-dfd4325da28a', 'rich_text', 1, ('{"text":"Some sports and roles reach near-maximal velocities regularly; others rarely do. G3 asks the demand question before prescribing the quality, and accepts \"not a priority this phase\" as a legitimate answer."}')::jsonb, 'b1'),
  ('6293ae97-e5e5-5016-add1-f505beec0b28', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c6d75245-f459-5862-8366-b0fc3dc529a0', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-1 — Speed Is Phase-Specific","body":"Acceleration and maximal velocity are related but distinct sprint qualities. Coaches identify which speed demand is being trained or assessed rather than treating sprint performance as one undifferentiated quality. — Teaching boundary: The distinction is established; exact phase boundaries are not. G3 publishes no universal distance cut-point. — Evidence class: A"}')::jsonb, 'a0'),
  ('6dde8c15-d193-5af1-8695-7b57580ce05d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c6d75245-f459-5862-8366-b0fc3dc529a0', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-3 — Mechanics Inform; They Do Not Dictate","body":"Biomechanics can describe characteristics associated with better sprint performance. A descriptive characteristic does not automatically become a causal coaching target. G3 does not impose one universal sprint-mechanics model on every athlete. — Teaching boundary: Descriptive support is A-class; technique-intervention evidence is limited by comparison; universalizing an elite track model is F. Technique coaching is not forbidden - gating exposure on it is. — Evidence class: B"}')::jsonb, 'a1'),
  ('a624f386-602b-5a12-9470-945d96b2e71a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c6d75245-f459-5862-8366-b0fc3dc529a0', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-2 — Exposure Is Irreplaceable","body":"General strength, power, and plyometric training can support sprint development, but they do not fully replace sprint-specific exposure when the desired adaptation is sprint performance. — Teaching boundary: Not a claim that the weight room is unimportant, and not a dose statement. Sets no minimum sprint volume (CJ-01). — Evidence class: B"}')::jsonb, 'a2'),
  ('04755722-0be5-5d8c-9720-ec30bfc89df2', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c6d75245-f459-5862-8366-b0fc3dc529a0', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Maximal-velocity mechanics differ from acceleration in posture, contact time, stride behavior, and force-time demands — Basis: EP103-01, EP103-13 · cite:96, cite:101"}')::jsonb, 'a3'),
  ('d618b4de-a687-5f2d-b816-fcece727341a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c6d75245-f459-5862-8366-b0fc3dc529a0', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Very short ground contacts and high vertical force requirements characterize maximal velocity — Basis: EP103-01, EP103-13"}')::jsonb, 'a4'),
  ('25365d2d-1565-577e-b696-e90690571827', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c6d75245-f459-5862-8366-b0fc3dc529a0', 'callout', 2, ('{"tone":"info","title":"Evidence — Class F","body":"\"Vertical force is all that matters at top speed\" — Basis: Top speed is not reducible to one isolated variable"}')::jsonb, 'a5'),
  ('f9f55548-635c-5516-a086-0b4c6cd6ae2b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c6d75245-f459-5862-8366-b0fc3dc529a0', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B","body":"Specific high-speed exposure is needed to develop maximal velocity — Basis: EP103-01 · cite:96"}')::jsonb, 'a6'),
  ('b619f42e-31f0-5df0-b9f7-95c086f3afb5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c6d75245-f459-5862-8366-b0fc3dc529a0', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A (evidence-to-practice limitation, documented)","body":"Many team-sport programs rarely use sprint distances sufficient to produce or measure maximal velocity — Basis: EP103-01, EP103-02"}')::jsonb, 'a7'),
  ('697b49c5-918d-5000-be62-a1c527128d53', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c6d75245-f459-5862-8366-b0fc3dc529a0', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D","body":"Fine-grained maximal-velocity technical prescriptions — Basis: EP103-01"}')::jsonb, 'a8'),
  ('abd22605-b409-5c67-981b-848c0ea4120d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c6d75245-f459-5862-8366-b0fc3dc529a0', 'callout', 2, ('{"tone":"info","title":"Evidence — Class F","body":"Universalizing elite track models — Basis: EP103-01, EP103-12"}')::jsonb, 'a9'),
  ('380a5e09-9fda-5eb3-aa94-f5b4110e714e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c6d75245-f459-5862-8366-b0fc3dc529a0', 'callout', 2, ('{"tone":"info","title":"Evidence — Class Gap","body":"Direct intervention evidence for maximal-velocity development in youth and general team-sport settings — Basis: EP103-06, EP103-01 — named as a research gap"}')::jsonb, 'b0'),
  ('6e72c73b-c21a-5dc1-98ea-e44eca65d9b0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c6d75245-f459-5862-8366-b0fc3dc529a0', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"whether this athlete needs maximal-velocity work this phase; distances used (CJ-02); volume and rest (CJ-01, CJ-03)."}')::jsonb, 'b1'),
  ('0288bcc3-846d-5082-94dc-cad06932f083', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c6d75245-f459-5862-8366-b0fc3dc529a0', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Labeling short sprint work as maximal-velocity training · Reporting a 10 m split as an athlete''s speed · Prescribing an elite track model without disclosure · Reducing maximal velocity to one variable · Assuming every athlete requires it · Filling the youth/team-sport gap with assertion"}')::jsonb, 'b2'),
  ('4a73838a-3737-5830-b400-2d55751d855e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'bb931e2c-b3e6-5c66-bcae-0002b5c862b8', 'rich_text', 1, ('{"text":"In a scholastic setting with a 40-yard-wide field and 50-minute sessions, honest maximal-velocity exposure is a scheduling and space decision before it is a programming one. The competent coach either creates the conditions for a real exposure or stops calling the work top-speed development."}')::jsonb, 'a0'),
  ('c8832794-f0ce-52ae-8814-961486eb079a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'bb931e2c-b3e6-5c66-bcae-0002b5c862b8', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"Feeds **PS-1** (observation of higher-speed sprint exposures)."}')::jsonb, 'a1'),
  ('f68fc1f8-47ba-5660-be75-5d5d3c153477', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '71ea56d4-9658-5e3c-a847-2e393d36cc10', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('238e245f-af6d-502f-9e01-11d27401b60c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '71ea56d4-9658-5e3c-a847-2e393d36cc10', 'assessment_reference', 1, ('{"assessmentId":"4615e5eb-2e6a-55f1-8c7d-ee2e39da840e","title":"G3-103 · M3 Assessment — Understanding Maximal Velocity"}')::jsonb, 'a1'),
  ('c84b4062-baff-523e-a125-b15d39282a63', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'bff1e05f-7080-52a3-b300-9f00944ea343', 'quote', 1, ('{"text":"You are allowed to coach sprinting. You are not allowed to hold an athlete''s sprint exposure hostage to a picture in your head."}')::jsonb, 'a0'),
  ('1e2b8d3a-63b8-5462-b1ec-65cd723990c3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'bff1e05f-7080-52a3-b300-9f00944ea343', 'rich_text', 1, ('{"text":"To build observation and coaching capability for sprinting that improves task execution while respecting the gap between descriptive biomechanics and intervention evidence, and while preserving meaningful sprint exposure."}')::jsonb, 'a1'),
  ('0b7c2ef2-e1ec-555b-a6bb-bcfc7926d72f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'bff1e05f-7080-52a3-b300-9f00944ea343', 'checklist', 1, ('{"items":[{"id":"a4a7d956-ee8e-5336-94ab-3c21c400029e","text":"M4.1 Observe sprinting and describe it in task-relevant terms"},{"id":"900abd72-ffa8-597d-b6c3-518e3e04ff8c","text":"M4.2 Distinguish technical error from individual variation"},{"id":"4a672222-d7b8-568a-ba52-bc110b2f2c46","text":"M4.3 Select a small number of relevant interventions"},{"id":"c56ff66d-b9d5-566d-9a49-9761ec13da6f","text":"M4.4 Use constraints and task design alongside verbal cueing"},{"id":"a7c40884-4896-5399-a74f-2eebd1333e8b","text":"M4.5 Explain why descriptive biomechanics cannot become a universal checklist"},{"id":"b75fb95d-4064-5177-a3d6-4441ae87e394","text":"M4.6 Preserve meaningful sprint exposure while coaching"},{"id":"de2eba4a-9eae-589c-a6a7-27df5c9278e9","text":"M4.7 State the evidence boundary of any technical intervention"}]}')::jsonb, 'a2'),
  ('05bc7617-2d85-53a7-8188-688dbb6f3121', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'bff1e05f-7080-52a3-b300-9f00944ea343', 'callout', 2, ('{"tone":"info","title":"Sequence & gating","body":"[object Object]"}')::jsonb, 'a3'),
  ('d487ebc3-778d-59ca-b1d1-fb577b9f8e86', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52b35d9c-0af3-592f-a141-a6a685175a4b', 'heading', 1, ('{"text":"L4.1 Observation before intervention","level":3}')::jsonb, 'a0'),
  ('a55348f4-b817-550c-868a-5b4c4c0e0927', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52b35d9c-0af3-592f-a141-a6a685175a4b', 'rich_text', 1, ('{"text":"What to actually look at: what the task demanded, what the athlete produced, what changed across repetitions, and what changed under fatigue. Observation is a description, not yet a verdict."}')::jsonb, 'a1'),
  ('2035bcbd-7410-54b0-ba5f-80ee0c43a123', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52b35d9c-0af3-592f-a141-a6a685175a4b', 'heading', 1, ('{"text":"L4.2 Error or variation?","level":3}')::jsonb, 'a2'),
  ('f1a90fa1-4170-5895-b9b5-c107d85e90d3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52b35d9c-0af3-592f-a141-a6a685175a4b', 'rich_text', 1, ('{"text":"Individual differences in limb length, strength, training history, and injury history produce legitimate variation. The operational question is not \"does this match the model?\" but \"is this limiting the athlete''s performance of this task, and do I have reason to believe changing it helps?\""}')::jsonb, 'a3'),
  ('579556a1-4a96-5d0f-b580-4d00b6ff68c7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52b35d9c-0af3-592f-a141-a6a685175a4b', 'heading', 1, ('{"text":"L4.3 Few interventions, chosen well","level":3}')::jsonb, 'a4'),
  ('3a03d2a7-b13c-571b-9fec-296ffcb59e0c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52b35d9c-0af3-592f-a141-a6a685175a4b', 'rich_text', 1, ('{"text":"A coach who gives eight cues has given none. Selecting one or two relevant interventions per exposure, and holding them long enough to see whether they change anything."}')::jsonb, 'a5'),
  ('8e34aaa5-d724-5f50-8ccf-18b8967759da', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52b35d9c-0af3-592f-a141-a6a685175a4b', 'heading', 1, ('{"text":"L4.4 Constraints as coaching","level":3}')::jsonb, 'a6'),
  ('73245681-56c4-5cd2-aa2b-c758a6435c3a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52b35d9c-0af3-592f-a141-a6a685175a4b', 'rich_text', 1, ('{"text":"Task design, entry conditions, distances, surfaces, targets, and competition can change movement without a single verbal cue. Where the evidence for a specific verbal cue is thin, a constraint may be the more honest tool — and this remains an Applied Coaching Inference, not a proven superiority claim."}')::jsonb, 'a7'),
  ('e01a4584-785b-52f2-9a0b-dcbc387c09bb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52b35d9c-0af3-592f-a141-a6a685175a4b', 'heading', 1, ('{"text":"L4.5 Front-side, back-side, and the checklist problem","level":3}')::jsonb, 'a8'),
  ('a1faa068-37b0-599c-ad08-5bf544462c0e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52b35d9c-0af3-592f-a141-a6a685175a4b', 'rich_text', 1, ('{"text":"Visually salient coaching concepts often have stronger descriptive than interventional support. G3 coaches may use them as observation language. They may not be converted into a pass/fail visual checklist that gates an athlete''s sprint exposure."}')::jsonb, 'a9'),
  ('f3949f41-e951-56fe-8491-0821fe21bf4b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52b35d9c-0af3-592f-a141-a6a685175a4b', 'heading', 1, ('{"text":"L4.6 Exposure is protected","level":3}')::jsonb, 'b0'),
  ('a36bf50f-6ab5-5e47-b39c-c95c9a4862c8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52b35d9c-0af3-592f-a141-a6a685175a4b', 'rich_text', 1, ('{"text":"AS-103-03 in practice: technique work is subordinate to the athlete actually sprinting. A session that spends 40 minutes on drills and 4 sprint efforts has made a choice, and the coach should be able to defend it in adaptation terms."}')::jsonb, 'b1'),
  ('674ae10a-4f54-526b-a341-46dc469c4719', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52b35d9c-0af3-592f-a141-a6a685175a4b', 'heading', 1, ('{"text":"L4.7 Saying the boundary out loud","level":3}')::jsonb, 'b2'),
  ('745cddb3-11b0-57ba-b202-5b40af0b5599', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '52b35d9c-0af3-592f-a141-a6a685175a4b', 'rich_text', 1, ('{"text":"Practising the sentence: *\"This is what better sprinters tend to look like; this is what I''m asking you to try; this is why I think it helps you specifically; and I''ll change it if it doesn''t.\"*"}')::jsonb, 'b3'),
  ('5d162f6f-919f-53b9-a4ab-feacbc593ba4', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '71d3b135-5106-59d7-a89a-09ac7c8e5c6d', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-3 — Mechanics Inform; They Do Not Dictate","body":"Biomechanics can describe characteristics associated with better sprint performance. A descriptive characteristic does not automatically become a causal coaching target. G3 does not impose one universal sprint-mechanics model on every athlete. — Teaching boundary: Descriptive support is A-class; technique-intervention evidence is limited by comparison; universalizing an elite track model is F. Technique coaching is not forbidden - gating exposure on it is. — Evidence class: B"}')::jsonb, 'a0'),
  ('18a5ea79-edc2-50f8-b4cc-e294536d92d4', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '71d3b135-5106-59d7-a89a-09ac7c8e5c6d', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-1 — Speed Is Phase-Specific","body":"Acceleration and maximal velocity are related but distinct sprint qualities. Coaches identify which speed demand is being trained or assessed rather than treating sprint performance as one undifferentiated quality. — Teaching boundary: The distinction is established; exact phase boundaries are not. G3 publishes no universal distance cut-point. — Evidence class: A"}')::jsonb, 'a1'),
  ('37c335a0-d81f-5613-aa96-827ed621d178', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '71d3b135-5106-59d7-a89a-09ac7c8e5c6d', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-2 — Exposure Is Irreplaceable","body":"General strength, power, and plyometric training can support sprint development, but they do not fully replace sprint-specific exposure when the desired adaptation is sprint performance. — Teaching boundary: Not a claim that the weight room is unimportant, and not a dose statement. Sets no minimum sprint volume (CJ-01). — Evidence class: B"}')::jsonb, 'a2'),
  ('78e41cfa-1bf1-5379-b0d4-d8c36f582934', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '71d3b135-5106-59d7-a89a-09ac7c8e5c6d', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"The biomechanics literature provides useful descriptive models of sprinting across phases — Basis: EP103-01, EP103-12, EP103-11"}')::jsonb, 'a3'),
  ('e51a5da2-56e9-5005-a702-173c06c24ab9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '71d3b135-5106-59d7-a89a-09ac7c8e5c6d', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A (a documented state of the evidence)","body":"Direct evidence for sprint-technical coaching interventions is limited relative to the descriptive literature — Basis: EP103-01, EP103-11"}')::jsonb, 'a4'),
  ('8d9dcc2e-0549-5372-8be7-b4a00cec8b0a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '71d3b135-5106-59d7-a89a-09ac7c8e5c6d', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B","body":"Coaching sprinting and exposing athletes to sprinting at appropriate intensities is supported — Basis: EP103-01 · cite:96"}')::jsonb, 'a5'),
  ('44c1b555-6f88-593f-9d5d-90bb1c5f2ba2', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '71d3b135-5106-59d7-a89a-09ac7c8e5c6d', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D, frequently asserted as F","body":"Precise universal technical cue rules for all populations — Basis: EP103-01"}')::jsonb, 'a6'),
  ('7aaab4d8-b124-58e3-8e3b-ea0cfbcd36f8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '71d3b135-5106-59d7-a89a-09ac7c8e5c6d', 'callout', 2, ('{"tone":"info","title":"Evidence — Class F","body":"\"Perfect technique must precede meaningful speed exposure\" — Basis: CA-14 — evidence does not support delaying exposure to a universal threshold"}')::jsonb, 'a7'),
  ('531ae6d8-5dc4-55a6-a28f-586cc4d98c86', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '71d3b135-5106-59d7-a89a-09ac7c8e5c6d', 'callout', 2, ('{"tone":"info","title":"Evidence — Class F","body":"\"Every athlete needs the same sprint mechanics\" — Basis: CA-13 — descriptive elite mechanics should not become one universal model"}')::jsonb, 'a8'),
  ('52d389d3-6085-5b2d-b249-cacf15c5d549', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '71d3b135-5106-59d7-a89a-09ac7c8e5c6d', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"which cues to use with which athlete; how much technical emphasis before increasing intensity (CJ-12)."}')::jsonb, 'a9'),
  ('0e141169-a03a-599d-b8e1-f3b5e99a7f0a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '71d3b135-5106-59d7-a89a-09ac7c8e5c6d', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Running a technical checklist and gating exposure on it · Cueing every athlete toward one visual model · Giving too many cues to evaluate any · Treating drills as the training · Claiming a cue ''fixes'' a characteristic without evidence · Coaching a track model with no disclosure"}')::jsonb, 'b0'),
  ('21e77120-bdd9-5e58-806e-c70a02c176c6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '3073c44f-99c7-51ff-8cef-e08488cc7a68', 'rich_text', 1, ('{"text":"Directly applicable in every G3 environment that runs a sprint warm-up. The standard is that an outside observer could watch a G3 coach for ten minutes and see: sprinting actually happening at intensity, a small number of interventions, and no athlete held back from running fast because their posture did not match a diagram."}')::jsonb, 'a0'),
  ('57b0b4f7-e7a0-5df1-a436-1454990fd74b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '3073c44f-99c7-51ff-8cef-e08488cc7a68', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"**PS-1 — Sprint Observation & Coaching.** See §14.2. **PS-1 gates M5.**"}')::jsonb, 'a1'),
  ('ff98d465-efe1-5026-a6db-e660667a5d82', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'bac1fd16-0fc7-5655-a3a7-06e8a0af45eb', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('90d3463c-209c-5391-9875-1a19ca3805ca', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'bac1fd16-0fc7-5655-a3a7-06e8a0af45eb', 'assessment_reference', 1, ('{"assessmentId":"9791558a-ad62-5832-8b21-482759050804","title":"G3-103 · M4 Assessment — Coaching Sprint Mechanics"}')::jsonb, 'a1'),
  ('e7a5aa0e-1ef8-5455-b207-eb40a3a85756', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b844497b-9658-5387-8666-c70f9fa51c61', 'callout', 2, ('{"tone":"info","title":"PS-1 — Observed practical sign-off","body":"Completed at: M4 — Function: gates M5 — This sign-off is observed and recorded by an approved G3 assessor. It cannot be self-recorded."}')::jsonb, 'a0'),
  ('5f440c6a-b27a-5681-9468-2da320485334', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b844497b-9658-5387-8666-c70f9fa51c61', 'heading', 1, ('{"text":"Observed behaviors","level":3}')::jsonb, 'a1'),
  ('69087b98-ba0e-5ef7-b0d5-26203be556d3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b844497b-9658-5387-8666-c70f9fa51c61', 'checklist', 1, ('{"items":[{"id":"b0e206e2-35eb-523a-9f47-c777fa083dea","text":"Distinguishes acceleration from higher-speed sprinting in setup and language"},{"id":"c08c97dd-3cd3-508b-89b0-3cde0c2b3c93","text":"Observes without forcing a universal visual model"},{"id":"d2b1b8c3-7b22-52a1-bbad-d0379d7487e3","text":"Selects a limited number of relevant interventions and holds them long enough to evaluate"},{"id":"6194eb96-6974-5199-b4b2-27509569bb3c","text":"Preserves meaningful sprint exposure - athletes actually sprint at intensity"},{"id":"3b46935a-2ff0-52dc-abe3-57a05a5368e7","text":"Explains the evidence boundary of any technical intervention"},{"id":"d9b3e167-a711-5858-baa5-c78a7351220e","text":"Names the quality being trained without prompting"}]}')::jsonb, 'a2'),
  ('18c5d045-9e95-58cd-9ff9-7bc232c0c969', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b844497b-9658-5387-8666-c70f9fa51c61', 'heading', 1, ('{"text":"Required artifacts","level":3}')::jsonb, 'a3'),
  ('2d2d180a-88d3-5caf-8701-358c96100544', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b844497b-9658-5387-8666-c70f9fa51c61', 'checklist', 1, ('{"items":[{"id":"97b04baf-953d-59dc-a37a-e088ba4b958d","text":"A1"},{"id":"bb59a5ba-c3c4-5170-b433-0ac3af8a2703","text":"A2"},{"id":"9b86abc2-29c8-5009-9ea9-1bf9998ea72f","text":"A3"},{"id":"416b738a-ad14-5515-a9ce-7197608538d1","text":"A4"}]}')::jsonb, 'a4'),
  ('80e8551d-81ff-53c9-8414-20ad312860ad', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b844497b-9658-5387-8666-c70f9fa51c61', 'heading', 1, ('{"text":"Assessor questions","level":3}')::jsonb, 'a5'),
  ('a702e2b1-e374-5fdd-bf1d-8de3d35d852c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b844497b-9658-5387-8666-c70f9fa51c61', 'checklist', 1, ('{"items":[{"id":"28a0d348-6930-561c-b82e-ea4566688ca6","text":"Which phase is this exposure targeting, and how do you know?"},{"id":"fe1af907-58b1-5b11-8ccc-e050432662b3","text":"Why that cue for that athlete?"},{"id":"b9d6fdf7-52ca-5a0e-a739-57bb3e785345","text":"What would tell you the cue isn''t helping?"},{"id":"16de49d0-22c7-5814-b138-47c0a61450bf","text":"Where did that model come from, and does it apply to this athlete?"}]}')::jsonb, 'a6'),
  ('2b8979cb-ad60-5396-aa6b-27e5a0bd98fb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b844497b-9658-5387-8666-c70f9fa51c61', 'callout', 2, ('{"tone":"warning","title":"Practical window","body":"This course carries a minimum four-week practical window.  Practical observation time is additional to directed study and is collected on the floor."}')::jsonb, 'a7'),
  ('36963f45-458a-5149-83db-d5a113059dd9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'fc0e0cce-b368-5a29-8ce2-42f1b559e1ec', 'quote', 1, ('{"text":"The most reliable way to make an athlete faster is to let them run fast, often enough to adapt and fresh enough to mean it."}')::jsonb, 'a0'),
  ('d6094615-e65f-5329-8b46-6399440f0913', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'fc0e0cce-b368-5a29-8ce2-42f1b559e1ec', 'rich_text', 1, ('{"text":"To build capability to design unresisted sprint exposures targeting a named phase, and to organize them so the intended quality survives contact with the session."}')::jsonb, 'a1'),
  ('02e92c58-b50f-5cd9-b84b-5ca03915f1a6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'fc0e0cce-b368-5a29-8ce2-42f1b559e1ec', 'checklist', 1, ('{"items":[{"id":"5a866ddc-0212-5d88-a389-62ca48bc6fc6","text":"M5.1 Design an acceleration exposure targeting a named phase"},{"id":"8f4a97bd-98ee-5c32-8d77-c98235f2ec2a","text":"M5.2 Design a maximal-velocity exposure including entry conditions"},{"id":"e2e73e4a-f604-5d90-b9fb-99dae8a5af57","text":"M5.3 Use flying sprints and rolling entries appropriately"},{"id":"70df067c-59b8-596d-b4e6-796bad6e99b5","text":"M5.4 State the evidence position on hill sprinting"},{"id":"d9d6371e-b91c-553a-8654-fd89c912a4b8","text":"M5.5 State the evidence position on assisted/overspeed sprinting"},{"id":"4ca351d6-8f8a-5e52-b0d5-46c29a34eb21","text":"M5.6 Apply quality-preservation principles"},{"id":"fcc59a26-e8ad-562c-9eb1-1e60540f4a51","text":"M5.7 Explain why fatigue does not make speed work more sport-specific"}]}')::jsonb, 'a2'),
  ('f3f6d1d0-959a-5209-a840-0d016694874a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'fc0e0cce-b368-5a29-8ce2-42f1b559e1ec', 'callout', 2, ('{"tone":"info","title":"Sequence & gating","body":"[object Object]"}')::jsonb, 'a3'),
  ('a80044a7-9130-56fe-a431-864a77613587', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e78e0a9e-c464-580c-a5a9-23dc914c0252', 'heading', 1, ('{"text":"L5.1 Sprinting is the method","level":3}')::jsonb, 'a0'),
  ('3577fe60-944c-5c1e-b972-120e2997052c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e78e0a9e-c464-580c-a5a9-23dc914c0252', 'rich_text', 1, ('{"text":"Before any tool is added, the athlete sprints. Unresisted sprinting exposes the force-time and coordination demands directly, which is why it anchors linear-speed development rather than competing with the additions."}')::jsonb, 'a1'),
  ('421f99d7-ede9-5510-ac00-2bd1d9208b09', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e78e0a9e-c464-580c-a5a9-23dc914c0252', 'heading', 1, ('{"text":"L5.2 Building an acceleration exposure","level":3}')::jsonb, 'a2'),
  ('9af05e08-062e-5246-a430-d03c1c3dd2b5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e78e0a9e-c464-580c-a5a9-23dc914c0252', 'rich_text', 1, ('{"text":"Entry condition, distance, intent, recovery, and what the coach is watching. Distances are chosen to target the phase named in AS-103-01, and the choice is defended by demand, not convention."}')::jsonb, 'a3'),
  ('fb200ab2-ecfd-53d6-b37e-9b7528a7ec03', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e78e0a9e-c464-580c-a5a9-23dc914c0252', 'heading', 1, ('{"text":"L5.3 Building a maximal-velocity exposure","level":3}')::jsonb, 'a4'),
  ('f0a92475-03d7-514b-8b61-19b642d66d59', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e78e0a9e-c464-580c-a5a9-23dc914c0252', 'rich_text', 1, ('{"text":"Rolling entries and flying efforts; the space and surface required; why a standing start over a short distance cannot substitute. This is where M3''s exposure problem becomes a design problem."}')::jsonb, 'a5'),
  ('db461a5c-6553-5894-a1bd-a876e209c518', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e78e0a9e-c464-580c-a5a9-23dc914c0252', 'heading', 1, ('{"text":"L5.4 Hills and sprint-specific resistance","level":3}')::jsonb, 'a6'),
  ('61bed84a-74fd-5a2b-8006-e8679e5c2942', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e78e0a9e-c464-580c-a5a9-23dc914c0252', 'rich_text', 1, ('{"text":"Used in practice, thinner in direct evidence within this pack than sled-based RST. Treated as lower-certainty supported practice or coaching inference and labeled as such — not banned, not endorsed as equivalent."}')::jsonb, 'a7'),
  ('93ce576a-6975-5c98-a7a4-8b9d3fb96e3b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e78e0a9e-c464-580c-a5a9-23dc914c0252', 'heading', 1, ('{"text":"L5.5 Assisted and overspeed work: the honest position","level":3}')::jsonb, 'a8'),
  ('e9d8380e-6547-536b-a6d5-e42ebcad8ffe', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e78e0a9e-c464-580c-a5a9-23dc914c0252', 'rich_text', 1, ('{"text":"Evidence is limited and does not establish superiority over normal sprinting. G3 does not adopt it as doctrine and does not prohibit it. A coach who uses it states that they are operating in a conditional area (CJ-08)."}')::jsonb, 'a9'),
  ('8f3b263d-ea1d-5da2-b95d-b67c77a40f36', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e78e0a9e-c464-580c-a5a9-23dc914c0252', 'heading', 1, ('{"text":"L5.6 Quality preservation in practice","level":3}')::jsonb, 'b0'),
  ('68d93def-f720-5f77-aa90-60da530317a2', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e78e0a9e-c464-580c-a5a9-23dc914c0252', 'rich_text', 1, ('{"text":"Output is the criterion: when times, velocities, or movement quality fall away from the session''s intent, the exposure has stopped serving its purpose. G3 publishes no rest ratio; it requires that the coach know what they are protecting and be watching for its loss."}')::jsonb, 'b1'),
  ('5b367dc4-49fe-5e40-bb71-910b64b8dae1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e78e0a9e-c464-580c-a5a9-23dc914c0252', 'heading', 1, ('{"text":"L5.7 The fatigue trap","level":3}')::jsonb, 'b2'),
  ('8b0d8838-6f6d-5f0a-94c8-513409b04816', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e78e0a9e-c464-580c-a5a9-23dc914c0252', 'rich_text', 1, ('{"text":"Fatigued sprint work is not automatically more sport-specific. It may be appropriate when the sport demand genuinely requires it — but that is a demand decision, not a virtue, and it must not be justified on specificity grounds the evidence does not support."}')::jsonb, 'b3'),
  ('cf8f066e-c9b9-5d88-9c90-7b7fe07159aa', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c01ac89a-b1a7-5742-8e98-ca420640ca46', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-2 — Exposure Is Irreplaceable","body":"General strength, power, and plyometric training can support sprint development, but they do not fully replace sprint-specific exposure when the desired adaptation is sprint performance. — Teaching boundary: Not a claim that the weight room is unimportant, and not a dose statement. Sets no minimum sprint volume (CJ-01). — Evidence class: B"}')::jsonb, 'a0'),
  ('c6a019bc-f7b6-5d9a-87f2-9f936761e5bd', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c01ac89a-b1a7-5742-8e98-ca420640ca46', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-8 — Speed Quality Requires Quality Exposure","body":"High-speed and high-intensity multidirectional work is generally organized to preserve meaningful output and technical quality. Fatigue is not evidence that speed training became more sport-specific. — Teaching boundary: No rest ratio, repetition count, or velocity-decrement threshold is established (CJ-03, CJ-07). Training under fatigue is not forbidden; claiming the fatigue made it specific is. — Evidence class: B"}')::jsonb, 'a1'),
  ('d4dd8de0-3fef-50bd-b21c-ab1072fd601b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c01ac89a-b1a7-5742-8e98-ca420640ca46', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-1 — Speed Is Phase-Specific","body":"Acceleration and maximal velocity are related but distinct sprint qualities. Coaches identify which speed demand is being trained or assessed rather than treating sprint performance as one undifferentiated quality. — Teaching boundary: The distinction is established; exact phase boundaries are not. G3 publishes no universal distance cut-point. — Evidence class: A"}')::jsonb, 'a2'),
  ('05b8ce0b-6dbc-5bf0-829f-8eef460b22ba', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c01ac89a-b1a7-5742-8e98-ca420640ca46', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Unresisted sprinting is a foundational method because it directly exposes athletes to sprint force-time and coordination demands — Basis: EP103-01, EP103-06 · cite:96, cite:84"}')::jsonb, 'a3'),
  ('e5bf32c0-9db0-52d6-aee8-2360d0a61809', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c01ac89a-b1a7-5742-8e98-ca420640ca46', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B","body":"Sprinting is an important stimulus when the intended adaptation is phase- or speed-specific — Basis: EP103-01"}')::jsonb, 'a4'),
  ('811d3e18-bef6-588a-b84d-88ff4dd2b8d6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c01ac89a-b1a7-5742-8e98-ca420640ca46', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B","body":"Flying sprints and rolling entries are relevant when true top-speed development is desired — Basis: EP103-01, EP103-02"}')::jsonb, 'a5'),
  ('409b849b-b729-52ca-baa1-ebd159f28830', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c01ac89a-b1a7-5742-8e98-ca420640ca46', 'callout', 2, ('{"tone":"info","title":"Evidence — Class C / D — thinner direct evidence base than sled-based RST in this pack","body":"Hill sprinting and similar sprint-specific resistance methods — Basis: EP103-01"}')::jsonb, 'a6'),
  ('25847115-3f4d-57d9-ae4b-89cdecff39ce', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c01ac89a-b1a7-5742-8e98-ca420640ca46', 'callout', 2, ('{"tone":"info","title":"Evidence — Class C — Emerging/Conditional; less secure than RST and not clearly superior to normal sprinting","body":"Assisted / overspeed sprinting — Basis: EP103-06, EP103-28 · cite:84, cite:74"}')::jsonb, 'a7'),
  ('642b1fe7-1b24-5726-baee-2313e520dc27', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c01ac89a-b1a7-5742-8e98-ca420640ca46', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B","body":"High-quality exposure supports high-speed development more than fatigued speed work does — Basis: EP103-01, EP103-14"}')::jsonb, 'a8'),
  ('be05a68c-afb9-556d-8649-3a95714568b3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c01ac89a-b1a7-5742-8e98-ca420640ca46', 'callout', 2, ('{"tone":"info","title":"Evidence — Class C/F","body":"\"Fatigue makes speed training more sport-specific\" — Basis: CA-15 — fatigue changes mechanics; the specificity claim is unsupported"}')::jsonb, 'a9'),
  ('15d99660-26b7-5e8e-aad6-dc2c6040e18c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c01ac89a-b1a7-5742-8e98-ca420640ca46', 'callout', 2, ('{"tone":"info","title":"Evidence — Class Not established","body":"Exact sprint volume, distance, and rest prescriptions — Basis: CJ-01 to CJ-03"}')::jsonb, 'b0'),
  ('669e47d1-f70e-576b-b282-fc2164fab6ce', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c01ac89a-b1a7-5742-8e98-ca420640ca46', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"volume (CJ-01), distances (CJ-02), rest (CJ-03), whether to use assisted methods at all (CJ-08), velocity-decrement thresholds if any (CJ-07)."}')::jsonb, 'b1'),
  ('42dd7b7a-b6a1-5d62-85e5-990ace27f47b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c01ac89a-b1a7-5742-8e98-ca420640ca46', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Speed work placed after conditioning · Repetition counts that guarantee quality loss · Copied rest ratios · Presenting overspeed as established · Justifying tired sprint work as sport-specific · Treating hills as equivalent to sled work on evidence"}')::jsonb, 'b2'),
  ('9df7f7be-e352-5f46-bd9a-8a21b0229721', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e1424e4a-9b02-5fdb-8175-cdf4f9655dd5', 'rich_text', 1, ('{"text":"For a scholastic team with two 45-minute slots, linear-speed work usually means a small number of high-quality exposures early in the session, protected from preceding conditioning, with distances chosen for the phase being targeted. The G3 102 session-order standard (AS-14) governs placement: if speed is the priority, it goes first."}')::jsonb, 'a0'),
  ('6b251860-66db-5562-b8bb-337095e38051', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e1424e4a-9b02-5fdb-8175-cdf4f9655dd5', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"Feeds **PS-4** (integrated session/microcycle)."}')::jsonb, 'a1'),
  ('402394ef-769b-5d10-b4aa-09161aefd679', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9f5aee2e-ae8b-5014-959a-ab4a36fa31cf', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('ba892a76-6736-5204-9127-14bdf352ff95', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9f5aee2e-ae8b-5014-959a-ab4a36fa31cf', 'assessment_reference', 1, ('{"assessmentId":"e9de21b2-c6d8-5115-918c-35f01ca99506","title":"G3-103 · M5 Assessment — Training Linear Speed"}')::jsonb, 'a1'),
  ('0776d4fa-fce4-5067-bf81-8a5fbe7fc614', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '18ef380a-df51-5f3b-b090-8d6c4136fa85', 'quote', 1, ('{"text":"The sled works. The number on the sled is not doctrine. And nothing in the weight room is a substitute for running."}')::jsonb, 'a0'),
  ('0d17909c-b71a-525d-a363-03c655259497', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '18ef380a-df51-5f3b-b090-8d6c4136fa85', 'rich_text', 1, ('{"text":"To make coaches capable of selecting resisted sprint methods by intended adaptation, and of integrating strength, power, and plyometric work as supporting contributors without treating them as sprint substitutes."}')::jsonb, 'a1'),
  ('bd36b2b2-5583-547e-8238-6f335ceecd6a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '18ef380a-df51-5f3b-b090-8d6c4136fa85', 'checklist', 1, ('{"items":[{"id":"b87b3ae7-0077-5be5-ad5e-cbf9a33fb1c2","text":"M6.1 State what RST is supported to improve"},{"id":"9f88819e-818a-57b5-8c8e-8e4514f303a4","text":"M6.2 Select RST load and method by intended adaptation"},{"id":"bfba3c39-b0af-56c4-8807-8a6eaca60c91","text":"M6.3 Explain why no universal loading percentage is adopted"},{"id":"a804987c-ae3d-54b4-b8c9-f07258928079","text":"M6.4 Describe velocity decrement without treating a threshold as established"},{"id":"097155c5-6df1-594f-abf2-ed54828311e5","text":"M6.5 State what resistance and plyometric training transfer to"},{"id":"3c81da23-5107-5420-9133-05c5d2c3c8ec","text":"M6.6 Explain why supporting modalities do not replace sprint exposure"},{"id":"2393e9e5-318a-58fe-8958-a9772b407a10","text":"M6.7 Apply demand-based transfer reasoning"}]}')::jsonb, 'a2'),
  ('9087c548-11f7-5b76-94d1-309880153591', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '18ef380a-df51-5f3b-b090-8d6c4136fa85', 'callout', 2, ('{"tone":"info","title":"Sequence & gating","body":"[object Object]"}')::jsonb, 'a3'),
  ('072ffaa3-a059-5273-ae9f-c000582aa2bc', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '411d6d54-5d83-56a2-969e-7ab062b7004b', 'heading', 1, ('{"text":"L6.1 What RST is supported to do","level":3}')::jsonb, 'a0'),
  ('9fb65ace-5648-5b10-9541-65bfda4ff264', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '411d6d54-5d83-56a2-969e-7ab062b7004b', 'rich_text', 1, ('{"text":"Improve sprint performance, particularly acceleration, in field-based athletes. That claim is well supported. Nothing about a specific percentage follows from it."}')::jsonb, 'a1'),
  ('d872fea4-0228-515a-891f-46d3ce53fc3b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '411d6d54-5d83-56a2-969e-7ab062b7004b', 'heading', 1, ('{"text":"L6.2 Why there is no G3 load rule","level":3}')::jsonb, 'a2'),
  ('9fb53978-a830-5af7-a1a8-c965b78911f2', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '411d6d54-5d83-56a2-969e-7ab062b7004b', 'rich_text', 1, ('{"text":"Reviews disagree about optimal loading; superiority over normal sprinting is less consistent beyond early acceleration; devices and loading conventions differ enough to explain part of the disagreement. A G3 number would be an invention, and inventing one would violate the course''s own integrity rule."}')::jsonb, 'a3'),
  ('d4d894a2-200c-5e1a-be15-04d8aa4ba6cf', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '411d6d54-5d83-56a2-969e-7ab062b7004b', 'heading', 1, ('{"text":"L6.3 Selecting by intent","level":3}')::jsonb, 'a4'),
  ('6809a8f4-f503-5c8f-a983-d6e6210b079f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '411d6d54-5d83-56a2-969e-7ab062b7004b', 'rich_text', 1, ('{"text":"AS-103-04 in practice: what adaptation is intended, what the athlete can produce at quality, what equipment exists, and what output is preserved. The coach states the intent before touching the load."}')::jsonb, 'a5'),
  ('f8c2b237-7376-5b86-a114-b41024b0656e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '411d6d54-5d83-56a2-969e-7ab062b7004b', 'heading', 1, ('{"text":"L6.4 Velocity decrement, carefully","level":3}')::jsonb, 'a6'),
  ('0f91a5a7-ca5d-5ef7-a997-0c383eca96e1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '411d6d54-5d83-56a2-969e-7ab062b7004b', 'rich_text', 1, ('{"text":"Useful operationally as a way of holding output within an intended band. Not an established threshold. A coach who uses one is setting a working convention (CJ-07), and says so."}')::jsonb, 'a7'),
  ('be1bf162-eef2-57e2-891a-94c1366f3b93', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '411d6d54-5d83-56a2-969e-7ab062b7004b', 'heading', 1, ('{"text":"L6.5 Supporting qualities: what transfers","level":3}')::jsonb, 'a8'),
  ('52f69a0d-f7f4-59ec-b76c-f56d198a59dd', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '411d6d54-5d83-56a2-969e-7ab062b7004b', 'rich_text', 1, ('{"text":"Resistance and combined resistance-plyometric methods support sprint development in partial, outcome-specific ways. Plyometrics have one of the more consistent literatures for sprint and COD outcomes, with effects varying by distance and comparator. None of this makes strength a sprint substitute."}')::jsonb, 'a9'),
  ('0a3020fd-75a8-5041-bdb2-7e2e7a079954', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '411d6d54-5d83-56a2-969e-7ab062b7004b', 'heading', 1, ('{"text":"L6.6 The substitution error","level":3}')::jsonb, 'b0'),
  ('3299af34-a584-52a2-a72b-75b98bcef107', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '411d6d54-5d83-56a2-969e-7ab062b7004b', 'rich_text', 1, ('{"text":"Improvements in strength, power, or jump performance do not automatically prove improvements in sprint coordination or maximal velocity. D103-2 in operational form: when the target is sprint performance, sprint exposure stays in the program."}')::jsonb, 'b1'),
  ('19c45366-d32f-5e7b-912b-1dc517c84d08', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '411d6d54-5d83-56a2-969e-7ab062b7004b', 'heading', 1, ('{"text":"L6.7 Demand-based method selection","level":3}')::jsonb, 'b2'),
  ('6d80a896-3fb4-5c14-bdbb-12d3862adc8b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '411d6d54-5d83-56a2-969e-7ab062b7004b', 'rich_text', 1, ('{"text":"Choosing a method by the demand it imposes rather than by its resemblance to sprinting. This is D103-7 applied to the weight room and the sled."}')::jsonb, 'b3'),
  ('05c37cd2-82ba-5141-8351-5341f5bb0666', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '35cad9bd-524f-5b4b-959d-dfbdeac203c5', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-9 — Load Serves the Intended Sprint Adaptation","body":"Resisted sprinting is a supported training tool, especially for acceleration, but G3 does not adopt one universal sled load or percentage for every athlete and outcome. — Teaching boundary: A that RST improves sprint performance; C for loading strategy. No percentage, decrement number, or load table appears anywhere in G3 103. Both absolutist claims rejected (CA-06, CA-07). — Evidence class: A"}')::jsonb, 'a0'),
  ('fe4ca2a8-4d7b-5573-a960-e203999984ac', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '35cad9bd-524f-5b4b-959d-dfbdeac203c5', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-2 — Exposure Is Irreplaceable","body":"General strength, power, and plyometric training can support sprint development, but they do not fully replace sprint-specific exposure when the desired adaptation is sprint performance. — Teaching boundary: Not a claim that the weight room is unimportant, and not a dose statement. Sets no minimum sprint volume (CJ-01). — Evidence class: B"}')::jsonb, 'a1'),
  ('0038a2ca-9886-5b15-beaf-e5a7363f0aeb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '35cad9bd-524f-5b4b-959d-dfbdeac203c5', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-7 — Transfer Is Demand-Based, Not Appearance-Based","body":"A drill does not transfer because it looks athletic or resembles sport. Transfer claims are tied to relevant force-time, velocity, coordination, braking, movement, or perception-action demands. — Teaching boundary: Not a rejection of specificity - a rejection of resemblance as evidence of it. Inherited from G3 102 Doctrine 5. — Evidence class: B"}')::jsonb, 'a2'),
  ('470802c3-a46b-5b3d-ad00-dc2a851622e0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '35cad9bd-524f-5b4b-959d-dfbdeac203c5', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Resisted sprint training can improve sprint performance in field-based athletes, particularly acceleration — Basis: EP103-05, EP103-06 · cite:81, cite:84"}')::jsonb, 'a3'),
  ('138b2e01-fde5-592d-bad4-234e91432646', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '35cad9bd-524f-5b4b-959d-dfbdeac203c5', 'callout', 2, ('{"tone":"info","title":"Evidence — Class C — contested; superiority over normal sprinting less consistent outside early acceleration; device…","body":"Optimal RST loading strategy; whether heavier is consistently preferable — Basis: EP103-05, EP103-06, EP103-27"}')::jsonb, 'a4'),
  ('7cc0968a-68d9-584b-94d3-2c13aee262d4', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '35cad9bd-524f-5b4b-959d-dfbdeac203c5', 'callout', 2, ('{"tone":"info","title":"Evidence — Class F (both)","body":"\"More resisted load is better\" / \"Sleds make athletes slow\" — Basis: CA-06, CA-07"}')::jsonb, 'a5'),
  ('92feaf50-7d49-5b67-892e-1237c934d986', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '35cad9bd-524f-5b4b-959d-dfbdeac203c5', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D","body":"Velocity decrement as an operational quality-control tool — Basis: EP103-01 — support is for preserving task quality, not for a threshold"}')::jsonb, 'a6'),
  ('a65a5d48-25c3-52fd-bbff-115f855926ce', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '35cad9bd-524f-5b4b-959d-dfbdeac203c5', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B","body":"Resistance training transfers to sprint outcomes, partially and outcome-specifically — Basis: EP103-07, EP103-08 · cite:87, cite:89"}')::jsonb, 'a7'),
  ('888b4f81-2ec3-5f0c-b299-31ee56522a94', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '35cad9bd-524f-5b4b-959d-dfbdeac203c5', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Plyometric training improves sprint and COD outcomes across several populations — Basis: EP103-07, EP103-09, EP103-10 · cite:87, cite:91, cite:95"}')::jsonb, 'a8'),
  ('f2c19573-5590-544b-8eb7-514bcc5681d3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '35cad9bd-524f-5b4b-959d-dfbdeac203c5', 'callout', 2, ('{"tone":"info","title":"Evidence — Class F","body":"Plyometrics are universally superior to resistance or sprint training — Basis: Effects vary by distance and comparator"}')::jsonb, 'a9'),
  ('71b43266-f20b-58f2-a3eb-de250e9bf6cf', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '35cad9bd-524f-5b4b-959d-dfbdeac203c5', 'callout', 2, ('{"tone":"info","title":"Evidence — Class C — plausible, partly supported, less direct","body":"A specific plyometric category uniquely develops deceleration — Basis: EP103-14"}')::jsonb, 'b0'),
  ('1fc52776-eac4-560f-addf-9584dc018ba5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '35cad9bd-524f-5b4b-959d-dfbdeac203c5', 'callout', 2, ('{"tone":"info","title":"Evidence — Class C/D — usually folded into broader combined-modality reviews","body":"Olympic-lift derivatives, loaded jumps, and similar methods as isolated causes of sprint improvement — Basis: EP103-08, EP103-26"}')::jsonb, 'b1'),
  ('0a204a80-0917-5fd5-a55e-014c06a68a99', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '35cad9bd-524f-5b4b-959d-dfbdeac203c5', 'callout', 2, ('{"tone":"info","title":"Evidence — Class F","body":"\"Strength automatically makes athletes faster\" — Basis: CA-03"}')::jsonb, 'b2'),
  ('417e9614-a105-5113-9404-41ab530fede9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '35cad9bd-524f-5b4b-959d-dfbdeac203c5', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"the load (CJ-06), the method, the decrement threshold if one is used (CJ-07)."}')::jsonb, 'b3'),
  ('339de712-831e-5985-b756-b252b40f1aa4', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '35cad9bd-524f-5b4b-959d-dfbdeac203c5', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Prescribing a sled percentage as established · Concluding sleds are harmful · Replacing sprinting with jumps and lifts · Claiming a plyometric family develops braking · Treating one pending meta-analysis as settling a contested question · Failing to disclose soccer-heavy adult evidence"}')::jsonb, 'b4'),
  ('5d47f9fb-a983-53a2-83bf-0e8b64a2f756', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f5197853-4423-50e4-9f9d-1864767bb554', 'rich_text', 1, ('{"text":"In G3 small-group and team settings, the practical decision is usually: how much of a limited session goes to sprinting versus supporting work. The defensible answer names the priority quality, protects sprint exposure when sprint performance is the target, and uses supporting methods for what they are supported to do."}')::jsonb, 'a0'),
  ('3f9f75b4-3a95-5263-8972-2fa49283a12d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f5197853-4423-50e4-9f9d-1864767bb554', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"Feeds **PS-4**."}')::jsonb, 'a1'),
  ('972b4729-5040-5ed7-98b4-722ecd850fb3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '2bc8060f-0bca-56eb-a6aa-d7a87820f4ce', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('cd4c1b3e-5ef8-5383-8827-bdf56228cb3c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '2bc8060f-0bca-56eb-a6aa-d7a87820f4ce', 'assessment_reference', 1, ('{"assessmentId":"f06db271-7476-59f2-ad3b-3f8905912fb8","title":"G3-103 · M6 Assessment — Resisted Sprinting + Supporting Physical Qualities"}')::jsonb, 'a1'),
  ('247cb6a2-fbbd-59fc-bbee-75faa27ac096', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7b3b6d1a-0e16-5845-b9ec-2a5e4e25ff78', 'quote', 1, ('{"text":"Deceleration is not the boring half of the cut - it is a demand with its own physics, coaching, and measurement limits."}')::jsonb, 'a0'),
  ('5f42077f-a391-5311-a78b-b320a274373c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7b3b6d1a-0e16-5845-b9ec-2a5e4e25ff78', 'rich_text', 1, ('{"text":"To establish deceleration as a trainable, coachable performance quality in its own right, and to build coaching capability for braking tasks without overclaiming diagnostics or injury protection."}')::jsonb, 'a1'),
  ('6eeca2dc-376c-55d1-8a57-5f807051bd9d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7b3b6d1a-0e16-5845-b9ec-2a5e4e25ff78', 'checklist', 1, ('{"items":[{"id":"459c6aea-15f2-5b44-afa8-f54ea496cd6b","text":"M7.1 Describe the demands of horizontal deceleration"},{"id":"404ea965-1a7c-59d3-91be-693d13eed4fb","text":"M7.2 Explain why approach velocity is the primary constraint"},{"id":"8996b59d-e197-5b1d-b430-a29ffa40d588","text":"M7.3 Coach a braking task including regression and progression"},{"id":"3e8dc70f-14a2-5752-b9d7-3585a8d33f89","text":"M7.4 Identify physical qualities associated with deceleration"},{"id":"e5047818-e026-56ee-9821-8f2d7ac50ef4","text":"M7.5 State the limits of deceleration diagnostics"},{"id":"8f1e0ed6-6cb9-5f4d-91c0-09d30c9903ef","text":"M7.6 Explain fatigue effects without an injury guarantee"},{"id":"867e6419-cb83-59cd-91c1-fabc6f7959eb","text":"M7.7 Apply causal restraint to deceleration injury claims"}]}')::jsonb, 'a2'),
  ('0b67cb49-ade7-5394-b2cf-6aac7b41b4cb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7b3b6d1a-0e16-5845-b9ec-2a5e4e25ff78', 'callout', 2, ('{"tone":"info","title":"Sequence & gating","body":"[object Object]"}')::jsonb, 'a3'),
  ('9a275f88-1b8a-5ecf-adc6-dd11144f2540', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a28f2b53-b0fe-5d02-a639-6fccda2f905f', 'heading', 1, ('{"text":"L7.1 The physics of stopping","level":3}')::jsonb, 'a0'),
  ('11749961-975a-5b45-b28c-fe72b5ca0628', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a28f2b53-b0fe-5d02-a639-6fccda2f905f', 'rich_text', 1, ('{"text":"Momentum entering the task, braking impulse required to remove it, eccentric demand distributed across the braking steps, and the postural organization that permits force to be applied. Higher entry velocity means more momentum to remove in the same or less space — which is why approach velocity, not drill complexity, is the primary constraint."}')::jsonb, 'a1'),
  ('6fa4d538-a516-5825-b9e9-fdb9fe7c8e35', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a28f2b53-b0fe-5d02-a639-6fccda2f905f', 'heading', 1, ('{"text":"L7.2 Deceleration is not \"the first half of the cut.\"","level":3}')::jsonb, 'a2'),
  ('6c95f057-e23c-57bb-b3d9-3ecbad05fa44', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a28f2b53-b0fe-5d02-a639-6fccda2f905f', 'rich_text', 1, ('{"text":"Treating it as a component of COD hides it. The athlete who cannot brake at a high entry velocity is not a COD problem to be solved with cone patterns; they are a braking problem."}')::jsonb, 'a3'),
  ('1b496667-8f8c-5706-8ebc-1b6ad1f61027', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a28f2b53-b0fe-5d02-a639-6fccda2f905f', 'heading', 1, ('{"text":"L7.3 Coaching the braking task","level":3}')::jsonb, 'a4'),
  ('42c8e58b-bdd1-50c4-80a2-6f150a038d44', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a28f2b53-b0fe-5d02-a639-6fccda2f905f', 'rich_text', 1, ('{"text":"What to look for: control of the centre of mass, the number of steps used, whether the athlete arrives in a position to do something next, and whether quality holds across repetitions. Coaching aims at task execution and control — not at \"stop faster,\" which is not a coaching point."}')::jsonb, 'a5'),
  ('3e64a457-6086-5a22-823f-de017bb9c0da', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a28f2b53-b0fe-5d02-a639-6fccda2f905f', 'heading', 1, ('{"text":"L7.4 Regression and progression","level":3}')::jsonb, 'a6'),
  ('9196fce8-b502-5373-934d-1ef756d5d497', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a28f2b53-b0fe-5d02-a639-6fccda2f905f', 'rich_text', 1, ('{"text":"The variables: entry velocity, distance available, direction and predictability of the stop, surface, what the athlete must do next, and total exposure. AS-103-05 states G3''s default order — braking competence before escalating velocity, cut severity, reactive complexity, or density — and states plainly that this is a **G3 Applied Standard, not a research-derived universal ladder** (CJ-10)."}')::jsonb, 'a7'),
  ('fa199b0c-ba7d-59de-8973-c0f838890ea0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a28f2b53-b0fe-5d02-a639-6fccda2f905f', 'heading', 1, ('{"text":"L7.5 Physical qualities","level":3}')::jsonb, 'a8'),
  ('affcc8b6-1a70-5cb8-94ea-2289a5538e7d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a28f2b53-b0fe-5d02-a639-6fccda2f905f', 'rich_text', 1, ('{"text":"Eccentric strength qualities, braking strategy, and technical control are associated with deceleration capability; the evidence is more associative than interventional, and no single quality is established as the lever."}')::jsonb, 'a9'),
  ('b0fc7be9-0b23-592e-98dd-aaa2ab0adffc', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a28f2b53-b0fe-5d02-a639-6fccda2f905f', 'heading', 1, ('{"text":"L7.6 Diagnostics and their limits","level":3}')::jsonb, 'b0'),
  ('40841b2b-0460-5871-8012-acb7c3465813', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a28f2b53-b0fe-5d02-a639-6fccda2f905f', 'rich_text', 1, ('{"text":"Deceleration deficit and related field metrics are promising analytical concepts and are not established diagnostics. They may add context. They may not decide a program on their own (CJ-14, AS-103-11)."}')::jsonb, 'b1'),
  ('af6995de-1b5f-502d-b06a-08ba86be63bc', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a28f2b53-b0fe-5d02-a639-6fccda2f905f', 'heading', 1, ('{"text":"L7.7 Injury language","level":3}')::jsonb, 'b2'),
  ('801d664e-ee76-554f-a2dd-46d2d017db91', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a28f2b53-b0fe-5d02-a639-6fccda2f905f', 'rich_text', 1, ('{"text":"Braking demands are large and plausibly relevant to tissue loading. That is not evidence that a drill prevents an injury. Coaches practise the accurate sentence and are scored on it: exposure and preparation are defensible; guarantees are not (D103-12, CA-16, CA-17)."}')::jsonb, 'b3'),
  ('3c781b08-d4aa-59bd-a252-4f138ff4ba91', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4c9a35fe-8178-58f8-87c7-f3231c4577e2', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-4 — Deceleration Is a Performance Quality","body":"Deceleration is not merely the first half of a COD drill. Braking capacity, momentum control, approach velocity, posture, and eccentric demands justify treating deceleration as a distinct training and assessment consideration. — Teaching boundary: Distinctness is A; diagnostics and the qualities that best develop it are C. No progression ladder is evidence-derived; AS-103-05 is an applied standard. — Evidence class: A"}')::jsonb, 'a0'),
  ('a3eced08-bd4b-5d57-812f-3e80b27b68e0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4c9a35fe-8178-58f8-87c7-f3231c4577e2', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-12 — Injury Claims Require Causal Restraint","body":"G3 distinguishes tissue demand, association, mechanistic plausibility, risk-factor evidence, and intervention evidence. Sprinting, deceleration, or COD training is not marketed as inherently dangerous or inherently injury-preventive without appropriate evidence. — Teaching boundary: Restraint runs both directions: no protection promises, and no withholding exposure on an unsupported danger claim. Binds marketing, parent, and athlete communication. — Evidence class: B"}')::jsonb, 'a1'),
  ('63c29ef4-1cc0-5779-b56f-4bfb1a8d7e67', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4c9a35fe-8178-58f8-87c7-f3231c4577e2', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-8 — Speed Quality Requires Quality Exposure","body":"High-speed and high-intensity multidirectional work is generally organized to preserve meaningful output and technical quality. Fatigue is not evidence that speed training became more sport-specific. — Teaching boundary: No rest ratio, repetition count, or velocity-decrement threshold is established (CJ-03, CJ-07). Training under fatigue is not forbidden; claiming the fatigue made it specific is. — Evidence class: B"}')::jsonb, 'a2'),
  ('d257ed02-2f23-5c8d-9061-a2712fd14d2b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4c9a35fe-8178-58f8-87c7-f3231c4577e2', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Deceleration is a distinct domain requiring high braking impulse, eccentric loading, momentum control, and postural organization — Basis: EP103-14, EP103-15 · cite:98, cite:108"}')::jsonb, 'a3'),
  ('83f40a49-6bbd-5aac-b531-7cfe1385bae3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4c9a35fe-8178-58f8-87c7-f3231c4577e2', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Deceleration warrants consideration on its own in intermittent multidirectional sport — Basis: EP103-14"}')::jsonb, 'a4'),
  ('e4e72b40-536f-52bb-9433-13fe35abbdee', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4c9a35fe-8178-58f8-87c7-f3231c4577e2', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B — associative more than interventional","body":"Eccentric strength qualities are associated with COD and sprint performance — Basis: EP103-16 · cite:100"}')::jsonb, 'a5'),
  ('8e387bc7-0270-542f-8c6f-ae4d05215865', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4c9a35fe-8178-58f8-87c7-f3231c4577e2', 'callout', 2, ('{"tone":"info","title":"Evidence — Class C — literature more descriptive than intervention-rich","body":"The physical qualities and technical strategies that best develop deceleration — Basis: EP103-14, EP103-16"}')::jsonb, 'a6'),
  ('25f60708-fc7e-5ee0-b441-ebf9e4fee7cd', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4c9a35fe-8178-58f8-87c7-f3231c4577e2', 'callout', 2, ('{"tone":"info","title":"Evidence — Class C — Emerging. Not a gold-standard metric","body":"Deceleration deficit as a diagnostic — Basis: EP103-14"}')::jsonb, 'a7'),
  ('9a51817b-5ea8-5d53-a79e-e7e15ed1b3c0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4c9a35fe-8178-58f8-87c7-f3231c4577e2', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D — Applied Coaching Inference / G3 Applied Standard","body":"AS-103-05 progression order (braking before directional complexity) — Basis: Labeled as such in the lesson"}')::jsonb, 'a8'),
  ('9b7b1ee1-990c-5aba-94ee-50221d77b8e2', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4c9a35fe-8178-58f8-87c7-f3231c4577e2', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B","body":"Braking imposes large tissue demands with plausible links to loading — Basis: EP103-14"}')::jsonb, 'a9'),
  ('c0116870-c484-5472-b6aa-42bf0e2ad721', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4c9a35fe-8178-58f8-87c7-f3231c4577e2', 'callout', 2, ('{"tone":"info","title":"Evidence — Class F","body":"A specific deceleration drill or metric reduces injury risk — Basis: Mechanistic plausibility is not intervention evidence — CJ-16, D103-12"}')::jsonb, 'b0'),
  ('b78978ea-acf8-5dfb-baf2-80b7a216f3ca', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4c9a35fe-8178-58f8-87c7-f3231c4577e2', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"the progression for this athlete (CJ-10); how much weight to give deceleration-deficit information (CJ-14)."}')::jsonb, 'b1'),
  ('ee951b73-af2d-59f3-b8ec-fd1b593393c1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4c9a35fe-8178-58f8-87c7-f3231c4577e2', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Treating deceleration as a warm-up drill · Escalating cut severity before braking competence · Coaching ''stop faster'' · Using deceleration deficit as established · Telling athletes braking drills prevent injuries · Ignoring total volume of high-force stops"}')::jsonb, 'b2'),
  ('0db759ed-f541-52ac-9321-7c628f81ef21', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b753f686-4187-5897-8599-c5462150ef9d', 'rich_text', 1, ('{"text":"In G3 Volleyball Development and court-sport groups, deceleration exposure is often the missing quality: athletes arrive with jump and COD exposure but little deliberate high-entry-velocity braking. In field-sport groups, the constraint is usually space — which is a design problem the coach must solve without simply reducing every stop to a low-velocity one."}')::jsonb, 'a0'),
  ('9c458833-56d4-55e5-8ac1-7d19cd3e57d3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b753f686-4187-5897-8599-c5462150ef9d', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"**PS-2 — Deceleration Coaching.** See §14.3. **PS-2 gates M8.**"}')::jsonb, 'a1'),
  ('742d3b44-4ab8-558b-97fb-f71e2e955d2d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '44ab0d24-3cc6-5df9-b9e4-2ad2ba8c6046', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('d9a68cfe-50ce-5af0-977e-157f2568d45a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '44ab0d24-3cc6-5df9-b9e4-2ad2ba8c6046', 'assessment_reference', 1, ('{"assessmentId":"fccb72ef-2bf4-556f-9aa9-40dad1196af0","title":"G3-103 · M7 Assessment — Deceleration as a Performance Quality"}')::jsonb, 'a1'),
  ('7857f3ef-0fb1-5c8e-b79a-d1595b5742f4', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '40494986-b75f-5442-9084-8243f39ebf55', 'callout', 2, ('{"tone":"info","title":"PS-2 — Observed practical sign-off","body":"Completed at: M7 — Function: gates M8 — This sign-off is observed and recorded by an approved G3 assessor. It cannot be self-recorded."}')::jsonb, 'a0'),
  ('8d702cbd-a125-5cb8-8350-5c358b027326', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '40494986-b75f-5442-9084-8243f39ebf55', 'heading', 1, ('{"text":"Observed behaviors","level":3}')::jsonb, 'a1'),
  ('0cf0ef92-5af0-5ef1-8818-bfee89714061', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '40494986-b75f-5442-9084-8243f39ebf55', 'checklist', 1, ('{"items":[{"id":"1c3743aa-73f6-51c5-8bce-43fbb488d4a4","text":"Identifies braking demand in momentum and entry-velocity terms"},{"id":"7b2aa3c0-afdf-5b00-98cf-af419b2859e1","text":"Manipulates approach velocity and complexity deliberately"},{"id":"1abc14b1-73c7-5f75-a3af-eb38fc93ec50","text":"Selects an appropriate regression or progression and states the criterion"},{"id":"9782893e-c9ee-55cb-947b-9ec3d9883241","text":"Coaches control and organization rather than ''stop faster''"},{"id":"7106df99-f4ef-545c-9958-6a19aa8f1d5d","text":"Avoids injury-prevention overclaims in everything said to athletes"},{"id":"42e068b1-bfb6-5a78-9404-0ae479bee32b","text":"Names AS-103-05 as an applied standard when asked"}]}')::jsonb, 'a2'),
  ('4715122c-5eca-53dc-9544-61dcbba5db0b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '40494986-b75f-5442-9084-8243f39ebf55', 'heading', 1, ('{"text":"Required artifacts","level":3}')::jsonb, 'a3'),
  ('c57b876a-2912-51df-b929-6467da485dc5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '40494986-b75f-5442-9084-8243f39ebf55', 'checklist', 1, ('{"items":[{"id":"6c727ca5-1e42-5260-aa7a-516884457add","text":"A5"},{"id":"2f4566af-a9e0-5be9-a741-0e1e7199291e","text":"A6"},{"id":"7133b40b-b53b-5e40-8c11-8aa694ae1888","text":"A7"}]}')::jsonb, 'a4'),
  ('82c4a9f3-36c2-51ae-b24e-ec61fb77fcd4', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '40494986-b75f-5442-9084-8243f39ebf55', 'heading', 1, ('{"text":"Assessor questions","level":3}')::jsonb, 'a5'),
  ('9d080660-8aad-5482-adbe-a0e31b9973b8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '40494986-b75f-5442-9084-8243f39ebf55', 'checklist', 1, ('{"items":[{"id":"dd300afb-f03b-578b-b8f8-bbcb4c7fcfd7","text":"What makes this task hard for this athlete?"},{"id":"2302a99e-c13f-5794-8641-9c30260a026d","text":"What are you changing to progress it, and why that variable?"},{"id":"ae7624dc-4ac3-5b3f-bfd5-91341348142e","text":"What would you say to a parent who asks whether this prevents knee injuries?"},{"id":"9a5ea216-9741-5369-9ff0-586600e439ed","text":"Is the order you''re using evidence or G3 standard?"}]}')::jsonb, 'a6'),
  ('df54ff72-b06b-5de1-91a3-6df3b19aa774', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '40494986-b75f-5442-9084-8243f39ebf55', 'callout', 2, ('{"tone":"warning","title":"Practical window","body":"This course carries a minimum four-week practical window.  Practical observation time is additional to directed study and is collected on the floor."}')::jsonb, 'a7'),
  ('2dea6373-f404-5770-8b58-2863989119d1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dfac3ab6-5087-571d-aeb4-2e8956518451', 'quote', 1, ('{"text":"A COD time is a number produced by several abilities at once."}')::jsonb, 'a0'),
  ('6e2ec063-d434-5fc1-925c-a67cba2922a8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dfac3ab6-5087-571d-aeb4-2e8956518451', 'rich_text', 1, ('{"text":"To build capability to analyze, design, and progress pre-planned directional-change tasks, and to interpret COD performance as the multi-determinant outcome it is."}')::jsonb, 'a1'),
  ('25e19390-2228-5948-893f-ba55d39a5f25', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dfac3ab6-5087-571d-aeb4-2e8956518451', 'checklist', 1, ('{"items":[{"id":"2bc4d675-7bcc-52c5-aee5-227d3d790066","text":"M8.1 Name the contributors to COD performance"},{"id":"6c68afc4-15e0-560f-b0ca-c83a1af8b325","text":"M8.2 Explain why a faster COD time does not identify one quality"},{"id":"ac6af5df-57c5-5aad-bdd7-7734b1259a55","text":"M8.3 Explain how cut angle changes determinants"},{"id":"08f731ac-401a-53d1-9adc-8899d745d22a","text":"M8.4 Design COD tasks manipulating velocity, angle, braking, reacceleration"},{"id":"3b8117c5-9b1a-5bf4-aedc-a3b38900c188","text":"M8.5 Use COD deficit while stating its task dependence"},{"id":"f9fa34f8-8f18-519b-9a5f-85ef93f54d0b","text":"M8.6 Explain why the fastest sprinter is not automatically the best cutter"},{"id":"486b373c-33a2-5c5d-8cb8-1c1a4d1ea98c","text":"M8.7 Progress and regress without a universal angle ladder"}]}')::jsonb, 'a2'),
  ('456deaaf-3743-57b5-8e68-3db85cf445d0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'dfac3ab6-5087-571d-aeb4-2e8956518451', 'callout', 2, ('{"tone":"info","title":"Sequence & gating","body":"[object Object]"}')::jsonb, 'a3'),
  ('e47e76e7-893b-5306-9106-eb98117b0f13', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '58223b7e-2676-57c4-82a0-12c6577f899f', 'heading', 1, ('{"text":"L8.1 What a COD time contains","level":3}')::jsonb, 'a0'),
  ('d74b78e5-65f9-54a6-80db-b9a26f026e40', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '58223b7e-2676-57c4-82a0-12c6577f899f', 'rich_text', 1, ('{"text":"Linear speed into the task, braking to manage entry velocity, the plant and orientation that redirect momentum, and reacceleration out. A single number sums all of it, which is why it cannot diagnose any of it."}')::jsonb, 'a1'),
  ('5ce687ef-6986-5ad4-83c0-a3bf53bdd66b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '58223b7e-2676-57c4-82a0-12c6577f899f', 'heading', 1, ('{"text":"L8.2 Angle changes the task","level":3}')::jsonb, 'a2'),
  ('7908a1e0-ce36-53ec-b5b5-9e941cb3da79', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '58223b7e-2676-57c4-82a0-12c6577f899f', 'rich_text', 1, ('{"text":"Sharper cuts and wider directional changes do not have identical determinants. Programming and testing should reflect the angles the sport actually demands rather than defaulting to whichever test is familiar."}')::jsonb, 'a3'),
  ('bce2a2d5-e31b-5887-9079-c3ebd5eeca5d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '58223b7e-2676-57c4-82a0-12c6577f899f', 'heading', 1, ('{"text":"L8.3 Entry velocity as the design variable","level":3}')::jsonb, 'a4'),
  ('65c9af69-ea4c-5df2-8f31-f80f340a0071', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '58223b7e-2676-57c4-82a0-12c6577f899f', 'rich_text', 1, ('{"text":"Inherited from M7: the same cut at a higher approach velocity is a different task with a different braking demand. Manipulating entry velocity is the most direct way to change COD difficulty without changing the pattern."}')::jsonb, 'a5'),
  ('7a318fa5-3ba4-501a-99cc-44ce1e1e25af', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '58223b7e-2676-57c4-82a0-12c6577f899f', 'heading', 1, ('{"text":"L8.4 Reacceleration","level":3}')::jsonb, 'a6'),
  ('6b1cdc4a-424f-57c3-81a3-4b8f1597f806', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '58223b7e-2676-57c4-82a0-12c6577f899f', 'rich_text', 1, ('{"text":"The exit is part of the quality, and is frequently ignored in both drill design and interpretation."}')::jsonb, 'a7'),
  ('32ee0b5a-3828-53fa-913e-7ce51c5ac69d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '58223b7e-2676-57c4-82a0-12c6577f899f', 'heading', 1, ('{"text":"L8.5 COD deficit as a lens","level":3}')::jsonb, 'a8'),
  ('3a651191-d2e9-565f-9453-3c3c2d96d0d1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '58223b7e-2676-57c4-82a0-12c6577f899f', 'rich_text', 1, ('{"text":"What it attempts, what it can add, and why it remains task-dependent and cannot be treated as an isolate of \"true COD ability.\" Used as context alongside other measures (AS-103-11), never as a verdict (CJ-13)."}')::jsonb, 'a9'),
  ('f3cf7997-4b71-515a-92f0-9fde48cc8c5c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '58223b7e-2676-57c4-82a0-12c6577f899f', 'heading', 1, ('{"text":"L8.6 Why fast athletes are not automatically good cutters","level":3}')::jsonb, 'b0'),
  ('90c4b764-da56-564d-86d2-43e9dcdc6e16', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '58223b7e-2676-57c4-82a0-12c6577f899f', 'rich_text', 1, ('{"text":"COD outcomes are influenced by braking, angle, technique, orientation, and reacceleration beyond linear speed. This is the mechanism behind Case 3."}')::jsonb, 'b1'),
  ('62955a8a-6026-5991-9004-a561b5cbe0f8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '58223b7e-2676-57c4-82a0-12c6577f899f', 'heading', 1, ('{"text":"L8.7 Progression without a ladder","level":3}')::jsonb, 'b2'),
  ('9a8e7da8-8174-51ea-b2f6-a8b77649da2c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '58223b7e-2676-57c4-82a0-12c6577f899f', 'rich_text', 1, ('{"text":"Variables to manipulate: entry velocity, angle, number of changes, space, surface, exit demand, and total exposure. G3 supplies the variables and worked examples; it does not publish a universal sequence (CJ-09)."}')::jsonb, 'b3'),
  ('8551b338-abf8-5abc-a934-cff0d45e1295', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'abafef31-8ee7-57bb-8c8c-35b7e217069e', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-5 — COD Is Not Agility","body":"Pre-planned COD and agility are different constructs. COD involves a known movement solution. Agility requires perception, decision, and response to external information. — Teaching boundary: Distinct does not mean unrelated. The doctrine forbids treating them as the same, not as connected. — Evidence class: A"}')::jsonb, 'a0'),
  ('48933e47-4897-5ba7-b6c4-80af00bdc98e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'abafef31-8ee7-57bb-8c8c-35b7e217069e', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-10 — Testing Measures Tasks, Not Labels","body":"A sprint split, COD test, or reactive test measures performance under its specific constraints. Coaches do not infer maximal velocity, agility, or isolated physical qualities from a test that does not directly establish them. — Teaching boundary: A labeling and inference rule, not a rejection of field testing. No universal smallest-worthwhile-change threshold is created. — Evidence class: A"}')::jsonb, 'a1'),
  ('986c243b-637d-5118-860c-7f41d4bdbd09', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'abafef31-8ee7-57bb-8c8c-35b7e217069e', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-4 — Deceleration Is a Performance Quality","body":"Deceleration is not merely the first half of a COD drill. Braking capacity, momentum control, approach velocity, posture, and eccentric demands justify treating deceleration as a distinct training and assessment consideration. — Teaching boundary: Distinctness is A; diagnostics and the qualities that best develop it are C. No progression ladder is evidence-derived; AS-103-05 is an applied standard. — Evidence class: A"}')::jsonb, 'a2'),
  ('c8a40f0d-39e2-54dc-934b-4f3e0390d830', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'abafef31-8ee7-57bb-8c8c-35b7e217069e', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"COD performance depends on entry velocity, braking, plant mechanics, orientation, angle, reacceleration, and physical qualities — Basis: EP103-18, EP103-17, EP103-14 · cite:79, cite:80, cite:98"}')::jsonb, 'a3'),
  ('ebf019d1-388f-5d38-9608-2002c0125feb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'abafef31-8ee7-57bb-8c8c-35b7e217069e', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"A faster COD test time cannot be interpreted as proof of one underlying quality — Basis: EP103-18, EP103-04"}')::jsonb, 'a4'),
  ('57c3403a-2369-5a76-a081-eb262736a639', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'abafef31-8ee7-57bb-8c8c-35b7e217069e', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Determinants of sharper cuts and wider directional changes are not identical — Basis: EP103-17, EP103-18"}')::jsonb, 'a5'),
  ('1817ea99-2c4c-5308-bbe7-56ba99009b43', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'abafef31-8ee7-57bb-8c8c-35b7e217069e', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"COD is trainable and mechanically analyzable — Basis: EP103-18"}')::jsonb, 'a6'),
  ('492bac95-400a-5144-aad6-ccf8b06c7c31', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'abafef31-8ee7-57bb-8c8c-35b7e217069e', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Common field tests do not fully isolate the relevant determinants — Basis: EP103-18, EP103-02"}')::jsonb, 'a7'),
  ('4d8228d9-543c-51ba-bc23-b978882c8a33', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'abafef31-8ee7-57bb-8c8c-35b7e217069e', 'callout', 2, ('{"tone":"info","title":"Evidence — Class C","body":"COD deficit adds insight beyond raw time in some cases, but is task-dependent — Basis: EP103-18, EP103-04"}')::jsonb, 'a8'),
  ('4f8da446-e0bb-53d4-a710-308dca78be70', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'abafef31-8ee7-57bb-8c8c-35b7e217069e', 'callout', 2, ('{"tone":"info","title":"Evidence — Class F","body":"\"The fastest athlete should always have the best COD\" — Basis: CA-12"}')::jsonb, 'a9'),
  ('e32fcef5-017d-56f0-bd4c-4231325f76bc', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'abafef31-8ee7-57bb-8c8c-35b7e217069e', 'callout', 2, ('{"tone":"info","title":"Evidence — Class Not established — CJ-09","body":"Exact COD angle progression sequences — Basis: EP103-03, EP103-18"}')::jsonb, 'b0'),
  ('f3afcde9-36c9-57ed-aabf-ed0423e82260', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'abafef31-8ee7-57bb-8c8c-35b7e217069e', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"angle progression (CJ-09); weight given to COD deficit (CJ-13)."}')::jsonb, 'b1'),
  ('f51c31d3-9bcf-5607-a769-105455f557cd', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'abafef31-8ee7-57bb-8c8c-35b7e217069e', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Reading a COD time as ''agility'' or one quality · Programming one angle because one test uses it · Ignoring entry velocity while adding cones · Ignoring the exit · Using COD deficit deterministically · Assuming the fastest sprinter needs no COD work"}')::jsonb, 'b2'),
  ('4f043ea4-3411-5a8f-a640-772718dd0d86', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6c2b5871-ae30-5792-903d-3472b9bc3e9f', 'rich_text', 1, ('{"text":"For court sports, most competitive directional change happens at moderate entry velocity in small spaces with immediate exit demands — a profile that differs sharply from a 505-style test. G3 coaches design to the sport''s angles and entry velocities and use tests for what tests are for (M10)."}')::jsonb, 'a0'),
  ('68e4b5a3-54ff-5617-80bc-1945b79912df', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6c2b5871-ae30-5792-903d-3472b9bc3e9f', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"Feeds **PS-3** (the planned-COD half of the design task)."}')::jsonb, 'a1'),
  ('634f40b0-c621-523f-b42f-62d017ea277a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '8fe21377-488c-5768-984f-3961fadf980c', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('d87d203b-576b-557d-8371-55e9a1830042', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '8fe21377-488c-5768-984f-3961fadf980c', 'assessment_reference', 1, ('{"assessmentId":"ff176c6f-0aed-57f3-bf45-9f3c1a030b4c","title":"G3-103 · M8 Assessment — Change of Direction"}')::jsonb, 'a1'),
  ('e43b343c-9fd3-50a3-8d61-df5f2c8c9733', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e7a874bc-4169-50c8-ba40-b0008ad6e920', 'quote', 1, ('{"text":"If the athlete knows what they are going to do before they do it, you are not training agility."}')::jsonb, 'a0'),
  ('d72d86af-085b-5979-9a25-0b33d35fc499', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e7a874bc-4169-50c8-ba40-b0008ad6e920', 'rich_text', 1, ('{"text":"To make the COD/agility distinction operational: to build tasks containing genuine information demand, and to stop the labeling error that lets closed drills be sold as agility development."}')::jsonb, 'a1'),
  ('bcbddd2d-ea22-569e-b598-4d718ae0bac9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e7a874bc-4169-50c8-ba40-b0008ad6e920', 'checklist', 1, ('{"items":[{"id":"67ce4d6e-66d9-5140-b1c6-d87a1612cf83","text":"M9.1 Explain perception-action coupling"},{"id":"51b4f8d8-616b-549f-b534-ec9445d6a627","text":"M9.2 Distinguish artificial cues from representative information"},{"id":"279d48d6-4a10-5f1c-8953-7966fcc93909","text":"M9.3 Design reactive agility tasks with meaningful perception-action requirements"},{"id":"6942a1aa-5785-5e33-8be9-a287fdf24ad5","text":"M9.4 Manipulate information demand as a training variable"},{"id":"b63ac7c6-5215-505d-b8a6-7b2932ae5632","text":"M9.5 State what closed drills do and do not train"},{"id":"c471d424-d885-5126-8942-1656353eab84","text":"M9.6 State the actual strength of the agility-intervention evidence base"},{"id":"4eb0714e-02aa-5d4a-9921-2c31261d9541","text":"M9.7 Apply demand-based transfer reasoning to agility drill selection"}]}')::jsonb, 'a2'),
  ('e0743ec7-c608-523a-8588-361c69d3c7b2', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e7a874bc-4169-50c8-ba40-b0008ad6e920', 'callout', 2, ('{"tone":"info","title":"Sequence & gating","body":"[object Object]"}')::jsonb, 'a3'),
  ('9b854a2b-4055-529a-adeb-de6269278eee', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1a59184f-0861-54f1-9098-a3ad34d3d39e', 'heading', 1, ('{"text":"L9.1 Perception-action coupling","level":3}')::jsonb, 'a0'),
  ('400f1971-be98-56ec-8f91-51f5ee87a8fd', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1a59184f-0861-54f1-9098-a3ad34d3d39e', 'rich_text', 1, ('{"text":"The athlete perceives information and produces a movement solution. Remove the perception and you have removed the quality — however fast the movement is."}')::jsonb, 'a1'),
  ('9938fa8b-5139-5cb4-bfee-687a79ced2f9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1a59184f-0861-54f1-9098-a3ad34d3d39e', 'heading', 1, ('{"text":"L9.2 Artificial versus representative information","level":3}')::jsonb, 'a2'),
  ('3406c4da-3833-5d18-a95d-f31fd121aa00', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1a59184f-0861-54f1-9098-a3ad34d3d39e', 'rich_text', 1, ('{"text":"A coach''s call or a light is information, and it makes a task reactive. It is not the same as an opponent''s hips, a ball''s flight, or a developing play. Both have uses; the more representative the information, the stronger the transfer claim (D103-7)."}')::jsonb, 'a3'),
  ('d8df81d5-353c-50a5-9ef5-f931a1d79556', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1a59184f-0861-54f1-9098-a3ad34d3d39e', 'heading', 1, ('{"text":"L9.3 Information demand as a variable","level":3}')::jsonb, 'a4'),
  ('47690d46-6541-516e-91a2-76d9569783a4', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1a59184f-0861-54f1-9098-a3ad34d3d39e', 'rich_text', 1, ('{"text":"Number of options, time available, cue clarity, whether the cue is deceptive, and whether it appears before or during movement. This is the agility equivalent of load — the variable the coach actually manipulates."}')::jsonb, 'a5'),
  ('2b1abc53-a28a-59cf-907a-dd6513062216', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1a59184f-0861-54f1-9098-a3ad34d3d39e', 'heading', 1, ('{"text":"L9.4 What closed drills train","level":3}')::jsonb, 'a6'),
  ('23c0b1cf-a046-592b-a7dd-59b1d77e960b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1a59184f-0861-54f1-9098-a3ad34d3d39e', 'rich_text', 1, ('{"text":"Coordination, rhythm, movement organization, pattern familiarity, tissue exposure, COD capability. All legitimate. None of them agility. Naming this correctly is AS-103-10 and is scored."}')::jsonb, 'a7'),
  ('7dd0d54e-c5c4-5ff7-b6d5-a2af0281e091', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1a59184f-0861-54f1-9098-a3ad34d3d39e', 'heading', 1, ('{"text":"L9.5 Designing a reactive task","level":3}')::jsonb, 'a8'),
  ('6684ebc2-d82a-57cc-8428-ed850c68066f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1a59184f-0861-54f1-9098-a3ad34d3d39e', 'rich_text', 1, ('{"text":"Starting from the sport''s actual information: what the athlete really reads, when, and under what time pressure. Then constraining the task so that reading it is required to solve it."}')::jsonb, 'a9'),
  ('6a45a7c7-5188-5c2d-9155-1348a256c062', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1a59184f-0861-54f1-9098-a3ad34d3d39e', 'heading', 1, ('{"text":"L9.6 The honest evidence position","level":3}')::jsonb, 'b0'),
  ('c2982705-1c26-53fd-931a-51a8ebf5202a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1a59184f-0861-54f1-9098-a3ad34d3d39e', 'rich_text', 1, ('{"text":"The construct distinction is strong. The training evidence is smaller, heterogeneous, and more sport-specific — so G3 requires information demand (AS-103-07) without claiming a validated dose or progression."}')::jsonb, 'b1'),
  ('44519922-3724-5098-bdfb-8822e34ced65', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1a59184f-0861-54f1-9098-a3ad34d3d39e', 'heading', 1, ('{"text":"L9.7 Busy is not open","level":3}')::jsonb, 'b2'),
  ('27452ea9-0a5e-596f-b361-4df8fff33259', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1a59184f-0861-54f1-9098-a3ad34d3d39e', 'rich_text', 1, ('{"text":"A visually complex drill with a fully known solution is closed. Complexity and information demand are different things, and coaches routinely confuse them."}')::jsonb, 'b3'),
  ('d028b51c-afcb-512f-8333-e544e52cddb4', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '0ed31104-04cb-57b5-82fd-898194b5a201', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-5 — COD Is Not Agility","body":"Pre-planned COD and agility are different constructs. COD involves a known movement solution. Agility requires perception, decision, and response to external information. — Teaching boundary: Distinct does not mean unrelated. The doctrine forbids treating them as the same, not as connected. — Evidence class: A"}')::jsonb, 'a0'),
  ('97f80b3c-efbe-5337-a482-f5ff2daa9533', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '0ed31104-04cb-57b5-82fd-898194b5a201', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-6 — Closed Drills Do Not Automatically Train Agility","body":"Cone patterns, ladders, and pre-planned movement drills may train coordination, rhythm, movement skill, or COD. They are not labeled true agility development unless meaningful external information and response demands are present. — Teaching boundary: Closed drills are not condemned. The error is the label, not the drill. — Evidence class: B"}')::jsonb, 'a1'),
  ('cf5b4acb-f890-54b7-afd8-0e6f4da8eff8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '0ed31104-04cb-57b5-82fd-898194b5a201', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-7 — Transfer Is Demand-Based, Not Appearance-Based","body":"A drill does not transfer because it looks athletic or resembles sport. Transfer claims are tied to relevant force-time, velocity, coordination, braking, movement, or perception-action demands. — Teaching boundary: Not a rejection of specificity - a rejection of resemblance as evidence of it. Inherited from G3 102 Doctrine 5. — Evidence class: B"}')::jsonb, 'a2'),
  ('f1cf88ca-a79f-545f-9ba1-22a799cad92d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '0ed31104-04cb-57b5-82fd-898194b5a201', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Agility is distinct from pre-planned COD because it depends on perception-action coupling — Basis: EP103-04, EP103-19, EP103-21 · cite:85, cite:90, cite:107"}')::jsonb, 'a3'),
  ('13493a22-5c01-512c-b62e-24e5cf01f6f7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '0ed31104-04cb-57b5-82fd-898194b5a201', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Reactive agility tests can discriminate skill level beyond planned COD tests — Basis: EP103-21, EP103-22 · cite:107, cite:110"}')::jsonb, 'a4'),
  ('49c506f2-8061-5b10-8fce-c9158f56a5ff', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '0ed31104-04cb-57b5-82fd-898194b5a201', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B","body":"Ladder and cone drills often train footwork rhythm or pre-planned execution rather than perception-driven agility — Basis: EP103-04, EP103-19"}')::jsonb, 'a5'),
  ('95a6da66-bd3d-5ac2-bb23-22800a4df52c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '0ed31104-04cb-57b5-82fd-898194b5a201', 'callout', 2, ('{"tone":"info","title":"Evidence — Class F (both)","body":"\"Ladder drills improve agility\" / \"Cone drills train agility\" — Basis: CA-09, CA-10"}')::jsonb, 'a6'),
  ('275826d7-39e9-5d72-bb9d-bd921225297f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '0ed31104-04cb-57b5-82fd-898194b5a201', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B / C","body":"Training that includes representative information and response demands plausibly benefits reactive agility — Basis: EP103-23, EP103-21"}')::jsonb, 'a7'),
  ('b12a4733-efe1-5537-93bb-5850a84c6b84', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '0ed31104-04cb-57b5-82fd-898194b5a201', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A (a documented state of the evidence)","body":"The agility-training evidence base is smaller and less standardized than for linear sprinting or planned COD — Basis: EP103-23, EP103-03"}')::jsonb, 'a8'),
  ('c11a7b04-3923-5b6d-92c1-ba6d0a2970c4', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '0ed31104-04cb-57b5-82fd-898194b5a201', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B","body":"Transfer claims strengthen with representative information and decision demands; weaken when drills are visually busy but informationally closed — Basis: EP103-23, EP103-21"}')::jsonb, 'a9'),
  ('8bd868d5-d9fe-5057-88cb-cfe27228601e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '0ed31104-04cb-57b5-82fd-898194b5a201', 'callout', 2, ('{"tone":"info","title":"Evidence — Class Not established — CJ-11","body":"Exact reactive-agility progressions — Basis: EP103-03, EP103-23"}')::jsonb, 'b0'),
  ('c6eb6a2e-c158-5bed-a02e-a381841e5060', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '0ed31104-04cb-57b5-82fd-898194b5a201', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"the progression (CJ-11); how much of a session should be reactive."}')::jsonb, 'b1'),
  ('584c813d-3260-5550-ae1b-f9420574789e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '0ed31104-04cb-57b5-82fd-898194b5a201', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Calling ladder or cone work agility training · Cues arriving too late to be read · Mistaking complexity for information demand · Running only artificial cues and claiming sport transfer · Claiming a validated reactive dose · Abandoning closed drills entirely"}')::jsonb, 'b2'),
  ('4f928e06-869e-5cd2-8b7f-4e81fee28533', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '31b1d853-bc01-51fe-8380-947b66d78f7f', 'rich_text', 1, ('{"text":"In G3 team environments, the highest-value application is usually converting existing closed patterns into reactive ones by changing who or what determines the movement — a partner, a ball, a live scenario — rather than adding new drills. The session gets no longer; the information demand appears."}')::jsonb, 'a0'),
  ('68a36754-d844-53ab-9635-00e7b8aa86e3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '31b1d853-bc01-51fe-8380-947b66d78f7f', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"**PS-3 — COD vs Agility Design.** See §14.4. **PS-3 gates M10.**"}')::jsonb, 'a1'),
  ('f23598eb-a1be-5ab3-8b38-cc8a18365d62', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ede678ab-347f-5365-9818-7215df079cb2', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('fb064638-ed0c-5408-aa00-f1453be24a9d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ede678ab-347f-5365-9818-7215df079cb2', 'assessment_reference', 1, ('{"assessmentId":"3f9d1c1d-0b2b-5d3f-bf4a-837ecdb9e5b1","title":"G3-103 · M9 Assessment — Agility & Perception-Action Coupling"}')::jsonb, 'a1'),
  ('9b77c45f-616c-50eb-a46b-a80af43d163b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9abd5426-63e2-5e1d-9c3a-7606851c6fb4', 'callout', 2, ('{"tone":"info","title":"PS-3 — Observed practical sign-off","body":"Completed at: M9 — Function: gates M10 — This sign-off is observed and recorded by an approved G3 assessor. It cannot be self-recorded."}')::jsonb, 'a0'),
  ('a7ed5f54-31e7-59f9-86f2-16db536bcf72', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9abd5426-63e2-5e1d-9c3a-7606851c6fb4', 'heading', 1, ('{"text":"Observed behaviors","level":3}')::jsonb, 'a1'),
  ('5bd8876a-9fb8-50e2-a9c5-8fa5320f5598', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9abd5426-63e2-5e1d-9c3a-7606851c6fb4', 'checklist', 1, ('{"items":[{"id":"cf212aac-eab4-552d-a185-7648f556e705","text":"Designs and delivers a pre-planned COD task with deliberate entry velocity, angle, and exit demand"},{"id":"0b38936e-67ec-512d-9b15-7937e717d99b","text":"Designs and delivers a reactive task where perceiving the information is required to solve it"},{"id":"af753044-e89b-5100-847c-d2d6630bb0f6","text":"Identifies the informational difference out loud in perception-action terms"},{"id":"8ac37ecd-7daf-5c66-a491-2dee72a577ec","text":"Manipulates movement and decision constraints separately"},{"id":"456b0547-6b51-5da0-908d-9fc2b2c407ba","text":"Labels each construct correctly to athletes and in the session document"},{"id":"2da01666-bc3e-52ce-a617-21fdc79f95ea","text":"Coaches both appropriately"}]}')::jsonb, 'a2'),
  ('7d65cc94-25f0-5325-be3b-8ab105851328', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9abd5426-63e2-5e1d-9c3a-7606851c6fb4', 'heading', 1, ('{"text":"Required artifacts","level":3}')::jsonb, 'a3'),
  ('6809e630-c78f-5953-a67b-43fdcc5306e5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9abd5426-63e2-5e1d-9c3a-7606851c6fb4', 'checklist', 1, ('{"items":[{"id":"e1a5146b-381c-5f34-8e50-2001964ed3f6","text":"A8"},{"id":"a6979980-9bee-541f-8669-f667cda14c92","text":"A9"}]}')::jsonb, 'a4'),
  ('9885c74d-167a-5d73-adf1-fb394694b665', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9abd5426-63e2-5e1d-9c3a-7606851c6fb4', 'heading', 1, ('{"text":"Assessor questions","level":3}')::jsonb, 'a5'),
  ('9512ea42-2813-5c67-9cbc-1481eba01060', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9abd5426-63e2-5e1d-9c3a-7606851c6fb4', 'checklist', 1, ('{"items":[{"id":"77f2589b-85bf-5eb4-a348-b3923062743b","text":"Which of these is agility, and what makes it so?"},{"id":"d0d8e274-86f9-5a85-acb0-7bbdb385993f","text":"What information is the athlete actually reading?"},{"id":"2f163a44-39ed-51cc-8f74-f71a04243e83","text":"What happens to this task if I remove the cue?"},{"id":"f06b003a-768f-5e7f-9f2e-07ffe5a29dc4","text":"Is this drill complex or is it open - and what is the difference?"}]}')::jsonb, 'a6'),
  ('f819c8a7-9e93-582b-91d2-c01e668d9dce', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9abd5426-63e2-5e1d-9c3a-7606851c6fb4', 'callout', 2, ('{"tone":"warning","title":"Practical window","body":"This course carries a minimum four-week practical window.  Practical observation time is additional to directed study and is collected on the floor."}')::jsonb, 'a7'),
  ('b4001461-b070-530a-87d2-0836914925c0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'fabcd315-b053-5fa8-9641-97739ebdedd8', 'quote', 1, ('{"text":"The test measures what the test measures. Everything else you say about it is a claim you have to defend."}')::jsonb, 'a0'),
  ('52c59738-ec13-5414-8cb5-312c078c7848', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'fabcd315-b053-5fa8-9641-97739ebdedd8', 'rich_text', 1, ('{"text":"To make coaches capable of selecting tests that match the construct being evaluated, standardizing them well enough that results mean something, and interpreting change inside measurement limits."}')::jsonb, 'a1'),
  ('0239bc99-d71c-59cd-bd8d-ac7f592aac33', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'fabcd315-b053-5fa8-9641-97739ebdedd8', 'checklist', 1, ('{"items":[{"id":"402a617b-4dc2-5415-a9fa-3bbab2b4afec","text":"M10.1 Select a test matching the construct evaluated"},{"id":"c3c0af30-1946-5059-8709-0df6746116eb","text":"M10.2 State what common tests actually measure"},{"id":"013e897e-0779-5ed1-8d5a-40ba9eb9c1a1","text":"M10.3 Apply standardization requirements"},{"id":"f7f2fa9c-317a-55fb-9421-eec34f36c364","text":"M10.4 Interpret results using reliability and typical error"},{"id":"3cac3300-6b37-5d82-bd6e-1490e73cec09","text":"M10.5 Explain why no universal change threshold is published"},{"id":"5d93177a-e015-548e-9377-d7c8d027fc3a","text":"M10.6 Combine measures rather than over-diagnosing"},{"id":"a2ccbd5f-d339-57ab-b306-f970da20b642","text":"M10.7 Label test outputs accurately"}]}')::jsonb, 'a2'),
  ('78487674-2505-58d7-b6b3-3f28343ee9bf', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'fabcd315-b053-5fa8-9641-97739ebdedd8', 'callout', 2, ('{"tone":"info","title":"Sequence & gating","body":"[object Object]"}')::jsonb, 'a3'),
  ('3bf10090-6578-5e0a-8189-9b0f916d5513', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9aa0f2bc-6273-5716-95ba-b3c239e351f5', 'heading', 1, ('{"text":"L10.1 Construct first","level":3}')::jsonb, 'a0'),
  ('93923edb-f0f3-5260-bb3f-31938e7280c7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9aa0f2bc-6273-5716-95ba-b3c239e351f5', 'rich_text', 1, ('{"text":"Decide what quality is being evaluated, then select the test. Reversing that order is how a program ends up reporting \"speed\" from a 10 m gate."}')::jsonb, 'a1'),
  ('55fc85c8-87c8-5c9c-a6d2-a6c11a818f83', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9aa0f2bc-6273-5716-95ba-b3c239e351f5', 'heading', 1, ('{"text":"L10.2 What common tests measure","level":3}')::jsonb, 'a2'),
  ('d6f3405d-dd76-5037-8f7e-3a9780287ac4', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9aa0f2bc-6273-5716-95ba-b3c239e351f5', 'rich_text', 1, ('{"text":"Short splits and acceleration; flying sprints and higher-velocity performance when set up appropriately; pre-planned COD tests and the mixture of linear speed, braking, technique, and reacceleration they contain; reactive tests and the construct relevance they add along with the variability they bring."}')::jsonb, 'a3'),
  ('a05ac126-263d-5436-885e-9d2de4364d8a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9aa0f2bc-6273-5716-95ba-b3c239e351f5', 'heading', 1, ('{"text":"L10.3 Standardization","level":3}')::jsonb, 'a4'),
  ('a05f85bf-43f2-506b-a26f-b4fb3949c386', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9aa0f2bc-6273-5716-95ba-b3c239e351f5', 'rich_text', 1, ('{"text":"Objective timing where practical, consistent setup and start procedure, familiarization, consistent surface and footwear, recorded conditions (inherited G3 102 AS-06), and consistent administration. Without these, a later difference cannot be distinguished from a difference in conditions."}')::jsonb, 'a5'),
  ('035841fe-f602-52f2-8676-1730f4f8393a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9aa0f2bc-6273-5716-95ba-b3c239e351f5', 'heading', 1, ('{"text":"L10.4 Reliability and typical error","level":3}')::jsonb, 'a6'),
  ('9f920390-56f7-51c0-bbe5-e62f32ff9c67', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9aa0f2bc-6273-5716-95ba-b3c239e351f5', 'rich_text', 1, ('{"text":"What noise looks like in a given test, and the discipline of refusing to act inside it. Carried directly from G3 102 M4 and applied to sprint and COD measures."}')::jsonb, 'a7'),
  ('4e26c819-de60-5c05-b28a-de309b6db0fa', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9aa0f2bc-6273-5716-95ba-b3c239e351f5', 'heading', 1, ('{"text":"L10.5 Why G3 publishes no universal change threshold","level":3}')::jsonb, 'a8'),
  ('65e0d7ad-dc53-5e25-bf6d-c6eb5da0a0b2', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9aa0f2bc-6273-5716-95ba-b3c239e351f5', 'rich_text', 1, ('{"text":"Thresholds depend on the exact test, setup, and population. Inventing one would create false precision, and the course prohibits it (§15.4). What G3 requires instead is that the coach know roughly how much their test moves when nothing has changed."}')::jsonb, 'a9'),
  ('b53fb8b2-0e9a-54c0-864b-c6bc004d14b2', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9aa0f2bc-6273-5716-95ba-b3c239e351f5', 'heading', 1, ('{"text":"L10.6 Multiple measures","level":3}')::jsonb, 'b0'),
  ('27a0e63f-a55e-524a-b696-de3641369502', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9aa0f2bc-6273-5716-95ba-b3c239e351f5', 'rich_text', 1, ('{"text":"AS-103-11: profile with a small set of construct-appropriate measures rather than diagnosing everything from one. No composite score is produced, and no automated recommendation is generated from any battery."}')::jsonb, 'b1'),
  ('b2945f7a-5a40-5e1a-ad97-d6f6e5cfc2b3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9aa0f2bc-6273-5716-95ba-b3c239e351f5', 'heading', 1, ('{"text":"L10.7 Labeling in reports and conversations","level":3}')::jsonb, 'b2'),
  ('acc6a461-c398-5949-b85e-6fcab38ccda7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9aa0f2bc-6273-5716-95ba-b3c239e351f5', 'rich_text', 1, ('{"text":"How results are written and spoken: what was measured, under what conditions, and what it does and does not tell us. This is the artifact that a sport coach or parent actually sees."}')::jsonb, 'b3'),
  ('74c0563e-ecde-52f4-9792-865002017357', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c13f0b7d-f33c-5ef1-8865-a6282df2e274', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-10 — Testing Measures Tasks, Not Labels","body":"A sprint split, COD test, or reactive test measures performance under its specific constraints. Coaches do not infer maximal velocity, agility, or isolated physical qualities from a test that does not directly establish them. — Teaching boundary: A labeling and inference rule, not a rejection of field testing. No universal smallest-worthwhile-change threshold is created. — Evidence class: A"}')::jsonb, 'a0'),
  ('c36324ad-52bd-59b1-916f-fa4d845d29d4', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c13f0b7d-f33c-5ef1-8865-a6282df2e274', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-1 — Speed Is Phase-Specific","body":"Acceleration and maximal velocity are related but distinct sprint qualities. Coaches identify which speed demand is being trained or assessed rather than treating sprint performance as one undifferentiated quality. — Teaching boundary: The distinction is established; exact phase boundaries are not. G3 publishes no universal distance cut-point. — Evidence class: A"}')::jsonb, 'a1'),
  ('f7289528-3c29-5a8e-bc4a-ae4446c3936e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c13f0b7d-f33c-5ef1-8865-a6282df2e274', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-5 — COD Is Not Agility","body":"Pre-planned COD and agility are different constructs. COD involves a known movement solution. Agility requires perception, decision, and response to external information. — Teaching boundary: Distinct does not mean unrelated. The doctrine forbids treating them as the same, not as connected. — Evidence class: A"}')::jsonb, 'a2'),
  ('b9d05b7d-7650-5dc5-b81a-1dfd05dc726c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c13f0b7d-f33c-5ef1-8865-a6282df2e274', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-4 — Deceleration Is a Performance Quality","body":"Deceleration is not merely the first half of a COD drill. Braking capacity, momentum control, approach velocity, posture, and eccentric demands justify treating deceleration as a distinct training and assessment consideration. — Teaching boundary: Distinctness is A; diagnostics and the qualities that best develop it are C. No progression ladder is evidence-derived; AS-103-05 is an applied standard. — Evidence class: A"}')::jsonb, 'a3'),
  ('bb309235-3dab-56a8-a2e0-b1da657fd3b5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c13f0b7d-f33c-5ef1-8865-a6282df2e274', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Electronic timing is strongly preferable to hand timing for sprint assessment — Basis: EP103-02 · cite:97"}')::jsonb, 'a4'),
  ('0dd789b8-0532-526d-90c2-737aae376ac8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c13f0b7d-f33c-5ef1-8865-a6282df2e274', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Linear sprint tests can show strong reliability, but values depend on distance, setup, population, and procedure — Basis: EP103-02"}')::jsonb, 'a5'),
  ('f68f16a2-a3bb-56de-8865-d231c964e4fe', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c13f0b7d-f33c-5ef1-8865-a6282df2e274', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"A short sprint split may reflect acceleration more than maximal velocity — Basis: EP103-02, EP103-01"}')::jsonb, 'a6'),
  ('0636288f-8c84-5de8-9953-d196094a8262', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c13f0b7d-f33c-5ef1-8865-a6282df2e274', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"A COD test may reflect linear speed and braking as much as or more than \"agility\" — Basis: EP103-18, EP103-19, EP103-02"}')::jsonb, 'a7'),
  ('28316334-3c44-51e3-b6aa-edffb1d7de87', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c13f0b7d-f33c-5ef1-8865-a6282df2e274', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Linear sprint, planned COD, and reactive tests are not interchangeable constructs — Basis: EP103-02, EP103-20, EP103-21"}')::jsonb, 'a8'),
  ('b40a6f31-997b-5c54-b8f9-59f7a5796c1d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c13f0b7d-f33c-5ef1-8865-a6282df2e274', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B","body":"Reactive agility tests are informative but often carry more variable reliability and construct specificity — Basis: EP103-20, EP103-21"}')::jsonb, 'a9'),
  ('91a7adfe-0202-5c51-bd3f-b0fbbe716aeb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c13f0b7d-f33c-5ef1-8865-a6282df2e274', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Learning effects, familiarization, surface, and environment affect interpretation — Basis: EP103-02, EP103-20"}')::jsonb, 'b0'),
  ('2aa367f2-9503-5865-9fb4-cd3015ab540a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c13f0b7d-f33c-5ef1-8865-a6282df2e274', 'callout', 2, ('{"tone":"info","title":"Evidence — Class C","body":"COD deficit as additional context — Basis: EP103-18, EP103-04"}')::jsonb, 'b1'),
  ('49e45dba-6666-582a-8804-d965db5463ae', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c13f0b7d-f33c-5ef1-8865-a6282df2e274', 'callout', 2, ('{"tone":"info","title":"Evidence — Class C — Emerging; clean field diagnostics are a named gap","body":"Deceleration field diagnostics — Basis: EP103-14"}')::jsonb, 'b2'),
  ('444f2d18-44c8-5526-9f45-ab5a808ff439', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c13f0b7d-f33c-5ef1-8865-a6282df2e274', 'callout', 2, ('{"tone":"info","title":"Evidence — Class Not supported — none created (§15.4)","body":"Universal smallest-worthwhile-change thresholds across tests and populations — Basis: EP103-02"}')::jsonb, 'b3'),
  ('13bd68e5-9cdb-5941-934a-abe13db57c9c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c13f0b7d-f33c-5ef1-8865-a6282df2e274', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"which tests are practical enough for a given G3 environment despite construct limits; how much weight to give COD deficit (CJ-13) or deceleration deficit (CJ-14)."}')::jsonb, 'b4'),
  ('50f1d7f4-f9ca-5309-baf4-32d886f200b8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c13f0b7d-f33c-5ef1-8865-a6282df2e274', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Choosing the familiar test then deciding what it proves · Reporting a 10 m time as speed · Calling a COD test an agility test · Comparing across surfaces or timing methods · Acting inside the noise band · Borrowing a change threshold as universal · Building a composite athleticism score"}')::jsonb, 'b5'),
  ('529a592e-b2ec-5bae-81b3-f053da7d1285', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '28016e18-e5dc-56b7-b370-2587d16785fc', 'rich_text', 1, ('{"text":"For a G3 scholastic testing day: a short split for acceleration, a flying effort where space permits for higher-velocity capability, a COD test at an angle the sport actually uses, and — where it can be run consistently — a reactive task. Reported with construct labels attached, and with the explicit statement that these are separate qualities rather than a single \"speed score.\""}')::jsonb, 'a0'),
  ('9785cb8a-63b4-516d-a986-6be9d0cba887', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '28016e18-e5dc-56b7-b370-2587d16785fc', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"Feeds **PS-4** and **T-01** (testing choices are defended)."}')::jsonb, 'a1'),
  ('bb656b10-740e-53d6-ac36-80751d082825', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '49d765f8-3845-5778-9e58-474f69583d9d', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('b641864a-7c81-5560-940b-de84040f5017', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '49d765f8-3845-5778-9e58-474f69583d9d', 'assessment_reference', 1, ('{"assessmentId":"ed4aaa1a-af15-5f19-af92-9522911995c9","title":"G3-103 · M10 Assessment — Testing Speed, COD & Agility"}')::jsonb, 'a1'),
  ('0b980fc7-348d-50b3-868b-7d98b73a6007', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '0e5346f0-0170-56e2-b86a-9c67f115b3c6', 'quote', 1, ('{"text":"Youth athletes are not small elite sprinters, and the week is not a formula."}')::jsonb, 'a0'),
  ('8c11f8fd-fd3f-54c0-8e52-df26d1d43ae3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '0e5346f0-0170-56e2-b86a-9c67f115b3c6', 'rich_text', 1, ('{"text":"To build developmentally appropriate youth speed and multidirectional programming, and to integrate speed, COD, and agility work into a real week without pretending any microcycle model is validated."}')::jsonb, 'a1'),
  ('e0178cf1-cd4b-5337-b584-91f8cf630100', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '0e5346f0-0170-56e2-b86a-9c67f115b3c6', 'checklist', 1, ('{"items":[{"id":"b4ccb587-8744-5547-9d41-c836e64cf64a","text":"M11.1 Apply readiness-based reasoning to youth speed development"},{"id":"590b1ac0-d321-5750-829e-db5214c25fdd","text":"M11.2 Reject rigid age-window mythology while accounting for maturation"},{"id":"960453c6-2769-51f7-9faf-823303203f0a","text":"M11.3 Select methods appropriate to training age and exposure history"},{"id":"6ce77893-c987-5f05-b3ba-fec26632d4c9","text":"M11.4 Place speed and high-braking work where high outputs can be expressed"},{"id":"dd32ecaa-bd8c-5908-98d4-2fa5f4c924ab","text":"M11.5 Integrate speed work with practice and competition"},{"id":"8b7b8510-5bcd-5636-94fb-c67c1b5840c3","text":"M11.6 Explain why exact weekly placement remains Coach Judgment"},{"id":"7335ae2c-7ba7-512c-bfde-5e909e04e771","text":"M11.7 Disclose population transfer when applying adult or elite models"}]}')::jsonb, 'a2'),
  ('9199ea87-c672-5ce0-8d3a-2ee977af692e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '0e5346f0-0170-56e2-b86a-9c67f115b3c6', 'callout', 2, ('{"tone":"info","title":"Sequence & gating","body":"[object Object]"}')::jsonb, 'a3'),
  ('332423dc-9aba-554b-8190-c4cbc3825186', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c0894735-ea89-5659-97cb-34cf89840062', 'heading', 1, ('{"text":"L11.1 What the youth evidence supports","level":3}')::jsonb, 'a0'),
  ('ef44af3f-cd52-57ae-ab6d-517b8a424579', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c0894735-ea89-5659-97cb-34cf89840062', 'rich_text', 1, ('{"text":"Trainability across sprint, COD, and agility-related qualities, with the strongest support for broad modalities. This is a green light for well-designed work, not a licence for adult programming at half the load."}')::jsonb, 'a1'),
  ('d3b50a09-d567-58c4-8308-802876cc6dc2', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c0894735-ea89-5659-97cb-34cf89840062', 'heading', 1, ('{"text":"L11.2 Readiness over age windows","level":3}')::jsonb, 'a2'),
  ('996d3dd7-741c-5be8-aacf-2782cf045202', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c0894735-ea89-5659-97cb-34cf89840062', 'rich_text', 1, ('{"text":"Maturation, coordination, training age, readiness, movement competency, exposure history, supervision, and task complexity. Continuous with G3 102 Doctrine 9 and AS-30. Rigid age-based rules are rejected; maturation is not."}')::jsonb, 'a3'),
  ('40d384e9-f12c-5055-b2ae-70342da6c07b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c0894735-ea89-5659-97cb-34cf89840062', 'heading', 1, ('{"text":"L11.3 Complexity is the expensive variable","level":3}')::jsonb, 'a4'),
  ('c169457a-5ecf-5480-8554-3195d20380b3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c0894735-ea89-5659-97cb-34cf89840062', 'rich_text', 1, ('{"text":"In youth groups, coordination and instruction load usually constrain the session before physiology does — which argues for simpler tasks, clearer information demands, and more actual running."}')::jsonb, 'a5'),
  ('2c72dd58-bdce-5ac0-98a2-7b0becaa79b1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c0894735-ea89-5659-97cb-34cf89840062', 'heading', 1, ('{"text":"L11.4 Do not delay sprinting","level":3}')::jsonb, 'a6'),
  ('6d8be873-5b2a-5cbb-9dc3-2be1d451d94f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c0894735-ea89-5659-97cb-34cf89840062', 'rich_text', 1, ('{"text":"Athletes are not held out of meaningful sprint exposure pending a technique standard (AS-103-03, CA-14). Youth athletes sprint; coaching happens alongside it."}')::jsonb, 'a7'),
  ('f52c468b-9c5b-59c7-93e2-b796d262546a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c0894735-ea89-5659-97cb-34cf89840062', 'heading', 1, ('{"text":"L11.5 Placement in the week","level":3}')::jsonb, 'a8'),
  ('94ee37b6-ad7b-5299-a5c5-d47e313619ee', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c0894735-ea89-5659-97cb-34cf89840062', 'rich_text', 1, ('{"text":"Speed and high-braking work is placed where high outputs can be expressed — which usually means early in a session and away from accumulated fatigue. The principle is supported; the exact schedule is not, and no G3 microcycle formula is published (CJ-04)."}')::jsonb, 'a9'),
  ('33ce07b8-f256-5c5a-83f7-b87b2aa958dd', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c0894735-ea89-5659-97cb-34cf89840062', 'heading', 1, ('{"text":"L11.6 High/low and other practitioner systems","level":3}')::jsonb, 'b0'),
  ('970a2e2f-e1a1-5623-863a-23051484df4d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c0894735-ea89-5659-97cb-34cf89840062', 'rich_text', 1, ('{"text":"Taught as **Class E/D** — historically influential organizing logic with limited direct comparative evidence in this pack. Coaches may use it; they may not present it as validated."}')::jsonb, 'b1'),
  ('9bd2441d-4841-520a-b6cf-63cb005b168a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c0894735-ea89-5659-97cb-34cf89840062', 'heading', 1, ('{"text":"L11.7 Integration with practice and competition","level":3}')::jsonb, 'b2'),
  ('1a269033-5840-5883-b160-73de9e4b40bc', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c0894735-ea89-5659-97cb-34cf89840062', 'rich_text', 1, ('{"text":"Practice already contains sprinting, braking, and directional change, most of it uncounted. Weekly planning starts from what the athlete is already doing, which is the DEMAND stage of the G3 102 model applied to the calendar."}')::jsonb, 'b3'),
  ('05e00a71-d0c5-53c8-87c3-863d89d5d9aa', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '16184197-d81e-5769-96f9-f2998cb0fd51', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-11 — Youth Speed Development Is Readiness- and Development-Aware","body":"Youth athletes can improve sprint, COD, and agility-related qualities. Programming considers maturation, coordination, training age, readiness, and exposure history rather than relying on rigid chronological-age windows. — Teaching boundary: Rejecting age-window mythology is not a claim that maturation is irrelevant. Youth sprint-mechanics prescriptions remain extrapolated and are labeled (AS-103-12). — Evidence class: B"}')::jsonb, 'a0'),
  ('6b6d630d-3b53-5e5b-be4f-cc7d2227e0f1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '16184197-d81e-5769-96f9-f2998cb0fd51', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-8 — Speed Quality Requires Quality Exposure","body":"High-speed and high-intensity multidirectional work is generally organized to preserve meaningful output and technical quality. Fatigue is not evidence that speed training became more sport-specific. — Teaching boundary: No rest ratio, repetition count, or velocity-decrement threshold is established (CJ-03, CJ-07). Training under fatigue is not forbidden; claiming the fatigue made it specific is. — Evidence class: B"}')::jsonb, 'a1'),
  ('190087fc-de77-5718-b683-a7c091ef28ba', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '16184197-d81e-5769-96f9-f2998cb0fd51', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-2 — Exposure Is Irreplaceable","body":"General strength, power, and plyometric training can support sprint development, but they do not fully replace sprint-specific exposure when the desired adaptation is sprint performance. — Teaching boundary: Not a claim that the weight room is unimportant, and not a dose statement. Sets no minimum sprint volume (CJ-01). — Evidence class: B"}')::jsonb, 'a2'),
  ('9aaa90b7-75ca-5db1-b143-4011737c1fbf', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '16184197-d81e-5769-96f9-f2998cb0fd51', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Youth athletes can improve sprint, agility, and COD-related qualities — Basis: EP103-03, EP103-24, EP103-09 · cite:88, cite:76, cite:91"}')::jsonb, 'a3'),
  ('8072f676-3340-5abb-ab74-4bedbf99d179', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '16184197-d81e-5769-96f9-f2998cb0fd51', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B","body":"Development is shaped by maturation, training age, coordination, and sport exposure rather than chronological age alone — Basis: EP103-03"}')::jsonb, 'a4'),
  ('c107ac61-cc2c-5c1c-b004-4f48fc5fe9c8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '16184197-d81e-5769-96f9-f2998cb0fd51', 'callout', 2, ('{"tone":"info","title":"Evidence — Class F as stated in coaching culture; maturation may matter, but narrow age rules are unsupported","body":"Rigid developmental \"windows\" for speed or agility — Basis: EP103-03"}')::jsonb, 'a5'),
  ('8d53d5a3-02e5-550f-9d16-e70870f58528', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '16184197-d81e-5769-96f9-f2998cb0fd51', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A / B — quality and specificity of evidence vary","body":"Plyometrics, repeated sprint work, and some agility training are trainable modalities in youth — Basis: EP103-09, EP103-24, EP103-03"}')::jsonb, 'a6'),
  ('7d1ef2dc-7180-5336-9e27-d98063225203', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '16184197-d81e-5769-96f9-f2998cb0fd51', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D — extrapolated from adult or more-trained populations","body":"Detailed sprint-mechanics prescriptions for youth — Basis: EP103-01, EP103-03"}')::jsonb, 'a7'),
  ('ee3f2de6-2021-5ebb-b062-0a93b675f022', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '16184197-d81e-5769-96f9-f2998cb0fd51', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B","body":"Well-designed youth speed development is not inherently unsafe — Basis: EP103-03, EP103-09"}')::jsonb, 'a8'),
  ('1d04dcc3-92cf-5e22-8fd5-84174bb0b08f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '16184197-d81e-5769-96f9-f2998cb0fd51', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B","body":"Speed work should be placed where high outputs can be expressed — Basis: EP103-01"}')::jsonb, 'a9'),
  ('1b5874b5-4f95-5d51-a259-8bf8c1de8e4a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '16184197-d81e-5769-96f9-f2998cb0fd51', 'callout', 2, ('{"tone":"info","title":"Evidence — Class Not supported; high/low style scheduling is E/D — historically influential, limited direct comparat…","body":"One universal microcycle organization model — Basis: EP103-01"}')::jsonb, 'b0'),
  ('33479680-0b5e-5aeb-b0ce-b7693a22e83d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '16184197-d81e-5769-96f9-f2998cb0fd51', 'callout', 2, ('{"tone":"info","title":"Evidence — Class Not established — CJ-04, CJ-05","body":"Exact weekly placement and concurrent-interaction rules — Basis: EP103-01, EP103-03"}')::jsonb, 'b1'),
  ('74989b90-b50a-5c85-9485-00a2b6f4597c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '16184197-d81e-5769-96f9-f2998cb0fd51', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"weekly placement (CJ-04); whether to use high/low organization (CJ-05); volume and rest (CJ-01, CJ-03)."}')::jsonb, 'b2'),
  ('525dbe96-70eb-53f0-9048-ed7ba0d7146e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '16184197-d81e-5769-96f9-f2998cb0fd51', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Age-window claims · Delaying sprint exposure pending technique · Applying adult elite mechanics without disclosure · Presenting high/low as validated · Adding sessions without counting practice load · Inventing sex-specific rules to fill a gap"}')::jsonb, 'b3'),
  ('efa05933-5089-5f7f-b690-c5c20b96cfa1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ba9e07c9-d100-5a1f-9d6f-00ad534f9a43', 'rich_text', 1, ('{"text":"In G3 Youth S&C, the highest-value integration decision is usually subtractive: recognizing how much high-intensity multidirectional work practice already provides, and protecting one or two genuine quality exposures rather than adding volume to a schedule that is already full."}')::jsonb, 'a0'),
  ('7574132e-e9e3-5cc4-af50-8985a127b3ca', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ba9e07c9-d100-5a1f-9d6f-00ad534f9a43', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"Feeds **PS-4**."}')::jsonb, 'a1'),
  ('a4ccb045-3796-532f-b513-e21b45b4d6b1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7e972d74-4198-5fbd-82ab-144f91a43cdb', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('6ccb956c-577b-5b68-83bb-d51d42d8d084', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7e972d74-4198-5fbd-82ab-144f91a43cdb', 'assessment_reference', 1, ('{"assessmentId":"1a7f85c5-0d85-5104-8df5-0239970a3e8b","title":"G3-103 · M11 Assessment — Youth Development + Programming Integration"}')::jsonb, 'a1'),
  ('f63e618d-81ad-5946-91c4-0df7d2a8fc40', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '5c4c3ab1-b553-502d-b814-4ce316588535', 'quote', 1, ('{"text":"Why this, for this athlete, now - and what would change your mind?"}')::jsonb, 'a0'),
  ('8acd6213-a7ce-5447-b805-16e00b5e4660', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '5c4c3ab1-b553-502d-b814-4ce316588535', 'rich_text', 1, ('{"text":"To integrate the course into the G3 102 decision model, applied end to end to a speed/COD/agility case, and to prepare the learner to defend the resulting decisions under questioning."}')::jsonb, 'a1'),
  ('30d2f025-c9cf-55bd-b3c2-efef9ba16c5e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '5c4c3ab1-b553-502d-b814-4ce316588535', 'checklist', 1, ('{"items":[{"id":"93f4b507-bbc6-5d7a-832d-265605b0722e","text":"M12.1 Run the G3 102 decision model on a speed/COD/agility case"},{"id":"ff02761e-9dab-5baf-ae08-90528790f355","text":"M12.2 Build a speed demand profile"},{"id":"5448a3b7-883e-5aee-bf2a-90578db278ad","text":"M12.3 Identify the priority quality and state its opportunity cost"},{"id":"8081f8cd-59ca-523f-b731-1defb3915cf9","text":"M12.4 Audit a coaching claim against the evidence classes"},{"id":"e95d89c4-de4f-55d6-b360-e9e109b51704","text":"M12.5 Apply causal restraint to injury claims in communication"},{"id":"5a79d265-f926-59c2-a50b-d824a9339589","text":"M12.6 Separate evidence, applied standard, and judgment on demand"},{"id":"a24c0849-5389-5593-b974-3fc87dbb0572","text":"M12.7 Defend a full speed-development prescription"}]}')::jsonb, 'a2'),
  ('450f2452-5562-5a9d-bce9-6f7c1c298904', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '5c4c3ab1-b553-502d-b814-4ce316588535', 'callout', 2, ('{"tone":"info","title":"Sequence & gating","body":"[object Object]"}')::jsonb, 'a3'),
  ('46f3cfc7-ae61-5cd0-ade4-e3082f9bd6be', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7b8e803f-926f-54e4-adcb-5340e7e01e2f', 'heading', 1, ('{"text":"L12.1 The speed demand profile","level":3}')::jsonb, 'a0'),
  ('e9014ff4-f7ca-56f1-b415-087fe57092b4', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7b8e803f-926f-54e4-adcb-5340e7e01e2f', 'rich_text', 1, ('{"text":"Applying G3 102''s DEMAND stage to this domain: which qualities the sport requires, at what distances and entry velocities, how much is pre-planned, and what the schedule already supplies."}')::jsonb, 'a1'),
  ('2b3f191d-c31f-5c4c-9d51-db27b84afd27', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7b8e803f-926f-54e4-adcb-5340e7e01e2f', 'heading', 1, ('{"text":"L12.2 Profile and gap in speed terms","level":3}')::jsonb, 'a2'),
  ('7ca09040-e88f-5880-bd3b-3d5dfca77073', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7b8e803f-926f-54e4-adcb-5340e7e01e2f', 'rich_text', 1, ('{"text":"Construct-appropriate testing (M10) into a gap statement that distinguishes an acceleration deficit from a maximal-velocity deficit from a braking deficit from an information-processing deficit."}')::jsonb, 'a3'),
  ('1b0bd074-0bd1-5a6a-8945-1370321600d2', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7b8e803f-926f-54e4-adcb-5340e7e01e2f', 'heading', 1, ('{"text":"L12.3 Priority and cost","level":3}')::jsonb, 'a4'),
  ('f6a18647-e0cd-538b-915b-c7d9a5cef97a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7b8e803f-926f-54e4-adcb-5340e7e01e2f', 'rich_text', 1, ('{"text":"One primary quality, tiered secondary qualities, and the written opportunity-cost statement carried from G3 102 AS-10."}')::jsonb, 'a5'),
  ('b5843ffd-7080-5bb7-b500-1dcf7aa70076', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7b8e803f-926f-54e4-adcb-5340e7e01e2f', 'heading', 1, ('{"text":"L12.4 Prescription","level":3}')::jsonb, 'a6'),
  ('2807edaa-4935-557c-85bb-748d54d5f536', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7b8e803f-926f-54e4-adcb-5340e7e01e2f', 'rich_text', 1, ('{"text":"Method selection, session order, weekly placement, and progression variables — assembled from M5 to M11."}')::jsonb, 'a7'),
  ('0065d929-a24b-5916-91e3-7ccc38d9b9e8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7b8e803f-926f-54e4-adcb-5340e7e01e2f', 'heading', 1, ('{"text":"L12.5 Response and adjustment","level":3}')::jsonb, 'a8'),
  ('b35efebd-7094-54a6-8d44-0825cd93e1b0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7b8e803f-926f-54e4-adcb-5340e7e01e2f', 'rich_text', 1, ('{"text":"Retesting against typical error with construct labels intact, and the four G3 102 adjustment actions: progress, hold, modify, re-enter."}')::jsonb, 'a9'),
  ('3a182f73-2dd1-5c1c-a1d3-148ab833b6b0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7b8e803f-926f-54e4-adcb-5340e7e01e2f', 'heading', 1, ('{"text":"L12.6 The claim audit","level":3}')::jsonb, 'b0'),
  ('5a8434b8-5521-5874-98eb-56a1d97e0911', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7b8e803f-926f-54e4-adcb-5340e7e01e2f', 'rich_text', 1, ('{"text":"Running the §16 register against a real program, a real conversation, or a real piece of marketing copy. Injury language is audited explicitly."}')::jsonb, 'b1'),
  ('7cbda6ef-d116-5893-bad8-ab172c4cd155', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7b8e803f-926f-54e4-adcb-5340e7e01e2f', 'heading', 1, ('{"text":"L12.7 The defense","level":3}')::jsonb, 'b2'),
  ('acd203b0-3d0b-55e2-b213-949808c3ae09', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '7b8e803f-926f-54e4-adcb-5340e7e01e2f', 'rich_text', 1, ('{"text":"Rehearsing the seven obligations (§1.3) out loud under questioning, including the sentence that names what remains judgment."}')::jsonb, 'b3'),
  ('d32a52b3-cecf-598e-bb63-447dfaaa987b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6648dcff-162e-5b36-887d-e9ed91bf191b', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-1 — Speed Is Phase-Specific","body":"Acceleration and maximal velocity are related but distinct sprint qualities. Coaches identify which speed demand is being trained or assessed rather than treating sprint performance as one undifferentiated quality. — Teaching boundary: The distinction is established; exact phase boundaries are not. G3 publishes no universal distance cut-point. — Evidence class: A"}')::jsonb, 'a0'),
  ('516d8854-31a9-5549-80b5-704f805fd461', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6648dcff-162e-5b36-887d-e9ed91bf191b', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-2 — Exposure Is Irreplaceable","body":"General strength, power, and plyometric training can support sprint development, but they do not fully replace sprint-specific exposure when the desired adaptation is sprint performance. — Teaching boundary: Not a claim that the weight room is unimportant, and not a dose statement. Sets no minimum sprint volume (CJ-01). — Evidence class: B"}')::jsonb, 'a1'),
  ('a84eaef9-fab9-5913-9f68-c0c1ad7d8d37', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6648dcff-162e-5b36-887d-e9ed91bf191b', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-3 — Mechanics Inform; They Do Not Dictate","body":"Biomechanics can describe characteristics associated with better sprint performance. A descriptive characteristic does not automatically become a causal coaching target. G3 does not impose one universal sprint-mechanics model on every athlete. — Teaching boundary: Descriptive support is A-class; technique-intervention evidence is limited by comparison; universalizing an elite track model is F. Technique coaching is not forbidden - gating exposure on it is. — Evidence class: B"}')::jsonb, 'a2'),
  ('e33aae4b-d490-5881-a43c-0734cc544631', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6648dcff-162e-5b36-887d-e9ed91bf191b', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-4 — Deceleration Is a Performance Quality","body":"Deceleration is not merely the first half of a COD drill. Braking capacity, momentum control, approach velocity, posture, and eccentric demands justify treating deceleration as a distinct training and assessment consideration. — Teaching boundary: Distinctness is A; diagnostics and the qualities that best develop it are C. No progression ladder is evidence-derived; AS-103-05 is an applied standard. — Evidence class: A"}')::jsonb, 'a3'),
  ('a3f69b6a-523e-58a2-a5fc-8c11bcd66368', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6648dcff-162e-5b36-887d-e9ed91bf191b', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-5 — COD Is Not Agility","body":"Pre-planned COD and agility are different constructs. COD involves a known movement solution. Agility requires perception, decision, and response to external information. — Teaching boundary: Distinct does not mean unrelated. The doctrine forbids treating them as the same, not as connected. — Evidence class: A"}')::jsonb, 'a4'),
  ('ee611f82-e93e-5f50-893e-fe13ebe62aa9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6648dcff-162e-5b36-887d-e9ed91bf191b', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-6 — Closed Drills Do Not Automatically Train Agility","body":"Cone patterns, ladders, and pre-planned movement drills may train coordination, rhythm, movement skill, or COD. They are not labeled true agility development unless meaningful external information and response demands are present. — Teaching boundary: Closed drills are not condemned. The error is the label, not the drill. — Evidence class: B"}')::jsonb, 'a5'),
  ('5040613d-74f8-5f16-a038-cc7805987816', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6648dcff-162e-5b36-887d-e9ed91bf191b', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-7 — Transfer Is Demand-Based, Not Appearance-Based","body":"A drill does not transfer because it looks athletic or resembles sport. Transfer claims are tied to relevant force-time, velocity, coordination, braking, movement, or perception-action demands. — Teaching boundary: Not a rejection of specificity - a rejection of resemblance as evidence of it. Inherited from G3 102 Doctrine 5. — Evidence class: B"}')::jsonb, 'a6'),
  ('b6acbe7c-c7a4-5636-8321-5cc509465a6d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6648dcff-162e-5b36-887d-e9ed91bf191b', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-8 — Speed Quality Requires Quality Exposure","body":"High-speed and high-intensity multidirectional work is generally organized to preserve meaningful output and technical quality. Fatigue is not evidence that speed training became more sport-specific. — Teaching boundary: No rest ratio, repetition count, or velocity-decrement threshold is established (CJ-03, CJ-07). Training under fatigue is not forbidden; claiming the fatigue made it specific is. — Evidence class: B"}')::jsonb, 'a7'),
  ('86dca6d5-9d8c-5841-b7ed-364c98a07581', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6648dcff-162e-5b36-887d-e9ed91bf191b', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-9 — Load Serves the Intended Sprint Adaptation","body":"Resisted sprinting is a supported training tool, especially for acceleration, but G3 does not adopt one universal sled load or percentage for every athlete and outcome. — Teaching boundary: A that RST improves sprint performance; C for loading strategy. No percentage, decrement number, or load table appears anywhere in G3 103. Both absolutist claims rejected (CA-06, CA-07). — Evidence class: A"}')::jsonb, 'a8'),
  ('6ac012c1-5acd-5695-8340-706a17fc19ff', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6648dcff-162e-5b36-887d-e9ed91bf191b', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-10 — Testing Measures Tasks, Not Labels","body":"A sprint split, COD test, or reactive test measures performance under its specific constraints. Coaches do not infer maximal velocity, agility, or isolated physical qualities from a test that does not directly establish them. — Teaching boundary: A labeling and inference rule, not a rejection of field testing. No universal smallest-worthwhile-change threshold is created. — Evidence class: A"}')::jsonb, 'a9'),
  ('a1e8c8c5-e646-5fcd-a8aa-464fc32b27f8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6648dcff-162e-5b36-887d-e9ed91bf191b', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-11 — Youth Speed Development Is Readiness- and Development-Aware","body":"Youth athletes can improve sprint, COD, and agility-related qualities. Programming considers maturation, coordination, training age, readiness, and exposure history rather than relying on rigid chronological-age windows. — Teaching boundary: Rejecting age-window mythology is not a claim that maturation is irrelevant. Youth sprint-mechanics prescriptions remain extrapolated and are labeled (AS-103-12). — Evidence class: B"}')::jsonb, 'b0'),
  ('7b0df50b-1116-5c77-83ad-a2df5a12e988', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6648dcff-162e-5b36-887d-e9ed91bf191b', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D103-12 — Injury Claims Require Causal Restraint","body":"G3 distinguishes tissue demand, association, mechanistic plausibility, risk-factor evidence, and intervention evidence. Sprinting, deceleration, or COD training is not marketed as inherently dangerous or inherently injury-preventive without appropriate evidence. — Teaching boundary: Restraint runs both directions: no protection promises, and no withholding exposure on an unsupported danger claim. Binds marketing, parent, and athlete communication. — Evidence class: B"}')::jsonb, 'b1'),
  ('67c2858a-4e24-5b6c-9e8e-80706fc461ff', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6648dcff-162e-5b36-887d-e9ed91bf191b', 'callout', 2, ('{"tone":"info","title":"Evidence — Class D — Applied Coaching Inference","body":"The G3 102 decision model as an integrated whole — Basis: Carried forward unchanged from G3 102 §5.1"}')::jsonb, 'b2'),
  ('64b29f15-b83b-5c7a-ba4b-d64bfa0a21f3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6648dcff-162e-5b36-887d-e9ed91bf191b', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B","body":"Sprint, braking, and cutting impose substantial tissue demands; maximal-velocity exposure is relevant to hamstring function and loading — Basis: EP103-14, EP103-11, EP103-16"}')::jsonb, 'b3'),
  ('b4f83c4f-2431-5aaa-b832-76fcbb5536ab', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6648dcff-162e-5b36-887d-e9ed91bf191b', 'callout', 2, ('{"tone":"info","title":"Evidence — Class F (both)","body":"\"Sprinting prevents hamstring injuries\" / \"Maximal-velocity sprinting is inherently dangerous\" — Basis: CA-16, CA-17"}')::jsonb, 'b4'),
  ('6fd14906-59e7-5480-a4e8-277717fc6dc8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6648dcff-162e-5b36-887d-e9ed91bf191b', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A (methodological)","body":"Association and mechanistic plausibility are not intervention proof — Basis: EP103-14, EP103-01"}')::jsonb, 'b5'),
  ('e1d9f0a9-d3a7-509b-ae17-fcc65aa2bf35', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6648dcff-162e-5b36-887d-e9ed91bf191b', 'callout', 2, ('{"tone":"info","title":"Evidence — Class Gap","body":"Exact dose-response for sprint, COD, and deceleration exposure in mixed-demand schedules — Basis: EP103-01 — named, not filled"}')::jsonb, 'b6'),
  ('48f08596-3372-5453-b126-7c960ca9a953', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6648dcff-162e-5b36-887d-e9ed91bf191b', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"the priority itself; every item in §8 that the case touches."}')::jsonb, 'b7'),
  ('eb42afc2-0e57-5b0c-baaa-d0f7278845df', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '6648dcff-162e-5b36-887d-e9ed91bf191b', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Running the model without naming the primary quality · A prescription contradicting its own priority in session order · Testing one construct and claiming another · Injury-prevention language in parent or marketing communication · Presenting judgment as evidence under questioning · Unable to name anything that would change the plan"}')::jsonb, 'b8'),
  ('3952cbe1-ab15-5db3-819f-3ecbc80e5652', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '2c35618b-5f12-5f26-806d-45336d235c2b', 'rich_text', 1, ('{"text":"This module produces the artifact a G3 coach actually carries: a one-page speed plan naming the priority quality, the methods, the tests, the progression variables, and the evidence boundaries — defensible to a sport coach in ninety seconds and to an assessor in twenty minutes."}')::jsonb, 'a0'),
  ('fb520abe-24db-5e68-b370-3e327045ab9a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '2c35618b-5f12-5f26-806d-45336d235c2b', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"**PS-4 — Integrated Speed Session / Microcycle** (§14.5), then **T-01 — Speed, COD & Agility Programming Defense** (§14.6)."}')::jsonb, 'a1'),
  ('3f904a6f-baa8-5c1d-b766-03f8afb691dc', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e40520ed-0d02-559a-9762-b797ff15f7ba', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('ee16aeda-93a4-5f54-8c05-751ac64484bc', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e40520ed-0d02-559a-9762-b797ff15f7ba', 'assessment_reference', 1, ('{"assessmentId":"54a55ead-22fc-5eac-8b60-c83ef7b6eee7","title":"G3-103 · M12 Assessment — Integrated G3 Speed Decision-Making"}')::jsonb, 'a1'),
  ('d121fbd5-642b-5e9b-ad3e-b6fc35577651', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ba231e65-3942-5007-ae7e-c2227561d64c', 'callout', 2, ('{"tone":"info","title":"PS-4 — Observed practical sign-off","body":"Completed at: M12 — Function: completion requirement; requires four-week delivery window — This sign-off is observed and recorded by an approved G3 assessor. It cannot be self-recorded."}')::jsonb, 'a0'),
  ('8155feb6-7d74-53a1-a244-17e68576d28d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ba231e65-3942-5007-ae7e-c2227561d64c', 'heading', 1, ('{"text":"Observed behaviors","level":3}')::jsonb, 'a1'),
  ('2fb5a79f-5d4d-5f4b-87ee-e6c3dccce01c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ba231e65-3942-5007-ae7e-c2227561d64c', 'checklist', 1, ('{"items":[{"id":"f888636f-c9c7-580c-8b45-d2a3a85f0b33","text":"Identifies primary and secondary qualities unprompted"},{"id":"a53a2828-3e84-519e-9a59-62a966c7633a","text":"Organizes exposures to protect output quality and adjusts when quality degrades"},{"id":"f73f3260-ebdb-5b02-be54-0e6311fe8bce","text":"Integrates supporting strength and plyometric work with stated intended adaptations"},{"id":"04a1fc3e-c1f8-5176-ae0b-b2b4635e44e9","text":"Justifies weekly placement in terms of where high outputs can be expressed"},{"id":"2dadd7da-7fe5-508e-9191-a5d3f50e27b1","text":"Identifies what remains Coach Judgment"},{"id":"f62399f3-71c4-57ba-952a-ec037ee8e576","text":"Delivers the session as planned or can say what was traded"}]}')::jsonb, 'a2'),
  ('10d266c9-720a-52b6-97a2-4eeef42291dd', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ba231e65-3942-5007-ae7e-c2227561d64c', 'heading', 1, ('{"text":"Required artifacts","level":3}')::jsonb, 'a3'),
  ('13fb7109-069b-512f-8c1a-0f47ae3f5ce6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ba231e65-3942-5007-ae7e-c2227561d64c', 'checklist', 1, ('{"items":[{"id":"87eb767d-f4dc-5a3b-bacf-a783541e609f","text":"A10"},{"id":"785c94c9-b8a3-5df0-9346-e5b5ad8ff729","text":"A11"},{"id":"fe9f598c-73fc-5fc5-ae4f-f76f4986e453","text":"A12"},{"id":"0fb54412-3bf4-5bf5-9f07-4b0f8509e052","text":"delivered plan (4-week minimum)"}]}')::jsonb, 'a4'),
  ('45509539-eb60-5361-bcc6-4174032e9f77', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ba231e65-3942-5007-ae7e-c2227561d64c', 'heading', 1, ('{"text":"Assessor questions","level":3}')::jsonb, 'a5'),
  ('9c24fb40-9e23-5447-8f91-9a3f5a076a3e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ba231e65-3942-5007-ae7e-c2227561d64c', 'checklist', 1, ('{"items":[{"id":"0e8c1180-6a9a-56e4-8584-c9a212b7e095","text":"What is the primary quality this week, and what is it costing?"},{"id":"ecd60bb2-b6be-595e-8711-b1af49f48a66","text":"What told you the quality had degraded?"},{"id":"2a330571-ba4b-5e95-a86b-0510d30cf28e","text":"Which placement decisions are evidence and which are your call?"},{"id":"5ac563d6-508d-5625-b879-54020c0d6e69","text":"What did practice already give these athletes this week?"}]}')::jsonb, 'a6'),
  ('b071249d-61ea-550b-9e42-28a2f14b9660', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'ba231e65-3942-5007-ae7e-c2227561d64c', 'callout', 2, ('{"tone":"warning","title":"Practical window","body":"This course carries a minimum four-week practical window. PS-4 cannot be scheduled until the delivery window is complete. Practical observation time is additional to directed study and is collected on the floor."}')::jsonb, 'a7'),
  ('1c8dcb78-54ae-5e37-b773-9c8e1456d0a9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '31b61e4c-90a1-50d8-b879-2399cc50fc39', 'callout', 2, ('{"tone":"info","title":"T-01 — Terminal defense","body":"20-30 minutes with an approved assessor using the coach''s own athlete and artifacts; assessor works the seven obligations in order and probes at least four — Required for: course competency completion — The defense is evaluated live by an approved G3 evaluator. Failure on T-01 cannot be offset by module performance."}')::jsonb, 'a0'),
  ('bb143b58-f59c-5b73-8e92-34a1386fd849', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '31b61e4c-90a1-50d8-b879-2399cc50fc39', 'heading', 1, ('{"text":"Must defend","level":3}')::jsonb, 'a1'),
  ('1f7c0f5d-c5a6-5bdc-a809-19843a38f50c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '31b61e4c-90a1-50d8-b879-2399cc50fc39', 'checklist', 1, ('{"items":[{"id":"15ea0595-79da-52e7-b409-7aaa7b160414","text":"demand analysis"},{"id":"d43dd357-9e5c-5569-95b6-738bf9b800ec","text":"terminology"},{"id":"8d602895-73f1-5622-909a-e9068d42136a","text":"priority"},{"id":"89741798-e535-58d0-8629-85734058dcd5","text":"method selection"},{"id":"405cb14a-6578-5803-99aa-62bcaa71bee3","text":"dosage logic"},{"id":"6db12f1d-f58d-5c2f-a027-d32e070b3413","text":"testing"},{"id":"d3dbac15-d780-52ad-bb88-18200b6570b0","text":"progression"},{"id":"1bd9783f-f05c-5479-aa34-4620290db1f8","text":"evidence classification"},{"id":"c752cc04-7970-5927-a0da-39a9b1ae3d42","text":"G3 Applied Standards applied"},{"id":"a368f85c-5c84-5f2c-bf56-609b7327c635","text":"remaining uncertainty"}]}')::jsonb, 'a2'),
  ('d1650995-d4c7-53de-8a46-7e254f3d0cea', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '31b61e4c-90a1-50d8-b879-2399cc50fc39', 'heading', 1, ('{"text":"Mandatory probes","level":3}')::jsonb, 'a3'),
  ('bfc5a868-ff1e-5bb9-b96b-7de87f5eac77', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '31b61e4c-90a1-50d8-b879-2399cc50fc39', 'checklist', 1, ('{"items":[{"id":"332df00f-1b5f-5ef2-84d9-eb9a2d9e3d41","text":"Name the primary quality in this plan, and show me where it appears in the session order."},{"id":"1328b9f4-c6b7-5e2e-9af8-dd7dcfd396d4","text":"This test - what does it actually measure, and what did you claim from it?"},{"id":"d729d763-6c7c-583f-b572-082b62236603","text":"Why this method rather than the alternative, and what adaptation are you buying?"},{"id":"bf19484a-99ef-5420-8692-975436438513","text":"Which part of what you just told me is evidence, which is G3 standard, and which is your judgment?"},{"id":"da6df9d0-2676-58fd-ad17-20807bfca009","text":"What would make you change this plan? Be specific."},{"id":"cfee8f73-d1c6-51f5-8e9e-27ed964b4eb9","text":"Say what you would tell this athlete''s parent about injury risk."}]}')::jsonb, 'a4'),
  ('ed29239d-98d1-5784-a0ed-c74e88710e37', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '31b61e4c-90a1-50d8-b879-2399cc50fc39', 'callout', 2, ('{"tone":"danger","title":"Non-compensable failures","body":"cannot answer probe 4 · makes an injury-prevention claim on probe 6"}')::jsonb, 'a5'),
  ('4d355744-5c1c-5dcc-9e1d-aed304379e30', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '31b61e4c-90a1-50d8-b879-2399cc50fc39', 'callout', 2, ('{"tone":"info","title":"Defense rubric","body":"defense_rubric"}')::jsonb, 'a6'),
  ('95788d0a-04dd-523f-b08d-c9d79840fab6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '31b61e4c-90a1-50d8-b879-2399cc50fc39', 'callout', 2, ('{"tone":"warning","title":"Practical window","body":"This course carries a minimum four-week practical window.  Practical observation time is additional to directed study and is collected on the floor."}')::jsonb, 'a7')
insert into public.lesson_versions (id, organization_id, lesson_id, course_id, version_number, title, required, estimated_minutes, blocks, published_by) values
  ('9d962985-faac-5507-b7a8-36ad0b93d7f3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c6a2a08c-de04-5172-982c-5971351f8a33', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 1, 'Overview & objectives', true, 8, (('[{"id":"0664f4d8-f321-584d-9cf2-3e129f8589ae","type":"quote","schemaVersion":1,"data":{"text":"Every bad speed program starts with a word."},"position":"a0"},{"id":"2f45796e-20b9-5123-a84a-82df34577dd7","type":"rich_text","schemaVersion":1,"data":{"text":"To install the controlled vocabulary the rest of the course depends on, and to make the learner capable of naming the quality a task actually trains before any programming decision is made."},"position":"a1"},{"id":"b5f01235-fcfa-544f-8c08-fbab43d5d7c6","type":"checklist","schemaVersion":1,"data":{"items":[{"id":"3c1cca94-5b02-5864-862c-0ecb7d76001a","text":"M1.1 Define speed, acceleration, maximal velocity, deceleration, COD, agility, reactive agility using G3 definitions"},{"id":"0f0dd205-96d0-5a01-98e0-5924377ef9ec","text":"M1.2 Explain why acceleration and maximal velocity are distinct qualities"},{"id":"eeae3418-fbaa-5efe-a08c-cebb3d9fbb19","text":"M1.3 Explain why COD and agility are distinct constructs"},{"id":"24df550f-acdf-59f6-a212-5a10bafd21dc","text":"M1.4 Apply the five task-identification questions"},{"id":"2e4c4e94-5be2-584a-949d-addba01d01d5","text":"M1.5 Describe COD deficit as a task-dependent lens"},{"id":"a1ddf'
