insert into public.assessment_items (id, organization_id, assessment_id, item_type, schema_version, data, position, required) values
  ('af07db61-66fb-5523-8e9c-32d2ffd8f8bf', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a3131faf-caa0-59ea-b442-d7f5ba6c6465', 'short_answer', 1, ('{"prompt":"K1.1 Which statement best describes the relationship between acceleration and maximal velocity?","instructions":"Source item format: MC. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a0', true),
  ('84513e3f-76bc-52b5-addb-338b8f86af25', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a3131faf-caa0-59ea-b442-d7f5ba6c6465', 'short_answer', 1, ('{"prompt":"K1.2 Which features distinguish agility from pre-planned COD?","instructions":"Source item format: Select all. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a1', true),
  ('f4e28ed5-1a5d-5227-8095-b863d6b580d3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a3131faf-caa0-59ea-b442-d7f5ba6c6465', 'short_answer', 1, ('{"prompt":"K1.3 A 10 m sprint split primarily reflects…","instructions":"Source item format: MC. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a2', true),
  ('21207fe8-45e0-5065-983c-cfe1475a6d2a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a3131faf-caa0-59ea-b442-d7f5ba6c6465', 'short_answer', 1, ('{"prompt":"K1.4 \"The acceleration phase ends at 10 m.\"","instructions":"Source item format: True/False + justification. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a3', true),
  ('11ddd8c7-3020-5a93-b86d-43739ea0254e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a3131faf-caa0-59ea-b442-d7f5ba6c6465', 'short_answer', 1, ('{"prompt":"K1.5 Classify six tasks by primary quality.","instructions":"Source item format: Drill classification. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a4', true),
  ('4eea3c45-e7b8-57b2-822d-972096d85e43', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a3131faf-caa0-59ea-b442-d7f5ba6c6465', 'short_answer', 1, ('{"prompt":"K1.6 State one reason COD deficit should not be treated as a pure measure of COD ability.","instructions":"Source item format: Short answer. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a5', true),
  ('a786eb22-1a63-5ab6-adee-3c4381a588d6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'a3131faf-caa0-59ea-b442-d7f5ba6c6465', 'long_answer', 1, ('{"prompt":"Applied competency A1 — Terminology audit: The learner submits a real session plan from their own environment, annotated task by task with primary quality, pre-planned versus information-driven status, and intended adaptation, plus a corrected session title.","maxLength":20000,"points":20,"rubric":"Standard: every task classified; no task labeled agility without an information demand; no acceleration/maximal-velocity conflation; the corrected title is defensible.. One revision permitted; applied work must reach standard."}')::jsonb, 'a6', true),
  ('1d973c94-62be-5ab2-8d27-5f5670c09c5a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9c31a308-2b5a-5b1b-af3c-841bebdf0829', 'short_answer', 1, ('{"prompt":"K2.1 Which best describes the role of horizontal force in acceleration?","instructions":"Source item format: MC. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a0', true),
  ('1655a4c6-08f5-5854-bf70-80f790db3cc9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9c31a308-2b5a-5b1b-af3c-841bebdf0829', 'short_answer', 1, ('{"prompt":"K2.2 Which are demands of the acceleration phase?","instructions":"Source item format: Select all. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a1', true),
  ('8d359d0d-2189-5d81-91d7-5ca74db12c0e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9c31a308-2b5a-5b1b-af3c-841bebdf0829', 'short_answer', 1, ('{"prompt":"K2.3 A study reports that faster athletes display characteristic X. Which conclusion is defensible?","instructions":"Source item format: Interpretation. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a2', true),
  ('f1ed7117-1815-5769-9814-3e50a7899e70', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9c31a308-2b5a-5b1b-af3c-841bebdf0829', 'short_answer', 1, ('{"prompt":"K2.4 Identify the flaw: \"The research proves you must coach X to accelerate better.\"","instructions":"Source item format: Error identification. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a3', true),
  ('e245b0e0-1502-5bf7-b67d-a66804b67fcb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9c31a308-2b5a-5b1b-af3c-841bebdf0829', 'short_answer', 1, ('{"prompt":"K2.5 State the population limitation of the sprint-start literature and how you would disclose it to a sport coach.","instructions":"Source item format: Short answer. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a4', true),
  ('2f13bc9a-3ef6-52f6-98a1-d96773d98f3c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9c31a308-2b5a-5b1b-af3c-841bebdf0829', 'long_answer', 1, ('{"prompt":"Applied competency A2 — Acceleration demand profile: For one sport-position group the learner coaches, produce a written acceleration demand profile: typical distances, entry conditions, frequency, what precedes each acceleration, and the three demands that will shape training. Every element labeled measured, estimated, or assumed (inherited G3 102 AS-04).","maxLength":20000,"points":20,"rubric":"Standard: demands tied to the actual sport; no track model imported without disclosure; no correlate presented as a coaching target.. One revision permitted; applied work must reach standard."}')::jsonb, 'a5', true),
  ('de8baf83-7ecb-507b-9f2b-d8e8a9c572e3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4615e5eb-2e6a-55f1-8c7d-ee2e39da840e', 'short_answer', 1, ('{"prompt":"K3.1 Which best characterizes maximal-velocity sprinting relative to acceleration?","instructions":"Source item format: MC. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a0', true),
  ('81d91a35-78fd-5165-bd8c-a4e6d2c4b40e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4615e5eb-2e6a-55f1-8c7d-ee2e39da840e', 'short_answer', 1, ('{"prompt":"K3.2 \"Vertical force is what matters at top speed.\"","instructions":"Source item format: True/False + justification. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a1', true),
  ('543914cb-e7f7-5d5f-91b6-e42f6aae8af0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4615e5eb-2e6a-55f1-8c7d-ee2e39da840e', 'short_answer', 1, ('{"prompt":"K3.3 A team''s fastest 10 m times belong to Athlete A; the highest flying-20 velocity belongs to Athlete B. What can and cannot be concluded?","instructions":"Source item format: Interpretation. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a2', true),
  ('08157d2b-49ca-59f0-af3a-629b787e2559', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4615e5eb-2e6a-55f1-8c7d-ee2e39da840e', 'short_answer', 1, ('{"prompt":"K3.4 A program of 6 × 20 m standing starts primarily develops…","instructions":"Source item format: MC. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a3', true),
  ('57b8fe48-f843-5742-8c32-3120e940bac7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4615e5eb-2e6a-55f1-8c7d-ee2e39da840e', 'short_answer', 1, ('{"prompt":"K3.5 Name the evidence gap in maximal-velocity development for youth and team-sport athletes, and state how it constrains your claims.","instructions":"Source item format: Short answer. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a4', true),
  ('610a6856-3c85-58a7-a104-0691cbef291a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4615e5eb-2e6a-55f1-8c7d-ee2e39da840e', 'long_answer', 1, ('{"prompt":"Applied competency A3 — Maximal-velocity decision: For one athlete or group, the learner states whether maximal-velocity development is a priority this phase, with reasoning tied to sport demand and athlete profile; if yes, they specify the exposure conditions required and the constraints in their facility; if no, they state what is being prioritized instead and at what cost (inherited G3 102 AS-10).","maxLength":20000,"points":20,"rubric":"Standard: the decision is defensible either way; no conflation of acceleration work with maximal-velocity work; population transfer disclosed if elite models are referenced.. One revision permitted; applied work must reach standard."}')::jsonb, 'a5', true),
  ('0b9df231-7595-5377-9ce9-6f5a3f1a7a87', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9791558a-ad62-5832-8b21-482759050804', 'short_answer', 1, ('{"prompt":"K4.1 The relationship between descriptive sprint biomechanics and technique coaching is best described as…","instructions":"Source item format: MC. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a0', true),
  ('577e7b0d-93b8-5123-8a21-c7d29f41cbb6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9791558a-ad62-5832-8b21-482759050804', 'short_answer', 1, ('{"prompt":"K4.2 Which are legitimate reasons to intervene on an athlete''s sprint technique?","instructions":"Source item format: Select all. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a1', true),
  ('a21e8d40-2915-58b3-9913-513ab7309077', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9791558a-ad62-5832-8b21-482759050804', 'short_answer', 1, ('{"prompt":"K4.3 \"He can''t sprint at full speed until his mechanics are cleaned up.\" Identify the error and its cost.","instructions":"Source item format: Error identification. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a2', true),
  ('a11eda46-c817-515e-9464-7aca7642e92c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9791558a-ad62-5832-8b21-482759050804', 'short_answer', 1, ('{"prompt":"K4.4 A constraint-based intervention is best understood as…","instructions":"Source item format: MC. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a3', true),
  ('7842dea3-c76e-57ef-8a7f-bfcd153a0e53', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9791558a-ad62-5832-8b21-482759050804', 'short_answer', 1, ('{"prompt":"K4.5 State the evidence boundary you would disclose when coaching a front-side mechanics cue.","instructions":"Source item format: Short answer. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a4', true),
  ('af7f5ae6-cd4d-5cfe-a035-4b7e8317bb58', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9791558a-ad62-5832-8b21-482759050804', 'long_answer', 1, ('{"prompt":"Applied competency A4 — Observation and intervention plan: From video or live observation of two athletes, the learner submits: a task-relevant description of each, a judgment of error versus variation with reasoning, one or two selected interventions per athlete, the intended effect, and what would count as evidence the intervention did not work.","maxLength":20000,"points":20,"rubric":"Standard: no universal model applied; no exposure gated on technique; interventions limited and justified; evidence boundary stated.. One revision permitted; applied work must reach standard."}')::jsonb, 'a5', true),
  ('65950068-17d7-5b94-8da1-535b1f006563', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'e9de21b2-c6d8-5115-918c-35f01ca99506', 'short_answer', 1, ('{"prompt":"K5.1 The primary reason unresisted sprinting anchors speed development is…","instructions":"Source item format: MC. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a0', true),
