  ('7f470d61-ca11-5182-a7b7-bf3bfe459b2a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'b844497b-9658-5387-8666-c70f9fa51c61', 'practical_sign_off', 'PS-1', 'Sprint Observation & Coaching', array['C103-02','C103-03']::text[], ('{"dimensions":["quality naming","observation","intervention","progression control","evidence honesty"],"scale":"0-3","pass":"11/15, no dimension below 2, never 0 on evidence honesty"}')::jsonb, 'M4 — Record: ["coach_id","sign_off_id","assessor_id","date","environment","athlete_or_group_ref","behaviors_observed","artifacts","questions_asked","outcome","expiry_date","notes"] — Minimum four-week practical window per course. Every recorded result carries the evaluator''s identity; results are immutable once recorded — corrections are new records.', '00000000-0000-4000-8000-000000000031'),
  ('210061d5-254a-59e3-b707-dcd92a64bcef', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', '40494986-b75f-5442-9084-8243f39ebf55', 'practical_sign_off', 'PS-2', 'Deceleration Coaching', array['C103-08']::text[], ('{"dimensions":["quality naming","observation","intervention","progression control","evidence honesty"],"scale":"0-3","pass":"11/15, no dimension below 2, never 0 on evidence honesty"}')::jsonb, 'M7 — Record: ["coach_id","sign_off_id","assessor_id","date","environment","athlete_or_group_ref","behaviors_observed","artifacts","questions_asked","outcome","expiry_date","notes"] — Minimum four-week practical window per course. Every recorded result carries the evaluator''s identity; results are immutable once recorded — corrections are new records.', '00000000-0000-4000-8000-000000000031'),
  ('c0f96424-23f0-540b-996c-84e22dbc394a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', '9abd5426-63e2-5e1d-9c3a-7606851c6fb4', 'practical_sign_off', 'PS-3', 'COD vs Agility Design', array['C103-01','C103-09','C103-10']::text[], ('{"dimensions":["quality naming","observation","intervention","progression control","evidence honesty"],"scale":"0-3","pass":"11/15, no dimension below 2, never 0 on evidence honesty"}')::jsonb, 'M9 — Record: ["coach_id","sign_off_id","assessor_id","date","environment","athlete_or_group_ref","behaviors_observed","artifacts","questions_asked","outcome","expiry_date","notes"] — Minimum four-week practical window per course. Every recorded result carries the evaluator''s identity; results are immutable once recorded — corrections are new records.', '00000000-0000-4000-8000-000000000031'),
  ('a74c260b-091e-5f28-a162-624c89ac49ba', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'ba231e65-3942-5007-ae7e-c2227561d64c', 'practical_sign_off', 'PS-4', 'Integrated Speed Session / Microcycle', array['C103-05','C103-06','C103-07','C103-11','C103-12','C103-14']::text[], ('{"dimensions":["quality naming","observation","intervention","progression control","evidence honesty"],"scale":"0-3","pass":"11/15, no dimension below 2, never 0 on evidence honesty"}')::jsonb, 'M12 — Record: ["coach_id","sign_off_id","assessor_id","date","environment","athlete_or_group_ref","behaviors_observed","artifacts","questions_asked","outcome","expiry_date","notes"] — Minimum four-week practical window per course. Every recorded result carries the evaluator''s identity; results are immutable once recorded — corrections are new records.', '00000000-0000-4000-8000-000000000031'),
  ('72545a8c-8b77-5454-bc55-dbfcb4302593', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', '31b61e4c-90a1-50d8-b879-2399cc50fc39', 'terminal_defense', 'T-01', 'Speed, COD & Agility Programming Defense', array['C103-01','C103-02','C103-03','C103-04','C103-05','C103-06','C103-07','C103-08','C103-09','C103-10','C103-11','C103-12','C103-13','C103-14','C103-15','C103-16']::text[], ('{"dimensions":["quality and demand fluency","method reasoning","measurement discipline","evidence honesty","falsifiability"],"scale":"0-3","pass":"11/15, no dimension below 2, never 0 on evidence honesty","nonCompensable":["cannot answer probe 4","makes an injury-prevention claim on probe 6"]}')::jsonb, '20-30 minutes with an approved assessor using the coach''s own athlete and artifacts; assessor works the seven obligations in order and probes at least four — Minimum four-week practical window per course. Every recorded result carries the evaluator''s identity; results are immutable once recorded — corrections are new records.', '00000000-0000-4000-8000-000000000031')
insert into public.curriculum_records (id, organization_id, course_id, kind, code, title, data, position) values
  ('ee604608-f471-58a4-8c71-232f15c63aa1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'doctrine', 'D103-1', 'Speed Is Phase-Specific', ('{"id":"D103-1","title":"Speed Is Phase-Specific","statement":"Acceleration and maximal velocity are related but distinct sprint qualities. Coaches identify which speed demand is being trained or assessed rather than treating sprint performance as one undifferentiated quality.","evidence_class":"A","teaching_boundary":"The distinction is established; exact phase boundaries are not. G3 publishes no universal distance cut-point.","modules":["M1","M2","M3"],"anchor_refs":["EP103-01","EP103-13","EP103-12"],"citation_tags":["cite:96","cite:101","cite:104"],"standing":"G3 Doctrine"}')::jsonb, 'a0'),
  ('d89fbda2-8031-5776-b217-1921a12c4fc1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'doctrine', 'D103-2', 'Exposure Is Irreplaceable', ('{"id":"D103-2","title":"Exposure Is Irreplaceable","statement":"General strength, power, and plyometric training can support sprint development, but they do not fully replace sprint-specific exposure when the desired adaptation is sprint performance.","evidence_class":"B","teaching_boundary":"Not a claim that the weight room is unimportant, and not a dose statement. Sets no minimum sprint volume (CJ-01).","modules":["M5","M6"],"anchor_refs":["EP103-07","EP103-08","EP103-09","EP103-01"],"citation_tags":["cite:87","cite:89","cite:91","cite:96"],"standing":"G3 Doctrine"}')::jsonb, 'a1'),
  ('a545b93e-5bd7-5662-87fb-425a4b14c555', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'doctrine', 'D103-3', 'Mechanics Inform; They Do Not Dictate', ('{"id":"D103-3","title":"Mechanics Inform; They Do Not Dictate","statement":"Biomechanics can describe characteristics associated with better sprint performance. A descriptive characteristic does not automatically become a causal coaching target. G3 does not impose one universal sprint-mechanics model on every athlete.","evidence_class":"B","teaching_boundary":"Descriptive support is A-class; technique-intervention evidence is limited by comparison; universalizing an elite track model is F. Technique coaching is not forbidden - gating exposure on it is.","modules":["M4"],"anchor_refs":["EP103-01","EP103-11","EP103-12"],"citation_tags":["cite:96","cite:104","cite:105"],"standing":"G3 Doctrine"}')::jsonb, 'a2'),
  ('d4a3f40a-2f6d-5c0e-9562-8cc4d532134e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'doctrine', 'D103-4', 'Deceleration Is a Performance Quality', ('{"id":"D103-4","title":"Deceleration Is a Performance Quality","statement":"Deceleration is not merely the first half of a COD drill. Braking capacity, momentum control, approach velocity, posture, and eccentric demands justify treating deceleration as a distinct training and assessment consideration.","evidence_class":"A","teaching_boundary":"Distinctness is A; diagnostics and the qualities that best develop it are C. No progression ladder is evidence-derived; AS-103-05 is an applied standard.","modules":["M7"],"anchor_refs":["EP103-14","EP103-15","EP103-16"],"citation_tags":["cite:98","cite:108","cite:100"],"standing":"G3 Doctrine"}')::jsonb, 'a3'),
  ('d636f784-30a9-5db4-8493-6667fc4de798', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'doctrine', 'D103-5', 'COD Is Not Agility', ('{"id":"D103-5","title":"COD Is Not Agility","statement":"Pre-planned COD and agility are different constructs. COD involves a known movement solution. Agility requires perception, decision, and response to external information.","evidence_class":"A","teaching_boundary":"Distinct does not mean unrelated. The doctrine forbids treating them as the same, not as connected.","modules":["M8","M9"],"anchor_refs":["EP103-04","EP103-19","EP103-21","EP103-22"],"citation_tags":["cite:85","cite:90","cite:107","cite:110"],"standing":"G3 Doctrine"}')::jsonb, 'a4'),
  ('cb759577-6d07-59b5-90b6-ed2c8eafa0f9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'doctrine', 'D103-6', 'Closed Drills Do Not Automatically Train Agility', ('{"id":"D103-6","title":"Closed Drills Do Not Automatically Train Agility","statement":"Cone patterns, ladders, and pre-planned movement drills may train coordination, rhythm, movement skill, or COD. They are not labeled true agility development unless meaningful external information and response demands are present.","evidence_class":"B","teaching_boundary":"Closed drills are not condemned. The error is the label, not the drill.","modules":["M9"],"anchor_refs":["EP103-04","EP103-19","EP103-21"],"citation_tags":["cite:85","cite:90","cite:107"],"standing":"G3 Doctrine"}')::jsonb, 'a5'),
  ('2124fa55-9f7e-5381-8c17-534516c086de', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'doctrine', 'D103-7', 'Transfer Is Demand-Based, Not Appearance-Based', ('{"id":"D103-7","title":"Transfer Is Demand-Based, Not Appearance-Based","statement":"A drill does not transfer because it looks athletic or resembles sport. Transfer claims are tied to relevant force-time, velocity, coordination, braking, movement, or perception-action demands.","evidence_class":"B","teaching_boundary":"Not a rejection of specificity - a rejection of resemblance as evidence of it. Inherited from G3 102 Doctrine 5.","modules":["M6","M9"],"anchor_refs":["EP103-23","EP103-01"],"citation_tags":["cite:75","cite:96"],"standing":"G3 Doctrine"}')::jsonb, 'a6'),
  ('c97b9a85-d305-5d41-93ee-5bed3c11ad69', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'doctrine', 'D103-8', 'Speed Quality Requires Quality Exposure', ('{"id":"D103-8","title":"Speed Quality Requires Quality Exposure","statement":"High-speed and high-intensity multidirectional work is generally organized to preserve meaningful output and technical quality. Fatigue is not evidence that speed training became more sport-specific.","evidence_class":"B","teaching_boundary":"No rest ratio, repetition count, or velocity-decrement threshold is established (CJ-03, CJ-07). Training under fatigue is not forbidden; claiming the fatigue made it specific is.","modules":["M5","M11"],"anchor_refs":["EP103-01","EP103-14"],"citation_tags":["cite:96","cite:98"],"standing":"G3 Doctrine"}')::jsonb, 'a7'),
  ('d0603221-bd66-5a5b-8360-06d04d6fcbfd', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'doctrine', 'D103-9', 'Load Serves the Intended Sprint Adaptation', ('{"id":"D103-9","title":"Load Serves the Intended Sprint Adaptation","statement":"Resisted sprinting is a supported training tool, especially for acceleration, but G3 does not adopt one universal sled load or percentage for every athlete and outcome.","evidence_class":"A","teaching_boundary":"A that RST improves sprint performance; C for loading strategy. No percentage, decrement number, or load table appears anywhere in G3 103. Both absolutist claims rejected (CA-06, CA-07).","modules":["M6"],"anchor_refs":["EP103-05","EP103-06","EP103-27"],"citation_tags":["cite:81","cite:84","cite:92"],"standing":"G3 Doctrine"}')::jsonb, 'a8'),
  ('2160c302-4499-51c6-847a-5dc1be336569', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'doctrine', 'D103-10', 'Testing Measures Tasks, Not Labels', ('{"id":"D103-10","title":"Testing Measures Tasks, Not Labels","statement":"A sprint split, COD test, or reactive test measures performance under its specific constraints. Coaches do not infer maximal velocity, agility, or isolated physical qualities from a test that does not directly establish them.","evidence_class":"A","teaching_boundary":"A labeling and inference rule, not a rejection of field testing. No universal smallest-worthwhile-change threshold is created.","modules":["M10"],"anchor_refs":["EP103-02","EP103-18","EP103-19","EP103-20","EP103-21"],"citation_tags":["cite:97","cite:79","cite:90","cite:102","cite:107"],"standing":"G3 Doctrine"}')::jsonb, 'a9'),
  ('e2582cf5-40bc-5c8a-8d79-5404089b0e38', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'doctrine', 'D103-11', 'Youth Speed Development Is Readiness- and Development-Aware', ('{"id":"D103-11","title":"Youth Speed Development Is Readiness- and Development-Aware","statement":"Youth athletes can improve sprint, COD, and agility-related qualities. Programming considers maturation, coordination, training age, readiness, and exposure history rather than relying on rigid chronological-age windows.","evidence_class":"B","teaching_boundary":"Rejecting age-window mythology is not a claim that maturation is irrelevant. Youth sprint-mechanics prescriptions remain extrapolated and are labeled (AS-103-12).","modules":["M11"],"anchor_refs":["EP103-03","EP103-24","EP103-09"],"citation_tags":["cite:88","cite:76","cite:91"],"standing":"G3 Doctrine"}')::jsonb, 'b0'),
  ('b8aa7b4e-1697-5e99-ae0e-3a3f2b925adb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'doctrine', 'D103-12', 'Injury Claims Require Causal Restraint', ('{"id":"D103-12","title":"Injury Claims Require Causal Restraint","statement":"G3 distinguishes tissue demand, association, mechanistic plausibility, risk-factor evidence, and intervention evidence. Sprinting, deceleration, or COD training is not marketed as inherently dangerous or inherently injury-preventive without appropriate evidence.","evidence_class":"B","teaching_boundary":"Restraint runs both directions: no protection promises, and no withholding exposure on an unsupported danger claim. Binds marketing, parent, and athlete communication.","modules":["M7","M12"],"anchor_refs":["EP103-14","EP103-16","EP103-11"],"citation_tags":["cite:98","cite:100","cite:105"],"standing":"G3 Doctrine"}')::jsonb, 'b1'),
  ('19c30e2d-c700-51c3-8901-5927dd25bce8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'applied_standard', 'AS-103-01', 'Name the Quality', ('{"id":"AS-103-01","title":"Name the Quality","text":"Every speed/COD/agility prescription identifies the primary quality being targeted: acceleration, maximal velocity, deceleration, planned COD, or reactive agility.","evidence_basis":"D","standing":"applied_standard","boundary_or_enforcement":"speed_task requires primary_quality"}')::jsonb, 'b2'),
  ('ec766fb3-b049-5424-a23f-f675868eee9d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'applied_standard', 'AS-103-02', 'Preserve Sprint Exposure', ('{"id":"AS-103-02","title":"Preserve Sprint Exposure","text":"When sprint performance is a priority, the program includes actual sprint exposure appropriate to the targeted phase rather than relying solely on weight-room or plyometric proxies.","evidence_basis":"B","standing":"applied_standard","boundary_or_enforcement":"sets no volume, distance, or frequency (CJ-01, CJ-02)"}')::jsonb, 'b3'),
  ('f2dc144a-b3f5-5d9a-a1d3-69bde6d98500', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'applied_standard', 'AS-103-03', 'Technique With Restraint', ('{"id":"AS-103-03","title":"Technique With Restraint","text":"Technique coaching is used to improve task execution. Athletes are not required to conform to a single visual model before meaningful sprint exposure is allowed.","evidence_basis":"B","standing":"applied_standard","boundary_or_enforcement":"restrains the gate, not the coaching"}')::jsonb, 'b4'),
  ('322b0c0c-9775-51f6-b974-ee5433f01dff', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'applied_standard', 'AS-103-04', 'Resisted Sprint Intent', ('{"id":"AS-103-04","title":"Resisted Sprint Intent","text":"Resisted sprint load and method are selected according to intended adaptation, athlete capacity, equipment, and output quality. No universal loading percentage is G3 law.","evidence_basis":"A/C","standing":"applied_standard","boundary_or_enforcement":"CJ-06 owns the number; any percentage stated as a rule fails production review"}')::jsonb, 'b5'),
  ('ed3f9c89-7de4-52cb-a082-f2906498fd5d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'applied_standard', 'AS-103-05', 'Deceleration Before Directional Complexity', ('{"id":"AS-103-05","title":"Deceleration Before Directional Complexity","text":"Where appropriate, athletes are taught and exposed to braking and momentum-control demands before approach velocity, cut severity, reactive complexity, or total multidirectional density are escalated.","evidence_basis":"D","standing":"applied_standard","boundary_or_enforcement":"explicitly an Applied Standard, NOT a universal research-derived progression ladder (CJ-10)"}')::jsonb, 'b6'),
  ('eb3689ef-7971-534a-86ea-007f6f57e1a5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'applied_standard', 'AS-103-06', 'COD Task Specificity', ('{"id":"AS-103-06","title":"COD Task Specificity","text":"COD is programmed and evaluated with awareness of approach velocity, cut angle, braking demand, reacceleration demand, and test/task structure.","evidence_basis":"A","standing":"applied_standard","boundary_or_enforcement":"no angle progression sequence prescribed (CJ-09)"}')::jsonb, 'b7'),
  ('f9f63876-d34a-5470-82f3-c82b4ec49009', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'applied_standard', 'AS-103-07', 'Agility Requires Information', ('{"id":"AS-103-07","title":"Agility Requires Information","text":"At least part of an agility-development progression requires athletes to perceive relevant information and select and execute a movement response.","evidence_basis":"A/B/C","standing":"applied_standard","boundary_or_enforcement":"''at least part'' is deliberate; no proven dose of reactive work is claimed"}')::jsonb, 'b8'),
  ('1777be40-0311-574d-926e-d706d5a206a5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'applied_standard', 'AS-103-08', 'Quality Preservation', ('{"id":"AS-103-08","title":"Quality Preservation","text":"Rest and repetition structure are sufficient to preserve the intended performance quality. Exact rest ratios are not universal G3 doctrine.","evidence_basis":"B","standing":"applied_standard","boundary_or_enforcement":"criterion is output, not the clock (CJ-03)"}')::jsonb, 'b9'),
  ('1628a73f-b591-51b0-86ed-ab4325fe9dc4', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'applied_standard', 'AS-103-09', 'Testing Standardization', ('{"id":"AS-103-09","title":"Testing Standardization","text":"G3 testing uses objective timing where practical, standardized setups, familiarization, consistent surfaces and conditions, and known measurement error before small changes are interpreted.","evidence_basis":"A","standing":"applied_standard","boundary_or_enforcement":"no universal smallest-worthwhile-change threshold is created"}')::jsonb, 'c0'),
  ('8717ed6e-89cd-56fb-96dd-409b7f1e3f9f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'applied_standard', 'AS-103-10', 'Construct-Appropriate Testing', ('{"id":"AS-103-10","title":"Construct-Appropriate Testing","text":"A pre-planned COD test is not called an agility test. A short acceleration split is not called a maximal-velocity test. G3 labels what was actually measured.","evidence_basis":"A","standing":"applied_standard + language rule","boundary_or_enforcement":"test_record requires construct_measured; mislabeling is a scored error"}')::jsonb, 'c1'),
  ('6827d712-2628-524e-b490-409ed7b8baa0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'applied_standard', 'AS-103-11', 'Multi-Measure Interpretation', ('{"id":"AS-103-11","title":"Multi-Measure Interpretation","text":"When profiling multidirectional performance, relevant measures are combined rather than using one test to diagnose all speed, COD, braking, and agility qualities.","evidence_basis":"D","standing":"applied_standard","boundary_or_enforcement":"no battery, weighting, or composite score prescribed"}')::jsonb, 'c2'),
  ('c9205426-ef9c-585e-87e4-8e40c1b7dfeb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'applied_standard', 'AS-103-12', 'Population Transfer Disclosure', ('{"id":"AS-103-12","title":"Population Transfer Disclosure","text":"When a prescription is substantially extrapolated from elite track, adult, soccer-heavy, or male-dominant evidence, the educational content says so.","evidence_basis":"A","standing":"applied_standard","boundary_or_enforcement":"every module evidence block carries a population-transfer line where extrapolation occurs"}')::jsonb, 'c3'),
  ('2290482c-1e2d-53e3-aab8-9f9e48f00337', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'coach_judgment', 'CJ-01', 'Exact sprint volume', ('{"id":"CJ-01","area":"Exact sprint volume","evidence_position":"No fixed prescription across populations and tasks","g3_supplies":"AS-103-02, AS-103-08","coach_call":"Volume for this athlete, phase, and schedule"}')::jsonb, 'c4'),
  ('1d6915f8-c304-5015-b3bd-c9e76245babe', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'coach_judgment', 'CJ-02', 'Exact sprint distance prescription', ('{"id":"CJ-02","area":"Exact sprint distance prescription","evidence_position":"Phase boundaries vary by task, athlete, distance","g3_supplies":"The phase concept (D103-1)","coach_call":"Distances used to target a phase"}')::jsonb, 'c5'),
  ('700dfcd2-bdfb-513a-a878-9a896cd0ac24', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'coach_judgment', 'CJ-03', 'Exact rest intervals', ('{"id":"CJ-03","area":"Exact rest intervals","evidence_position":"No universal rest ratio established","g3_supplies":"Quality preservation as the criterion (AS-103-08)","coach_call":"The interval"}')::jsonb, 'c6'),
  ('1f157495-11d0-579d-a2c7-0046d1cd7edf', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'coach_judgment', 'CJ-04', 'Exact weekly placement', ('{"id":"CJ-04","area":"Exact weekly placement","evidence_position":"No universal microcycle model supported","g3_supplies":"The principle of protecting high-quality exposures","coach_call":"Placement in this week"}')::jsonb, 'c7'),
  ('26ecb786-1f52-5e5a-98f8-669a76f68d0f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'coach_judgment', 'CJ-05', 'High/low microcycle organization', ('{"id":"CJ-05","area":"High/low microcycle organization","evidence_position":"E/D - historically influential, limited direct comparative evidence","g3_supplies":"Taught as a practitioner framework","coach_call":"Whether to use it"}')::jsonb, 'c8'),
  ('0d1bfdd3-e5e5-560c-8858-8d089676c846', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'coach_judgment', 'CJ-06', 'Exact resisted-sprint load', ('{"id":"CJ-06","area":"Exact resisted-sprint load","evidence_position":"C - loading strategy contested; no universal threshold","g3_supplies":"AS-103-04 intent-based selection","coach_call":"The load and method"}')::jsonb, 'c9'),
  ('513d36a3-306d-537d-8ef3-2747db19e9a1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'coach_judgment', 'CJ-07', 'Exact velocity-decrement threshold', ('{"id":"CJ-07","area":"Exact velocity-decrement threshold","evidence_position":"Operationally useful; no one threshold supported","g3_supplies":"Quality preservation as the criterion","coach_call":"Whether and where to set one"}')::jsonb, 'd0'),
  ('3f411463-b9d7-5305-8de8-7468404f5758', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'coach_judgment', 'CJ-08', 'Assisted / overspeed use', ('{"id":"CJ-08","area":"Assisted / overspeed use","evidence_position":"C - less secure than RST; not clearly superior to normal sprinting","g3_supplies":"The evidence position stated plainly","coach_call":"Whether to use it at all"}')::jsonb, 'd1'),
  ('f73839f2-1046-5bb6-a08b-34f353ee0bfb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'coach_judgment', 'CJ-09', 'Exact COD angle progression', ('{"id":"CJ-09","area":"Exact COD angle progression","evidence_position":"No universal ladder","g3_supplies":"AS-103-06 variables","coach_call":"The sequence for this athlete"}')::jsonb, 'd2'),
  ('397a6cea-6636-5703-bdd2-7576472aef57', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'coach_judgment', 'CJ-10', 'Exact deceleration progression', ('{"id":"CJ-10","area":"Exact deceleration progression","evidence_position":"No universal ladder","g3_supplies":"AS-103-05 as a labeled Applied Standard","coach_call":"The sequence for this athlete"}')::jsonb, 'd3'),
  ('04ca5c39-dcab-51ee-8a40-32879793cdef', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'coach_judgment', 'CJ-11', 'Exact reactive-agility progression', ('{"id":"CJ-11","area":"Exact reactive-agility progression","evidence_position":"Intervention evidence smaller and heterogeneous","g3_supplies":"AS-103-07 - information must be present","coach_call":"The progression"}')::jsonb, 'd4'),
  ('15ac0c1f-08b3-5c5f-9396-6eb638e31a3a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'coach_judgment', 'CJ-12', 'Exact technique thresholds before faster sprinting', ('{"id":"CJ-12","area":"Exact technique thresholds before faster sprinting","evidence_position":"F - delaying exposure to a universal standard is unsupported","g3_supplies":"AS-103-03","coach_call":"Coaching emphasis and task constraints"}')::jsonb, 'd5'),
  ('7ba2a6c4-2e86-5c04-a3c6-4755d5eb0754', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'coach_judgment', 'CJ-13', 'Deterministic COD-deficit interpretation', ('{"id":"CJ-13","area":"Deterministic COD-deficit interpretation","evidence_position":"Task-dependent; not a complete isolate","g3_supplies":"The lens and its limits (M8, M10)","coach_call":"How much weight to give it"}')::jsonb, 'd6'),
  ('7d7c396d-a212-5645-bfbc-1e6cd1227e12', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'coach_judgment', 'CJ-14', 'Deterministic deceleration-deficit interpretation', ('{"id":"CJ-14","area":"Deterministic deceleration-deficit interpretation","evidence_position":"C - emerging analytical concept","g3_supplies":"The concept and its limits (M7, M10)","coach_call":"How much weight to give it"}')::jsonb, 'd7'),
  ('d3fc29fd-5d9f-5b8c-80f0-b245ff30bd17', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'coach_judgment', 'CJ-15', 'Sex-specific programming rules', ('{"id":"CJ-15","area":"Sex-specific programming rules","evidence_position":"Evidence limited across several domains","g3_supplies":"AS-103-12 disclosure; restraint position","coach_call":"Individual modification on individual grounds"}')::jsonb, 'd8'),
  ('05abee54-8365-5f8c-9822-b8feb81137e9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'coach_judgment', 'CJ-16', 'Injury-prevention guarantees from sprint, deceleration, or COD exposure', ('{"id":"CJ-16","area":"Injury-prevention guarantees from sprint, deceleration, or COD exposure","evidence_position":"F in both directions","g3_supplies":"D103-12 restraint","coach_call":"Exposure decisions, communicated without guarantees"}')::jsonb, 'd9'),
  ('77bdf077-8811-5c50-a64b-400a2d429cee', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'claim_audit', 'CA-01', 'Speed cannot be trained', ('{"id":"CA-01","claim":"Speed cannot be trained","class":"F","taught_instead":"Sprint and sprint-related qualities are trainable; adaptations vary by quality and population.","citation_tags":["cite:81","cite:87","cite:96"]}')::jsonb, 'e0'),
  ('ec81d210-3b26-5c8b-86f6-f8bbc72a3fd9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'claim_audit', 'CA-02', 'Athletes either have speed or they do not', ('{"id":"CA-02","claim":"Athletes either have speed or they do not","class":"F","taught_instead":"Athlete qualities differ, and sprint performance responds to multiple training methods.","citation_tags":["cite:81","cite:89","cite:96"]}')::jsonb, 'e1'),
  ('41080382-0119-51dc-af2d-5d79daefed7f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'claim_audit', 'CA-03', 'Strength automatically makes athletes faster', ('{"id":"CA-03","claim":"Strength automatically makes athletes faster","class":"F","taught_instead":"Strength transfers partially and outcome-specifically; it does not replace sprint exposure.","citation_tags":["cite:87","cite:89"]}')::jsonb, 'e2'),
  ('764d2c16-9371-5963-aba1-eb9773ef6476', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'claim_audit', 'CA-04', 'Horizontal force is all that matters in acceleration', ('{"id":"CA-04","claim":"Horizontal force is all that matters in acceleration","class":"F","taught_instead":"Horizontal impulse and force orientation matter within a whole-system task.","citation_tags":["cite:96","cite:105"]}')::jsonb, 'e3'),
  ('c654ae48-6ad6-5ae0-9354-4db413419175', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'claim_audit', 'CA-05', 'Vertical force is all that matters at maximal velocity', ('{"id":"CA-05","claim":"Vertical force is all that matters at maximal velocity","class":"F","taught_instead":"Vertical force is important; top speed is not reducible to one variable.","citation_tags":["cite:96","cite:101"]}')::jsonb, 'e4'),
  ('46687d09-a3c6-5d7f-b139-db096206d4ae', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'claim_audit', 'CA-06', 'Heavier resisted sprint loads are always better', ('{"id":"CA-06","claim":"Heavier resisted sprint loads are always better","class":"F","taught_instead":"Load magnitude matters; no universal monotonic rule is established.","citation_tags":["cite:81","cite:92"]}')::jsonb, 'e5'),
  ('f4567971-70cb-5898-a4bb-1dd7ef965721', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'claim_audit', 'CA-07', 'Sleds make athletes slow', ('{"id":"CA-07","claim":"Sleds make athletes slow","class":"F","taught_instead":"RST can improve acceleration; the blanket negative claim is unsupported.","citation_tags":["cite:81","cite:84"]}')::jsonb, 'e6'),
  ('497fa6ff-5fb3-5746-b405-3206e3523b0f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'claim_audit', 'CA-08', 'Overspeed is necessary for top-speed development', ('{"id":"CA-08","claim":"Overspeed is necessary for top-speed development","class":"F","taught_instead":"Evidence is limited and does not establish superiority over normal sprinting.","citation_tags":["cite:84"]}')::jsonb, 'e7'),
  ('ac083ea0-d53e-5896-856a-912824112038', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'claim_audit', 'CA-09', 'Ladder drills inherently improve agility', ('{"id":"CA-09","claim":"Ladder drills inherently improve agility","class":"F","taught_instead":"Ladders may train footwork rhythm and coordination - useful, and not agility.","citation_tags":["cite:85","cite:90"]}')::jsonb, 'e8'),
  ('c0a68800-6542-5378-8cd1-e46697eedbc6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'claim_audit', 'CA-10', 'Cone drills are automatically agility training', ('{"id":"CA-10","claim":"Cone drills are automatically agility training","class":"F","taught_instead":"Pre-planned cone work trains COD unless reactive information is added.","citation_tags":["cite:85","cite:107"]}')::jsonb, 'e9'),
  ('4d091f09-f165-5e84-b5af-5112999fd190', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'claim_audit', 'CA-11', 'COD and agility are the same', ('{"id":"CA-11","claim":"COD and agility are the same","class":"F","taught_instead":"Distinct constructs; agility requires perception and decision.","citation_tags":["cite:85","cite:90"]}')::jsonb, 'f0'),
  ('437f0be5-29f4-55a5-bee4-31d0ea2a85c3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'claim_audit', 'CA-12', 'The fastest linear sprinter should automatically have the best COD', ('{"id":"CA-12","claim":"The fastest linear sprinter should automatically have the best COD","class":"F","taught_instead":"COD is influenced by braking, angle, technique, orientation, and reacceleration beyond linear speed.","citation_tags":["cite:79","cite:80"]}')::jsonb, 'f1'),
  ('fda88e19-b2e1-5f51-9340-ce69ce3ec6d6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'claim_audit', 'CA-13', 'Every athlete needs the same sprint mechanics', ('{"id":"CA-13","claim":"Every athlete needs the same sprint mechanics","class":"F","taught_instead":"Descriptive elite mechanics do not become one universal model.","citation_tags":["cite:96","cite:104"]}')::jsonb, 'f2'),
  ('49553275-8824-50c6-94f4-54a8d899e561', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'claim_audit', 'CA-14', 'Perfect technique must precede meaningful speed exposure', ('{"id":"CA-14","claim":"Perfect technique must precede meaningful speed exposure","class":"F","taught_instead":"Exposure is not gated on a universal technique threshold; coaching happens alongside it.","citation_tags":["cite:96"]}')::jsonb, 'f3'),
