  ('300382f6-a888-58a8-83e7-aa6703017f16', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'reference', 'EP103-20', 'Reference 20', ('{"id":"EP103-20","citation":"Pojskic H et al. Reliability, Validity and Usefulness of a New Response Time Test Battery for Agility-Based Sports. 2019.","type":"primary research","citation_tag":"cite:102","domain":"reactive testing","limitation":"Sport/test specificity","verification_status":"verified"}')::jsonb, 'j4'),
  ('62446115-d182-5332-b7b0-5630baba233e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'reference', 'EP103-21', 'Reference 21', ('{"id":"EP103-21","citation":"The Importance of Reactive Agility Tests in Differentiating Adolescent Soccer Players. 2020.","type":"primary research","citation_tag":"cite:107","domain":"reactive agility discrimination","limitation":"Adolescent soccer population","verification_status":"verified"}')::jsonb, 'j5'),
  ('afaac5d1-3508-53cf-9de6-cb5bb4fb17b0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'reference', 'EP103-22', 'Reference 22', ('{"id":"EP103-22","citation":"Importance of Reactive Agility and COD Speed in Differentiating Performance Levels in Youth Soccer Players. 2018.","type":"primary research","citation_tag":"cite:110","domain":"youth reactive agility and CODS","limitation":"Soccer-specific sample","verification_status":"verified"}')::jsonb, 'j6'),
  ('769f38a0-1df3-5df2-bd29-6bb82f11a4a3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'reference', 'EP103-23', 'Reference 23', ('{"id":"EP103-23","citation":"Optimizing Agility Training in Team Sport Players - The Role of Specificity and Transfer. 2026.","type":"review","citation_tag":"cite:75","domain":"agility training and transfer","limitation":"Newer source","verification_status":"pending"}')::jsonb, 'j7'),
  ('3dc16057-22fa-5426-bda8-450f724860d2', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'reference', 'EP103-24', 'Reference 24', ('{"id":"EP103-24","citation":"The effect of repeated-sprint training on performance in youth athletes: a meta-analysis. 2026.","type":"meta-analysis","citation_tag":"cite:76","domain":"youth repeated sprint ability","limitation":"Newer source","verification_status":"pending"}')::jsonb, 'j8'),
  ('d7b79d0b-f469-5daa-9228-002f519f43d7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'reference', 'EP103-25', 'Reference 25', ('{"id":"EP103-25","citation":"Effects of speed, agility, and quickness training on athletic performance in soccer players. 2025.","type":"primary/review","citation_tag":"cite:94","domain":"SAQ outcomes","limitation":"Soccer-specific; conceptually broad category","verification_status":"pending"}')::jsonb, 'j9'),
  ('f6c2bb2e-04aa-5345-93d4-a6773d602ab2', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'reference', 'EP103-26', 'Reference 26', ('{"id":"EP103-26","citation":"Thapa RK et al. Effects of Complex Training on Sprint, Jump, and COD Ability among Soccer Players: A Meta-Analysis. 2021.","type":"meta-analysis","citation_tag":"cite:83","domain":"combined training effects","limitation":"Soccer concentration","verification_status":"verified"}')::jsonb, 'k0'),
  ('ea8c42a1-68dd-537e-b0c1-a74174ef42e3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'reference', 'EP103-27', 'Reference 27', ('{"id":"EP103-27","citation":"Effects of Resisted Sprint Training on Sprint Performance and Mechanics, focusing on load magnitude. 2025/2026 repository record.","type":"SR/meta-analysis (repository)","citation_tag":"cite:92","domain":"RST load magnitude","limitation":"Repository-hosted; final publication details to be confirmed","verification_status":"pending"}')::jsonb, 'k1'),
  ('831ba2bb-bcc5-5fa6-941f-88d5ee448a37', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'reference', 'EP103-28', 'Reference 28', ('{"id":"EP103-28","citation":"Matusinski A et al. Acute effects of resisted and assisted locomotor activation on sprint performance. 2022.","type":"primary research","citation_tag":"cite:74","domain":"acute resisted/assisted activation","limitation":"Acute response data, not long-term adaptation","verification_status":"verified"}')::jsonb, 'k2'),
  ('6d7f842a-a95a-519e-9990-6b7476a425c5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'case', 'case-1', 'Middle-School Field/Court Athlete', ('{"id":"case-1","title":"Middle-School Field/Court Athlete","competencies":["C103-01","C103-04","C103-08","C103-13"],"doctrine":["D103-11","D103-3","D103-2"],"modules":["M1","M4","M7","M11"],"situation_summary":"12-year-old, two seasonal sports, no training history, high instructional responsiveness, poor braking organization at speed. Group of 16, one coach, two 50-minute sessions. Parent asks about ''proper sprint mechanics work'' and sled sprints.","decision_prompt":"What does the speed and multidirectional work consist of, what is deliberately excluded, and what do you tell the parent?","failure_modes":["Age-window claims","Delaying sprinting for technique","Adult track model applied without disclosure","A sled percentage quoted as a rule","Complexity beyond coordination and supervision","Deceleration left untrained"],"delivery":["situation","decision (commit before feedback)","defense","discussion"],"rubric":"universal_case_rubric"}')::jsonb, 'k3'),
  ('57754e3c-e927-5751-bc65-de29069e2783', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'case', 'case-2', 'High-School Athlete With Strong 10 m but Poorer High-Speed Capacity', ('{"id":"case-2","title":"High-School Athlete With Strong 10 m but Poorer High-Speed Capacity","competencies":["C103-01","C103-02","C103-05","C103-11"],"doctrine":["D103-1","D103-2","D103-10"],"modules":["M2","M3","M5","M10"],"situation_summary":"16-year-old wide midfielder. 10 m among the best on the team; flying 10 m velocity in the bottom third; consistent across two occasions on the same surface with electronic gates. Program has run 6 x 20 m standing starts labeled ''speed''.","decision_prompt":"What quality is actually deficient, what has the program been training, and what changes?","failure_modes":["Calling every sprint exposure ''speed''","Treating the 10 m result as top-speed evidence","Adding volume rather than changing entry conditions and distance","Attributing the difference to noise when data rules it out","Prescribing max-velocity work with no demand justification"],"delivery":["situation","decision (commit before feedback)","defense","discussion"],"rubric":"universal_case_rubric"}')::jsonb, 'k4'),
  ('da0e1b0c-a090-5eff-bc3a-4f120f187264', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'case', 'case-3', 'Fast Linear Speed, Weak Planned COD', ('{"id":"case-3","title":"Fast Linear Speed, Weak Planned COD","competencies":["C103-08","C103-09","C103-12"],"doctrine":["D103-5","D103-10","D103-4"],"modules":["M7","M8","M10"],"situation_summary":"17-year-old outside back. Among the fastest at 10 m and flying 10 m; among the poorest 505-style results with a large left/right difference and a correspondingly large COD deficit. No pain. Video shows high entry velocity, four short braking steps, upright plant, slow exit.","decision_prompt":"What is the probable limiting factor, what would distinguish the candidates, and what is the first block?","failure_modes":["Reading COD deficit deterministically","Ignoring entry velocity","Ignoring the exit","Treating asymmetry as injury prediction","Assuming linear speed means no COD work needed","Adding pattern volume without changing the constraint"],"delivery":["situation","decision (commit before feedback)","defense","discussion"],"rubric":"universal_case_rubric"}')::jsonb, 'k5'),
  ('e1452d18-e0e3-5126-9eb3-e535c83a49c5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'case', 'case-4', 'Excellent on Cone Drills, Poor in Live Play', ('{"id":"case-4","title":"Excellent on Cone Drills, Poor in Live Play","competencies":["C103-01","C103-09","C103-10"],"doctrine":["D103-5","D103-6","D103-7"],"modules":["M1","M8","M9"],"situation_summary":"16-year-old in a reactive defensive role. Best times in the program on every pre-planned drill; consistently a step late in live play, commits early to the wrong side. Physical testing strong. Program has responded by adding faster cone work.","decision_prompt":"What is the actual gap, and what does the next block look like?","failure_modes":["Adding cone volume","Adding complexity and calling it information demand","Cues arriving too late to be read","Claiming a validated reactive progression","Labeling closed work ''agility''","Concluding a physical deficit when testing says otherwise"],"delivery":["situation","decision (commit before feedback)","defense","discussion"],"rubric":"universal_case_rubric"}')::jsonb, 'k6'),
  ('5cbc04f0-45d4-5018-9bf3-cf520dc9ab1f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'case', 'case-5', 'Team With Limited Weekly Training Time', ('{"id":"case-5","title":"Team With Limited Weekly Training Time","competencies":["C103-04","C103-08","C103-10","C103-14"],"doctrine":["D103-8","D103-2","D103-11"],"modules":["M5","M9","M11"],"situation_summary":"Scholastic squad of 30, in-season. Five practices, one match, two 40-minute G3 slots with one lost roughly every other week. Practice already contains substantial sprinting, braking, and directional change, uncounted. Sport coach wants speed, agility, and conditioning every session.","decision_prompt":"What goes in the two slots, what is protected, what is compromised, and what do you tell the sport coach cannot be achieved?","failure_modes":["Ignoring practice load","Promising all three outcomes","A ''speed'' block placed after conditioning","A copied rest ratio","A validated-microcycle claim","Dropping reactive work silently"],"delivery":["situation","decision (commit before feedback)","defense","discussion"],"rubric":"universal_case_rubric"}')::jsonb, 'k7'),
  ('a06afd57-5dd9-5940-a741-210aee3534ae', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'case', 'case-6', 'Youth Athlete and the Heavy Sled Question', ('{"id":"case-6","title":"Youth Athlete and the Heavy Sled Question","competencies":["C103-06","C103-13","C103-15"],"doctrine":["D103-9","D103-11","D103-2"],"modules":["M6","M11"],"situation_summary":"Parent asks what percentage of body weight a 15-year-old with one year of structured training should pull, citing conflicting figures and an article claiming heavy sleds are fastest for acceleration. One sled, 30 m indoor lane.","decision_prompt":"What do you say, what do you program, and how do you decide the load?","failure_modes":["Inventing a number","Deferring to the parent''s article","Claiming sleds are harmful","Treating one pending-verification meta-analysis as settling loading","Dropping sprint exposure for the tool","Adding an injury-prevention claim"],"delivery":["situation","decision (commit before feedback)","defense","discussion"],"rubric":"universal_case_rubric"}')::jsonb, 'k8'),
  ('64588597-5d71-548a-8481-08c18d2c6cf0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'case', 'case-7', 'Hamstring / Maximal-Velocity Claim Audit', ('{"id":"case-7","title":"Hamstring / Maximal-Velocity Claim Audit","competencies":["C103-05","C103-15","C103-16"],"doctrine":["D103-12","D103-3"],"modules":["M3","M12"],"situation_summary":"Draft program copy claims maximal-velocity sprinting prevents hamstring injuries. A second coach argues maximal-velocity sprinting is dangerous for high-school athletes and should be removed. A parent asks whether sprinting is safe after her son''s hamstring strain.","decision_prompt":"Audit both claims, write the replacement copy, and script the parent conversation.","failure_modes":["Softening a prevention claim rather than removing it","Removing max-velocity sprinting to satisfy the danger claim","Treating mechanistic rationale as intervention evidence","Reassurance instead of accuracy with the parent","Publishing external copy without Director of Training approval"],"delivery":["situation","decision (commit before feedback)","defense","discussion"],"rubric":"universal_case_rubric"}')::jsonb, 'k9'),
  ('48029e80-8ff2-5f31-a726-05c8dacb0149', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'evidence_classification', 'CLASS-A', 'A — Established Evidence', ('{"class":"A","name":"Established Evidence"}')::jsonb, 'l0'),
  ('48d41d5c-4e55-5d1d-9acb-e6e6df2d83e5', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'evidence_classification', 'CLASS-B', 'B — Supported Practice', ('{"class":"B","name":"Supported Practice"}')::jsonb, 'l1'),
  ('ed1a49ba-52fe-5f2a-996f-d406eb905864', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'evidence_classification', 'CLASS-C', 'C — Emerging / Conditional Evidence', ('{"class":"C","name":"Emerging / Conditional Evidence"}')::jsonb, 'l2'),
  ('59469773-0b46-5efc-8e12-1c579d6a6793', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'evidence_classification', 'CLASS-D', 'D — Applied Coaching Inference', ('{"class":"D","name":"Applied Coaching Inference"}')::jsonb, 'l3'),
  ('241a8f57-f341-5dcf-9108-430ddb2db721', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'evidence_classification', 'CLASS-E', 'E — Historical / Practitioner Framework', ('{"class":"E","name":"Historical / Practitioner Framework"}')::jsonb, 'l4'),
  ('43d4055a-c58d-53c1-86cf-b6273ae6bb74', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'evidence_classification', 'CLASS-F', 'F — Unsupported / Overstated Claim', ('{"class":"F","name":"Unsupported / Overstated Claim"}')::jsonb, 'l5'),
  ('1294ea58-6684-5793-a742-31644fd80125', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'evidence_classification', 'CLASS-U', 'U — Unresolved / Unknown', ('{"class":"U","name":"Unresolved / Unknown"}')::jsonb, 'l6'),
  ('a6915da1-edea-5bfe-84c8-b7fb49310702', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'governance', 'course-version', 'G3-103 version 1.0', ('{"course":"G3-103","version":"1.0","status":"APPROVED FOR NOVAKORE PRODUCTION","review_gates":{"evidence_review_gate":{"applies_to":"G3 103 Evidence Pack FINAL","status":"PASS WITH EVIDENCE-INTEGRITY CONDITIONS","conditions_count":10},"intellectual_development":{"applies_to":"G3 103 Production Handoff v1.0","status":"COMPLETE"},"production_qa":{"applies_to":"this specification and build file","status":"PASSED","checks":79,"unresolved":0}}}')::jsonb, 'l7'),
  ('feb58e3b-07da-51e8-922a-4f6ad9c7cb65', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'governance', 'workload', 'G3-103 directed study', ('{"modules":12,"directed_study_minutes":1170,"directed_study_hours":19.5,"practical_window_weeks_min":4,"note":"Directed study excludes practical windows, sign-off observation, artifact work, and terminal defenses."}')::jsonb, 'l8'),
  ('de96a241-deee-5e96-a5dc-ee466c942013', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'governance', 'standing', 'G3-103 standing', ('{"standing":"Internal G3 CEU course. External recognition not claimed; external-use gate closed until released by the Director of Training.","prerequisite":"G3 102 complete including T-01; active G3 Performance coaching status"}')::jsonb, 'l9'),
  ('30e2692c-d6c7-5295-a0d1-ceaa124a08fa', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f066bff2-1c9a-5388-b12a-d77b430200f6', 'governance', 'foundations', 'G3-103 Foundations position', (('{"series":"G3 Performance Foundations","series_version":"v1.0","gate":"G3 Performance Foundations — 101–105 Curriculum Review Gate v1.0","gate_status":"CONDITIONAL PASS — corrections applied; see the Foundations manifest for the post-correction gate status","sequence":["G3-101","G3-102","G3-103","G3-104","G3-105"],"position":3,"series_prerequisite":"G3-102","series_completion_rule":"A learner completes G3 Performance Foundations only when G3 101 through G3 105 are complete in sequence, all required module assessments are at standard, all 20 practical sign-offs are recorded, all 5 terminal defenses are passed, required practical windows are satisfied, and no required remediation remains open.","course_role":"Speed / Multidirectional Domain","authority_rule":{"this_course_is_authoritative_on":"speed, deceleration, COD, and agility — where its standard is narrower than the upstream rule","hierarchy":[{"course":"G3-101","authoritative_on":"the G3 reasoning system: evidence classes, certainty language, Evidence / G3 Applied Standard / Coach Judgment separation, population-transfer disclosure, testing and monitoring interpretation, claim-correction symmetry, scope of practice, and eviden'
insert into public.courses (id, organization_id, slug, title, summary, description, status, completion_rule, enforce_sequence) values
  ('815eac17-e5d1-5010-88fc-c3fa412e47ee', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'g3-104', 'G3-104 — Strength Development', 'Strength Domain · Curriculum G3-104 v1.0 · 12 modules · 20.75 directed-study hours · PS-1–PS-4 + T-01 · Internal G3 CEU', 'Teach coaches to understand strength as a task-specific physical quality, develop it through defensible resistance-training decisions, measure it appropriately, and integrate it into athletic preparation without confusing gym performance with sport performance. Prerequisite: G3 102 and G3 103 complete including both terminal defenses; active G3 Performance coaching status. Practical window: minimum 4 weeks (additional to directed study). Standing: Internal G3 CEU — external recognition not claimed.',
