  ('da42829c-5b27-5c1e-852f-dcd5fe89b54d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'd715666f-aed4-575d-8d94-3fd05fda9466', 'short_answer', 1, ('{"prompt":"K12.4 Which statement about resistance training and injury is defensible?","instructions":"Source item format: MC. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a3', true),
