  ('19630e79-545c-53d5-9bdc-009ddb33fe5f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', '062a7124-ef33-5e09-bce9-407f4075ddd2', 'practical_sign_off', 'PS-3', 'Youth / Contextual Strength Coaching', array['C104-13']::text[], ('{"dimensions":["task definition","instruction","observation","regression/progression","evidence honesty"],"scale":"0-3","pass":"11/15, no dimension below 2, never 0 on evidence honesty"}')::jsonb, 'M11 — Record: ["coach_id","sign_off_id","assessor_id","date","environment","athlete_or_group_ref","behaviors_observed","artifacts","questions_asked","outcome","expiry_date","notes"] — Minimum four-week practical window per course. Every recorded result carries the evaluator''s identity; results are immutable once recorded — corrections are new records.', '00000000-0000-4000-8000-000000000031'),
  ('343cf226-cfb0-5ada-866b-cd589ba5db7d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', '3f006cda-7423-53ce-8319-82e2ab5eaca3', 'practical_sign_off', 'PS-4', 'Integrated Strength Program / Microcycle', array['C104-10','C104-11','C104-12','C104-14']::text[], ('{"dimensions":["task definition","instruction","observation","regression/progression","evidence honesty"],"scale":"0-3","pass":"11/15, no dimension below 2, never 0 on evidence honesty"}')::jsonb, 'M12 — Record: ["coach_id","sign_off_id","assessor_id","date","environment","athlete_or_group_ref","behaviors_observed","artifacts","questions_asked","outcome","expiry_date","notes"] — Minimum four-week practical window per course. Every recorded result carries the evaluator''s identity; results are immutable once recorded — corrections are new records.', '00000000-0000-4000-8000-000000000031'),
  ('354fa4a4-9315-5bb7-b580-f3aa2917d435', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', '69a1eb87-1114-5c36-830e-058446b92117', 'terminal_defense', 'T-01', 'Strength Development Programming Defense', array['C104-01','C104-02','C104-03','C104-04','C104-05','C104-06','C104-07','C104-08','C104-09','C104-10','C104-11','C104-12','C104-13','C104-14','C104-15','C104-16','C104-17']::text[], ('{"dimensions":["demand and task fluency","method reasoning","dose reasoning","measurement discipline","evidence honesty"],"scale":"0-3","pass":"11/15, no dimension below 2, never 0 on evidence honesty","nonCompensable":["cannot answer probe 4","injury-prevention guarantee on probe 6","cites a universal ratio, threshold, or mandatory lift as justification anywhere"]}')::jsonb, '20-30 minutes with an approved assessor using the coach''s own athlete and artifacts; assessor works the eight obligations in order and probes at least four — Minimum four-week practical window per course. Every recorded result carries the evaluator''s identity; results are immutable once recorded — corrections are new records.', '00000000-0000-4000-8000-000000000031')
insert into public.curriculum_records (id, organization_id, course_id, kind, code, title, data, position) values
  ('4b72b75a-6e04-500c-9eb1-0bd5957e6b9c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'doctrine', 'D104-1', 'Strength Is Task-Specific', ('{"id":"D104-1","title":"Strength Is Task-Specific","statement":"Strength must be interpreted relative to the task used to express or measure it. A barbell result is evidence of performance in that lift, not a complete measure of athletic strength.","evidence_class":"A","teaching_boundary":"Does not devalue the barbell. Governs what may be concluded from a result, not whether it is worth testing.","modules":["M1","M12"],"anchor_refs":["EP104-14","EP104-13","EP104-43","EP104-44"],"standing":"G3 Doctrine"}')::jsonb, 'a0'),
  ('3ad5cc19-9170-59dd-987b-839fa191db99', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'doctrine', 'D104-2', 'Strength Is Foundational, Not Sufficient', ('{"id":"D104-2","title":"Strength Is Foundational, Not Sufficient","statement":"Strength supports many athletic outcomes, but increases in gym strength do not guarantee proportional improvements in sprinting, jumping, COD, or sport performance. Transfer depends on the athlete, task, training status, body mass, technical exposure, and surrounding program.","evidence_class":"B","teaching_boundary":"Cuts both ways: ''get strong and everything follows'' and ''strength doesn''t transfer'' are both unsupported.","modules":["M3"],"anchor_refs":["EP104-21","EP104-03","EP104-31","EP104-12"],"standing":"G3 Doctrine"}')::jsonb, 'a1'),
  ('1218c71c-daa3-50fc-a565-541c178c652a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'doctrine', 'D104-3', 'Adaptation Zones Overlap', ('{"id":"D104-3","title":"Adaptation Zones Overlap","statement":"Rep ranges and loading zones influence adaptation but are not discrete biological compartments. G3 rejects rigid rules such as ''1-5 strength, 6-12 hypertrophy, 12+ endurance.''","evidence_class":"A","teaching_boundary":"Overlapping is not identical; load still matters (D104-4). The rejection is of the boxes.","modules":["M4"],"anchor_refs":["EP104-06","EP104-25","EP104-13"],"standing":"G3 Doctrine"}')::jsonb, 'a2'),
  ('33520cac-1b7d-5b41-a6f8-d8b83ede4d3b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'doctrine', 'D104-4', 'Heavy Loading Is a Tool for Maximal Strength', ('{"id":"D104-4","title":"Heavy Loading Is a Tool for Maximal Strength","statement":"Higher loads are generally effective for maximizing dynamic 1RM strength, but lower and moderate loads can still produce strength adaptation. G3 does not define strength training exclusively by heavy loading.","evidence_class":"A/B","teaching_boundary":"No percentage, rep number, or loading table is published as a G3 rule. CA-01 and its mirror are both F.","modules":["M4"],"anchor_refs":["EP104-06","EP104-25","EP104-13"],"standing":"G3 Doctrine"}')::jsonb, 'a3'),
  ('1f256edc-fea5-5fec-a76d-fa93b9d9539e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'doctrine', 'D104-5', 'Failure Is Optional', ('{"id":"D104-5","title":"Failure Is Optional","statement":"Momentary muscular failure is not required for strength development. Failure may be used selectively when its benefits justify fatigue, technical, and recovery costs.","evidence_class":"A","teaching_boundary":"''Failure is necessary'' and ''failure should never be used'' are both F. No RIR target is published.","modules":["M5"],"anchor_refs":["EP104-19","EP104-08","EP104-07"],"standing":"G3 Doctrine"}')::jsonb, 'a4'),
  ('2eda19ff-9287-51f0-a2c9-edb9f6ff821e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'doctrine', 'D104-6', 'Exercise Selection Is Constraint-Based', ('{"id":"D104-6","title":"Exercise Selection Is Constraint-Based","statement":"G3 does not prescribe universal ''best lifts.'' Exercise selection reflects objective, athlete competence, anthropometry, loadability, stability, technical demand, fatigue cost, equipment, and transfer needs.","evidence_class":"B","teaching_boundary":"Not a claim that all exercises are equivalent for an objective. No mandatory lift list exists in G3 104.","modules":["M6"],"anchor_refs":["EP104-14","EP104-54","EP104-26","EP104-29"],"standing":"G3 Doctrine"}')::jsonb, 'a5'),
  ('93e2659e-2e36-51da-8942-11dd2f405259', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'doctrine', 'D104-7', 'Specificity Governs Modality', ('{"id":"D104-7","title":"Specificity Governs Modality","statement":"Free weights and machines, bilateral and unilateral exercises, dynamic and isometric methods, and full or partial ROM can all be useful. Their value depends on the adaptation and task, not ideological hierarchy.","evidence_class":"A","teaching_boundary":"Four F claims corrected without inversion (CA-07 to CA-10); instability functionality also F. Open- vs closed-kinetic-chain superiority is U.","modules":["M6","M7"],"anchor_refs":["EP104-24","EP104-27","EP104-40","EP104-26","EP104-29","EP104-30"],"standing":"G3 Doctrine"}')::jsonb, 'a6'),
  ('fd1b710f-94ea-5572-a274-ee53651df78d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'doctrine', 'D104-8', 'Full ROM Is a Broad Default, Not a Law', ('{"id":"D104-8","title":"Full ROM Is a Broad Default, Not a Law","statement":"Full ROM is a strong general default for broad strength development, while partial ROM can be used intentionally for joint-angle specificity, overload, progression, exposure, or contextual demands.","evidence_class":"B","teaching_boundary":"''On average'' is taught explicitly. Partial ROM requires a stated rationale; ''sport-specific'' alone does not qualify.","modules":["M7"],"anchor_refs":["EP104-36","EP104-38"],"standing":"G3 Doctrine"}')::jsonb, 'a7'),
  ('318ddecf-062b-5dce-a5cb-46f5cff30d14', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'doctrine', 'D104-9', 'Strength Programming Is Dose Management', ('{"id":"D104-9","title":"Strength Programming Is Dose Management","statement":"Volume, frequency, intensity, rest, effort, and exercise selection interact. No single variable is treated as an independent universal prescription.","evidence_class":"B","teaching_boundary":"No weekly set target, frequency prescription, or rest duration is published. The rest finding is directional, not numeric.","modules":["M5"],"anchor_refs":["EP104-37","EP104-09","EP104-10","EP104-11","EP104-05","EP104-14"],"standing":"G3 Doctrine"}')::jsonb, 'a8'),
  ('c841a668-5516-5e73-83f0-506c27b6e515', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'doctrine', 'D104-10', 'Autoregulation Is a Decision Tool', ('{"id":"D104-10","title":"Autoregulation Is a Decision Tool","statement":"RPE, RIR, APRE, VBT, and percentage-based methods are tools for prescription and adjustment. No one system is G3 doctrine or universally superior.","evidence_class":"C","teaching_boundary":"''VBT is inherently superior'' is F; so is dismissing it. No velocity-loss threshold, zone, RIR, or RPE cut-point is published.","modules":["M8"],"anchor_refs":["EP104-15","EP104-16","EP104-17","EP104-23"],"standing":"G3 Doctrine"}')::jsonb, 'a9'),
  ('c70f9b67-9d6a-50cb-a3eb-001ec8968745', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'doctrine', 'D104-11', 'Periodization Organizes Adaptation', ('{"id":"D104-11","title":"Periodization Organizes Adaptation","statement":"Periodization is the purposeful organization of training variables over time. No single named periodization model is universally superior across athletes and contexts.","evidence_class":"B/A","teaching_boundary":"Two findings held together: organizing beats not organizing; no organization wins. Named models are Class E.","modules":["M9"],"anchor_refs":["EP104-20","EP104-22","EP104-45"],"standing":"G3 Doctrine"}')::jsonb, 'b0'),
  ('3597ab5f-b6e0-5787-9d6a-ed4d1cfb30e3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'doctrine', 'D104-12', 'Concurrent Interference Is Conditional', ('{"id":"D104-12","title":"Concurrent Interference Is Conditional","statement":"Strength development can coexist with sprinting, conditioning, plyometrics, and sport practice. Interference depends on modality, dose, sequence, recovery, and athlete context rather than being inevitable.","evidence_class":"B","teaching_boundary":"Concurrent evidence base is older and adult-weighted; no numeric spacing or sequencing threshold is created.","modules":["M10"],"anchor_refs":["EP104-28","EP104-12"],"standing":"G3 Doctrine"}')::jsonb, 'b1'),
  ('0d378d88-c7fb-5978-9041-6a827d71aeee', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'doctrine', 'D104-13', 'Youth Can Train Strength', ('{"id":"D104-13","title":"Youth Can Train Strength","statement":"Properly supervised and progressively loaded resistance training is appropriate for youth. Readiness, technique, training age, maturation, supervision, and context matter more than outdated prohibitions based solely on chronological age.","evidence_class":"A","teaching_boundary":"Claim is conditioned on supervision, technical coaching, and progression, stated every time. ''Technique first'' must not become indefinite underloading.","modules":["M11"],"anchor_refs":["EP104-01","EP104-02","EP104-04"],"standing":"G3 Doctrine"}')::jsonb, 'b2'),
  ('c169eaf5-75d4-51cb-aecb-1a561f8f95f0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'doctrine', 'D104-14', 'Standards Must Earn Their Authority', ('{"id":"D104-14","title":"Standards Must Earn Their Authority","statement":"Universal bodyweight ratios, ''strong enough'' thresholds, mandatory exercise prerequisites, and fixed asymmetry cutoffs are not treated as G3 scientific standards without adequate population- and outcome-specific evidence.","evidence_class":"A/U","teaching_boundary":"Relative strength contextualizes; it may not gate a method. No replacement number is published.","modules":["M12"],"anchor_refs":["EP104-21","EP104-14","EP104-49"],"standing":"G3 Doctrine"}')::jsonb, 'b3'),
  ('b7915b7b-acac-5513-9157-a53ef445e2f7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'doctrine', 'D104-15', 'Safety Claims Require Evidence', ('{"id":"D104-15","title":"Safety Claims Require Evidence","statement":"No exercise is automatically safe or dangerous independent of loading, technique, athlete capacity, exposure, and context. G3 avoids simplistic claims about deep squats, knees-over-toes, deadlifts, or individual exercises ''preventing'' injury.","evidence_class":"B/A/U","teaching_boundary":"Restraint runs both directions. G3 uses injury-risk-reduction language, not prevention guarantees. Binds marketing and parent communication.","modules":["M11","M12"],"anchor_refs":["EP104-18","EP104-48","EP104-47","EP104-35","EP104-44"],"standing":"G3 Doctrine"}')::jsonb, 'b4'),
  ('55b6fefe-2c6f-5b33-abd4-d46845051128', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'applied_standard', 'AS-104-01', 'Define the Strength Task', ('{"id":"AS-104-01","title":"Define the Strength Task","text":"Every assessment or prescription identifies what form of strength is being trained or measured.","evidence_basis":"A","standing":"applied_standard","boundary_or_enforcement":"strength_task and test_record require strength_expression and task"}')::jsonb, 'b5'),
  ('3e7984bf-6f26-5b48-b0ca-bd2d99627ec2', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'applied_standard', 'AS-104-02', 'Match Load to Adaptation', ('{"id":"AS-104-02","title":"Match Load to Adaptation","text":"Loading is selected for the desired adaptation and athlete. Heavy loading is prioritized when maximal dynamic strength is the main target, without making it the only valid loading strategy.","evidence_basis":"A/B","standing":"applied_standard","boundary_or_enforcement":"no percentage, rep number, or loading table published (CJ-09)"}')::jsonb, 'b6'),
  ('adf4f43f-9f78-5fe5-9444-9436424e55ae', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'applied_standard', 'AS-104-03', 'Preserve Technical Quality', ('{"id":"AS-104-03","title":"Preserve Technical Quality","text":"Load progression is subordinate to acceptable execution, task intent, and athlete readiness.","evidence_basis":"D","standing":"applied_standard","boundary_or_enforcement":"does not license indefinite underloading (section 18.1)"}')::jsonb, 'b7'),
  ('f87a4a70-3a6e-5052-949a-a4774e37b5f9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'applied_standard', 'AS-104-04', 'Use Failure Deliberately', ('{"id":"AS-104-04","title":"Use Failure Deliberately","text":"Failure is not a default requirement. Its use accounts for exercise complexity, athlete experience, fatigue cost, recovery, and session purpose.","evidence_basis":"A","standing":"applied_standard","boundary_or_enforcement":"no RIR target or proximity rule published (CJ-04)"}')::jsonb, 'b8'),
  ('ac560e03-f133-5817-8435-06426e42b392', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'applied_standard', 'AS-104-05', 'Exercise Categories Before Exercise Dogma', ('{"id":"AS-104-05","title":"Exercise Categories Before Exercise Dogma","text":"Coaches select movement and exercise categories and constraints before declaring individual exercises mandatory.","evidence_basis":"B","standing":"applied_standard","boundary_or_enforcement":"naming a specific lift as mandatory fails production review"}')::jsonb, 'b9'),
  ('1cf8497c-732c-5dc5-978d-4e5b00f11387', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'applied_standard', 'AS-104-06', 'Use ROM Intentionally', ('{"id":"AS-104-06","title":"Use ROM Intentionally","text":"Full ROM is the broad default where appropriate. Partial ROM requires an explicit rationale rather than a generic ''sport-specific'' claim.","evidence_basis":"B","standing":"applied_standard","boundary_or_enforcement":"no universal full-ROM-only rule (CJ-14)"}')::jsonb, 'c0'),
  ('02203ad2-614e-5a41-b29d-7c5c48828a93', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'applied_standard', 'AS-104-07', 'Rest to Preserve the Intended Output', ('{"id":"AS-104-07","title":"Rest to Preserve the Intended Output","text":"For demanding strength work, rest generally supports force output and technical quality. Exact rest intervals remain contextual.","evidence_basis":"B","standing":"applied_standard","boundary_or_enforcement":"criterion is output, not the clock (CJ-03)"}')::jsonb, 'c1'),
  ('80cf2887-e566-54d6-88bd-db75c33f2456', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'applied_standard', 'AS-104-08', 'Frequency Organizes the Dose', ('{"id":"AS-104-08","title":"Frequency Organizes the Dose","text":"Frequency is used to distribute volume, technical exposures, fatigue, and recovery. It is not prescribed as an isolated magic variable.","evidence_basis":"B","standing":"applied_standard","boundary_or_enforcement":"no frequency prescription published (CJ-02)"}')::jsonb, 'c2'),
  ('12210a58-e08c-534d-844f-ae9a1d77b6db', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'applied_standard', 'AS-104-09', 'Autoregulate With Known Limits', ('{"id":"AS-104-09","title":"Autoregulate With Known Limits","text":"If RPE, RIR, VBT, or APRE are used, coaches must understand measurement error, athlete skill, exercise specificity, and the decision being informed.","evidence_basis":"C","standing":"applied_standard","boundary_or_enforcement":"no threshold, zone, or velocity-loss figure published (CJ-05 to CJ-07)"}')::jsonb, 'c3'),
  ('2801214a-34ec-5bc3-b698-531cf3e605ad', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'applied_standard', 'AS-104-10', 'Test the Construct', ('{"id":"AS-104-10","title":"Test the Construct","text":"1RM, submaximal RM, isometric tests, dynamometry, and velocity estimates measure different expressions of strength. G3 labels results according to what was actually measured.","evidence_basis":"A","standing":"applied_standard + language rule","boundary_or_enforcement":"test_record requires construct_measured; mislabeling is a scored error"}')::jsonb, 'c4'),
  ('5fbbf9b9-042c-59d2-87d7-f43d87b831af', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'applied_standard', 'AS-104-11', 'Avoid Universal Ratio Thresholds', ('{"id":"AS-104-11","title":"Avoid Universal Ratio Thresholds","text":"Relative-strength metrics may contextualize athlete performance, but universal bodyweight ratios cannot automatically gate advanced training methods.","evidence_basis":"A","standing":"applied_standard + prohibition","boundary_or_enforcement":"CJ-10, CJ-11, CJ-20"}')::jsonb, 'c5'),
  ('f2057983-bcd5-56c3-947d-af6881e49a9d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'applied_standard', 'AS-104-12', 'Interpret Asymmetry Cautiously', ('{"id":"AS-104-12","title":"Interpret Asymmetry Cautiously","text":"Asymmetry values require reliable measurement, task context, repeated observation, and athlete-specific interpretation. A single fixed percentage does not automatically mandate correction.","evidence_basis":"A/U","standing":"applied_standard","boundary_or_enforcement":"no threshold published; local adoption requires Director of Training approval and a measurement-error basis (CJ-18)"}')::jsonb, 'c6'),
  ('9465a88b-d0c2-5074-b0be-3745c65dcacd', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'applied_standard', 'AS-104-13', 'Youth Training Requires Qualified Supervision', ('{"id":"AS-104-13","title":"Youth Training Requires Qualified Supervision","text":"Youth resistance training is technically coached, progressively dosed, developmentally appropriate, and supervised.","evidence_basis":"A","standing":"applied_standard","boundary_or_enforcement":"supervision ratio documented for every youth group; safety claim stated with conditions"}')::jsonb, 'c7'),
  ('e87f0695-3c94-552b-9edc-39edd4475ffa', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'applied_standard', 'AS-104-14', 'In-Season Strength Is Constraint-Driven', ('{"id":"AS-104-14","title":"In-Season Strength Is Constraint-Driven","text":"In-season strength decisions protect meaningful exposure while adapting volume and frequency to sport load, competition density, recovery, and priority.","evidence_basis":"B/C","standing":"applied_standard","boundary_or_enforcement":"no maintenance dose or microdose model published (CJ-16, CJ-17)"}')::jsonb, 'c8'),
  ('05c435d0-7b50-5556-915e-521c88ae77a7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'coach_judgment', 'CJ-01', 'Exact weekly sets', ('{"id":"CJ-01","area":"Exact weekly sets","evidence_position":"Volume links more clearly to hypertrophy than maximal strength; physique set rules do not import","g3_supplies":"AS-104-09 dose-management framing","coach_call":"Weekly volume for this athlete and phase"}')::jsonb, 'c9'),
  ('84b59f84-ddb1-5040-9f41-0313c6ec5c74', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'coach_judgment', 'CJ-02', 'Exact frequency', ('{"id":"CJ-02","area":"Exact frequency","evidence_position":"Frequency distributes volume; independent effect limited when volume equated","g3_supplies":"AS-104-08","coach_call":"Frequency"}')::jsonb, 'd0'),
  ('ecdde887-a2f5-57d0-9481-a4c682dd9f64', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'coach_judgment', 'CJ-03', 'Exact rest duration', ('{"id":"CJ-03","area":"Exact rest duration","evidence_position":"Longer rest generally preserves output; no universal interval","g3_supplies":"AS-104-07, output as criterion","coach_call":"The interval"}')::jsonb, 'd1'),
  ('eac79fcf-3e71-5441-8568-c24b70057221', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'coach_judgment', 'CJ-04', 'Exact RIR', ('{"id":"CJ-04","area":"Exact RIR","evidence_position":"Failure not required; no target established","g3_supplies":"AS-104-04","coach_call":"Proximity to failure"}')::jsonb, 'd2'),
  ('20ad045d-68b2-5e6d-b053-26c18963fcc9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'coach_judgment', 'CJ-05', 'Exact RPE', ('{"id":"CJ-05","area":"Exact RPE","evidence_position":"Scale- and context-dependent","g3_supplies":"AS-104-09","coach_call":"The rating used and its weight"}')::jsonb, 'd3'),
