insert into public.content_blocks (id, organization_id, lesson_id, block_type, schema_version, data, position) values
  ('fd546176-d913-5148-91ff-9d1aa60d2510', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1d40d53c-0b08-554b-aeab-30b8913c9cb6', 'quote', 1, ('{"text":"\"He needs to be more explosive\" is not a coaching statement. It names no task, no quality, and no decision — and this course begins by taking it away."}')::jsonb, 'a0'),
  ('5452c7d0-e575-578f-ba51-6c00f13751a0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1d40d53c-0b08-554b-aeab-30b8913c9cb6', 'rich_text', 1, ('{"text":"To install the mechanical vocabulary the course depends on, and to end the use of \"explosiveness\" as a diagnostic category."}')::jsonb, 'a1'),
  ('118b2f0b-f5fe-57cf-9ca4-35e6dc26ecef', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1d40d53c-0b08-554b-aeab-30b8913c9cb6', 'checklist', 1, ('{"items":[{"id":"a5d7694b-2aae-5811-9774-84260904c49a","text":"M1.1 Define mechanical power as rate of work, and state when force × velocity applies."},{"id":"776ea08a-0ab7-5122-85af-79c37387ee04","text":"M1.2 Distinguish force, strength, work, power, impulse, RFD, velocity, and acceleration."},{"id":"3a678176-4c2a-52f7-a69d-ec7948c167b7","text":"M1.3 Distinguish peak and mean power, and state why interval and calculation must be specified."},{"id":"097f5127-1244-5231-ad20-f8aca96d8bc9","text":"M1.4 Explain why relative power is not universally more meaningful than absolute power."},{"id":"7c669b51-6ca9-5909-9824-65ea538500dc","text":"M1.5 Explain why \"explosiveness\" is not a stable scientific construct."},{"id":"65b9d768-1386-5126-9f40-adc42b729f9a","text":"M1.6 Replace an \"explosiveness\" statement with the actual quality and task."}]}')::jsonb, 'a2'),
  ('3e024672-eae4-5f7b-bdd5-d572c6da49f7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1d40d53c-0b08-554b-aeab-30b8913c9cb6', 'callout', 2, ('{"tone":"info","title":"Sequence & gating","body":"entry module"}')::jsonb, 'a3'),
  ('951bd250-a095-5ce5-9df0-6146f013291f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1d40d53c-0b08-554b-aeab-30b8913c9cb6', 'lesson_reference', 1, ('{"courseId":"b17cac49-2d2b-59c4-bc80-5de456998e75","lessonId":"460effc6-93c3-5f5f-8336-fdae680089d1","label":"Recall — the G3 reasoning system (G3 101, Module 12)","note":"Evidence classes, certainty language, and the three-layer discipline are governed by G3 101."}')::jsonb, 'a4'),
  ('e8883402-c706-5ae9-8846-f97d63953f88', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1d40d53c-0b08-554b-aeab-30b8913c9cb6', 'lesson_reference', 1, ('{"courseId":"4832fade-c765-5fcd-b784-d1a4103394fd","lessonId":"81e0bab6-4baa-5a42-93cb-7c47b740ac4f","label":"Recall — the G3 programming decision model (G3 102, Module 1)","note":"DEMAND → PROFILE → GAP → PRIORITY → PRESCRIPTION → RESPONSE → ADJUST is governed by G3 102 and is never modified downstream."}')::jsonb, 'a5'),
  ('5319d3ee-07fc-5ca1-9cc1-d661f5451b02', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '33bfcdb2-a39d-507e-b8f6-474f91cb4573', 'heading', 1, ('{"text":"L1.1 The word that means nothing","level":3}')::jsonb, 'a0'),
  ('72c2aadd-d0f4-5e79-843d-05e580ba4e8b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '33bfcdb2-a39d-507e-b8f6-474f91cb4573', 'rich_text', 1, ('{"text":"Four coaches use \"explosive\" for four different qualities in one session. The cost is that none of them can select a method or a test."}')::jsonb, 'a1'),
  ('e6755a8b-155d-55ea-bfbe-aab48d1364af', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '33bfcdb2-a39d-507e-b8f6-474f91cb4573', 'heading', 1, ('{"text":"L1.2 Power, properly defined","level":3}')::jsonb, 'a2'),
  ('7388e240-b447-5f58-9505-23c191972a38', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '33bfcdb2-a39d-507e-b8f6-474f91cb4573', 'rich_text', 1, ('{"text":"Rate of work; force × velocity in aligned conditions; and why the definition already contains the task-specificity of D105-01."}')::jsonb, 'a3'),
  ('7ffdc5e7-df86-54ff-a7f1-d8a265a1c8b4', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '33bfcdb2-a39d-507e-b8f6-474f91cb4573', 'heading', 1, ('{"text":"L1.3 The neighbours","level":3}')::jsonb, 'a4'),
  ('286995f4-9b79-55e9-b3f4-287b26047a47', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '33bfcdb2-a39d-507e-b8f6-474f91cb4573', 'rich_text', 1, ('{"text":"Force, strength, work, impulse, velocity, acceleration — each defined against power and against each other."}')::jsonb, 'a5'),
  ('035fbfa5-eb50-5f05-8c8b-86adb6bd89b2', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '33bfcdb2-a39d-507e-b8f6-474f91cb4573', 'heading', 1, ('{"text":"L1.4 Peak, mean, and the protocol","level":3}')::jsonb, 'a6'),
  ('66a36866-8951-5faf-b79e-afbb94798a1d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '33bfcdb2-a39d-507e-b8f6-474f91cb4573', 'rich_text', 1, ('{"text":"Why a power number without its interval, model, and device is not a result."}')::jsonb, 'a7'),
  ('ac690f0a-d76a-5a39-a042-1968cd7dce77', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '33bfcdb2-a39d-507e-b8f6-474f91cb4573', 'heading', 1, ('{"text":"L1.5 Relative and absolute","level":3}')::jsonb, 'a8'),
  ('b71a64bb-4b30-5beb-962a-699bfb1980e8', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '33bfcdb2-a39d-507e-b8f6-474f91cb4573', 'rich_text', 1, ('{"text":"When normalizing helps, when it distorts, and why neither is universally superior."}')::jsonb, 'a9'),
  ('7f6ba796-231c-5302-9654-bf8f0050eb2f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '33bfcdb2-a39d-507e-b8f6-474f91cb4573', 'heading', 1, ('{"text":"L1.6 RFD, introduced honestly","level":3}')::jsonb, 'b0'),
  ('b6b986c5-fbf0-544e-911c-2c9d7bc0e15e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '33bfcdb2-a39d-507e-b8f6-474f91cb4573', 'rich_text', 1, ('{"text":"Conceptually important, measurement-sensitive, and not a synonym for power. Full treatment in M8."}')::jsonb, 'b1'),
  ('cf30b094-3d72-5edd-9e4d-51cf756f8379', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '33bfcdb2-a39d-507e-b8f6-474f91cb4573', 'heading', 1, ('{"text":"L1.7 Rewriting the claim","level":3}')::jsonb, 'b2'),
  ('1b8dc31b-598d-51cd-9b46-4ae0df9b053c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '33bfcdb2-a39d-507e-b8f6-474f91cb4573', 'rich_text', 1, ('{"text":"Coaches convert real statements — \"she needs more explosiveness,\" \"he''s a power athlete\" — into task-and-quality language, or flag them as unanswerable."}')::jsonb, 'b3'),
  ('2b607d27-895f-5d32-a8d7-6ac9872e37f2', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f681fb59-04ba-595c-85e8-d2fd0df0801f', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D105-01 — Power Is Task-Specific","body":"Interpret power within the movement, load, body mass, force-time constraints, and measurement method used to express it. — Teaching boundary: This does not make power measurement useless. It makes an unlabeled power number meaningless. Every power value in G3 carries its task, load, and calculation method. — Evidence class: A"}')::jsonb, 'a0'),
  ('c986952a-0c97-5a8e-9f8e-6040b085d7ec', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f681fb59-04ba-595c-85e8-d2fd0df0801f', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D105-02 — Related Qualities Are Not Interchangeable","body":"Strength, force, impulse, velocity, power, and RFD interact but are distinct. — Teaching boundary: Distinct does not mean unrelated — these qualities interact continuously in every athletic task. The doctrine forbids substitution, not integration. \"Explosiveness\" is Class F as a precise diagnostic term and is replaced by the actual quality and task. — Evidence class: A"}')::jsonb, 'a1'),
  ('2d4bf4d9-2e0a-5ef3-9feb-ebca82860c29', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f681fb59-04ba-595c-85e8-d2fd0df0801f', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A / Known","body":"Force, strength, work, mechanical power, impulse, velocity, and acceleration are distinct constructs — Basis: EP105-01, EP105-02; EP105-01; EP105-02"}')::jsonb, 'a2'),
  ('8d36a66a-60d2-58ce-8cb3-8dbc90744bcd', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f681fb59-04ba-595c-85e8-d2fd0df0801f', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A / Known","body":"Mechanical power is rate of work; force × velocity applies when vectors are aligned — Basis: EP105-01, EP105-02; EP105-01; EP105-02"}')::jsonb, 'a3'),
  ('d47a8c05-f9c8-52e8-aa9a-3f593dfbc38c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f681fb59-04ba-595c-85e8-d2fd0df0801f', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B / Probable","body":"Peak power is the highest instantaneous power in a defined interval and model — Basis: EP105-02, EP105-08; EP105-02; EP105-08"}')::jsonb, 'a4'),
  ('05c42316-8a48-59bf-849a-dd20f4743cde', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f681fb59-04ba-595c-85e8-d2fd0df0801f', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B / Probable","body":"Mean power requires its interval and calculation to be specified — Basis: EP105-02; EP105-02"}')::jsonb, 'a5'),
  ('a6049190-32dd-5481-a871-46dcfdfb366c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f681fb59-04ba-595c-85e8-d2fd0df0801f', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A for definition; B/C for routine field interpretation","body":"RFD is distinct from power — Basis: EP105-03; EP105-03"}')::jsonb, 'a6'),
  ('c506c305-14bf-5452-ab3f-e129742fef47', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f681fb59-04ba-595c-85e8-d2fd0df0801f', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B / Context dependent","body":"Relative power is context dependent, not universally superior — Basis: EP105-02; EP105-02"}')::jsonb, 'a7'),
  ('e4dda8cc-7548-50f9-9e51-24244e27ff10', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f681fb59-04ba-595c-85e8-d2fd0df0801f', 'callout', 2, ('{"tone":"info","title":"Evidence — Class F","body":"\"Explosiveness\" as a precise diagnostic term — Basis: EP105-02, EP105-03; EP105-02; EP105-03"}')::jsonb, 'a8'),
  ('8a45f1dc-28ee-50c3-9d31-bb88bd989ba7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f681fb59-04ba-595c-85e8-d2fd0df0801f', 'callout', 2, ('{"tone":"success","title":"G3 Applied Standard AS-105-01 — Name the Output","body":"Identify the actual task and output requirement before prescribing \"power.\" — Enforcement: every power_task object requires output_requirement and task (§21.4)."}')::jsonb, 'a9'),
  ('c2559fc0-4bb3-5656-b423-307bf760794a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f681fb59-04ba-595c-85e8-d2fd0df0801f', 'callout', 2, ('{"tone":"success","title":"G3 Applied Standard AS-105-10 — Measure the Construct Actually Tested","body":"Label CMJ, broad jump, RSI, loaded jump, medicine-ball throw, or bar-velocity results according to the task performed. — Enforcement: test_record requires construct_measured."}')::jsonb, 'b0'),
  ('c084e7f0-0799-5228-90a8-0096b139a69b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f681fb59-04ba-595c-85e8-d2fd0df0801f', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"none. Definitions are not negotiable inside G3."}')::jsonb, 'b1'),
  ('69f03088-101a-55ed-a5a9-db2ce2af47b1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f681fb59-04ba-595c-85e8-d2fd0df0801f', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Using \"explosiveness\" as a diagnosis (D105-02; Class F as a precise term) · reporting a power value with no task or calculation · using power and RFD interchangeably · assuming relative power is always the better expression · treating a peak-power figure as an athlete attribute."}')::jsonb, 'b2'),
  ('f9b287db-213c-54f2-8d80-207cc24ccacf', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'f681fb59-04ba-595c-85e8-d2fd0df0801f', 'callout', 2, ('{"tone":"warning","title":"Population-transfer disclosure (AS-101-16)","body":"definitional evidence is mechanical and not population-limited; the field-interpretation caveat on RFD carries adult laboratory origins."}')::jsonb, 'b3'),
  ('8055b429-eac1-5522-a5a5-3211b88fa063', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c05661d6-6188-5ba6-9fd7-96c339badce5', 'rich_text', 1, ('{"text":"Applied immediately to G3 session plans and testing language. A block labeled \"power\" is incomplete; \"vertical projection output in a loaded jump for an athlete whose demand is repeated jump performance\" can be evaluated by someone else."}')::jsonb, 'a0'),
  ('4dacc37e-eda4-545e-842f-337f916a4e45', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c05661d6-6188-5ba6-9fd7-96c339badce5', 'scenario', 1, ('{"intro":"Scenario M1-A — Rewrite the claim. Eight real coaching statements rewritten into G3 form with task, quality, and measurement named — or flagged as unanswerable without more information.","steps":[{"id":"39048161-f1c9-5a2e-80d6-4a7237946b30","situation":"Work the case with your assessor: name the decision, the evidence class behind it, and what would change your answer."}]}')::jsonb, 'a1'),
  ('48013c1e-1f74-57f4-908e-cf6837d6af98', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'c05661d6-6188-5ba6-9fd7-96c339badce5', 'callout', 2, ('{"tone":"info","title":"Practical sign-off linkage","body":"None. Terminology accuracy carries into PS-1 and is scored in T-01."}')::jsonb, 'a2'),
  ('cd94155b-9766-5b66-98da-23015a80569d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '90dd064f-dee2-5b1b-b0dc-684135aa808a', 'rich_text', 1, ('{"text":"This module closes with its assessment: the knowledge component (80% standard) and the applied competency component (at standard or better, one revision permitted). Written items are graded by a G3 assessor against the recorded keys and standards — applied coaching competence is never certified by written work alone."}')::jsonb, 'a0'),
  ('8b361a99-3a5e-5961-9261-2e6ab0670799', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '90dd064f-dee2-5b1b-b0dc-684135aa808a', 'assessment_reference', 1, ('{"assessmentId":"379465b5-7587-53d7-956d-00e5a283bcab","title":"G3-105 · M1 Assessment — What Power Actually Is"}')::jsonb, 'a1'),
  ('26a44607-43f1-5a46-b404-bb364e086838', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '37f4fa18-78ed-5804-b932-525d309a4b52', 'quote', 1, ('{"text":"Jump height can improve for at least five different reasons. Until you know which one, you do not know what you trained."}')::jsonb, 'a0'),
  ('90cf79b6-36c1-5d79-b7ca-b292ae7dbc30', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '37f4fa18-78ed-5804-b932-525d309a4b52', 'rich_text', 1, ('{"text":"To ground power reasoning in impulse, force-time, and body mass, and to install the association-versus-transfer discipline before any method is discussed."}')::jsonb, 'a1'),
  ('0cf15f1d-15f4-5395-a648-f86bfe714a01', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '37f4fa18-78ed-5804-b932-525d309a4b52', 'checklist', 1, ('{"items":[{"id":"3978a280-63cd-5c1b-8a31-9364e1194530","text":"M2.1 Explain work/time and force × velocity as descriptions, not prescriptions."},{"id":"611396ec-993e-5fd1-97f5-4cfffc2b1f62","text":"M2.2 Explain impulse–momentum and why net impulse relative to body mass governs takeoff velocity."},{"id":"2be5e6a6-ee5e-59e9-a055-692e5aaed1f5","text":"M2.3 Name the multiple pathways by which a jump outcome can change."},{"id":"a09c3d8e-e4fc-52e5-aee6-077e5aa2ab3a","text":"M2.4 Explain force-time constraints — why time available changes which quality matters."},{"id":"fc1a02b3-ef84-5a2f-9472-716b4d7d29ec","text":"M2.5 Distinguish association from transfer."},{"id":"3c35510f-cd5c-55c8-8cbc-b71c5736450a","text":"M2.6 Explain why directional similarity does not guarantee transfer."},{"id":"b8eabb65-8b4a-533c-8130-1220813d286c","text":"M2.7 State a transfer pathway for any method proposed."}]}')::jsonb, 'a2'),
  ('e1515b43-6d66-59d0-86f5-951e48ff7cd6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '37f4fa18-78ed-5804-b932-525d309a4b52', 'callout', 2, ('{"tone":"info","title":"Sequence & gating","body":"requires M1"}')::jsonb, 'a3'),
  ('3220dd87-35d1-5981-9c0b-67adddb9b804', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '39ec8274-1d2d-5287-bcd0-78bf3164659e', 'heading', 1, ('{"text":"L2.1 Work, time, force, velocity","level":3}')::jsonb, 'a0'),
  ('04ac93fc-934d-5037-82fb-bd82976fab01', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '39ec8274-1d2d-5287-bcd0-78bf3164659e', 'rich_text', 1, ('{"text":"The mechanics, stated so they describe rather than prescribe."}')::jsonb, 'a1'),
  ('e78f9c3b-ee5f-56ed-ba1e-a01eab4b2739', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '39ec8274-1d2d-5287-bcd0-78bf3164659e', 'heading', 1, ('{"text":"L2.2 Impulse and momentum","level":3}')::jsonb, 'a2'),
  ('f70cc175-b5bf-5a12-8143-05126a6fe9e6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '39ec8274-1d2d-5287-bcd0-78bf3164659e', 'rich_text', 1, ('{"text":"The force-time integral, and why it is the honest way to think about jumping and acceleration."}')::jsonb, 'a3'),
  ('d0b04ee6-21f8-5de1-8298-9f1f8d95b13c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '39ec8274-1d2d-5287-bcd0-78bf3164659e', 'heading', 1, ('{"text":"L2.3 Five ways a jump improves","level":3}')::jsonb, 'a4'),
  ('2a9fe49b-730f-521b-9a12-7d79d0bffcf0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '39ec8274-1d2d-5287-bcd0-78bf3164659e', 'rich_text', 1, ('{"text":"Force magnitude · force-application time · timing and coordination · movement strategy · body mass. This lesson is the mechanical basis for the entire limitation-hypothesis method in M3."}')::jsonb, 'a5'),
  ('100ea49d-ac6a-57ae-84d1-fdb8f0aa07be', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '39ec8274-1d2d-5287-bcd0-78bf3164659e', 'heading', 1, ('{"text":"L2.4 Time available changes the question","level":3}')::jsonb, 'a6'),
  ('2c40e6e4-bb6c-5e67-9e06-1501ffe00e94', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '39ec8274-1d2d-5287-bcd0-78bf3164659e', 'rich_text', 1, ('{"text":"When time is constrained, peak force achieved too late does not help — which is why impulse and RFD enter the conversation, and why neither is universally primary."}')::jsonb, 'a7'),
  ('880d9ce1-b712-55d1-bc85-d2c2dab9fc40', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '39ec8274-1d2d-5287-bcd0-78bf3164659e', 'heading', 1, ('{"text":"L2.5 Association is not transfer","level":3}')::jsonb, 'a8'),
  ('97c13d7a-3966-5cb5-b097-d609648e259f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '39ec8274-1d2d-5287-bcd0-78bf3164659e', 'rich_text', 1, ('{"text":"Test outcomes correlate with sport tasks. That identifies neither the limiting quality nor the method."}')::jsonb, 'a9'),
  ('b4c0db1e-eabc-5f8e-858e-1cbd1c141d8a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '39ec8274-1d2d-5287-bcd0-78bf3164659e', 'heading', 1, ('{"text":"L2.6 Direction, carefully","level":3}')::jsonb, 'b0'),
  ('39803e32-1e7a-5ab8-8a5b-d568cb6f77c4', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '39ec8274-1d2d-5287-bcd0-78bf3164659e', 'rich_text', 1, ('{"text":"Horizontal and vertical tasks can both contribute to sprint-related outcomes; visual direction alone establishes nothing (D105-08)."}')::jsonb, 'b1'),
  ('e51b33c6-5fcc-5768-a93a-ee89a126a631', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '39ec8274-1d2d-5287-bcd0-78bf3164659e', 'heading', 1, ('{"text":"L2.7 Stating the transfer pathway","level":3}')::jsonb, 'b2'),
  ('d23c7e0f-1457-532c-bd27-ee970363ada3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '39ec8274-1d2d-5287-bcd0-78bf3164659e', 'rich_text', 1, ('{"text":"For any method: what adaptation, expressed in which task, supported by what exposure, and what would show it did not occur."}')::jsonb, 'b3'),
  ('fab8955c-fd6d-5b8c-80db-9815dca2dd34', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '86c27c82-e437-5372-b473-029307330ebb', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D105-01 — Power Is Task-Specific","body":"Interpret power within the movement, load, body mass, force-time constraints, and measurement method used to express it. — Teaching boundary: This does not make power measurement useless. It makes an unlabeled power number meaningless. Every power value in G3 carries its task, load, and calculation method. — Evidence class: A"}')::jsonb, 'a0'),
  ('c38bb41d-6232-567b-9448-9c3574fadac9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '86c27c82-e437-5372-b473-029307330ebb', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D105-07 — Transfer Must Be Demonstrated, Not Assumed","body":"Improvement in a jump, lift, throw, profile, or laboratory metric does not automatically establish sport transfer. — Teaching boundary: Continuous with G3 103 D103-7 and G3 104 D104-2. This is not a claim that transfer is rare — it is a requirement that the transfer pathway be stated and, where possible, observed. — Evidence class: A"}')::jsonb, 'a1'),
  ('6df47427-a80f-5cc8-bf57-6c60fb0a30d0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '86c27c82-e437-5372-b473-029307330ebb', 'callout', 2, ('{"tone":"note","title":"G3 Doctrine D105-08 — Directional Similarity Is Not Sufficient Specificity","body":"Horizontal, vertical, unilateral, bilateral, or visually sport-like exercises do not guarantee direction- or sport-specific transfer. — Teaching boundary: Direction may matter. What is unsupported is the inference from visual direction to guaranteed transfer. Selecting unilateral or bilateral work by task, competence, tolerance, and desired loading is Class D — legitimate coaching inference, labeled as such (CJ-12). — Evidence class: B"}')::jsonb, 'a2'),
  ('2d87e86c-3a67-5627-9502-443582d30909', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '86c27c82-e437-5372-b473-029307330ebb', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Force and velocity jointly determine external mechanical power — Basis: EP105-01; EP105-01"}')::jsonb, 'a3'),
  ('4fb72256-6cc6-595f-a1f0-8056a11fb22e', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '86c27c82-e437-5372-b473-029307330ebb', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Impulse is the force-time integral; net vertical impulse relative to body mass determines takeoff velocity — Basis: EP105-01, EP105-08; EP105-01; EP105-08"}')::jsonb, 'a4'),
  ('cc4a97f5-fcda-59d2-a310-3298a7dc8540', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '86c27c82-e437-5372-b473-029307330ebb', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Jump height can change through force magnitude, force-application time, timing/coordination, movement strategy, or body mass — Basis: EP105-01, EP105-08; EP105-01; EP105-08"}')::jsonb, 'a5'),
  ('caef7796-ad9f-5955-8ae7-bfb579984854', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '86c27c82-e437-5372-b473-029307330ebb', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A/B — mechanical principle; task application is reasonable extrapolation","body":"Impulse is often more task-informative than peak force alone when time is constrained — Basis: EP105-02; EP105-02"}')::jsonb, 'a6'),
  ('76bd5f17-4b2b-5f04-8920-1313d3ea2567', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '86c27c82-e437-5372-b473-029307330ebb', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Power-related test outcomes are associated with sprinting, jumping, and COD — Basis: EP105-02, EP105-07; EP105-02; EP105-07"}')::jsonb, 'a7'),
  ('54cad49a-6aac-5163-9f05-8e3780b3d1ae', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '86c27c82-e437-5372-b473-029307330ebb', 'callout', 2, ('{"tone":"info","title":"Evidence — Class A","body":"Association does not identify the causal quality to train — Basis: EP105-02, EP105-07; EP105-02; EP105-07"}')::jsonb, 'a8'),
  ('adbe4dec-63f6-58f9-8a60-05aec3c58e53', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '86c27c82-e437-5372-b473-029307330ebb', 'callout', 2, ('{"tone":"info","title":"Evidence — Class B — spans different sports and interventions","body":"Resistance training can improve sport-specific performance in elite athletes — Basis: Evidence Pack §5; supporting record not itemized (§20.3b)"}')::jsonb, 'a9'),
  ('111d3e5c-cf2c-5150-bd30-2211d50c4523', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '86c27c82-e437-5372-b473-029307330ebb', 'callout', 2, ('{"tone":"info","title":"Evidence — Class F","body":"Directional similarity guarantees transfer — Basis: EP105-02, EP105-07; EP105-02; EP105-07"}')::jsonb, 'b0'),
  ('b69efb46-0ecb-54f8-ae4b-08201c76f35d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '86c27c82-e437-5372-b473-029307330ebb', 'callout', 2, ('{"tone":"info","title":"Evidence — Class F","body":"Vertical jump alone predicts or develops maximal velocity — Basis: EP105-02; EP105-02"}')::jsonb, 'b1'),
  ('b7d69106-f5f4-55aa-a7d0-44e406a559ce', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '86c27c82-e437-5372-b473-029307330ebb', 'callout', 2, ('{"tone":"success","title":"G3 Applied Standard AS-105-01 — Name the Output","body":"Identify the actual task and output requirement before prescribing \"power.\" — Enforcement: every power_task object requires output_requirement and task (§21.4)."}')::jsonb, 'b2'),
  ('36ac8a45-e713-5abc-8d85-b20434ed0a42', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '86c27c82-e437-5372-b473-029307330ebb', 'callout', 2, ('{"tone":"success","title":"G3 Applied Standard AS-105-02 — Build Limitation Hypotheses From Multiple Sources","body":"Use task performance, strength/force capacity, technical observation, training history, and context before labeling an athlete."}')::jsonb, 'b3'),
  ('75ff72f4-9e45-5808-b09d-626bd10fd91d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '86c27c82-e437-5372-b473-029307330ebb', 'callout', 2, ('{"tone":"warning","title":"Coach Judgment","body":"which pathway to pursue for a given athlete — that is M3''s hypothesis work."}')::jsonb, 'b4'),
  ('d2472e8a-4528-52ff-844a-6a63e11856f4', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '86c27c82-e437-5372-b473-029307330ebb', 'callout', 2, ('{"tone":"danger","title":"Common coaching errors — claim audit","body":"Treating jump height as a power diagnosis · reading a correlation as a prescription · vector-matching claims (CA-14) · assuming vertical work develops maximal velocity · ignoring body mass in tasks the athlete must move · reporting exercise improvement as sport transfer (§1.2)."}')::jsonb, 'b5'),
  ('7d103459-330a-5d81-a4e2-74f83e9195eb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '86c27c82-e437-5372-b473-029307330ebb', 'callout', 2, ('{"tone":"warning","title":"Population-transfer disclosure (AS-101-16)","body":"transfer evidence spans athlete populations with substantial heterogeneity; elite-sample findings are not generalized to developing athletes."}')::jsonb, 'b6'),
  ('1606b3c5-c994-5f20-b877-ebd267275edd', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '88e4e95a-2751-5612-b3ce-b3b6b7e32fd7', 'rich_text', 1, ('{"text":"The practical use is diagnostic restraint. When an athlete''s jump improves, the competent coach can name which pathways plausibly moved and which were not addressed — before deciding what the improvement means."}')::jsonb, 'a0'),
  ('c309c9b0-6fd7-5e33-8fce-c60d816f14c3', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '88e4e95a-2751-5612-b3ce-b3b6b7e32fd7', 'scenario', 1, (('{"intro":"Strong High-School Athlete With Poor Acceleration. Marcus, 17, three years of well-coached strength training. Trap-bar deadlift and squat among the strongest in the program absolutely and relative to body mass. CMJ above team average. First-step and 10 m acceleration among the poorest in the squad, consistently, across two testing occasions on the same surface with the same timing method. Video shows a tall first step, late shin angle, and a hesitant initiation under reactive conditions. Sport practice is dense; there has been no dedicated sprint-technical exposure.","steps":[{"id":"491aa3ab-2a22-5ec8-9918-9789b8c5746c","situation":"Situation"},{"id":"195b0f4a-0f76-50af-a69d-573b9170e1fc","situation":"Decision"},{"id":"a66765c7-9b98-5b98-bb2e-c163c9284ad6","situation":"Defense"},{"id":"ae400b12-dbf3-5108-abbf-f46620d87ba9","situation":"Discussion"}],"debrief":"Decision required: What is the limitation hypothesis, and what does the block contain?\n\nFailure modes: \"He needs more power\" as the plan · a jump metric used to diagnose acceleration · an F-V label applied without a profile, or with one · vector-matching justification · ignoring the absence of sprint exposure · '
insert into public.lesson_versions (id, organization_id, lesson_id, course_id, version_number, title, required, estimated_minutes, blocks, published_by) values
  ('493df076-8fef-5bbd-89e8-54c58e98dba7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '1d40d53c-0b08-554b-aeab-30b8913c9cb6', '9104a610-53ae-5fc5-b565-23db55089bb0', 1, 'Overview & objectives', true, 9, (('[{"id":"fd546176-d913-5148-91ff-9d1aa60d2510","type":"quote","schemaVersion":1,"data":{"text":"\"He needs to be more explosive\" is not a coaching statement. It names no task, no quality, and no decision — and this course begins by taking it away."},"position":"a0"},{"id":"5452c7d0-e575-578f-ba51-6c00f13751a0","type":"rich_text","schemaVersion":1,"data":{"text":"To install the mechanical vocabulary the course depends on, and to end the use of \"explosiveness\" as a diagnostic category."},"position":"a1"},{"id":"118b2f0b-f5fe-57cf-9ca4-35e6dc26ecef","type":"checklist","schemaVersion":1,"data":{"items":[{"id":"a5d7694b-2aae-5811-9774-84260904c49a","text":"M1.1 Define mechanical power as rate of work, and state when force × velocity applies."},{"id":"776ea08a-0ab7-5122-85af-79c37387ee04","text":"M1.2 Distinguish force, strength, work, power, impulse, RFD, velocity, and acceleration."},{"id":"3a678176-4c2a-52f7-a69d-ec7948c167b7","text":"M1.3 Distinguish peak and mean power, and state why interval and calculation must be specified."},{"id":"097f5127-1244-5231-ad20-f8aca96d8bc9","text":"M1.4 Explain why relative power is not universally more meaningful than absolute power."},{"id":"7c66'
