  ('353caa8c-30bb-539f-9b2b-7d3f3a10ab9a', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '379465b5-7587-53d7-956d-00e5a283bcab', 'short_answer', 1, ('{"prompt":"K1.1 Which definition of mechanical power does G3 use?","instructions":"Source item format: MC. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a0', true),
  ('79a0f5f3-008a-520d-8337-551227c7930d', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '379465b5-7587-53d7-956d-00e5a283bcab', 'short_answer', 1, ('{"prompt":"K1.2 Match seven constructs to their defining relationship.","instructions":"Source item format: Matching. Answer in writing; your assessor grades against the G3 standard (80% per module).","maxLength":2000,"points":10}')::jsonb, 'a1', true),
