insert into public.practical_requirements (id, organization_id, course_id, lesson_id, kind, code, title, competency_codes, rubric, guidance, created_by) values
  ('76a40f45-3d54-5e0f-bef4-130c64c030cb', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9104a610-53ae-5fc5-b565-23db55089bb0', '6d9a306d-d657-5d88-9e20-c2103322d57e', 'practical_sign_off', 'PS-1', 'Power Evaluation & Method Selection', array['C105-01','C105-02','C105-03','C105-04','C105-05']::text[], ('{"dimensions":["Task and output definition","Instruction and intent","Observation","Regression/progression","Evidence honesty"],"pass":"11/15, no dimension below 2, never 0 on Evidence honesty"}')::jsonb, 'Completed at M4. Gates M5. — Minimum four-week practical window per course. Every recorded result carries the evaluator''s identity; results are immutable once recorded — corrections are new records.', '00000000-0000-4000-8000-000000000031'),
  ('8f706277-82e0-551c-8b5f-2a64c2a58604', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9104a610-53ae-5fc5-b565-23db55089bb0', 'b082c091-4245-5527-8496-97d588c55d2d', 'practical_sign_off', 'PS-2', 'Power Exercise Coaching', array['C105-06','C105-07','C105-09']::text[], ('{"dimensions":["Task and output definition","Instruction and intent","Observation","Regression/progression","Evidence honesty"],"pass":"11/15, no dimension below 2, never 0 on Evidence honesty"}')::jsonb, 'Completed at M7. Gates M8. — Minimum four-week practical window per course. Every recorded result carries the evaluator''s identity; results are immutable once recorded — corrections are new records.', '00000000-0000-4000-8000-000000000031'),
  ('9e56d592-18ae-571f-8b59-42395b8871bd', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9104a610-53ae-5fc5-b565-23db55089bb0', '8311200a-fd84-5a83-9b07-86b7799cb925', 'practical_sign_off', 'PS-3', 'Contextual Power Session Design', array['C105-07','C105-13','C105-15','C105-18']::text[], ('{"dimensions":["Task and output definition","Instruction and intent","Observation","Regression/progression","Evidence honesty"],"pass":"11/15, no dimension below 2, never 0 on Evidence honesty"}')::jsonb, 'Completed at M11. Gates M12. — Minimum four-week practical window per course. Every recorded result carries the evaluator''s identity; results are immutable once recorded — corrections are new records.', '00000000-0000-4000-8000-000000000031'),
  ('49889292-f7fd-5ef0-9184-b9d4bc58c8db', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9104a610-53ae-5fc5-b565-23db55089bb0', '7f05dab6-0130-5d58-a2ff-9e3eedfa9cf2', 'practical_sign_off', 'PS-4', 'Integrated Power Microcycle', array['C105-03','C105-08','C105-09','C105-10','C105-11','C105-12','C105-14','C105-16','C105-17']::text[], ('{"dimensions":["Task and output definition","Instruction and intent","Observation","Regression/progression","Evidence honesty"],"pass":"11/15, no dimension below 2, never 0 on Evidence honesty"}')::jsonb, 'Completed at M12. Requires the four-week delivery window complete. — Minimum four-week practical window per course. Every recorded result carries the evaluator''s identity; results are immutable once recorded — corrections are new records.', '00000000-0000-4000-8000-000000000031'),
  ('7e202be5-7714-58e3-8dea-fdcf4c094752', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9104a610-53ae-5fc5-b565-23db55089bb0', 'fc9ed188-04fb-5d2a-a50f-ac4577327c77', 'terminal_defense', 'T-01', 'Power Development Programming Defense', array['C105-01','C105-02','C105-03','C105-04','C105-05','C105-06','C105-07','C105-08','C105-09','C105-10','C105-11','C105-12','C105-13','C105-14','C105-15','C105-16','C105-17','C105-18','C105-19']::text[], ('{"dimensions":["Demand and task fluency","Hypothesis discipline","Method reasoning","Measurement discipline","Evidence honesty"],"pass":"11/15, no dimension below 2, never 0 on Evidence honesty","nonCompensable":["cannot answer probe 4 (evidence vs G3 standard vs judgment)","cannot answer probe 5 (acute vs chronic evidence)","makes an injury-prevention guarantee on probe 7","cites a threshold, percentage, contact count, or required method as justification"]}')::jsonb, '20–30 minutes with an approved assessor, using the coach''s own athlete or group and their own artifacts. The assessor works the ten obligations (§1.4) in order and probes at least four. — Minimum four-week practical window per course. Every recorded result carries the evaluator''s identity; results are immutable once recorded — corrections are new records.', '00000000-0000-4000-8000-000000000031')
insert into public.curriculum_records (id, organization_id, course_id, kind, code, title, data, position) values
  ('06da2421-50c1-557e-8b9b-257c63208bb6', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9104a610-53ae-5fc5-b565-23db55089bb0', 'doctrine', 'D105-01', 'Power Is Task-Specific', ('{"id":"D105-01","title":"Power Is Task-Specific","statement":"Interpret power within the movement, load, body mass, force-time constraints, and measurement method used to express it.","evidence_class":"A","evidence_note":"A — Established / Known. Mechanical power may be expressed as work over time and, in aligned conditions, as force × velocity — but neither relationship establishes that a high power measurement represents a stable trait independent of task, body mass, equipment, calculation method, and movement strategy. [EP105-01, EP105-02, EP105-08]","teaching_boundary":"This does not make power measurement useless. It makes an unlabeled power number meaningless. Every power value in G3 carries its task, load, and calculation method.","sources":["EP105-01","EP105-02","EP105-08"]}')::jsonb, 'a0'),
  ('258c257a-da48-5356-a218-95f24746f7c9', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9104a610-53ae-5fc5-b565-23db55089bb0', 'doctrine', 'D105-02', 'Related Qualities Are Not Interchangeable', ('{"id":"D105-02","title":"Related Qualities Are Not Interchangeable","statement":"Strength, force, impulse, velocity, power, and RFD interact but are distinct.","evidence_class":"A","evidence_note":"A — Established / Known for the mechanical distinctions; A for definition, B/C for routine field interpretation in the case of RFD. [EP105-01, EP105-02, EP105-03]","teaching_boundary":"Distinct does not mean unrelated — these qualities interact continuously in every athletic task. The doctrine forbids substitution, not integration. \"Explosiveness\" is Class F as a precise diagnostic term and is replaced by the actual quality and task.","sources":["EP105-01","EP105-02","EP105-03"]}')::jsonb, 'a1'),
  ('ef98c5c2-fa2a-5467-9c65-aa6d3f6ec6ed', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9104a610-53ae-5fc5-b565-23db55089bb0', 'doctrine', 'D105-03', 'Power Development Is Method-Neutral', ('{"id":"D105-03","title":"Power Development Is Method-Neutral","statement":"Plyometrics, ballistic resistance exercise, sprinting, resistance training, medicine-ball work, and weightlifting derivatives can all contribute. No method is universally required.","evidence_class":"B","evidence_note":"B — Supported Practice that multiple method families are effective for power-related outcomes when selected for the athlete, task, and context; F for any claim that a named method is universally superior or universally required. The Evidence Pack rates the comparative method evidence B, never A, and G3 does not raise it. Plyometric-versus-resistance comparisons show no consistent difference for jump outcomes, with mixed sprint findings; weightlifting and plyometric training may yield similar improvements in several outcomes. [EP105-02, EP105-04, EP105-14, EP105-15]","teaching_boundary":"Method-neutral is not method-indifferent. Methods differ in learning cost, equipment demand, fatigue cost, and coachability — which is exactly what AS-105-03 asks the coach to weigh. No G3 material may require any exercise or method.","sources":["EP105-02","EP105-04","EP105-14","EP105-15"]}')::jsonb, 'a2'),
  ('113a58b0-98f6-535a-abc1-42daacd7fd93', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9104a610-53ae-5fc5-b565-23db55089bb0', 'doctrine', 'D105-04', 'Strength Supports Power but Does Not Gate It', ('{"id":"D105-04","title":"Strength Supports Power but Does Not Gate It","statement":"Strength matters, especially in weaker and less-trained athletes, but G3 does not require a universal strength phase or squat ratio before appropriate power training.","evidence_class":"A","evidence_note":"A — Known that strength is a contributor to power; B — Probable that weaker athletes often benefit materially from strength development; F for the claim that athletes must get strong before any power training, and F for a universal squat-ratio prerequisite — a youth resistance-training review specifically states that the frequently proposed 1.5×-bodyweight squat prerequisite for lower-body plyometrics is not supported. [EP105-02, EP105-10, EP105-11]","teaching_boundary":"Rejecting the gate is not rejecting strength. Competence, exposure, readiness, supervision, and task demand still govern what an athlete does (AS-105-06) — those are coaching judgments, not a ratio.","sources":["EP105-02","EP105-10","EP105-11"]}')::jsonb, 'a3'),
  ('38920ba4-82ea-5e1e-bced-bc95a25225e7', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9104a610-53ae-5fc5-b565-23db55089bb0', 'doctrine', 'D105-05', 'Acute Output Does Not Dictate Chronic Prescription', ('{"id":"D105-05","title":"Acute Output Does Not Dictate Chronic Prescription","statement":"The load producing the highest acute measured power is not automatically the best long-term training load.","evidence_class":"A","evidence_note":"A — Established as a distinction. Maximal measured power often occurs at an intermediate load, but the exact load varies by exercise, athlete, measurement method, external versus system power, body mass, and peak versus mean outcome; training outcomes depend on stimulus, specificity, volume, technical quality, fatigue, athlete status, and concurrent training. The universal \"30% 1RM\" rule is F. [EP105-02, EP105-08]","teaching_boundary":"No load percentage is published anywhere in this course (CJ-01, CJ-02). Acute peak-power testing may describe an exercise response for an athlete; it does not set the chronic training load.","sources":["EP105-02","EP105-08"]}')::jsonb, 'a4'),
  ('b8c724b5-f3c0-54e2-ae55-5952ccd8a987', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9104a610-53ae-5fc5-b565-23db55089bb0', 'doctrine', 'D105-06', 'Output Quality Governs Power Training', ('{"id":"D105-06","title":"Output Quality Governs Power Training","statement":"Preserve movement intent, technical execution, and output quality appropriate to the objective. Fatigue that materially changes the task changes the stimulus.","evidence_class":"B","evidence_note":"B — Supported Practice. Power work generally requires more recovery than hypertrophy-oriented training when the priority is preserving velocity, jump height, technical execution, or output; exact rest requirements vary by task, load, athlete, and objective. [EP105-02]","teaching_boundary":"No rest interval, repetition count, or velocity-loss cutoff is published (CJ-10, CJ-11). \"Fatigue makes power work more sport-specific\" is an F/B boundary claim: training under fatigue may develop fatigue tolerance, but it does not make maximal-power work more specific.","sources":["EP105-02"]}')::jsonb, 'a5'),
  ('6dc2fd7a-c6e2-5034-89b3-a9003921982f', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9104a610-53ae-5fc5-b565-23db55089bb0', 'doctrine', 'D105-07', 'Transfer Must Be Demonstrated, Not Assumed', ('{"id":"D105-07","title":"Transfer Must Be Demonstrated, Not Assumed","statement":"Improvement in a jump, lift, throw, profile, or laboratory metric does not automatically establish sport transfer.","evidence_class":"A","evidence_note":"A — Established. Power-related test outcomes are commonly associated with sprinting, jumping, and COD, but association does not identify the causal quality to train; isolated improvements in a training exercise cannot be assumed to transfer to sport performance. [EP105-02, EP105-07, EP105-14, EP105-15]","teaching_boundary":"Continuous with G3 103 D103-7 and G3 104 D104-2. This is not a claim that transfer is rare — it is a requirement that the transfer pathway be stated and, where possible, observed.","sources":["EP105-02","EP105-07","EP105-14","EP105-15"]}')::jsonb, 'a6'),
  ('975074f3-7292-5b86-a9c5-53a64da99e3b', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9104a610-53ae-5fc5-b565-23db55089bb0', 'doctrine', 'D105-08', 'Directional Similarity Is Not Sufficient Specificity', ('{"id":"D105-08","title":"Directional Similarity Is Not Sufficient Specificity","statement":"Horizontal, vertical, unilateral, bilateral, or visually sport-like exercises do not guarantee direction- or sport-specific transfer.","evidence_class":"B","evidence_note":"B — Supported Practice for considering direction and task demands; F for automatic vector-matching claims and for the blanket claim that unilateral work is inherently more sport-specific. [EP105-02, EP105-07, EP105-13]","teaching_boundary":"Direction may matter. What is unsupported is the inference from visual direction to guaranteed transfer. Selecting unilateral or bilateral work by task, competence, tolerance, and desired loading is Class D — legitimate coaching inference, labeled as such (CJ-12).","sources":["EP105-02","EP105-07","EP105-13"]}')::jsonb, 'a7'),
  ('05c082e2-a595-52ca-989e-07ae83cec179', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '9104a610-53ae-5fc5-b565-23db55089bb0', 'doctrine', 'D105-09', 'Profiling Generates Hypotheses', (('{"id":"D105-09","title":"Profiling Generates Hypotheses","statement":"Force–velocity profiles may describe performance and support hypotheses; profile labels are not definitive diagnoses.","evidence_class":"B for describing performance across selected loads with transparent protocol; C/D for generating training hypotheses; F for definitively diagnosing \"force deficiency\" or \"velocity deficiency,\" for using an \"optimal profile\" as an exact target for all athletes, and for replacing sprint/jump testing, technical observation, and sport context","evidence_note":"B for describing performance across selected loads with transparent protocol; C/D for generating training hypotheses; F for definitively diagnosing \"force deficiency\" or \"velocity deficiency,\" for using an \"optimal profile\" as an exact target for all athletes, and for replacing sprint/jump testing, technical observation, and sport context. Reliability is method-dependent — reported slope reliability across methods has been poor, and validity differs by method. Recent meta-analytic evidence on profile-based individualized training is C — Emerging. [EP105-05, EP105-06, EP105-07, EP105-16, EP105-25]","teaching_boundar'
