  ('ea592c24-0282-5eed-a627-e422cb17bb86', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b17cac49-2d2b-59c4-bc80-5de456998e75', 'evidence_classification', 'CLASS-E', 'E — Historical / Practitioner Framework', ('{"class":"E","name":"Historical / Practitioner Framework"}')::jsonb, 'q2'),
  ('ff873f8c-fbce-57a8-812b-96c313cba15c', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', 'b17cac49-2d2b-59c4-bc80-5de456998e75', 'evidence_classification', 'CLASS-F', 'F — Unsupported / Overstated Claim', ('{"class":"F","name":"Unsupported / Overstated Claim"}')::jsonb, 'q3'),
