  ('ba884d40-fe06-56f5-a1f6-29113de75ef0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4832fade-c765-5fcd-b784-d1a4103394fd', 'governance', 'change-control', 'G3-102 governance', ('{"approver":"Director of Training","review_cycle_months":24,"review_triggers":["Class A or B claim contradicted by new evidence","Class C claim strengthens enough to change practice","citation integrity flag resolved"],"version_rules":["Course version stamped on every certification record","Doctrine changes require minor version increment and delta notice","Evidence class change on A/B claims triggers content review of all tagged objects","Prohibited-claims register changes are major and require re-acknowledgment"],"production_checklist":["All twelve content objects present and in order","Every claim carries an evidence class","Three-column discipline rendered visually","No prohibited claim present","No key depends on a Class C, D, or E claim","No key depends on an unmapped citation tag","Glossary terms linked on first use","Every scenario commits the learner before feedback","Every applied assessment states criteria and rubric","All references resolve to EP IDs","Voice conforms to G3 Performance Brand Standards v1.0","Doctrine, standard, and judgment distinguishable without prompting"]}')::jsonb, 'n7'),
  ('e75cec79-f09c-52ef-88a5-658ce3ac51b1', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4832fade-c765-5fcd-b784-d1a4103394fd', 'governance', 'decision-model', 'G3 programming decision model', (('{"id":"g3-decision-model","sequence":["DEMAND","PROFILE","GAP","PRIORITY","PRESCRIPTION","RESPONSE","ADJUST"],"evidence_class":"D","integrity_rules":["No stage is skipped; a program without a documented priority stage is not a G3 program.","Changing a prescription requires revisiting the priority that produced it.","The model produces defensible decisions, not correct ones.","No automated scoring; any tool converting inputs into a recommended target requires Director of Training approval."],"stages":[{"id":"demand","name":"DEMAND","question":"What does this sport, position, or role actually require?","artifact":"sport_demand_profile","exit_criterion":"Three to five demands named; peak separated from average","common_failure":"Listing every demand as important; using averages as the whole picture"},{"id":"profile","name":"PROFILE","question":"What does this athlete currently possess?","artifact":"athlete_profile","exit_criterion":"Complete enough to program from; no item without a decision","common_failure":"Testing to fill a form; failing to record conditions"},{"id":"gap","name":"GAP","question":"Which differences are real, and which are relevant?","artifact":"gap_statement","exit'
    || '_criterion":"Carried-forward and set-aside items both stated","common_failure":"Treating the lowest score as the biggest problem"},{"id":"priority","name":"PRIORITY","question":"What earns the athlete''s highest-quality effort right now?","artifact":"priority_sheet","exit_criterion":"Every quality tiered; cost written","common_failure":"Weakness-first reflex; everything primary"},{"id":"prescription","name":"PRESCRIPTION","question":"What is the actual program, and does it reflect the priorities?","artifact":"program","exit_criterion":"An outside coach can infer the priority from the order","common_failure":"Priority stated but contradicted by session order"},{"id":"response","name":"RESPONSE","question":"What is actually happening?","artifact":"response_review","exit_criterion":"Working, not working, or cannot yet tell","common_failure":"Judging the program by competitive results"},{"id":"adjust","name":"ADJUST","question":"Change, hold, or progress - and why?","artifact":"adjustment_log_entry","exit_criterion":"Every change has a reason that is not the calendar","common_failure":"Change for novelty; no record of reasoning"}],"applications":["education","practical coaching","athlet'
    || 'e evaluations","GPI interpretation","team programming","NovaKore workflows"],"gpi_rule":"GPI output enters at PROFILE and is filtered at GAP. GPI never enters at PRIORITY."}'))::jsonb, 'n8'),
  ('80c1776c-8db3-586d-8b30-75da71388e54', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '4832fade-c765-5fcd-b784-d1a4103394fd', 'governance', 'sequencing', 'G3-102 sequencing and hard gates', ('{"order":["M1","M2","M3","M4","PS-1","M5","M6","M7","M8","PS-2","M9","M10","PS-3","M11","M12","PS-4","T-01"],"hard_gates":["PS-1 gates M5","PS-2 gates M9"],"rules":["Module assessments must be at standard before the next module unlocks.","The four-week delivery window may run in parallel with M9-M11.","PS-4 cannot be scheduled until the delivery window is complete.","Completed modules remain accessible."]}')::jsonb, 'n9')
