  ('c27ea1a4-db72-5920-a1c9-775a0c2d6786', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'governance', 'change-control', 'G3-104 governance', (('{"approver":"Director of Training","review_cycle_months":24,"review_triggers":["Class A or B claim contradicted by new evidence","Class C claim strengthens enough to change practice","a U topic is resolved","the citation-mapping issue is closed"],"version_rules":["Course version stamped on every certification record","Doctrine changes require a minor version increment and delta notice","Resolution of the citation-mapping issue triggers content review of affected objects","Claim Audit register changes are major and require re-acknowledgment","Any locally adopted working figure is reviewed on its stated review date or removed"],"approval_matrix":[{"item":"doctrine or applied standard change","approver":"Director of Training"},{"item":"any locally adopted ratio, threshold, dose, or velocity figure","approver":"Director of Training, with population, measurement basis, and review date documented"},{"item":"external copy referencing strength training, injury, or youth training","approver":"Director of Training (Brand Standards governance)"},{"item":"any tool that automates a prescription, readiness threshold, or asymmetry alert","approver":"Director of Training, with documented evidence '
    || 'basis"}]}'))::jsonb, 'q9'),
  ('7054e7a3-e41c-5b71-982f-b991cfbbeef0', '26f6aa4a-4ade-4bb0-842f-12ca2e5bc115', '815eac17-e5d1-5010-88fc-c3fa412e47ee', 'governance', 'sequencing', 'G3-104 sequencing and hard gates', ('{"order":["M1","M2","M3","M4","PS-1","M5","M6","M7","PS-2","M8","M9","M10","M11","PS-3","M12","PS-4","T-01"],"hard_gates":["PS-1 gates M5","PS-2 gates M8","PS-3 gates M12"],"rules":["Modules unlock sequentially; module assessments must be at standard before the next module unlocks.","PS-1 is required before advanced applied-method work (M5 onward).","PS-4 requires the four-week delivery window complete.","T-01 requires PS-1 through PS-4 recorded and all module assessments at standard.","T-01 is required for course competency completion.","Completed modules remain accessible."]}')::jsonb, 'r0')
on conflict (id) do nothing;

